/* ============================================================
   AMaC — MRCS Part A Applied Knowledge Bank  (mrcs-a-applied-knowledge-questions.js)
   ------------------------------------------------------------
   Used by mrcs-a-applied-knowledge.html. A separate set from the
   MRCS Part A bank in data/reviewed.json; the two are not merged.

   Each question carries these fields:
     id, subject, topic, title, stem, options {A-E},
     correct_letter, correct_answer, why_correct, exam_trap,
     takeaway, source

   ids are MAK- plus the source question number, so every item
   traces back to the source text file. Stored option letters follow
   the source and are skewed towards A/B; the page shuffles the
   options for display and remaps the answer letter, so the stored
   order is never what a candidate sees.

   exam_trap is an empty string where the source has none.

   Review: reviewed by the AMaC team, 2026-09-26.
   ============================================================ */
window.MRCSA_AK_QUESTIONS = [
  {"id": "MAK-031", "subject": "Anatomy", "topic": "intercostal neurovascular bundle", "title": "Thorax: intercostal neurovascular bundle", "stem": "A 72-year-old patient requires an intercostal drain. The surgeon wants to minimise the risk of injury to the main intercostal neurovascular bundle. Where does the main bundle normally run within an intercostal space?", "options": {"A": "Along the superior border of the upper rib", "B": "Along the inferior border of the upper rib", "C": "Within the centre of the intercostal muscle", "D": "Along the superior border of the lower rib", "E": "Immediately superficial to the skin"}, "correct_letter": "B", "correct_answer": "B. Along the inferior border of the upper rib", "why_correct": "The principal intercostal neurovascular bundle runs in the costal groove along the inferior border of the rib forming the upper boundary of the intercostal space. The usual safe principle for procedures entering the chest wall is to pass immediately superior to the rib below the chosen space, while recognising that collateral vessels and anatomical variation exist.", "exam_trap": "The bundle is VAN in the costal groove: vein, artery, nerve.", "takeaway": "For an intercostal procedure, understand the relationship of the main neurovascular bundle to the rib before inserting anything.", "source": "[GAFS4], Thorax chapter."},
  {"id": "MAK-032", "subject": "Anatomy", "topic": "phrenic nerve", "title": "Thorax: phrenic nerve", "stem": "During mediastinal surgery, a nerve running on the lateral surface of the pericardium is identified. Which nerve is most likely being seen?", "options": {"A": "Vagus nerve", "B": "Recurrent laryngeal nerve", "C": "Phrenic nerve", "D": "Greater splanchnic nerve", "E": "Sympathetic trunk"}, "correct_letter": "C", "correct_answer": "C. Phrenic nerve", "why_correct": "The phrenic nerves descend through the thorax on the fibrous pericardium, anterior to the roots of the lungs. They provide the motor supply to the diaphragm and sensory supply to parts of the pericardium and pleura.", "exam_trap": "The vagus nerves pass posterior to the roots of the lungs and contribute to the pulmonary and oesophageal plexuses.", "takeaway": "Phrenic nerve = diaphragm motor supply + runs on pericardium.", "source": "[GAFS4], Thorax chapter."},
  {"id": "MAK-033", "subject": "Anatomy", "topic": "vagus nerve and lung root", "title": "Thorax: vagus nerve and lung root", "stem": "A thoracic surgeon is dissecting around the root of the lung. Which relationship is correct?", "options": {"A": "Phrenic nerve passes posterior to the lung root", "B": "Vagus nerve passes anterior to the lung root", "C": "Phrenic nerve passes anterior to the lung root", "D": "Both nerves pass through the pulmonary artery", "E": "Neither nerve is related to the lung root"}, "correct_letter": "C", "correct_answer": "C. Phrenic nerve passes anterior to the lung root", "why_correct": "The phrenic nerve passes anterior to the root of the lung, whereas the vagus nerve passes posterior to it.", "exam_trap": "This relationship is commonly tested because both nerves enter the mediastinum and descend toward the diaphragm.", "takeaway": "Phrenic = anterior to lung root. Vagus = posterior to lung root.", "source": "[GAFS4], Thorax chapter."},
  {"id": "MAK-034", "subject": "Anatomy", "topic": "bronchopulmonary segments", "title": "Thorax: bronchopulmonary segments", "stem": "A surgeon is planning a segmental lung resection. Which anatomical feature makes an anatomical pulmonary segment suitable for segmentectomy?", "options": {"A": "It is supplied by a segmental bronchus and accompanying branch of the pulmonary artery", "B": "It is supplied only by the bronchial arteries", "C": "It has no independent bronchial supply", "D": "It contains a complete independent pleural cavity", "E": "It is defined solely by the pulmonary veins"}, "correct_letter": "A", "correct_answer": "A. It is supplied by a segmental bronchus and accompanying branch of the pulmonary artery", "why_correct": "Bronchopulmonary segments are anatomically defined territories supplied by a segmental bronchus and a corresponding branch of the pulmonary artery. Pulmonary veins tend to run in the intersegmental planes.", "exam_trap": "The pulmonary veins are important landmarks between segments rather than the principal vessels defining the segment itself.", "takeaway": "Segment = segmental bronchus + pulmonary arterial supply; veins tend to mark boundaries.", "source": "[GAFS4], Thorax chapter."},
  {"id": "MAK-035", "subject": "Anatomy", "topic": "thoracic duct", "title": "Thorax: thoracic duct", "stem": "A patient undergoes extensive left-sided neck surgery. Postoperatively, milky fluid is noted in the wound drain. Which structure is most likely to have been injured?", "options": {"A": "Right lymphatic duct", "B": "Thoracic duct", "C": "Internal jugular vein only", "D": "Phrenic nerve", "E": "Vagus nerve"}, "correct_letter": "B", "correct_answer": "B. Thoracic duct", "why_correct": "The thoracic duct terminates at the junction of the left internal jugular and left subclavian veins. It therefore lies at risk during surgery in the left lower neck.", "exam_trap": "The right lymphatic duct drains the right upper quadrant of the body and terminates on the right side.", "takeaway": "Left lower neck + chyle leak = thoracic duct injury.", "source": "[GAFS4], Thorax chapter."},
  {"id": "MAK-036", "subject": "Anatomy", "topic": "epiploic foramen", "title": "Abdomen: epiploic foramen", "stem": "During an operation, a surgeon places a finger through the epiploic foramen. Which structure forms the anterior boundary of this opening?", "options": {"A": "Inferior vena cava", "B": "Caudate lobe of liver", "C": "Portal triad within the hepatoduodenal ligament", "D": "Left gastric artery", "E": "Splenic artery"}, "correct_letter": "C", "correct_answer": "C. Portal triad within the hepatoduodenal ligament", "why_correct": "The epiploic foramen connects the greater and lesser sacs. Its anterior boundary is the free edge of the lesser omentum, containing the portal triad. The posterior boundary is related to the inferior vena cava.", "exam_trap": "The portal triad is within the hepatoduodenal ligament, not simply a free-standing group of structures in the abdominal cavity.", "takeaway": "Epiploic foramen anterior = hepatoduodenal ligament/portal triad.", "source": "[GAFS4], Abdomen chapter."},
  {"id": "MAK-037", "subject": "Anatomy", "topic": "Pringle manoeuvre", "title": "Abdomen: Pringle manoeuvre", "stem": "During surgery for major hepatic haemorrhage, temporary compression is applied to the hepatoduodenal ligament. What is the principal purpose?", "options": {"A": "Occlude the inferior vena cava", "B": "Control inflow through the portal triad", "C": "Occlude the splenic artery", "D": "Control hepatic venous outflow", "E": "Occlude the superior mesenteric artery"}, "correct_letter": "B", "correct_answer": "B. Control inflow through the portal triad", "why_correct": "Compression of the hepatoduodenal ligament, known as the Pringle manoeuvre, temporarily controls hepatic arterial and portal venous inflow.", "exam_trap": "Persistent bleeding despite effective inflow occlusion suggests a possible hepatic venous or retrohepatic caval source.", "takeaway": "Pringle manoeuvre = temporary control of hepatic inflow.", "source": "[GAFS4], Abdomen chapter."},
  {"id": "MAK-038", "subject": "Anatomy", "topic": "lesser sac", "title": "Abdomen: lesser sac", "stem": "A patient develops a pancreatic pseudocyst that expands into a peritoneal compartment behind the stomach. Which space is involved?", "options": {"A": "Greater sac", "B": "Lesser sac", "C": "Pelvic cavity", "D": "Right paracolic gutter", "E": "Retroperitoneal space only"}, "correct_letter": "B", "correct_answer": "B. Lesser sac", "why_correct": "The lesser sac lies posterior to the stomach and lesser omentum and anterior to structures including the pancreas.", "exam_trap": "The pancreas itself is largely retroperitoneal, but inflammatory collections can extend into adjacent peritoneal spaces including the lesser sac.", "takeaway": "Behind stomach = lesser sac.", "source": "[GAFS4], Abdomen chapter."},
  {"id": "MAK-039", "subject": "Anatomy", "topic": "foregut blood supply", "title": "Abdomen: foregut blood supply", "stem": "Which artery is the principal arterial supply to the embryological foregut?", "options": {"A": "Superior mesenteric artery", "B": "Inferior mesenteric artery", "C": "Coeliac trunk", "D": "Internal iliac artery", "E": "Renal artery"}, "correct_letter": "C", "correct_answer": "C. Coeliac trunk", "why_correct": "The coeliac trunk supplies the embryological foregut, including structures such as the distal oesophagus, stomach, proximal duodenum, liver, gallbladder, pancreas and spleen.", "exam_trap": "The spleen is not a gut-derived organ, but its arterial supply arises from the coeliac trunk.", "takeaway": "Foregut = coeliac. Midgut = SMA. Hindgut = IMA.", "source": "[GAFS4], Abdomen chapter."},
  {"id": "MAK-040", "subject": "Anatomy", "topic": "midgut blood supply", "title": "Abdomen: midgut blood supply", "stem": "A patient undergoes resection for acute small-bowel ischaemia. Which artery provides the principal arterial supply to most of the small intestine?", "options": {"A": "Coeliac trunk", "B": "Inferior mesenteric artery", "C": "Superior mesenteric artery", "D": "Internal iliac artery", "E": "Inferior epigastric artery"}, "correct_letter": "C", "correct_answer": "C. Superior mesenteric artery", "why_correct": "The superior mesenteric artery supplies the embryological midgut, including most of the small intestine and proximal colon.", "exam_trap": "The terminal ileum and caecum remain within the SMA territory despite being anatomically close to the pelvic colon.", "takeaway": "Small bowel = predominantly SMA territory.", "source": "[GAFS4], Abdomen chapter."},
  {"id": "MAK-041", "subject": "Anatomy", "topic": "marginal artery", "title": "Abdomen: marginal artery", "stem": "During colorectal surgery, the surgeon is concerned about the arterial collateral circulation along the mesenteric border of the colon. Which vessel is most relevant?", "options": {"A": "Marginal artery of Drummond", "B": "Inferior vena cava", "C": "Portal vein", "D": "Gastroduodenal artery", "E": "Renal artery"}, "correct_letter": "A", "correct_answer": "A. Marginal artery of Drummond", "why_correct": "The marginal artery forms an arterial arcade along the mesenteric border of much of the colon and provides collateral communication between branches of the superior and inferior mesenteric arteries.", "exam_trap": "Do not confuse the marginal artery with the arc of Riolan, which is a more variable collateral connection between mesenteric arterial territories.", "takeaway": "Colon + marginal arterial arcade = artery of Drummond.", "source": "[GAFS4], Abdomen chapter."},
  {"id": "MAK-042", "subject": "Anatomy", "topic": "ureteric narrowing", "title": "Abdomen: ureteric narrowing", "stem": "A patient has a ureteric calculus that becomes impacted at a common anatomical site of ureteric narrowing. Which location is a recognised normal narrowing?", "options": {"A": "At the renal cortex", "B": "At the pelviureteric junction", "C": "At the midpoint of the urethra", "D": "At the splenic hilum", "E": "At the common bile duct"}, "correct_letter": "B", "correct_answer": "B. At the pelviureteric junction", "why_correct": "Common sites of ureteric narrowing include the pelviureteric junction, crossing of the pelvic brim/iliac vessels and the vesicoureteric junction.", "exam_trap": "The three classic constrictions should be understood anatomically rather than memorised as an isolated list.", "takeaway": "PUJ → pelvic brim → VUJ are classic ureteric narrowing sites.", "source": "[GAFS4], Abdomen and Pelvis chapters."},
  {"id": "MAK-043", "subject": "Anatomy", "topic": "retroperitoneal structures", "title": "Abdomen: retroperitoneal structures", "stem": "Which structure is primarily retroperitoneal?", "options": {"A": "Stomach", "B": "Jejunum", "C": "Transverse colon", "D": "Pancreas, apart from its tail", "E": "Spleen"}, "correct_letter": "D", "correct_answer": "D. Pancreas, apart from its tail", "why_correct": "Most of the pancreas is secondarily retroperitoneal. The tail extends toward the splenic hilum within the splenorenal ligament.", "exam_trap": "The pancreas is not uniformly retroperitoneal.", "takeaway": "Pancreas = mostly retroperitoneal; tail is the important exception.", "source": "[GAFS4], Abdomen chapter."},
  {"id": "MAK-044", "subject": "Anatomy", "topic": "Calot/hepatocystic triangle", "title": "Abdomen: Calot/hepatocystic triangle", "stem": "During laparoscopic cholecystectomy, the surgeon identifies the cystic artery within the hepatocystic triangle. Which structure forms an important boundary of this triangle?", "options": {"A": "Common hepatic artery", "B": "Cystic duct", "C": "Inferior vena cava", "D": "Left hepatic vein", "E": "Splenic artery"}, "correct_letter": "B", "correct_answer": "B. Cystic duct", "why_correct": "The hepatocystic triangle is bounded by the cystic duct, common hepatic duct and inferior surface of the liver. It contains structures including the cystic artery in the usual anatomical arrangement.", "exam_trap": "Terminology varies between descriptions of the \"Calot triangle\" and the hepatocystic triangle. For surgical anatomy, the boundaries and contents should be understood rather than relying only on the name.", "takeaway": "Cholecystectomy anatomy = identify the cystic duct and arterial structures safely before division.", "source": "[GAFS4], Abdomen chapter."},
  {"id": "MAK-045", "subject": "Anatomy", "topic": "internal iliac artery", "title": "Pelvis: internal iliac artery", "stem": "A pelvic surgeon is reviewing the arterial supply of the pelvis. Which vessel is a branch of the internal iliac artery?", "options": {"A": "Superior mesenteric artery", "B": "Inferior mesenteric artery", "C": "Superior gluteal artery", "D": "Coeliac trunk", "E": "Inferior epigastric artery"}, "correct_letter": "C", "correct_answer": "C. Superior gluteal artery", "why_correct": "The superior gluteal artery is a branch of the posterior division of the internal iliac artery.", "exam_trap": "The inferior epigastric artery arises from the external iliac artery, not the internal iliac artery.", "takeaway": "Internal iliac branches supply pelvic viscera, pelvic walls, gluteal region and perineal structures.", "source": "[GAFS4], Pelvis and Perineum chapter."},
  {"id": "MAK-046", "subject": "Anatomy", "topic": "ureter and uterine artery", "title": "Pelvis: ureter and uterine artery", "stem": "During pelvic surgery, a surgeon is mobilising the uterus. Which relationship is clinically important when protecting the ureter?", "options": {"A": "The ureter passes over the uterine artery", "B": "The uterine artery crosses over the ureter", "C": "The ureter lies inside the uterine artery", "D": "The ureter passes through the ovary", "E": "The uterine artery arises from the external iliac artery"}, "correct_letter": "B", "correct_answer": "B. The uterine artery crosses over the ureter", "why_correct": "The uterine artery crosses superior to the ureter near the lateral cervix. This relationship is important during gynaecological surgery because ureteric injury can occur during ligation or division of uterine vessels.", "exam_trap": "The memorable relationship is \"water under the bridge\": ureter = water, uterine artery = bridge.", "takeaway": "Pelvic surgery + uterine artery = always think about the ureter underneath it.", "source": "[GAFS4], Pelvis and Perineum chapter."},
  {"id": "MAK-047", "subject": "Anatomy", "topic": "pudendal nerve", "title": "Pelvis: pudendal nerve", "stem": "A patient develops persistent perineal pain following pelvic surgery. The pudendal nerve is being considered. Which spinal nerve roots contribute to the pudendal nerve?", "options": {"A": "L1–L2", "B": "L2–L4", "C": "L4–S1", "D": "S2–S4", "E": "S4–Co1"}, "correct_letter": "D", "correct_answer": "D. S2–S4", "why_correct": "The pudendal nerve arises from the anterior rami of S2, S3 and S4. It supplies much of the somatic motor and sensory innervation of the perineum.", "exam_trap": "Do not confuse pudendal innervation with the pelvic autonomic nerves.", "takeaway": "Pudendal nerve = S2, S3, S4.", "source": "[GAFS4], Pelvis and Perineum chapter."},
  {"id": "MAK-048", "subject": "Anatomy", "topic": "ischioanal fossa", "title": "Perineum: ischioanal fossa", "stem": "A patient develops a perianal abscess that spreads laterally through a fat-filled space adjacent to the anal canal. Which space is involved?", "options": {"A": "Retropubic space", "B": "Ischioanal fossa", "C": "Lesser sac", "D": "Femoral canal", "E": "Superficial inguinal ring"}, "correct_letter": "B", "correct_answer": "B. Ischioanal fossa", "why_correct": "The ischioanal fossae are wedge-shaped spaces lateral to the anal canal containing fat and structures including the pudendal canal along their lateral walls.", "exam_trap": "The ischioanal fossa communicates across the posterior midline, allowing infection to spread between sides.", "takeaway": "Perianal abscess + lateral fat-filled space = ischioanal fossa.", "source": "[GAFS4], Pelvis and Perineum chapter."},
  {"id": "MAK-049", "subject": "Anatomy", "topic": "brachial plexus", "title": "Upper limb: brachial plexus", "stem": "A patient has weakness of elbow flexion and sensory disturbance along the lateral aspect of the forearm following an upper brachial plexus injury. Which nerve is most directly responsible for these functions?", "options": {"A": "Axillary nerve", "B": "Musculocutaneous nerve", "C": "Median nerve", "D": "Ulnar nerve", "E": "Radial nerve"}, "correct_letter": "B", "correct_answer": "B. Musculocutaneous nerve", "why_correct": "The musculocutaneous nerve supplies the anterior compartment of the arm, including the principal elbow flexors, and continues as the lateral cutaneous nerve of the forearm.", "exam_trap": "Elbow flexion is not supplied exclusively by the musculocutaneous nerve, but the combination of anterior arm weakness and lateral forearm sensory loss strongly points toward it.", "takeaway": "Musculocutaneous = anterior arm + lateral forearm sensation.", "source": "[GAFS4], Upper Limb chapter."},
  {"id": "MAK-050", "subject": "Anatomy", "topic": "axillary nerve", "title": "Upper limb: axillary nerve", "stem": "A patient sustains an anterior shoulder dislocation. Which nerve is particularly vulnerable?", "options": {"A": "Median nerve", "B": "Ulnar nerve", "C": "Axillary nerve", "D": "Musculocutaneous nerve", "E": "Radial nerve at the elbow"}, "correct_letter": "C", "correct_answer": "C. Axillary nerve", "why_correct": "The axillary nerve passes around the surgical neck of the humerus with the posterior circumflex humeral vessels and may be injured in shoulder dislocation or proximal humeral injury.", "exam_trap": "Always assess axillary nerve function after shoulder dislocation.", "takeaway": "Shoulder dislocation → axillary nerve risk.", "source": "[GAFS4], Upper Limb chapter."},
  {"id": "MAK-051", "subject": "Anatomy", "topic": "carpal tunnel", "title": "Upper limb: carpal tunnel", "stem": "A patient has nocturnal paraesthesia affecting the thumb, index finger, middle finger and radial half of the ring finger. Which structure is most likely compressed?", "options": {"A": "Ulnar nerve", "B": "Radial nerve", "C": "Median nerve", "D": "Ulnar artery", "E": "Musculocutaneous nerve"}, "correct_letter": "C", "correct_answer": "C. Median nerve", "why_correct": "The median nerve passes through the carpal tunnel with the long flexor tendons. Compression produces sensory symptoms in the median distribution.", "exam_trap": "The palmar cutaneous branch of the median nerve passes superficial to the flexor retinaculum and therefore sensation over the thenar eminence may be relatively preserved in carpal tunnel syndrome.", "takeaway": "Carpal tunnel = median nerve beneath flexor retinaculum.", "source": "[GAFS4], Upper Limb chapter."},
  {"id": "MAK-052", "subject": "Anatomy", "topic": "ulnar nerve", "title": "Upper limb: ulnar nerve", "stem": "A patient develops numbness of the little finger and ulnar half of the ring finger after trauma around the medial elbow. Which nerve has most likely been injured?", "options": {"A": "Median", "B": "Radial", "C": "Axillary", "D": "Ulnar", "E": "Musculocutaneous"}, "correct_letter": "D", "correct_answer": "D. Ulnar", "why_correct": "The ulnar nerve passes posterior to the medial epicondyle and supplies sensation to the little finger and ulnar side of the ring finger.", "exam_trap": "The ulnar nerve can be injured at several sites, so the examination should distinguish elbow-level injury from wrist-level injury using motor findings.", "takeaway": "Medial epicondyle = ulnar nerve danger zone.", "source": "[GAFS4], Upper Limb chapter."},
  {"id": "MAK-053", "subject": "Anatomy", "topic": "femoral triangle", "title": "Lower limb: femoral triangle", "stem": "A surgeon identifies the major neurovascular structures within the femoral triangle. From lateral to medial, which arrangement is correct?", "options": {"A": "Vein–artery–nerve", "B": "Artery–nerve–vein", "C": "Nerve–artery–vein", "D": "Nerve–vein–artery", "E": "Artery–vein–nerve"}, "correct_letter": "C", "correct_answer": "C. Nerve–artery–vein", "why_correct": "The principal arrangement within the femoral triangle from lateral to medial is nerve, artery, vein, followed by the femoral canal.", "exam_trap": "The femoral nerve lies outside the femoral sheath, whereas the artery and vein are within it.", "takeaway": "Femoral triangle lateral → medial: NAV.", "source": "[GAFS4], Lower Limb chapter."},
  {"id": "MAK-054", "subject": "Anatomy", "topic": "femoral canal", "title": "Lower limb: femoral canal", "stem": "A patient develops a groin swelling below and lateral to the pubic tubercle. Which anatomical structure is involved in a femoral hernia?", "options": {"A": "Femoral canal", "B": "Inguinal canal", "C": "Obturator canal", "D": "Adductor canal", "E": "Greater sciatic foramen"}, "correct_letter": "A", "correct_answer": "A. Femoral canal", "why_correct": "A femoral hernia passes through the femoral ring into the femoral canal. The femoral canal lies medial to the femoral vein within the femoral sheath.", "exam_trap": "Femoral hernias occur below the inguinal ligament and are classically associated with a higher risk of strangulation because of the relatively rigid femoral ring.", "takeaway": "Femoral hernia = femoral ring → femoral canal.", "source": "[GAFS4], Lower Limb chapter."},
  {"id": "MAK-055", "subject": "Anatomy", "topic": "popliteal fossa", "title": "Lower limb: popliteal fossa", "stem": "During surgery behind the knee, the surgeon identifies the principal structures of the popliteal fossa. Which structure is deepest?", "options": {"A": "Tibial nerve", "B": "Common fibular nerve", "C": "Popliteal vein", "D": "Popliteal artery", "E": "Small saphenous vein"}, "correct_letter": "D", "correct_answer": "D. Popliteal artery", "why_correct": "The usual superficial-to-deep relationship is tibial nerve, popliteal vein and popliteal artery.", "exam_trap": "The common fibular nerve runs laterally and is not part of the central neurovascular sequence.", "takeaway": "Popliteal fossa: nerve → vein → artery, superficial to deep.", "source": "[GAFS4], Lower Limb chapter."},
  {"id": "MAK-056", "subject": "Anatomy", "topic": "cauda equina", "title": "Spine: cauda equina", "stem": "A patient develops bilateral leg weakness, saddle sensory loss and urinary retention following a large lumbar disc prolapse. Which structure is being compressed?", "options": {"A": "Cervical spinal cord", "B": "Cauda equina nerve roots", "C": "Femoral nerve only", "D": "Sciatic nerve only", "E": "Sympathetic chain"}, "correct_letter": "B", "correct_answer": "B. Cauda equina nerve roots", "why_correct": "The cauda equina consists of lumbar, sacral and coccygeal nerve roots descending within the vertebral canal below the termination of the spinal cord. Compression can cause saddle anaesthesia, bladder/bowel dysfunction and lower-limb neurological deficits.", "exam_trap": "The spinal cord itself does not extend throughout the lumbar vertebral canal in adults.", "takeaway": "Saddle anaesthesia + bladder dysfunction + bilateral leg symptoms = cauda equina emergency.", "source": "[GAFS4], Back chapter."},
  {"id": "MAK-057", "subject": "Anatomy", "topic": "spinal cord termination", "title": "Spine: spinal cord termination", "stem": "In a healthy adult, approximately where does the spinal cord normally terminate?", "options": {"A": "C7", "B": "T6", "C": "T12", "D": "L1–L2 region", "E": "L5–S1"}, "correct_letter": "D", "correct_answer": "D. L1–L2 region", "why_correct": "The conus medullaris typically terminates around the L1–L2 vertebral level in adults, although there is normal anatomical variation.", "exam_trap": "The vertebral level of the spinal cord termination is not identical to the level of the corresponding spinal nerve roots.", "takeaway": "Adult spinal cord → conus around L1–L2.", "source": "[GAFS4], Back chapter."},
  {"id": "MAK-058", "subject": "Anatomy", "topic": "cavernous sinus", "title": "Head and neck: cavernous sinus", "stem": "A patient develops ophthalmoplegia and facial sensory disturbance following infection involving the face. Which venous structure is particularly relevant?", "options": {"A": "Cavernous sinus", "B": "Superior sagittal sinus only", "C": "Inferior vena cava", "D": "Portal vein", "E": "External jugular vein"}, "correct_letter": "A", "correct_answer": "A. Cavernous sinus", "why_correct": "The cavernous sinus communicates with facial and orbital venous pathways and contains or is closely related to several cranial nerves. Infection can spread into the cavernous sinus and produce ophthalmoplegia and sensory deficits.", "exam_trap": "The facial venous system has clinically important connections with intracranial venous sinuses.", "takeaway": "Facial infection + ophthalmoplegia = consider cavernous sinus involvement.", "source": "[GAFS4], Head and Neck chapter."},
  {"id": "MAK-059", "subject": "Anatomy", "topic": "recurrent laryngeal nerve course", "title": "Head and neck: recurrent laryngeal nerve course", "stem": "A surgeon is operating near the root of the neck and asks why the left recurrent laryngeal nerve has a longer intrathoracic course than the right. What structure does the left recurrent laryngeal nerve loop beneath?", "options": {"A": "Right subclavian artery", "B": "Aortic arch", "C": "Pulmonary artery", "D": "Common carotid artery", "E": "Internal jugular vein"}, "correct_letter": "B", "correct_answer": "B. Aortic arch", "why_correct": "The left recurrent laryngeal nerve loops beneath the aortic arch in the thorax before ascending toward the larynx. The right recurrent laryngeal nerve loops around the right subclavian artery.", "exam_trap": "The asymmetry is important in thoracic and thyroid surgery.", "takeaway": "Left RLN → aortic arch. Right RLN → right subclavian artery.", "source": "[GAFS4], Head and Neck chapter."},
  {"id": "MAK-060", "subject": "Anatomy", "topic": "tongue sensory innervation", "title": "Head and neck: tongue sensory innervation", "stem": "A patient has loss of general sensation from the anterior two-thirds of the tongue but retains taste sensation in the same region. Which nerve has most likely been injured?", "options": {"A": "Glossopharyngeal nerve", "B": "Chorda tympani alone", "C": "Lingual nerve proximal to the chorda tympani junction", "D": "Hypoglossal nerve", "E": "Internal laryngeal nerve"}, "correct_letter": "C", "correct_answer": "C. Lingual nerve proximal to the chorda tympani junction", "why_correct": "The lingual nerve carries general somatic sensation from the anterior two-thirds of the tongue. Taste fibres from the same region travel with the chorda tympani, which joins the lingual nerve. Therefore, an appropriately located isolated lingual nerve lesion can affect general sensation while taste pathways may be affected depending on the site of injury.", "exam_trap": "Do not simply associate all anterior tongue sensation with one nerve. General sensation and taste have different origins and travel together only after the chorda tympani joins the lingual nerve.", "takeaway": "Anterior 2/3: General sensation = lingual nerve. Taste = chorda tympani travelling with lingual nerve.", "source": "[GAFS4], Head and Neck chapter."},
  {"id": "MAK-061", "subject": "Anatomy", "topic": "middle cerebral artery", "title": "Brain: middle cerebral artery", "stem": "A patient develops sudden weakness predominantly affecting the face and upper limb, with aphasia. Which arterial territory is most likely affected in a patient with dominant-hemisphere involvement?", "options": {"A": "Anterior cerebral artery", "B": "Middle cerebral artery", "C": "Posterior cerebral artery", "D": "Superior cerebellar artery", "E": "Posterior inferior cerebellar artery"}, "correct_letter": "B", "correct_answer": "B. Middle cerebral artery", "why_correct": "The middle cerebral artery supplies large areas of the lateral cerebral hemisphere, including motor and sensory cortical regions representing the face and upper limb. In the dominant hemisphere, involvement of language areas can produce aphasia.", "exam_trap": "The anterior cerebral artery predominantly supplies the medial frontal and parietal cortex, including much of the lower-limb representation.", "takeaway": "MCA = lateral hemisphere + face/upper limb + dominant-language areas.", "source": "[GAFS4], Head and Neck chapter (cerebral vasculature)."},
  {"id": "MAK-062", "subject": "Anatomy", "topic": "anterior cerebral artery", "title": "Brain: anterior cerebral artery", "stem": "A patient develops contralateral weakness predominantly affecting the lower limb following an intracranial arterial occlusion. Which vascular territory is most likely involved?", "options": {"A": "Middle cerebral artery", "B": "Posterior cerebral artery", "C": "Anterior cerebral artery", "D": "Basilar artery", "E": "Middle meningeal artery"}, "correct_letter": "C", "correct_answer": "C. Anterior cerebral artery", "why_correct": "The anterior cerebral artery supplies the medial frontal and parietal cerebral cortex, including the cortical representation of the contralateral lower limb.", "exam_trap": "Face and upper limb predominance suggests MCA territory; lower-limb predominance suggests ACA territory.", "takeaway": "ACA = medial hemisphere = lower limb.", "source": "[GAFS4], Head and Neck chapter (cerebral vasculature)."},
  {"id": "MAK-063", "subject": "Anatomy", "topic": "facial nerve", "title": "Cranial nerves: facial nerve", "stem": "A patient has an isolated lower motor neurone facial nerve palsy. Which finding would be expected?", "options": {"A": "Sparing of forehead movement", "B": "Weakness of all muscles of facial expression on the affected side", "C": "Contralateral tongue weakness", "D": "Isolated loss of facial sensation", "E": "Loss of shoulder elevation"}, "correct_letter": "B", "correct_answer": "B. Weakness of all muscles of facial expression on the affected side", "why_correct": "A lower motor neurone facial nerve lesion affects the ipsilateral upper and lower facial muscles.", "exam_trap": "Forehead sparing is characteristic of many supranuclear upper motor neurone lesions because the upper facial nucleus receives bilateral cortical input.", "takeaway": "LMN VII = whole ipsilateral face. UMN lesion = classically forehead relatively spared.", "source": "[GAFS4], Head and Neck chapter."},
  {"id": "MAK-064", "subject": "Anatomy", "topic": "hypoglossal nerve", "title": "Cranial nerves: hypoglossal nerve", "stem": "A patient protrudes their tongue and it deviates to the right. A right hypoglossal nerve lesion is suspected. What additional finding is most likely?", "options": {"A": "Left facial weakness", "B": "Right-sided tongue weakness", "C": "Right-sided loss of facial sensation", "D": "Bilateral deafness", "E": "Left vocal-cord paralysis"}, "correct_letter": "B", "correct_answer": "B. Right-sided tongue weakness", "why_correct": "The hypoglossal nerve supplies the intrinsic and extrinsic muscles of the tongue, apart from palatoglossus. A unilateral lower motor neurone lesion causes weakness on the affected side, with deviation of the protruded tongue toward that side.", "exam_trap": "Do not confuse hypoglossal dysfunction with vagal dysfunction.", "takeaway": "CN XII lesion → tongue deviates toward the weak side.", "source": "[GAFS4], Head and Neck chapter."},
  {"id": "MAK-065", "subject": "Anatomy", "topic": "accessory nerve", "title": "Cranial nerves: accessory nerve", "stem": "Following lymph-node surgery in the posterior triangle of the neck, a patient has difficulty shrugging the affected shoulder. Which nerve is most likely injured?", "options": {"A": "Phrenic nerve", "B": "Hypoglossal nerve", "C": "Accessory nerve", "D": "Vagus nerve", "E": "Greater auricular nerve"}, "correct_letter": "C", "correct_answer": "C. Accessory nerve", "why_correct": "The spinal accessory nerve supplies the sternocleidomastoid and trapezius muscles. It is particularly vulnerable during surgery in the posterior triangle of the neck.", "exam_trap": "Shoulder shrugging tests trapezius function and therefore helps assess the spinal accessory nerve.", "takeaway": "Posterior triangle surgery + shoulder droop/weak shrug = CN XI.", "source": "[GAFS4], Head and Neck chapter."},
  {"id": "MAK-066", "subject": "Physiology", "topic": "Autonomic nervous system", "title": "Autonomic nervous system", "stem": "Which neurotransmitter is released by most postganglionic sympathetic neurons at their target organs?", "options": {"A": "Acetylcholine", "B": "Dopamine", "C": "Noradrenaline", "D": "Serotonin", "E": "Glutamate"}, "correct_letter": "C", "correct_answer": "C. Noradrenaline", "why_correct": "Most postganglionic sympathetic fibres release noradrenaline at their target organs. Important exceptions include sympathetic innervation of eccrine sweat glands, where acetylcholine is used.", "exam_trap": "All autonomic preganglionic neurons release acetylcholine.", "takeaway": "Preganglionic autonomic = ACh. Most sympathetic postganglionic = noradrenaline. Sympathetic sweat glands = ACh.", "source": "[GH14]."},
  {"id": "MAK-067", "subject": "Physiology", "topic": "Parasympathetic outflow", "title": "Parasympathetic outflow", "stem": "Which spinal segments contribute to the sacral parasympathetic outflow?", "options": {"A": "T1–T4", "B": "T5–T9", "C": "T10–L1", "D": "L1–L3", "E": "S2–S4"}, "correct_letter": "E", "correct_answer": "E. S2–S4", "why_correct": "Parasympathetic outflow is craniosacral. The sacral component arises from S2–S4 and contributes to pelvic visceral function.", "exam_trap": "The sympathetic system is thoracolumbar; the parasympathetic system is craniosacral.", "takeaway": "Parasympathetic sacral outflow = S2–S4.", "source": "[GH14]."},
  {"id": "MAK-068", "subject": "Physiology", "topic": "Pain pathways", "title": "Pain pathways", "stem": "A patient undergoes an anterolateral spinal cord procedure intended to interrupt transmission of pain and temperature sensation. Which tract is being targeted?", "options": {"A": "Dorsal columns", "B": "Corticospinal tract", "C": "Spinothalamic tract", "D": "Spinocerebellar tract", "E": "Vestibulospinal tract"}, "correct_letter": "C", "correct_answer": "C. Spinothalamic tract", "why_correct": "The anterolateral/spinothalamic pathway carries pain and temperature information from the body toward higher centres.", "exam_trap": "Fine touch, vibration and proprioception are principally carried in the dorsal column-medial lemniscus pathway.", "takeaway": "Pain + temperature = spinothalamic pathway.", "source": "[GH14]."},
  {"id": "MAK-069", "subject": "Physiology", "topic": "Dorsal columns", "title": "Dorsal columns", "stem": "Which sensory modality is predominantly transmitted through the dorsal column-medial lemniscus system?", "options": {"A": "Pain", "B": "Temperature", "C": "Vibration", "D": "Itch only", "E": "Crude visceral pain"}, "correct_letter": "C", "correct_answer": "C. Vibration", "why_correct": "The dorsal columns carry discriminative/fine touch, vibration and conscious proprioception.", "exam_trap": "Pain and temperature travel primarily through the anterolateral/spinothalamic system.", "takeaway": "Dorsal columns = vibration + proprioception + fine touch.", "source": "[GH14]."},
  {"id": "MAK-070", "subject": "Physiology", "topic": "Cerebellum", "title": "Cerebellum", "stem": "A patient has ipsilateral limb ataxia and dysmetria following a posterior fossa lesion. Which structure is most likely involved?", "options": {"A": "Cerebellum", "B": "Frontal cortex", "C": "Basal ganglia only", "D": "Medulla only", "E": "Hippocampus"}, "correct_letter": "A", "correct_answer": "A. Cerebellum", "why_correct": "The cerebellum coordinates movement and contributes to balance and motor learning. Cerebellar lesions classically produce ipsilateral limb coordination deficits.", "exam_trap": "Cerebellar disease causes incoordination rather than primary paralysis.", "takeaway": "Ipsilateral dysmetria/ataxia → think cerebellum.", "source": "[GH14]."},
  {"id": "MAK-071", "subject": "Physiology", "topic": "Basal ganglia", "title": "Basal ganglia", "stem": "Which clinical feature is most closely associated with dysfunction of the basal ganglia?", "options": {"A": "Pure loss of peripheral sensation", "B": "Movement disorder", "C": "Isolated hearing loss", "D": "Complete loss of visual acuity", "E": "Loss of diaphragmatic movement"}, "correct_letter": "B", "correct_answer": "B. Movement disorder", "why_correct": "The basal ganglia participate in the regulation and initiation of movement. Disorders affecting these structures can produce hypokinetic or hyperkinetic movement disorders.", "exam_trap": "The cerebellum is particularly important for coordination, whereas the basal ganglia are heavily involved in movement regulation.", "takeaway": "Basal ganglia = movement regulation.", "source": "[GH14]."},
  {"id": "MAK-072", "subject": "Physiology", "topic": "Raised intracranial pressure", "title": "Raised intracranial pressure", "stem": "A patient with an intracranial mass develops progressive headache, vomiting and papilloedema. Which mechanism best explains the clinical deterioration?", "options": {"A": "Reduced intracranial pressure", "B": "Increased intracranial pressure with impaired cerebral perfusion", "C": "Isolated peripheral neuropathy", "D": "Increased cerebrospinal fluid absorption", "E": "Reduced cerebral blood volume with improved perfusion"}, "correct_letter": "B", "correct_answer": "B. Increased intracranial pressure with impaired cerebral perfusion", "why_correct": "Increasing intracranial volume can raise intracranial pressure. If cerebral perfusion pressure falls sufficiently, cerebral blood flow may become compromised.", "exam_trap": "A patient with a space-occupying lesion can deteriorate despite initially preserved neurological function.", "takeaway": "Raised ICP can become a perfusion problem, not merely a pressure problem.", "source": "[GH14]."},
  {"id": "MAK-073", "subject": "Physiology", "topic": "CSF circulation", "title": "CSF circulation", "stem": "Cerebrospinal fluid is produced predominantly by which structure?", "options": {"A": "Arachnoid granulations", "B": "Choroid plexus", "C": "Dural venous sinuses", "D": "Pituitary gland", "E": "Cerebral aqueduct"}, "correct_letter": "B", "correct_answer": "B. Choroid plexus", "why_correct": "The choroid plexus is the principal site of cerebrospinal fluid production. Arachnoid granulations are involved in CSF absorption into the venous system.", "exam_trap": "Production and absorption are separate anatomical processes.", "takeaway": "CSF production = choroid plexus. CSF absorption = arachnoid granulations.", "source": "[GH14]."},
  {"id": "MAK-074", "subject": "Anatomy", "topic": "CSF obstruction", "title": "CSF obstruction", "stem": "A lesion obstructs the cerebral aqueduct. Which ventricular compartments are directly separated by the obstructed structure?", "options": {"A": "Lateral ventricles and third ventricle", "B": "Third and fourth ventricles", "C": "Fourth ventricle and central canal only", "D": "Lateral ventricles and subarachnoid space", "E": "Third ventricle and subarachnoid space"}, "correct_letter": "B", "correct_answer": "B. Third and fourth ventricles", "why_correct": "The cerebral aqueduct connects the third and fourth ventricles.", "exam_trap": "The foramina of Monro connect the lateral ventricles with the third ventricle.", "takeaway": "Aqueduct = third → fourth ventricle.", "source": "[GAFS4], Head and Neck chapter (ventricular system)."},
  {"id": "MAK-075", "subject": "Anatomy", "topic": "midgut rotation", "title": "Embryology: midgut rotation", "stem": "During embryological development, the midgut undergoes rotation around which vascular axis?", "options": {"A": "Coeliac trunk", "B": "Inferior mesenteric artery", "C": "Superior mesenteric artery", "D": "Renal artery", "E": "Internal iliac artery"}, "correct_letter": "C", "correct_answer": "C. Superior mesenteric artery", "why_correct": "The embryological midgut rotates around the axis of the superior mesenteric artery.", "exam_trap": "Midgut vascular anatomy and embryological rotation are closely linked.", "takeaway": "Midgut rotation = around SMA.", "source": "[MCOA9], Abdomen chapter (embryology)."},
  {"id": "MAK-076", "subject": "Anatomy", "topic": "Meckel diverticulum", "title": "Embryology: Meckel diverticulum", "stem": "A patient has a congenital true diverticulum arising from the ileum. Which embryological remnant is responsible?", "options": {"A": "Vitelline duct", "B": "Urachus", "C": "Allantois", "D": "Mesonephric duct", "E": "Müllerian duct"}, "correct_letter": "A", "correct_answer": "A. Vitelline duct", "why_correct": "Meckel diverticulum results from persistence of the vitelline/omphalomesenteric duct. It is a true diverticulum because it contains all layers of the intestinal wall.", "exam_trap": "The urachus is associated with the embryological allantois and bladder apex, not the ileum.", "takeaway": "Meckel = persistent vitelline duct.", "source": "[MCOA9], Abdomen chapter (embryology)."},
  {"id": "MAK-077", "subject": "Anatomy", "topic": "urachus", "title": "Embryology: urachus", "stem": "A child presents with urine discharge from the umbilicus. Persistence of which embryological structure is most likely responsible?", "options": {"A": "Vitelline duct", "B": "Urachus", "C": "Ductus arteriosus", "D": "Foramen ovale", "E": "Neural crest"}, "correct_letter": "B", "correct_answer": "B. Urachus", "why_correct": "The urachus is the embryological connection between the bladder apex and umbilicus. Persistence can result in a patent urachus and urine discharge through the umbilicus.", "exam_trap": "Faecal discharge from the umbilicus suggests a different embryological abnormality, such as a persistent vitelline duct.", "takeaway": "Urine from umbilicus = patent urachus.", "source": "[MCOA9], Abdomen and Pelvis chapter (embryology)."},
  {"id": "MAK-078", "subject": "Anatomy", "topic": "branchial apparatus", "title": "Embryology: branchial apparatus", "stem": "A congenital lateral neck cyst is identified along the anterior border of the sternocleidomastoid muscle in an adult. Which embryological structure is classically associated with a second branchial cleft cyst?", "options": {"A": "First branchial cleft", "B": "Second branchial cleft", "C": "Third pharyngeal pouch only", "D": "Thyroglossal duct", "E": "Neural tube"}, "correct_letter": "B", "correct_answer": "B. Second branchial cleft", "why_correct": "Second branchial cleft cysts are common congenital lateral neck lesions and are typically located along the anterior border of the sternocleidomastoid.", "exam_trap": "A midline neck cyst that moves with swallowing or tongue protrusion suggests a thyroglossal duct anomaly rather than a branchial cleft cyst.", "takeaway": "Lateral neck congenital cyst = think branchial cleft. Midline = think thyroglossal duct.", "source": "[MCOA9], Head and Neck chapter (embryology)."},
  {"id": "MAK-079", "subject": "Anatomy", "topic": "thyroid descent", "title": "Embryology: thyroid descent", "stem": "A patient has a midline neck swelling that moves upward when they protrude their tongue. Which embryological remnant is most likely involved?", "options": {"A": "Second branchial cleft", "B": "Thyroglossal duct", "C": "Vitelline duct", "D": "Urachus", "E": "Ductus venosus"}, "correct_letter": "B", "correct_answer": "B. Thyroglossal duct", "why_correct": "The thyroid descends from the foramen caecum of the tongue through the embryological thyroglossal duct. Persistence can produce a thyroglossal duct cyst.", "exam_trap": "Movement with tongue protrusion is particularly characteristic because of the lesion's relationship with the tract of thyroid descent.", "takeaway": "Midline + moves with tongue protrusion = thyroglossal duct cyst.", "source": "[MCOA9], Head and Neck chapter (embryology)."},
  {"id": "MAK-080", "subject": "Anatomy", "topic": "testicular descent", "title": "Embryology: testicular descent", "stem": "Which structure is most directly associated with the descent of the testis into the scrotum?", "options": {"A": "Gubernaculum", "B": "Median arcuate ligament", "C": "Falciform ligament", "D": "Round ligament of the liver", "E": "Ligamentum arteriosum"}, "correct_letter": "A", "correct_answer": "A. Gubernaculum", "why_correct": "The gubernaculum is involved in guiding the testis during its descent toward the scrotum. The processus vaginalis is another important embryological structure associated with testicular descent and the development of certain inguinal hernias and hydroceles.", "exam_trap": "Do not confuse the gubernaculum with the spermatic cord.", "takeaway": "Testicular descent = gubernaculum + processus vaginalis.", "source": "[MCOA9], Abdomen and Pelvis chapter (embryology)."},
  {"id": "MAK-081", "subject": "Physiology", "topic": "Starling forces", "title": "Physiology: Starling forces", "stem": "A patient develops generalised oedema because of a substantial reduction in plasma oncotic pressure. Which change most directly promotes movement of fluid out of capillaries?", "options": {"A": "Increased plasma oncotic pressure", "B": "Reduced capillary hydrostatic pressure", "C": "Reduced plasma oncotic pressure", "D": "Increased lymphatic drainage", "E": "Increased interstitial oncotic pressure with intact lymphatic drainage"}, "correct_letter": "C", "correct_answer": "C. Reduced plasma oncotic pressure", "why_correct": "Plasma proteins contribute to the oncotic force retaining water within the vascular compartment. Reduced plasma oncotic pressure favours net filtration into the interstitial space.", "exam_trap": "Oedema can result from several mechanisms, including increased hydrostatic pressure, reduced oncotic pressure, increased permeability and lymphatic obstruction.", "takeaway": "Low plasma albumin → lower oncotic pull → increased filtration.", "source": "[GH14]."},
  {"id": "MAK-082", "subject": "Cardiorespiratory physiology", "topic": "cardiac output", "title": "Physiology: cardiac output", "stem": "A patient's heart rate is 75 beats/minute and stroke volume is 80 mL. What is the approximate cardiac output?", "options": {"A": "0.6 L/min", "B": "2.0 L/min", "C": "4.0 L/min", "D": "6.0 L/min", "E": "12.0 L/min"}, "correct_letter": "D", "correct_answer": "D. 6.0 L/min", "why_correct": "Cardiac output = heart rate × stroke volume. 75 × 80 mL = 6000 mL/min = 6 L/min.", "exam_trap": "Do not confuse stroke volume with cardiac output.", "takeaway": "CO = HR × SV.", "source": "[GH14]."},
  {"id": "MAK-083", "subject": "Cardiorespiratory physiology", "topic": "preload", "title": "Physiology: preload", "stem": "Which factor most directly reflects ventricular preload?", "options": {"A": "End-diastolic ventricular volume", "B": "End-systolic ventricular volume only", "C": "Systemic vascular resistance only", "D": "Arterial oxygen saturation", "E": "Respiratory rate"}, "correct_letter": "A", "correct_answer": "A. End-diastolic ventricular volume", "why_correct": "Preload is related to myocardial fibre stretch at the end of diastole and is commonly represented clinically by ventricular end-diastolic volume or pressure.", "exam_trap": "Afterload relates to the resistance against which the ventricle ejects blood.", "takeaway": "Preload = ventricular filling/stretch before contraction.", "source": "[GH14]."},
  {"id": "MAK-084", "subject": "Cardiorespiratory physiology", "topic": "afterload", "title": "Physiology: afterload", "stem": "Which factor is most closely related to left ventricular afterload?", "options": {"A": "Venous return", "B": "Systemic vascular resistance", "C": "End-diastolic volume alone", "D": "Plasma albumin", "E": "Respiratory rate"}, "correct_letter": "B", "correct_answer": "B. Systemic vascular resistance", "why_correct": "Left ventricular afterload represents the load against which the ventricle ejects blood and is strongly related to arterial pressure and systemic vascular resistance.", "exam_trap": "Preload is related to ventricular filling; afterload is related to resistance to ejection.", "takeaway": "Preload = filling. Afterload = resistance to ejection.", "source": "[GH14]."},
  {"id": "MAK-085", "subject": "Cardiorespiratory physiology", "topic": "Fick principle", "title": "Physiology: Fick principle", "stem": "A physiological measurement uses oxygen consumption and the arterial-venous oxygen content difference to determine cardiac output. Which principle is being used?", "options": {"A": "Laplace law", "B": "Fick principle", "C": "Boyle law", "D": "Poiseuille law", "E": "Frank-Starling law"}, "correct_letter": "B", "correct_answer": "B. Fick principle", "why_correct": "The Fick principle can be used to calculate cardiac output from oxygen consumption divided by the arterial-venous oxygen content difference.", "exam_trap": "", "takeaway": "Fick cardiac output = oxygen consumption ÷ A–V oxygen difference.", "source": "[GH14]."},
  {"id": "MAK-086", "subject": "Cardiorespiratory physiology", "topic": "respiratory dead space", "title": "Physiology: respiratory dead space", "stem": "Which situation would increase physiological dead space?", "options": {"A": "Increased perfusion of well-ventilated alveoli", "B": "Pulmonary embolism", "C": "Complete airway obstruction with no ventilation", "D": "Increased pulmonary capillary recruitment", "E": "Increased effective gas exchange"}, "correct_letter": "B", "correct_answer": "B. Pulmonary embolism", "why_correct": "A pulmonary embolus can produce ventilated alveoli that are inadequately perfused, increasing alveolar dead space and therefore physiological dead space.", "exam_trap": "Dead space represents ventilation that does not participate effectively in gas exchange.", "takeaway": "Ventilation without adequate perfusion = dead space.", "source": "[GH14]."},
  {"id": "MAK-087", "subject": "Cardiorespiratory physiology", "topic": "oxygen delivery", "title": "Physiology: oxygen delivery", "stem": "Which factor contributes directly to arterial oxygen content?", "options": {"A": "Haemoglobin concentration", "B": "Serum sodium concentration", "C": "Plasma potassium concentration", "D": "Platelet count", "E": "Serum bilirubin concentration"}, "correct_letter": "A", "correct_answer": "A. Haemoglobin concentration", "why_correct": "Most oxygen in arterial blood is carried bound to haemoglobin, with a smaller amount dissolved in plasma. Therefore haemoglobin concentration is a major determinant of oxygen content.", "exam_trap": "A normal oxygen saturation does not guarantee normal oxygen content if haemoglobin concentration is substantially reduced.", "takeaway": "Oxygen delivery depends on oxygen content as well as cardiac output.", "source": "[GH14]."},
  {"id": "MAK-088", "subject": "Major trauma & fluids", "topic": "CT", "title": "Imaging: CT", "stem": "A patient with suspected intra-abdominal trauma requires rapid cross-sectional imaging. Which imaging modality is generally best suited to rapidly demonstrate many forms of acute traumatic injury in a haemodynamically appropriate patient?", "options": {"A": "Plain radiograph only", "B": "CT", "C": "Ultrasound only", "D": "MRI", "E": "Nuclear medicine bone scan"}, "correct_letter": "B", "correct_answer": "B. CT", "why_correct": "CT provides rapid cross-sectional imaging and is widely used in the assessment of significant trauma when the patient is sufficiently stable for CT.", "exam_trap": "Imaging choice depends on the clinical situation. An unstable patient may require immediate intervention rather than transfer for CT.", "takeaway": "Stable major trauma + need for detailed rapid cross-sectional assessment = CT is often central.", "source": "Imaging principles — Intercollegiate MRCS syllabus; RCS England MRCS preparation resources."},
  {"id": "MAK-089", "subject": "Perioperative medicine & nutrition", "topic": "ultrasound", "title": "Imaging: ultrasound", "stem": "Which characteristic makes ultrasound particularly useful for repeated assessment of soft tissues and fluid collections?", "options": {"A": "It uses ionising radiation", "B": "It requires general anaesthesia", "C": "It uses sound waves rather than ionising radiation", "D": "It cannot demonstrate fluid", "E": "It always provides better bone imaging than CT"}, "correct_letter": "C", "correct_answer": "C. It uses sound waves rather than ionising radiation", "why_correct": "Ultrasound uses high-frequency sound waves and does not expose the patient to ionising radiation. It is particularly useful for fluid-filled structures, vascular assessment with Doppler and many superficial structures.", "exam_trap": "Ultrasound is operator-dependent and can be limited by bowel gas, obesity and anatomical depth.", "takeaway": "Ultrasound = no ionising radiation + real-time imaging + Doppler capability.", "source": "Applied imaging — Intercollegiate MRCS syllabus; RCS England MRCS preparation resources."},
  {"id": "MAK-090", "subject": "Perioperative medicine & nutrition", "topic": "MRI", "title": "Imaging: MRI", "stem": "A patient requires detailed imaging of a soft-tissue structure where excellent tissue contrast is important and there is no immediate need for rapid CT imaging. Which modality is particularly suited to this purpose?", "options": {"A": "MRI", "B": "Plain radiograph", "C": "Fluoroscopy only", "D": "Mammography only", "E": "DEXA"}, "correct_letter": "A", "correct_answer": "A. MRI", "why_correct": "MRI provides excellent soft-tissue contrast and uses magnetic fields and radiofrequency energy rather than ionising radiation.", "exam_trap": "MRI can be unsuitable or require special precautions in some patients with implanted devices or metallic foreign bodies, depending on the device and circumstances.", "takeaway": "MRI = excellent soft-tissue contrast + no ionising radiation.", "source": "Applied imaging — Intercollegiate MRCS syllabus; RCS England MRCS preparation resources."},
  {"id": "MAK-091", "subject": "Major trauma & fluids", "topic": "Hypovolaemic shock", "title": "Hypovolaemic shock", "stem": "A patient develops significant blood loss during emergency abdominal surgery. Which physiological response occurs early in hypovolaemic shock?", "options": {"A": "Increased vagal activity", "B": "Reduced sympathetic activity", "C": "Increased heart rate", "D": "Increased renal blood flow", "E": "Reduced systemic vascular resistance"}, "correct_letter": "C", "correct_answer": "C. Increased heart rate", "why_correct": "Acute reduction in circulating volume reduces venous return and cardiac output. Baroreceptor-mediated sympathetic activation produces tachycardia, increased myocardial contractility and peripheral vasoconstriction.", "exam_trap": "A patient may initially maintain a relatively normal blood pressure despite significant blood loss because of compensatory vasoconstriction.", "takeaway": "Early haemorrhage → sympathetic activation → tachycardia + vasoconstriction.", "source": "[GH14]."},
  {"id": "MAK-092", "subject": "Major trauma & fluids", "topic": "Shock and systemic vascular resistance", "title": "Shock and systemic vascular resistance", "stem": "Which haemodynamic change is characteristic of early hypovolaemic shock?", "options": {"A": "Reduced systemic vascular resistance", "B": "Increased systemic vascular resistance", "C": "Increased circulating volume", "D": "Increased venous return", "E": "Increased stroke volume"}, "correct_letter": "B", "correct_answer": "B. Increased systemic vascular resistance", "why_correct": "Sympathetic activation causes peripheral vasoconstriction, increasing systemic vascular resistance and helping preserve perfusion of vital organs.", "exam_trap": "Do not assume that all forms of shock have the same vascular response. Distributive shock, particularly early septic shock, may have reduced systemic vascular resistance.", "takeaway": "Hypovolaemia → vasoconstriction. Early distributive shock → vasodilation can predominate.", "source": "[GH14]."},
  {"id": "MAK-093", "subject": "Cardiorespiratory physiology", "topic": "Oxygen delivery", "title": "Oxygen delivery", "stem": "A patient has a normal arterial oxygen saturation but severe anaemia. Why can tissue oxygen delivery nevertheless be impaired?", "options": {"A": "Oxygen saturation is unrelated to haemoglobin", "B": "Most arterial oxygen is carried dissolved in plasma", "C": "Reduced haemoglobin reduces arterial oxygen content", "D": "Anaemia increases arterial oxygen content", "E": "Anaemia always increases cardiac output sufficiently to normalise oxygen delivery"}, "correct_letter": "C", "correct_answer": "C. Reduced haemoglobin reduces arterial oxygen content", "why_correct": "Most oxygen in arterial blood is carried bound to haemoglobin. Therefore a major reduction in haemoglobin concentration reduces arterial oxygen content even when oxygen saturation is normal.", "exam_trap": "SpO₂ measures haemoglobin saturation, not total oxygen content.", "takeaway": "Normal SpO₂ ≠ normal oxygen content.", "source": "[GH14]."},
  {"id": "MAK-094", "subject": "Major trauma & fluids", "topic": "Oxygen extraction", "title": "Oxygen extraction", "stem": "During severe circulatory shock, tissues extract a greater proportion of delivered oxygen. Which change would be expected in mixed venous oxygen content?", "options": {"A": "Increased mixed venous oxygen content", "B": "Reduced mixed venous oxygen content", "C": "No change under any circumstances", "D": "Complete absence of oxygen", "E": "Increased arterial carbon dioxide only"}, "correct_letter": "B", "correct_answer": "B. Reduced mixed venous oxygen content", "why_correct": "When tissue oxygen extraction increases, less oxygen remains in venous blood.", "exam_trap": "", "takeaway": "Increased tissue extraction → lower venous oxygen content.", "source": "[GH14]."},
  {"id": "MAK-095", "subject": "Major trauma & fluids", "topic": "Lactate", "title": "Lactate", "stem": "A patient with severe circulatory failure develops a rising serum lactate concentration. What does lactate most directly indicate in this context?", "options": {"A": "Guaranteed bacterial infection", "B": "A marker that may reflect impaired cellular oxygen utilisation or delivery", "C": "Isolated liver disease", "D": "Increased renal clearance", "E": "Increased tissue oxygenation"}, "correct_letter": "B", "correct_answer": "B. A marker that may reflect impaired cellular oxygen utilisation or delivery", "why_correct": "Lactate can rise when tissue oxygen delivery is inadequate, but it is not specific for hypoxia. Increased adrenergic stimulation and impaired clearance, among other mechanisms, can also contribute.", "exam_trap": "Lactate is not synonymous with sepsis and should not be interpreted in isolation.", "takeaway": "High lactate = physiological warning signal, not a diagnosis.", "source": "[GH14]."},
  {"id": "MAK-096", "subject": "Perioperative medicine & nutrition", "topic": "Fluid compartments", "title": "Fluid compartments", "stem": "Approximately which proportion of total body water is intracellular in a healthy adult?", "options": {"A": "10%", "B": "25%", "C": "40%", "D": "65%", "E": "90%"}, "correct_letter": "D", "correct_answer": "D. 65%", "why_correct": "Approximately two-thirds of total body water is intracellular, with approximately one-third extracellular.", "exam_trap": "", "takeaway": "Total body water → roughly 2/3 intracellular, 1/3 extracellular.", "source": "[GH14]."},
  {"id": "MAK-097", "subject": "Perioperative medicine & nutrition", "topic": "Sodium and extracellular fluid", "title": "Sodium and extracellular fluid", "stem": "Which electrolyte is the major determinant of extracellular fluid osmolality?", "options": {"A": "Potassium", "B": "Sodium", "C": "Magnesium", "D": "Phosphate", "E": "Calcium"}, "correct_letter": "B", "correct_answer": "B. Sodium", "why_correct": "Sodium and its accompanying anions constitute the major effective osmoles in extracellular fluid and are important determinants of extracellular fluid volume.", "exam_trap": "Potassium is the major intracellular cation.", "takeaway": "Na⁺ = major extracellular cation. K⁺ = major intracellular cation.", "source": "[GH14]."},
  {"id": "MAK-098", "subject": "Perioperative medicine & nutrition", "topic": "Potassium distribution", "title": "Potassium distribution", "stem": "Which hormone promotes movement of potassium into cells?", "options": {"A": "Aldosterone only", "B": "Insulin", "C": "Parathyroid hormone", "D": "Cortisol only", "E": "Glucagon only"}, "correct_letter": "B", "correct_answer": "B. Insulin", "why_correct": "Insulin promotes cellular uptake of potassium, partly through stimulation of Na⁺/K⁺-ATPase activity. Beta-2 adrenergic stimulation also promotes intracellular potassium shift.", "exam_trap": "This is one reason insulin is used as part of emergency treatment for significant hyperkalaemia.", "takeaway": "Insulin shifts K⁺ into cells.", "source": "[GH14]."},
  {"id": "MAK-099", "subject": "Perioperative medicine & nutrition", "topic": "Acid–base physiology", "title": "Acid–base physiology", "stem": "A patient has the following arterial blood gas: pH 7.25 PaCO₂ elevated HCO₃⁻ initially near normal Which primary disturbance is most likely?", "options": {"A": "Respiratory acidosis", "B": "Respiratory alkalosis", "C": "Metabolic acidosis", "D": "Metabolic alkalosis", "E": "Mixed metabolic alkalosis and respiratory alkalosis"}, "correct_letter": "A", "correct_answer": "A. Respiratory acidosis", "why_correct": "A raised PaCO₂ with acidemia indicates a primary respiratory acidosis when no other information suggests an alternative primary process.", "exam_trap": "", "takeaway": "pH down + CO₂ up → respiratory acidosis.", "source": "[GH14]."},
  {"id": "MAK-100", "subject": "GI physiology & metabolism", "topic": "Metabolic acidosis", "title": "Metabolic acidosis", "stem": "A patient with severe diarrhoea develops a metabolic acidosis. Which mechanism best explains this?", "options": {"A": "Excessive gastric acid loss", "B": "Bicarbonate loss from the gastrointestinal tract", "C": "Increased bicarbonate retention", "D": "Reduced hydrogen ion production", "E": "Primary respiratory hypoventilation"}, "correct_letter": "B", "correct_answer": "B. Bicarbonate loss from the gastrointestinal tract", "why_correct": "Significant gastrointestinal bicarbonate loss can produce a metabolic acidosis.", "exam_trap": "Vomiting classically causes loss of gastric acid and tends toward metabolic alkalosis.", "takeaway": "Diarrhoea → bicarbonate loss → metabolic acidosis. Vomiting → acid loss → metabolic alkalosis.", "source": "[GH14]."},
  {"id": "MAK-101", "subject": "Perioperative medicine & nutrition", "topic": "Anion gap", "title": "Anion gap", "stem": "Which calculation is commonly used to estimate the serum anion gap?", "options": {"A": "Na⁺ + Cl⁻ − HCO₃⁻", "B": "Na⁺ − (Cl⁻ + HCO₃⁻)", "C": "K⁺ − Na⁺", "D": "HCO₃⁻ − Cl⁻", "E": "Na⁺ + HCO₃⁻"}, "correct_letter": "B", "correct_answer": "B. Na⁺ − (Cl⁻ + HCO₃⁻)", "why_correct": "The commonly used clinical calculation is: Anion gap = Na⁺ − (Cl⁻ + HCO₃⁻) Potassium is generally omitted from the standard calculation.", "exam_trap": "", "takeaway": "AG = Na − (Cl + HCO₃).", "source": "[GH14]."},
  {"id": "MAK-102", "subject": "Perioperative medicine & nutrition", "topic": "Respiratory compensation", "title": "Respiratory compensation", "stem": "A patient develops an acute metabolic acidosis. What is the immediate physiological respiratory response?", "options": {"A": "Hypoventilation", "B": "Hyperventilation", "C": "Apnoea", "D": "Reduced respiratory drive", "E": "Reduced alveolar ventilation with CO₂ retention"}, "correct_letter": "B", "correct_answer": "B. Hyperventilation", "why_correct": "The respiratory system can compensate rapidly for metabolic acidosis by increasing alveolar ventilation and reducing PaCO₂.", "exam_trap": "", "takeaway": "Metabolic acidosis → respiratory compensation → CO₂ falls.", "source": "[GH14]."},
  {"id": "MAK-103", "subject": "Perioperative medicine & nutrition", "topic": "Renal response to acidosis", "title": "Renal response to acidosis", "stem": "Which renal response helps compensate for a sustained metabolic acidosis?", "options": {"A": "Increased bicarbonate loss", "B": "Reduced hydrogen ion secretion", "C": "Increased hydrogen ion excretion", "D": "Reduced ammonium production", "E": "Complete cessation of bicarbonate reclamation"}, "correct_letter": "C", "correct_answer": "C. Increased hydrogen ion excretion", "why_correct": "The kidneys contribute to acid–base regulation through hydrogen ion excretion, ammonium handling and generation/reabsorption of bicarbonate.", "exam_trap": "", "takeaway": "Lungs = rapid compensation. Kidneys = slower but sustained acid–base regulation.", "source": "[GH14]."},
  {"id": "MAK-104", "subject": "Perioperative medicine & nutrition", "topic": "Acute kidney injury", "title": "Acute kidney injury", "stem": "Which change is most consistent with reduced glomerular filtration rate?", "options": {"A": "Reduced serum creatinine", "B": "Rising serum creatinine", "C": "Increased creatinine clearance", "D": "Increased urine production in every case", "E": "Reduced blood urea concentration in every case"}, "correct_letter": "B", "correct_answer": "B. Rising serum creatinine", "why_correct": "A fall in GFR reduces renal clearance of creatinine, causing serum creatinine to rise.", "exam_trap": "Serum creatinine is an imperfect marker and may change relatively late in acute kidney injury.", "takeaway": "Reduced GFR → reduced creatinine clearance → rising serum creatinine.", "source": "[GH14]."},
  {"id": "MAK-105", "subject": "Perioperative medicine & nutrition", "topic": "Renin–angiotensin–aldosterone system", "title": "Renin–angiotensin–aldosterone system", "stem": "Reduced renal perfusion activates the renin–angiotensin–aldosterone system. Which effect is associated with aldosterone?", "options": {"A": "Increased sodium excretion", "B": "Increased potassium excretion", "C": "Reduced sodium reabsorption", "D": "Reduced extracellular fluid volume", "E": "Reduced hydrogen ion secretion"}, "correct_letter": "B", "correct_answer": "B. Increased potassium excretion", "why_correct": "Aldosterone promotes sodium reabsorption and potassium secretion in the distal nephron and collecting duct.", "exam_trap": "", "takeaway": "Aldosterone retains Na⁺ and promotes K⁺ secretion.", "source": "[GH14]."},
  {"id": "MAK-106", "subject": "Pathology: inflammation & wound healing", "topic": "Inflammation", "title": "Inflammation", "stem": "Which leukocyte is typically prominent during the early phase of acute inflammation?", "options": {"A": "Neutrophil", "B": "Plasma cell", "C": "Eosinophil only", "D": "Memory B cell", "E": "Fibroblast"}, "correct_letter": "A", "correct_answer": "A. Neutrophil", "why_correct": "Neutrophils are important early cellular participants in acute inflammation. Monocytes/macrophages become increasingly important as the inflammatory response evolves.", "exam_trap": "Do not confuse the typical cellular pattern of acute inflammation with chronic inflammation.", "takeaway": "Acute inflammation → neutrophils early. Chronic inflammation → macrophages/lymphocytes and tissue remodelling.", "source": "[RBP10]."},
  {"id": "MAK-107", "subject": "Pathology: inflammation & wound healing", "topic": "Chronic inflammation", "title": "Chronic inflammation", "stem": "Which cell type is particularly important in chronic inflammation?", "options": {"A": "Neutrophil only", "B": "Macrophage", "C": "Platelet only", "D": "Erythrocyte", "E": "Megakaryocyte"}, "correct_letter": "B", "correct_answer": "B. Macrophage", "why_correct": "Macrophages are major effector and regulatory cells in chronic inflammation and contribute to tissue injury, repair and fibrosis.", "exam_trap": "", "takeaway": "Macrophage = central cell of chronic inflammation.", "source": "[RBP10]."},
  {"id": "MAK-108", "subject": "Pathology: inflammation & wound healing", "topic": "vascular permeability", "title": "Acute inflammation: vascular permeability", "stem": "Which mediator is strongly associated with increased vascular permeability during acute inflammation?", "options": {"A": "Histamine", "B": "Haemoglobin", "C": "Albumin", "D": "Insulin", "E": "Erythropoietin"}, "correct_letter": "A", "correct_answer": "A. Histamine", "why_correct": "Histamine released from mast cells and other cells contributes to vasodilation and increased vascular permeability during acute inflammatory responses.", "exam_trap": "", "takeaway": "Histamine → vasodilation + increased vascular permeability.", "source": "[RBP10]."},
  {"id": "MAK-109", "subject": "Pathology: inflammation & wound healing", "topic": "proliferative phase", "title": "Wound healing: proliferative phase", "stem": "Which cell is particularly important for collagen production during the proliferative phase of wound healing?", "options": {"A": "Fibroblast", "B": "Neutrophil", "C": "Platelet only", "D": "Erythrocyte", "E": "Osteoclast"}, "correct_letter": "A", "correct_answer": "A. Fibroblast", "why_correct": "Fibroblasts migrate into the wound and synthesise extracellular matrix components, including collagen, during the proliferative phase.", "exam_trap": "", "takeaway": "Fibroblast = collagen production and extracellular matrix formation.", "source": "[RBP10]."},
  {"id": "MAK-110", "subject": "Pathology: inflammation & wound healing", "topic": "tensile strength", "title": "Wound healing: tensile strength", "stem": "Which process is primarily responsible for the increasing tensile strength of a healing wound over time?", "options": {"A": "Immediate vasoconstriction", "B": "Collagen remodelling", "C": "Red-cell production", "D": "Neutrophil apoptosis alone", "E": "Platelet aggregation alone"}, "correct_letter": "B", "correct_answer": "B. Collagen remodelling", "why_correct": "Collagen deposition is followed by maturation and remodelling of the extracellular matrix. Wound strength increases over time but does not simply return immediately to the strength of uninjured tissue.", "exam_trap": "", "takeaway": "Healing is not complete when the wound closes.", "source": "[RBP10]."},
  {"id": "MAK-111", "subject": "Pathology: inflammation & wound healing", "topic": "Collagen", "title": "Collagen", "stem": "Which vitamin is particularly important for normal collagen synthesis?", "options": {"A": "Vitamin A", "B": "Vitamin B12", "C": "Vitamin C", "D": "Vitamin D", "E": "Vitamin K"}, "correct_letter": "C", "correct_answer": "C. Vitamin C", "why_correct": "Vitamin C is required for hydroxylation reactions involved in collagen synthesis. Deficiency impairs collagen formation and wound healing.", "exam_trap": "", "takeaway": "Vitamin C deficiency → impaired collagen synthesis → impaired wound healing.", "source": "[RBP10]."},
  {"id": "MAK-112", "subject": "Pathology: inflammation & wound healing", "topic": "Wound healing and diabetes", "title": "Wound healing and diabetes", "stem": "Which mechanism contributes to impaired wound healing in poorly controlled diabetes?", "options": {"A": "Enhanced leukocyte function in every patient", "B": "Improved microvascular perfusion", "C": "Impaired immune function and microvascular disease", "D": "Increased collagen deposition in all wounds", "E": "Accelerated epithelialisation"}, "correct_letter": "C", "correct_answer": "C. Impaired immune function and microvascular disease", "why_correct": "Diabetes can impair host defence, microvascular perfusion and several aspects of tissue repair, increasing the risk of infection and delayed healing.", "exam_trap": "", "takeaway": "Diabetes can impair healing through multiple mechanisms, not simply hyperglycaemia alone.", "source": "[RBP10]."},
  {"id": "MAK-113", "subject": "Pathology: oncology & haematology", "topic": "Virchow triad", "title": "Thrombosis: Virchow triad", "stem": "Which combination represents Virchow's triad?", "options": {"A": "Hypertension, anaemia and fever", "B": "Stasis, endothelial injury and hypercoagulability", "C": "Hypoxia, acidosis and hyperthermia", "D": "Infection, haemolysis and thrombocytopenia", "E": "Vasodilation, hypovolaemia and anaemia"}, "correct_letter": "B", "correct_answer": "B. Stasis, endothelial injury and hypercoagulability", "why_correct": "Virchow's triad describes the three major contributors to thrombosis: • abnormal blood flow/stasis • endothelial injury • hypercoagulability.", "exam_trap": "", "takeaway": "Think: flow + vessel wall + blood tendency.", "source": "[RBP10]."},
  {"id": "MAK-114", "subject": "Vascular & fracture complications", "topic": "Venous thromboembolism", "title": "Venous thromboembolism", "stem": "A patient presents with suspected DVT. Which clinical scoring system is recommended by NICE for estimating the clinical probability of DVT?", "options": {"A": "CHA₂DS₂-VASc", "B": "Wells score", "C": "CURB-65", "D": "Glasgow Coma Scale", "E": "APACHE II"}, "correct_letter": "B", "correct_answer": "B. Wells score", "why_correct": "NICE recommends the 2-level DVT Wells score when DVT is suspected. A score of 2 or more is classified as DVT likely; 1 or less is DVT unlikely.", "exam_trap": "", "takeaway": "Suspected DVT → 2-level DVT Wells score.", "source": "NICE NG158."},
  {"id": "MAK-115", "subject": "Vascular & fracture complications", "topic": "Pulmonary embolism", "title": "Pulmonary embolism", "stem": "A patient has a suspected pulmonary embolism and a PE Wells score of 6. What does this score indicate under the NICE two-level Wells approach?", "options": {"A": "PE unlikely", "B": "PE likely", "C": "PE excluded", "D": "DVT excluded", "E": "No further assessment is required"}, "correct_letter": "B", "correct_answer": "B. PE likely", "why_correct": "Under the NICE two-level PE Wells pathway, a score greater than 4 indicates PE is likely. NICE recommends immediate CTPA where possible for PE-likely patients, with alternatives in specified circumstances.", "exam_trap": "Do not confuse the two-level PE threshold with the DVT threshold.", "takeaway": "PE Wells >4 = PE likely.", "source": "NICE NG158; recommendations 1.1.17 onward."},
  {"id": "MAK-116", "subject": "Pathology: oncology & haematology", "topic": "platelets", "title": "Haemostasis: platelets", "stem": "Which event occurs early after vascular endothelial injury and contributes to primary haemostasis?", "options": {"A": "Platelet adhesion", "B": "Fibrinolysis only", "C": "Red-cell aggregation", "D": "Plasminogen activation only", "E": "Albumin synthesis"}, "correct_letter": "A", "correct_answer": "A. Platelet adhesion", "why_correct": "Primary haemostasis begins with platelet adhesion to the injured vascular surface, followed by platelet activation and aggregation.", "exam_trap": "", "takeaway": "Primary haemostasis = platelet plug. Secondary haemostasis = fibrin stabilisation.", "source": "[GH14]."},
  {"id": "MAK-117", "subject": "Pathology: oncology & haematology", "topic": "Coagulation", "title": "Coagulation", "stem": "What is the principal role of thrombin in coagulation?", "options": {"A": "Breakdown of fibrin", "B": "Conversion of fibrinogen to fibrin", "C": "Inhibition of platelet activation only", "D": "Conversion of haemoglobin to bilirubin", "E": "Destruction of red cells"}, "correct_letter": "B", "correct_answer": "B. Conversion of fibrinogen to fibrin", "why_correct": "Thrombin converts soluble fibrinogen into insoluble fibrin, which contributes to stabilisation of the platelet plug. Thrombin also has multiple regulatory and cellular effects within haemostasis.", "exam_trap": "", "takeaway": "Thrombin → fibrinogen → fibrin.", "source": "[GH14]."},
  {"id": "MAK-118", "subject": "Pathology: oncology & haematology", "topic": "Fibrinolysis", "title": "Fibrinolysis", "stem": "Which enzyme directly degrades fibrin during fibrinolysis?", "options": {"A": "Thrombin", "B": "Plasmin", "C": "Factor VIII", "D": "Fibrinogen", "E": "Protein C"}, "correct_letter": "B", "correct_answer": "B. Plasmin", "why_correct": "Plasmin is generated from plasminogen and degrades fibrin within thrombi.", "exam_trap": "Thrombin promotes fibrin formation; plasmin participates in fibrin breakdown.", "takeaway": "Thrombin builds fibrin. Plasmin breaks fibrin down.", "source": "[GH14]."},
  {"id": "MAK-119", "subject": "Pathology: oncology & haematology", "topic": "metastasis", "title": "Neoplasia: metastasis", "stem": "Which feature distinguishes a malignant neoplasm from a benign neoplasm most reliably?", "options": {"A": "It is always large", "B": "It is always painful", "C": "It can invade surrounding tissue and metastasise", "D": "It always grows rapidly", "E": "It always causes systemic symptoms"}, "correct_letter": "C", "correct_answer": "C. It can invade surrounding tissue and metastasise", "why_correct": "Malignant tumours characteristically have the capacity for local invasion and/or metastatic spread. Size, growth rate and symptoms are variable and cannot alone establish malignancy.", "exam_trap": "A large tumour is not automatically malignant, and some malignant tumours can initially be small and asymptomatic.", "takeaway": "Malignancy = biological capacity for invasion and metastatic spread.", "source": "[RBP10]."},
  {"id": "MAK-120", "subject": "Pathology: oncology & haematology", "topic": "Tumour grading versus staging", "title": "Tumour grading versus staging", "stem": "Which statement best describes tumour staging?", "options": {"A": "It describes only microscopic differentiation", "B": "It describes the extent of disease", "C": "It describes only the tumour's cellular appearance", "D": "It is synonymous with histological grade", "E": "It is determined solely by symptoms"}, "correct_letter": "B", "correct_answer": "B. It describes the extent of disease", "why_correct": "Staging describes the anatomical extent of a malignancy, including features such as local invasion and metastatic disease. Grading describes histological characteristics such as differentiation and, depending on the tumour, proliferative/aggressive features.", "exam_trap": "Stage and grade are not interchangeable.", "takeaway": "STAGE = where/how far. GRADE = what it looks like biologically under the microscope.", "source": "[RBP10]."},
  {"id": "MAK-121", "subject": "Pharmacology", "topic": "half-life", "title": "Pharmacokinetics: half-life", "stem": "A drug has a long elimination half-life. Which consequence is most likely when repeated doses are given at regular intervals?", "options": {"A": "It reaches steady state immediately", "B": "It generally takes longer to approach steady state", "C": "It cannot accumulate", "D": "It is always eliminated by the lungs", "E": "Its volume of distribution must be zero"}, "correct_letter": "B", "correct_answer": "B. It generally takes longer to approach steady state", "why_correct": "For many drugs administered repeatedly, the time required to approach steady state depends principally on the elimination half-life.", "exam_trap": "A loading dose can be used when rapid attainment of a target concentration is required for an appropriate drug.", "takeaway": "Long half-life → slow approach to steady state.", "source": "[RD9]."},
  {"id": "MAK-122", "subject": "Pharmacology", "topic": "Loading dose", "title": "Loading dose", "stem": "A drug needs to achieve a therapeutic plasma concentration rapidly. Which pharmacokinetic principle is most relevant to determining the loading dose?", "options": {"A": "Volume of distribution", "B": "Platelet count", "C": "Renal blood flow only", "D": "Drug colour", "E": "Respiratory rate"}, "correct_letter": "A", "correct_answer": "A. Volume of distribution", "why_correct": "Loading dose is related to the desired concentration and the apparent volume of distribution, together with bioavailability where relevant.", "exam_trap": "", "takeaway": "Loading dose is about getting to the target concentration quickly.", "source": "[RD9]."},
  {"id": "MAK-123", "subject": "Pharmacology", "topic": "Renal drug clearance", "title": "Renal drug clearance", "stem": "A patient with significant renal impairment is prescribed a drug that is predominantly eliminated unchanged by the kidneys. What is the most important prescribing consideration?", "options": {"A": "Renal impairment can increase drug exposure", "B": "Renal impairment always makes the drug ineffective", "C": "Renal impairment always increases drug clearance", "D": "Dose adjustment can never be necessary", "E": "The drug automatically becomes hepatically eliminated"}, "correct_letter": "A", "correct_answer": "A. Renal impairment can increase drug exposure", "why_correct": "Reduced renal clearance can increase plasma concentrations of renally eliminated drugs, potentially increasing adverse effects. The appropriate response depends on the drug and may involve dose reduction, increased dosing interval or use of an alternative.", "exam_trap": "", "takeaway": "Before prescribing a renally cleared drug → check renal function and the relevant dosing guidance.", "source": "[RD9]."},
  {"id": "MAK-124", "subject": "Pharmacology", "topic": "Hepatic first-pass metabolism", "title": "Hepatic first-pass metabolism", "stem": "A drug is extensively metabolised during its first passage through the liver after oral administration. What is the likely consequence?", "options": {"A": "Increased oral bioavailability", "B": "Reduced oral bioavailability", "C": "Complete absence of hepatic metabolism", "D": "Guaranteed increased half-life", "E": "Elimination only through the lungs"}, "correct_letter": "B", "correct_answer": "B. Reduced oral bioavailability", "why_correct": "Extensive first-pass metabolism can substantially reduce the fraction of an orally administered drug reaching systemic circulation unchanged.", "exam_trap": "", "takeaway": "First-pass metabolism can reduce oral bioavailability.", "source": "[RD9]."},
  {"id": "MAK-125", "subject": "Pharmacology", "topic": "Opioid adverse effects", "title": "Opioid adverse effects", "stem": "Which adverse effect is particularly characteristic of opioid analgesics?", "options": {"A": "Respiratory depression", "B": "Severe hypoglycaemia in every patient", "C": "Permanent hypertension", "D": "Increased bowel motility", "E": "Bronchodilation as the universal effect"}, "correct_letter": "A", "correct_answer": "A. Respiratory depression", "why_correct": "Opioids can cause dose-dependent respiratory depression. They can also cause sedation, nausea, vomiting, constipation and other adverse effects.", "exam_trap": "", "takeaway": "Opioids: analgesia + sedation + respiratory depression + constipation.", "source": "[BNF]."},
  {"id": "MAK-126", "subject": "Pharmacology", "topic": "Opioid toxicity", "title": "Opioid toxicity", "stem": "A patient develops marked respiratory depression following opioid administration. Which drug is used as an opioid antagonist in an emergency?", "options": {"A": "Flumazenil", "B": "Naloxone", "C": "Protamine", "D": "Vitamin K", "E": "Atropine"}, "correct_letter": "B", "correct_answer": "B. Naloxone", "why_correct": "Naloxone is an opioid receptor antagonist used to reverse opioid-induced respiratory depression.", "exam_trap": "Flumazenil is associated with reversal of benzodiazepine effects, not opioid toxicity.", "takeaway": "Opioid toxicity → naloxone.", "source": "[BNF]."},
  {"id": "MAK-127", "subject": "Pharmacology", "topic": "Paracetamol toxicity", "title": "Paracetamol toxicity", "stem": "Which organ is primarily at risk following a significant paracetamol overdose?", "options": {"A": "Liver", "B": "Spleen", "C": "Thyroid", "D": "Pancreas only", "E": "Pituitary gland"}, "correct_letter": "A", "correct_answer": "A. Liver", "why_correct": "Significant paracetamol overdose can cause severe hepatic injury.", "exam_trap": "", "takeaway": "Paracetamol overdose → think hepatotoxicity.", "source": "[BNF]."},
  {"id": "MAK-128", "subject": "Pharmacology", "topic": "NSAIDs", "title": "NSAIDs", "stem": "Which adverse effect is particularly important when prescribing NSAIDs?", "options": {"A": "Increased gastrointestinal mucosal injury", "B": "Universal severe hypoglycaemia", "C": "Complete suppression of platelet production", "D": "Permanent bronchodilation", "E": "Increased bone formation"}, "correct_letter": "A", "correct_answer": "A. Increased gastrointestinal mucosal injury", "why_correct": "NSAIDs inhibit cyclo-oxygenase pathways and can increase the risk of gastrointestinal ulceration and bleeding. They can also cause renal and cardiovascular adverse effects.", "exam_trap": "The risks are not limited to the gastrointestinal tract.", "takeaway": "NSAIDs → GI + renal + cardiovascular considerations.", "source": "[BNF]."},
  {"id": "MAK-129", "subject": "Pharmacology", "topic": "Local anaesthetics", "title": "Local anaesthetics", "stem": "What is the principal mechanism of action of local anaesthetic drugs?", "options": {"A": "Blockade of voltage-gated sodium channels", "B": "Activation of opioid receptors", "C": "Blockade of calcium absorption from the gut", "D": "Activation of beta-2 receptors", "E": "Inhibition of acetylcholinesterase"}, "correct_letter": "A", "correct_answer": "A. Blockade of voltage-gated sodium channels", "why_correct": "Local anaesthetics inhibit voltage-gated sodium channels, preventing propagation of action potentials.", "exam_trap": "", "takeaway": "Local anaesthetic → Na⁺ channel blockade → failure of nerve impulse propagation.", "source": "[RD9]."},
  {"id": "MAK-130", "subject": "Pharmacology", "topic": "Local anaesthetic systemic toxicity", "title": "Local anaesthetic systemic toxicity", "stem": "A patient develops neurological and cardiovascular features shortly after receiving a large dose of local anaesthetic. What complication should be considered?", "options": {"A": "Local anaesthetic systemic toxicity", "B": "Isolated hypocalcaemia", "C": "Acute appendicitis", "D": "Thyroid storm", "E": "Pulmonary fibrosis"}, "correct_letter": "A", "correct_answer": "A. Local anaesthetic systemic toxicity", "why_correct": "Systemic absorption of excessive local anaesthetic can cause neurological and cardiovascular toxicity.", "exam_trap": "", "takeaway": "After local anaesthetic + neurological/cardiovascular deterioration → consider LAST.", "source": "[BNF]."},
  {"id": "MAK-131", "subject": "Pharmacology", "topic": "heparin", "title": "Anticoagulation: heparin", "stem": "Which anticoagulant acts by enhancing the activity of antithrombin?", "options": {"A": "Heparin", "B": "Aspirin", "C": "Clopidogrel", "D": "Tranexamic acid", "E": "Warfarin"}, "correct_letter": "A", "correct_answer": "A. Heparin", "why_correct": "Heparin potentiates antithrombin activity, producing inhibition of several activated coagulation factors.", "exam_trap": "", "takeaway": "Heparin → antithrombin potentiation.", "source": "[RD9]."},
  {"id": "MAK-132", "subject": "Pharmacology", "topic": "Warfarin", "title": "Warfarin", "stem": "Warfarin reduces synthesis of several vitamin K-dependent clotting factors. Which additional protein is also affected?", "options": {"A": "Protein C", "B": "Haemoglobin", "C": "Albumin", "D": "Fibrinogen", "E": "von Willebrand factor"}, "correct_letter": "A", "correct_answer": "A. Protein C", "why_correct": "Vitamin K is required for synthesis of factors II, VII, IX and X, as well as the anticoagulant proteins C and S.", "exam_trap": "", "takeaway": "Warfarin affects both procoagulant and anticoagulant vitamin-K-dependent proteins.", "source": "[RD9]."},
  {"id": "MAK-133", "subject": "Pharmacology", "topic": "Antiplatelet therapy", "title": "Antiplatelet therapy", "stem": "Aspirin reduces platelet aggregation primarily by inhibiting which enzyme?", "options": {"A": "Cyclo-oxygenase", "B": "Acetylcholinesterase", "C": "Carbonic anhydrase", "D": "Na⁺/K⁺-ATPase", "E": "Xanthine oxidase"}, "correct_letter": "A", "correct_answer": "A. Cyclo-oxygenase", "why_correct": "Aspirin irreversibly inhibits cyclo-oxygenase in platelets, reducing thromboxane A₂ synthesis and therefore platelet activation/aggregation.", "exam_trap": "", "takeaway": "Aspirin → irreversible COX inhibition → ↓ TXA₂ → ↓ platelet aggregation.", "source": "[RD9]."},
  {"id": "MAK-134", "subject": "Pharmacology", "topic": "Tranexamic acid", "title": "Tranexamic acid", "stem": "Which statement best describes tranexamic acid?", "options": {"A": "It promotes fibrinolysis", "B": "It inhibits fibrinolysis", "C": "It directly activates thrombin", "D": "It destroys platelets", "E": "It blocks vitamin K absorption"}, "correct_letter": "B", "correct_answer": "B. It inhibits fibrinolysis", "why_correct": "Tranexamic acid is an antifibrinolytic agent. It inhibits plasminogen activation/plasmin-mediated fibrin breakdown.", "exam_trap": "", "takeaway": "Tranexamic acid = antifibrinolytic.", "source": "[RD9]."},
  {"id": "MAK-135", "subject": "Microbiology & surgical infection", "topic": "beta-lactams", "title": "Antibiotic mechanism: beta-lactams", "stem": "Beta-lactam antibiotics primarily interfere with which bacterial process?", "options": {"A": "Cell-wall synthesis", "B": "Human DNA replication", "C": "Human mitochondrial respiration", "D": "Bacterial folate absorption only", "E": "Viral capsid formation"}, "correct_letter": "A", "correct_answer": "A. Cell-wall synthesis", "why_correct": "Beta-lactam antibiotics inhibit bacterial cell-wall synthesis by binding penicillin-binding proteins.", "exam_trap": "", "takeaway": "Beta-lactam → bacterial cell wall.", "source": "[RD9]."},
  {"id": "MAK-136", "subject": "Microbiology & surgical infection", "topic": "Aminoglycosides", "title": "Aminoglycosides", "stem": "Which adverse effect is particularly important with aminoglycosides?", "options": {"A": "Nephrotoxicity", "B": "Severe hyperglycaemia in every patient", "C": "Permanent neutrophilia", "D": "Gastric ulcer healing", "E": "Hyperthyroidism"}, "correct_letter": "A", "correct_answer": "A. Nephrotoxicity", "why_correct": "Aminoglycosides can cause nephrotoxicity and ototoxicity. Their use therefore requires appropriate prescribing and monitoring according to the drug and clinical setting.", "exam_trap": "", "takeaway": "Aminoglycosides → kidneys + ears.", "source": "[BNF]."},
  {"id": "MAK-137", "subject": "Microbiology & surgical infection", "topic": "Macrolides", "title": "Macrolides", "stem": "Macrolide antibiotics primarily inhibit bacterial protein synthesis by acting on which ribosomal subunit?", "options": {"A": "10S", "B": "20S", "C": "30S", "D": "50S", "E": "80S"}, "correct_letter": "D", "correct_answer": "D. 50S", "why_correct": "Macrolides bind to the bacterial 50S ribosomal subunit and inhibit protein synthesis.", "exam_trap": "Aminoglycosides and tetracyclines are associated with the 30S subunit.", "takeaway": "Macrolides → 50S.", "source": "[RD9]."},
  {"id": "MAK-138", "subject": "Microbiology & surgical infection", "topic": "Tetracyclines", "title": "Tetracyclines", "stem": "Tetracycline antibiotics act primarily at which bacterial ribosomal subunit?", "options": {"A": "10S", "B": "20S", "C": "30S", "D": "50S", "E": "80S"}, "correct_letter": "C", "correct_answer": "C. 30S", "why_correct": "Tetracyclines inhibit bacterial protein synthesis by binding the 30S ribosomal subunit.", "exam_trap": "", "takeaway": "30S = tetracyclines and aminoglycosides.", "source": "[RD9]."},
  {"id": "MAK-139", "subject": "Microbiology & surgical infection", "topic": "Fluoroquinolones", "title": "Fluoroquinolones", "stem": "Fluoroquinolones exert their antibacterial effect principally by inhibiting bacterial enzymes involved in DNA replication. Which pair is most relevant?", "options": {"A": "DNA gyrase/topoisomerase IV", "B": "Acetylcholinesterase/monoamine oxidase", "C": "Cyclo-oxygenase/lipoxygenase", "D": "Carbonic anhydrase/renin", "E": "Na⁺/K⁺-ATPase/calcium ATPase"}, "correct_letter": "A", "correct_answer": "A. DNA gyrase/topoisomerase IV", "why_correct": "Fluoroquinolones inhibit bacterial DNA gyrase and/or topoisomerase IV.", "exam_trap": "", "takeaway": "Fluoroquinolones → bacterial DNA replication machinery.", "source": "[RD9]."},
  {"id": "MAK-140", "subject": "Microbiology & surgical infection", "topic": "Antibiotic resistance", "title": "Antibiotic resistance", "stem": "Which mechanism can contribute to bacterial antibiotic resistance?", "options": {"A": "Enzymatic destruction or modification of the antibiotic", "B": "Increased susceptibility of bacteria to the drug", "C": "Elimination of all bacterial genetic variation", "D": "Permanent sterilisation of the environment", "E": "Increased host albumin concentration"}, "correct_letter": "A", "correct_answer": "A. Enzymatic destruction or modification of the antibiotic", "why_correct": "Bacteria can develop resistance through mechanisms including enzymatic drug inactivation, altered target sites, reduced permeability and active efflux.", "exam_trap": "", "takeaway": "Resistance can involve the drug, its target, bacterial entry or bacterial efflux.", "source": "[RD9]."},
  {"id": "MAK-141", "subject": "Microbiology & surgical infection", "topic": "Antibiotic stewardship", "title": "Antibiotic stewardship", "stem": "Which prescribing practice best supports antimicrobial stewardship?", "options": {"A": "Use the broadest-spectrum antibiotic indefinitely", "B": "Continue antibiotics without reviewing the indication", "C": "Use an appropriate narrow-spectrum agent when clinically suitable", "D": "Prescribe antibiotics for all postoperative wounds", "E": "Avoid microbiological sampling in severe infection"}, "correct_letter": "C", "correct_answer": "C. Use an appropriate narrow-spectrum agent when clinically suitable", "why_correct": "Antimicrobial stewardship aims to use antibiotics appropriately, balancing effective treatment with minimisation of resistance and adverse effects.", "exam_trap": "", "takeaway": "Right drug + right indication + right duration + review.", "source": "[BNF]."},
  {"id": "MAK-142", "subject": "Microbiology & surgical infection", "topic": "Surgical antibiotic prophylaxis", "title": "Surgical antibiotic prophylaxis", "stem": "Which statement about surgical antibiotic prophylaxis is most appropriate?", "options": {"A": "It should routinely continue for several days after every operation", "B": "Timing is irrelevant", "C": "It should be selected according to the operation, patient and local antimicrobial policy", "D": "It is never indicated for implant surgery", "E": "Treatment antibiotics and prophylaxis are always identical strategies"}, "correct_letter": "C", "correct_answer": "C. It should be selected according to the operation, patient and local antimicrobial policy", "why_correct": "NICE recommends antibiotic prophylaxis for specified operations, including clean surgery involving prosthetic material/implants and clean-contaminated or contaminated surgery, while routine prophylaxis is not recommended for uncomplicated clean non-prosthetic surgery. Local antimicrobial policy and patient-specific factors are important.", "exam_trap": "", "takeaway": "Surgical prophylaxis is procedure-specific—not \"antibiotics for every operation.\"", "source": "NICE NG125."},
  {"id": "MAK-143", "subject": "Microbiology & surgical infection", "topic": "Antibiotic prophylaxis timing", "title": "Antibiotic prophylaxis timing", "stem": "Why should the timing of perioperative antibiotic prophylaxis be considered carefully?", "options": {"A": "It determines whether adequate tissue concentrations are present when contamination occurs", "B": "Antibiotics only work after skin closure", "C": "Antibiotics cannot enter tissues", "D": "Timing has no relationship to efficacy", "E": "Antibiotics should always be given 24 hours before surgery"}, "correct_letter": "A", "correct_answer": "A. It determines whether adequate tissue concentrations are present when contamination occurs", "why_correct": "Prophylaxis aims to ensure effective antimicrobial concentrations during the period when contamination and bacterial proliferation can occur. NICE recommends considering timing, pharmacokinetics and infusion requirements, with repeat dosing when appropriate for prolonged procedures or other circumstances.", "exam_trap": "", "takeaway": "Prophylaxis must be present when contamination risk is highest.", "source": "NICE NG125."},
  {"id": "MAK-144", "subject": "Microbiology & surgical infection", "topic": "Clostridioides difficile", "title": "Clostridioides difficile", "stem": "A patient develops profuse diarrhoea following recent broad-spectrum antibiotic exposure. Which organism should be considered?", "options": {"A": "Clostridioides difficile", "B": "Mycobacterium tuberculosis", "C": "Neisseria meningitidis", "D": "Plasmodium falciparum", "E": "Treponema pallidum"}, "correct_letter": "A", "correct_answer": "A. Clostridioides difficile", "why_correct": "Antibiotic exposure can disrupt normal intestinal flora and predispose to C. difficile infection.", "exam_trap": "Do not treat every episode of post-antibiotic diarrhoea as uncomplicated antibiotic-associated diarrhoea without considering C. difficile.", "takeaway": "Recent antibiotics + significant diarrhoea → consider C. difficile.", "source": "[MMM9]."},
  {"id": "MAK-145", "subject": "Microbiology & surgical infection", "topic": "Staphylococcus aureus", "title": "Staphylococcus aureus", "stem": "Which organism is a common cause of surgical-site and skin/soft-tissue infection?", "options": {"A": "Staphylococcus aureus", "B": "Plasmodium vivax", "C": "Giardia lamblia", "D": "Vibrio cholerae", "E": "Treponema pallidum"}, "correct_letter": "A", "correct_answer": "A. Staphylococcus aureus", "why_correct": "S. aureus is an important cause of skin, soft-tissue and surgical infections.", "exam_trap": "", "takeaway": "S. aureus is a major surgical pathogen.", "source": "[MMM9]."},
  {"id": "MAK-146", "subject": "Microbiology & surgical infection", "topic": "Necrotising soft-tissue infection", "title": "Necrotising soft-tissue infection", "stem": "A patient has severe pain out of proportion to the visible skin findings, systemic toxicity and rapidly progressive soft-tissue swelling. What diagnosis should be urgently considered?", "options": {"A": "Simple superficial cellulitis only", "B": "Necrotising soft-tissue infection", "C": "Chronic venous insufficiency", "D": "Uncomplicated eczema", "E": "Stable lipoma"}, "correct_letter": "B", "correct_answer": "B. Necrotising soft-tissue infection", "why_correct": "Severe pain, systemic toxicity, rapid progression and concerning examination findings should raise suspicion of necrotising infection. The diagnosis is primarily clinical and should not be delayed while waiting for definitive imaging when urgent surgical assessment is required.", "exam_trap": "", "takeaway": "Pain out of proportion + systemic toxicity + rapid progression = emergency surgical assessment.", "source": "[MMM9]."},
  {"id": "MAK-147", "subject": "Microbiology & surgical infection", "topic": "Gas gangrene", "title": "Gas gangrene", "stem": "A rapidly progressive wound infection produces tissue destruction and gas formation. Which organism is classically associated with gas gangrene?", "options": {"A": "Clostridium perfringens", "B": "Staphylococcus epidermidis", "C": "Corynebacterium diphtheriae", "D": "Bordetella pertussis", "E": "Helicobacter pylori"}, "correct_letter": "A", "correct_answer": "A. Clostridium perfringens", "why_correct": "C. perfringens is classically associated with clostridial myonecrosis (gas gangrene).", "exam_trap": "", "takeaway": "Rapid muscle destruction + gas → think clostridial myonecrosis.", "source": "[MMM9]."},
  {"id": "MAK-148", "subject": "Microbiology & surgical infection", "topic": "Sterilisation", "title": "Sterilisation", "stem": "Which process is designed to destroy all forms of microbial life, including bacterial spores?", "options": {"A": "Sterilisation", "B": "Cleaning only", "C": "Disinfection only", "D": "Hand washing only", "E": "Antisepsis of intact skin only"}, "correct_letter": "A", "correct_answer": "A. Sterilisation", "why_correct": "Sterilisation is the process intended to eliminate all forms of microbial life, including spores. Disinfection does not necessarily achieve the same level of microbial destruction.", "exam_trap": "", "takeaway": "Sterilisation ≠ disinfection.", "source": "[MMM9]."},
  {"id": "MAK-149", "subject": "Microbiology & surgical infection", "topic": "Autoclaving", "title": "Autoclaving", "stem": "Which principle underlies steam sterilisation in an autoclave?", "options": {"A": "Moist heat under pressure", "B": "Dry cold air only", "C": "Ultraviolet radiation only", "D": "Freezing", "E": "Alcohol evaporation"}, "correct_letter": "A", "correct_answer": "A. Moist heat under pressure", "why_correct": "Autoclaves use saturated steam under pressure to achieve temperatures sufficient for sterilisation.", "exam_trap": "", "takeaway": "Autoclave = pressurised steam sterilisation.", "source": "[MMM9]."},
  {"id": "MAK-150", "subject": "Microbiology & surgical infection", "topic": "Blood-borne viruses", "title": "Blood-borne viruses", "stem": "A healthcare worker sustains a needlestick injury from a source patient. Which group contains the principal blood-borne viral infections that should be considered?", "options": {"A": "HIV, hepatitis B and hepatitis C", "B": "Influenza, RSV and measles", "C": "Rotavirus, norovirus and adenovirus", "D": "Varicella, mumps and rubella only", "E": "Rhinovirus, coronavirus and parainfluenza only"}, "correct_letter": "A", "correct_answer": "A. HIV, hepatitis B and hepatitis C", "why_correct": "HIV, hepatitis B and hepatitis C are important blood-borne viral infections relevant to occupational exposure. The actual risk and required post-exposure management depend on the source, exposure and vaccination/status information.", "exam_trap": "Do not assume that every needlestick exposure carries the same transmission risk.", "takeaway": "Needlestick → assess HIV + HBV + HCV risk and follow occupational-exposure protocols.", "source": "[MMM9]."},
  {"id": "MAK-151", "subject": "Cardiorespiratory physiology", "topic": "Cardiac cycle", "title": "Cardiac cycle", "stem": "During which phase of the cardiac cycle are the mitral and tricuspid valves normally closed?", "options": {"A": "Ventricular systole", "B": "Atrial systole only", "C": "Passive ventricular filling only", "D": "Isovolumetric ventricular relaxation only", "E": "Throughout diastole"}, "correct_letter": "A", "correct_answer": "A. Ventricular systole", "why_correct": "During ventricular systole, ventricular pressure rises above atrial pressure, closing the atrioventricular valves. The semilunar valves open once ventricular pressure exceeds arterial pressure.", "exam_trap": "The AV valves close at the beginning of ventricular systole; they are not open throughout systole.", "takeaway": "Ventricular systole → AV valves closed.", "source": "[GH14]."},
  {"id": "MAK-152", "subject": "Cardiorespiratory physiology", "topic": "First heart sound", "title": "First heart sound", "stem": "The first heart sound, S1, is primarily produced by:", "options": {"A": "Closure of the aortic and pulmonary valves", "B": "Closure of the mitral and tricuspid valves", "C": "Opening of the mitral valve", "D": "Opening of the pulmonary valve", "E": "Atrial contraction alone"}, "correct_letter": "B", "correct_answer": "B. Closure of the mitral and tricuspid valves", "why_correct": "S1 is associated principally with closure of the atrioventricular valves at the beginning of ventricular systole.", "exam_trap": "", "takeaway": "S1 = AV valve closure. S2 = semilunar valve closure.", "source": "[GH14]."},
  {"id": "MAK-153", "subject": "Cardiorespiratory physiology", "topic": "Second heart sound", "title": "Second heart sound", "stem": "Which event produces the second heart sound?", "options": {"A": "Closure of the atrioventricular valves", "B": "Opening of the atrioventricular valves", "C": "Closure of the aortic and pulmonary valves", "D": "Atrial contraction", "E": "Ventricular filling"}, "correct_letter": "C", "correct_answer": "C. Closure of the aortic and pulmonary valves", "why_correct": "S2 occurs at the end of ventricular systole when the semilunar valves close.", "exam_trap": "", "takeaway": "S2 = aortic + pulmonary valve closure.", "source": "[GH14]."},
  {"id": "MAK-154", "subject": "Cardiorespiratory physiology", "topic": "Frank–Starling mechanism", "title": "Frank–Starling mechanism", "stem": "A patient develops increased venous return while myocardial contractility remains unchanged. Which immediate effect is most consistent with the Frank–Starling mechanism?", "options": {"A": "Reduced stroke volume", "B": "Increased stroke volume", "C": "Complete cessation of ventricular contraction", "D": "Reduced end-diastolic volume", "E": "Reduced myocardial fibre stretch"}, "correct_letter": "B", "correct_answer": "B. Increased stroke volume", "why_correct": "Increased venous return increases ventricular filling and myocardial fibre stretch. Within physiological limits, this produces a stronger subsequent contraction and increased stroke volume.", "exam_trap": "", "takeaway": "More filling → more stretch → stronger contraction, within physiological limits.", "source": "[GH14]."},
  {"id": "MAK-155", "subject": "Cardiorespiratory physiology", "topic": "Coronary perfusion", "title": "Coronary perfusion", "stem": "Most left ventricular coronary blood flow occurs during which part of the cardiac cycle?", "options": {"A": "Ventricular systole", "B": "Ventricular diastole", "C": "Isovolumetric contraction only", "D": "Atrial systole only", "E": "During valve opening only"}, "correct_letter": "B", "correct_answer": "B. Ventricular diastole", "why_correct": "Contraction of the left ventricular myocardium during systole compresses intramyocardial coronary vessels. Coronary perfusion of the left ventricle is therefore particularly dependent on diastolic flow.", "exam_trap": "", "takeaway": "Left coronary perfusion → mainly diastolic.", "source": "[GH14]."},
  {"id": "MAK-156", "subject": "Cardiorespiratory physiology", "topic": "P wave", "title": "ECG: P wave", "stem": "What does the P wave on a normal ECG represent?", "options": {"A": "Ventricular depolarisation", "B": "Ventricular repolarisation", "C": "Atrial depolarisation", "D": "Atrial repolarisation", "E": "Closure of the aortic valve"}, "correct_letter": "C", "correct_answer": "C. Atrial depolarisation", "why_correct": "The P wave represents atrial depolarisation.", "exam_trap": "", "takeaway": "P = atrial depolarisation.", "source": "[GH14]."},
  {"id": "MAK-157", "subject": "Cardiorespiratory physiology", "topic": "QRS complex", "title": "ECG: QRS complex", "stem": "The QRS complex primarily represents:", "options": {"A": "Atrial depolarisation", "B": "Ventricular depolarisation", "C": "Atrial repolarisation only", "D": "Ventricular filling", "E": "Ventricular repolarisation"}, "correct_letter": "B", "correct_answer": "B. Ventricular depolarisation", "why_correct": "The QRS complex represents ventricular depolarisation. Atrial repolarisation occurs at approximately the same time but is usually obscured by the QRS complex.", "exam_trap": "", "takeaway": "QRS = ventricular depolarisation.", "source": "[GH14]."},
  {"id": "MAK-158", "subject": "Cardiorespiratory physiology", "topic": "T wave", "title": "ECG: T wave", "stem": "The T wave represents:", "options": {"A": "Atrial depolarisation", "B": "Ventricular depolarisation", "C": "Ventricular repolarisation", "D": "Atrial contraction", "E": "Ventricular ejection"}, "correct_letter": "C", "correct_answer": "C. Ventricular repolarisation", "why_correct": "The T wave represents ventricular repolarisation.", "exam_trap": "", "takeaway": "T = ventricular repolarisation.", "source": "[GH14]."},
  {"id": "MAK-159", "subject": "Cardiorespiratory physiology", "topic": "ECG conduction", "title": "ECG conduction", "stem": "Which structure normally provides the major physiological delay between atrial and ventricular electrical activation?", "options": {"A": "Sinoatrial node", "B": "Atrioventricular node", "C": "Purkinje fibres", "D": "Left bundle branch", "E": "Ventricular myocardium"}, "correct_letter": "B", "correct_answer": "B. Atrioventricular node", "why_correct": "The AV node slows conduction, allowing time for ventricular filling after atrial contraction before ventricular depolarisation.", "exam_trap": "", "takeaway": "AV node = physiological delay.", "source": "[GH14]."},
  {"id": "MAK-160", "subject": "Cardiorespiratory physiology", "topic": "Blood pressure", "title": "Blood pressure", "stem": "Which equation most closely represents mean arterial pressure in a normal resting adult?", "options": {"A": "Systolic pressure + diastolic pressure", "B": "Diastolic pressure + approximately one-third of pulse pressure", "C": "Systolic pressure − diastolic pressure", "D": "Pulse pressure × heart rate", "E": "Cardiac output ÷ heart rate"}, "correct_letter": "B", "correct_answer": "B. Diastolic pressure + approximately one-third of pulse pressure", "why_correct": "At normal heart rates, a useful approximation is: MAP ≈ DBP + 1/3(SBP − DBP) The exact relationship varies with heart rate because the relative duration of systole and diastole changes.", "exam_trap": "", "takeaway": "MAP ≈ DBP + ⅓ pulse pressure at ordinary resting rates.", "source": "[GH14]."},
  {"id": "MAK-161", "subject": "Cardiorespiratory physiology", "topic": "Systemic vascular resistance", "title": "Systemic vascular resistance", "stem": "Which change would most directly increase systemic vascular resistance?", "options": {"A": "Widespread arteriolar vasodilation", "B": "Widespread arteriolar vasoconstriction", "C": "Reduced sympathetic activity", "D": "Reduced arteriolar smooth-muscle tone", "E": "Increased capillary permeability alone"}, "correct_letter": "B", "correct_answer": "B. Widespread arteriolar vasoconstriction", "why_correct": "Arteriolar diameter is a major determinant of systemic vascular resistance. Vasoconstriction increases resistance.", "exam_trap": "", "takeaway": "Small arteries/arterioles = major resistance vessels.", "source": "[GH14]."},
  {"id": "MAK-162", "subject": "Cardiorespiratory physiology", "topic": "Baroreceptor reflex", "title": "Baroreceptor reflex", "stem": "A sudden fall in arterial blood pressure occurs. What is the expected immediate baroreceptor response?", "options": {"A": "Increased vagal activity", "B": "Reduced sympathetic activity", "C": "Increased sympathetic activity", "D": "Reduced heart rate", "E": "Reduced peripheral vascular resistance"}, "correct_letter": "C", "correct_answer": "C. Increased sympathetic activity", "why_correct": "Reduced stretch of arterial baroreceptors reduces their firing. This increases sympathetic and reduces parasympathetic activity, producing tachycardia, increased contractility and vasoconstriction.", "exam_trap": "", "takeaway": "BP falls → baroreceptor firing falls → sympathetic activity rises.", "source": "[GH14]."},
  {"id": "MAK-163", "subject": "Cardiorespiratory physiology", "topic": "Pulmonary ventilation", "title": "Pulmonary ventilation", "stem": "Which equation best describes alveolar ventilation?", "options": {"A": "Cardiac output × heart rate", "B": "Respiratory rate × tidal volume", "C": "Respiratory rate × (tidal volume − dead-space volume)", "D": "Tidal volume ÷ respiratory rate", "E": "Dead-space volume × cardiac output"}, "correct_letter": "C", "correct_answer": "C. Respiratory rate × (tidal volume − dead-space volume)", "why_correct": "Only the portion of each breath reaching ventilated alveoli beyond anatomical/physiological dead space contributes to alveolar ventilation.", "exam_trap": "", "takeaway": "Alveolar ventilation = rate × effective tidal volume.", "source": "[GH14]."},
  {"id": "MAK-164", "subject": "Cardiorespiratory physiology", "topic": "Alveolar gas exchange", "title": "Alveolar gas exchange", "stem": "Which process is primarily responsible for movement of oxygen from alveolar gas into pulmonary capillary blood?", "options": {"A": "Active transport", "B": "Osmosis", "C": "Diffusion down a partial-pressure gradient", "D": "Pinocytosis", "E": "Filtration"}, "correct_letter": "C", "correct_answer": "C. Diffusion down a partial-pressure gradient", "why_correct": "Oxygen diffuses across the alveolar-capillary membrane down its partial-pressure gradient.", "exam_trap": "", "takeaway": "O₂ and CO₂ cross the alveolar-capillary membrane mainly by diffusion.", "source": "[GH14]."},
  {"id": "MAK-165", "subject": "Cardiorespiratory physiology", "topic": "Ventilation-perfusion relationship", "title": "Ventilation-perfusion relationship", "stem": "A region of lung is ventilated but receives essentially no pulmonary blood flow. What is the physiological consequence?", "options": {"A": "Shunt", "B": "Dead-space ventilation", "C": "Complete V/Q matching", "D": "Increased oxygen extraction by that alveolus", "E": "Reduced alveolar ventilation"}, "correct_letter": "B", "correct_answer": "B. Dead-space ventilation", "why_correct": "Ventilation without perfusion does not contribute effectively to gas exchange and behaves as increased alveolar dead space.", "exam_trap": "", "takeaway": "V without Q = dead space. Q without adequate V = shunt-like physiology.", "source": "[GH14]."},
  {"id": "MAK-166", "subject": "Cardiorespiratory physiology", "topic": "Pulmonary shunt", "title": "Pulmonary shunt", "stem": "Which situation most closely represents a pulmonary shunt?", "options": {"A": "Ventilated alveolus with no perfusion", "B": "Perfused alveolus with no effective ventilation", "C": "Increased anatomical dead space", "D": "Increased alveolar ventilation with normal perfusion", "E": "Increased diffusion capacity"}, "correct_letter": "B", "correct_answer": "B. Perfused alveolus with no effective ventilation", "why_correct": "Blood passing through poorly or non-ventilated lung units can remain inadequately oxygenated, producing shunt physiology.", "exam_trap": "", "takeaway": "Shunt = blood reaches circulation without effective alveolar ventilation.", "source": "[GH14]."},
  {"id": "MAK-167", "subject": "Cardiorespiratory physiology", "topic": "Oxygen dissociation curve", "title": "Oxygen dissociation curve", "stem": "Which change shifts the oxyhaemoglobin dissociation curve to the right?", "options": {"A": "Reduced temperature", "B": "Reduced carbon dioxide", "C": "Reduced 2,3-DPG", "D": "Increased temperature", "E": "Increased pH"}, "correct_letter": "D", "correct_answer": "D. Increased temperature", "why_correct": "Increased temperature, increased CO₂, increased 2,3-DPG and reduced pH shift the curve to the right, reducing haemoglobin's affinity for oxygen and facilitating oxygen unloading to tissues.", "exam_trap": "", "takeaway": "Right shift = easier oxygen unloading.", "source": "[GH14]."},
  {"id": "MAK-168", "subject": "Cardiorespiratory physiology", "topic": "Carbon dioxide transport", "title": "Carbon dioxide transport", "stem": "What is the major form in which carbon dioxide is transported in blood?", "options": {"A": "Dissolved CO₂ only", "B": "Carbaminohaemoglobin only", "C": "Bicarbonate", "D": "Carbon monoxide", "E": "Carbonic acid crystals"}, "correct_letter": "C", "correct_answer": "C. Bicarbonate", "why_correct": "Most carbon dioxide is transported in blood after conversion to bicarbonate.", "exam_trap": "", "takeaway": "Most CO₂ transport = bicarbonate.", "source": "[GH14]."},
  {"id": "MAK-169", "subject": "Cardiorespiratory physiology", "topic": "Ventilatory response to carbon dioxide", "title": "Ventilatory response to carbon dioxide", "stem": "In a healthy person, an acute rise in arterial PaCO₂ normally produces:", "options": {"A": "Reduced ventilation", "B": "Increased ventilation", "C": "Complete respiratory arrest", "D": "Reduced respiratory drive in all circumstances", "E": "No physiological response"}, "correct_letter": "B", "correct_answer": "B. Increased ventilation", "why_correct": "Raised PaCO₂ is a powerful stimulus to ventilation, mediated largely through central and peripheral chemoreceptor mechanisms.", "exam_trap": "", "takeaway": "CO₂ rises → ventilation rises.", "source": "[GH14]."},
  {"id": "MAK-170", "subject": "Physiology", "topic": "Renal filtration", "title": "Renal filtration", "stem": "Which structure forms the principal filtration barrier between glomerular capillary blood and Bowman's space?", "options": {"A": "Glomerular filtration barrier", "B": "Collecting duct epithelium", "C": "Loop of Henle", "D": "Ureteric epithelium", "E": "Renal pelvis"}, "correct_letter": "A", "correct_answer": "A. Glomerular filtration barrier", "why_correct": "The filtration barrier consists of specialised fenestrated endothelium, glomerular basement membrane and podocyte slit diaphragms.", "exam_trap": "", "takeaway": "Glomerular filtration = endothelium + basement membrane + podocytes.", "source": "[GH14]."},
  {"id": "MAK-171", "subject": "Physiology", "topic": "Proximal tubule", "title": "Proximal tubule", "stem": "Which statement about the proximal renal tubule is most accurate?", "options": {"A": "It performs no sodium reabsorption", "B": "It reabsorbs a large proportion of filtered sodium and water", "C": "It is the principal site of urinary concentration", "D": "It is impermeable to water under all conditions", "E": "It secretes no substances"}, "correct_letter": "B", "correct_answer": "B. It reabsorbs a large proportion of filtered sodium and water", "why_correct": "The proximal tubule reabsorbs a substantial proportion of filtered sodium and water and is also important for bicarbonate, glucose, amino acid and other solute handling.", "exam_trap": "", "takeaway": "Proximal tubule = bulk reabsorption.", "source": "[GH14]."},
  {"id": "MAK-172", "subject": "Physiology", "topic": "Loop of Henle", "title": "Loop of Henle", "stem": "Which segment of the nephron is particularly important for establishing the medullary osmotic gradient?", "options": {"A": "Thin and thick ascending limbs as part of countercurrent multiplication", "B": "Ureter", "C": "Renal pelvis", "D": "Glomerular capsule only", "E": "Proximal urethra"}, "correct_letter": "A", "correct_answer": "A. Thin and thick ascending limbs as part of countercurrent multiplication", "why_correct": "The loop of Henle contributes to the medullary concentration gradient through countercurrent multiplication. The thick ascending limb actively reabsorbs electrolytes and is relatively impermeable to water.", "exam_trap": "", "takeaway": "Loop of Henle = countercurrent multiplication + medullary gradient.", "source": "[GH14]."},
  {"id": "MAK-174", "subject": "Physiology", "topic": "ADH and urine concentration", "title": "ADH and urine concentration", "stem": "Which effect of ADH allows production of concentrated urine?", "options": {"A": "Reduced collecting-duct water permeability", "B": "Increased collecting-duct water permeability", "C": "Complete inhibition of medullary osmotic gradients", "D": "Increased sodium loss from the proximal tubule only", "E": "Suppression of thirst"}, "correct_letter": "B", "correct_answer": "B. Increased collecting-duct water permeability", "why_correct": "ADH allows water to move from the collecting duct into the hyperosmotic renal medulla, concentrating the urine.", "exam_trap": "", "takeaway": "ADH conserves water by allowing collecting-duct water reabsorption.", "source": "[GH14]."},
  {"id": "MAK-175", "subject": "Physiology", "topic": "Renin", "title": "Renin", "stem": "Which renal cells release renin?", "options": {"A": "Podocytes", "B": "Juxtaglomerular cells", "C": "Principal cells", "D": "Intercalated cells", "E": "Mesangial cells only"}, "correct_letter": "B", "correct_answer": "B. Juxtaglomerular cells", "why_correct": "Juxtaglomerular cells in the afferent arteriole release renin in response to appropriate stimuli, including reduced renal perfusion pressure.", "exam_trap": "", "takeaway": "Juxtaglomerular cells → renin.", "source": "[GH14]."},
  {"id": "MAK-176", "subject": "Physiology", "topic": "Parathyroid hormone", "title": "Parathyroid hormone", "stem": "Which effect is associated with parathyroid hormone?", "options": {"A": "Reduced serum calcium", "B": "Increased renal calcium reabsorption", "C": "Reduced vitamin D activation", "D": "Increased renal phosphate reabsorption", "E": "Complete suppression of osteoclast-mediated bone resorption"}, "correct_letter": "B", "correct_answer": "B. Increased renal calcium reabsorption", "why_correct": "PTH increases renal calcium reabsorption and decreases phosphate reabsorption. It also promotes activation of vitamin D in the kidney, contributing to increased intestinal calcium absorption.", "exam_trap": "", "takeaway": "PTH → calcium up, phosphate down.", "source": "[GH14]."},
  {"id": "MAK-177", "subject": "Physiology", "topic": "Vitamin D", "title": "Vitamin D", "stem": "Which physiological effect is promoted by active vitamin D?", "options": {"A": "Reduced intestinal calcium absorption", "B": "Increased intestinal calcium absorption", "C": "Complete inhibition of phosphate absorption", "D": "Reduced bone mineral availability", "E": "Complete suppression of PTH under all circumstances"}, "correct_letter": "B", "correct_answer": "B. Increased intestinal calcium absorption", "why_correct": "Active vitamin D increases intestinal absorption of calcium and phosphate and participates in calcium-phosphate homeostasis.", "exam_trap": "", "takeaway": "Vitamin D → intestinal calcium/phosphate absorption ↑.", "source": "[GH14]."},
  {"id": "MAK-178", "subject": "Physiology", "topic": "Cortisol", "title": "Cortisol", "stem": "Which physiological effect is associated with cortisol?", "options": {"A": "Promotion of gluconeogenesis", "B": "Complete suppression of vascular responsiveness to catecholamines", "C": "Universal reduction in blood glucose", "D": "Elimination of all inflammatory responses", "E": "Complete inhibition of protein catabolism"}, "correct_letter": "A", "correct_answer": "A. Promotion of gluconeogenesis", "why_correct": "Cortisol contributes to maintenance of glucose availability, including promotion of gluconeogenesis, and has important effects on immune and inflammatory responses.", "exam_trap": "", "takeaway": "Cortisol = stress metabolism + permissive cardiovascular effects + immunomodulation.", "source": "[GH14]."},
  {"id": "MAK-179", "subject": "Physiology", "topic": "Aldosterone", "title": "Aldosterone", "stem": "A patient develops primary hyperaldosteronism. Which biochemical pattern is most consistent with aldosterone excess?", "options": {"A": "Hyperkalaemia and metabolic acidosis", "B": "Hypokalaemia and metabolic alkalosis", "C": "Hyperkalaemia and respiratory acidosis", "D": "Hypokalaemia and respiratory alkalosis", "E": "Hyponatraemia and metabolic acidosis as the defining pattern"}, "correct_letter": "B", "correct_answer": "B. Hypokalaemia and metabolic alkalosis", "why_correct": "Excess aldosterone promotes sodium retention and potassium and hydrogen ion secretion, which can produce hypokalaemia and metabolic alkalosis.", "exam_trap": "", "takeaway": "Aldosterone excess → Na⁺ retention + K⁺ loss + H⁺ loss.", "source": "[GH14]."},
  {"id": "MAK-180", "subject": "Physiology", "topic": "Hyperkalaemia and the heart", "title": "Hyperkalaemia and the heart", "stem": "A patient with acute kidney injury develops severe hyperkalaemia with ECG changes. Which treatment is specifically used to protect the myocardium from the immediate electrical effects of hyperkalaemia?", "options": {"A": "Intravenous calcium", "B": "Oral iron", "C": "Intravenous bicarbonate in every case as sole treatment", "D": "Oral potassium", "E": "Intravenous magnesium as sole treatment"}, "correct_letter": "A", "correct_answer": "A. Intravenous calcium", "why_correct": "In significant hyperkalaemia with ECG changes, intravenous calcium is used to stabilise the cardiac membrane. It does not remove potassium from the body, so additional potassium-lowering treatment and treatment of the underlying cause are required. Current UK guidance distinguishes cardiac membrane stabilisation from measures that shift potassium intracellularly or remove potassium. NICE-supported guidance identifies IV calcium for ECG evidence of hyperkalaemia and insulin/glucose as a potassium-shifting treatment.", "exam_trap": "Calcium protects the heart; it does not lower the serum potassium concentration.", "takeaway": "Hyperkalaemia + ECG changes → calcium protects the heart; then actively lower/remove K⁺.", "source": "NICE hyperkalaemia evidence/guidance referencing UK Renal Association guidance; current material accessed September 2026."},
  {"id": "MAK-181", "subject": "GI physiology & metabolism", "topic": "Gastric acid secretion", "title": "Gastric acid secretion", "stem": "A patient is given a drug that directly inhibits the final common pathway responsible for gastric hydrochloric acid secretion. Which cellular mechanism is being inhibited?", "options": {"A": "Na+/K+ ATPase in gastric chief cells", "B": "H+/K+ ATPase in gastric parietal cells", "C": "Na+/H+ exchanger in gastric mucosal cells", "D": "Cl−/HCO3− exchanger in gastric chief cells", "E": "Ca2+ ATPase in gastric parietal cells"}, "correct_letter": "B", "correct_answer": "B. H+/K+ ATPase in gastric parietal cells", "why_correct": "Parietal cells secrete hydrochloric acid through the apical H+/K+ ATPase. This exchanges intracellular hydrogen ions for luminal potassium.", "exam_trap": "Do not confuse the H+/K+ ATPase with the Na+/K+ ATPase found in many cell membranes.", "takeaway": "Parietal cell → H+/K+ ATPase → gastric HCl.", "source": "[GH14]."},
  {"id": "MAK-182", "subject": "GI physiology & metabolism", "topic": "Gastrin", "title": "Gastrin", "stem": "A patient develops marked hypersecretion of gastric acid due to excessive gastrin production. Which cell normally secretes gastrin?", "options": {"A": "G cells", "B": "I cells", "C": "S cells", "D": "D cells", "E": "Chief cells"}, "correct_letter": "A", "correct_answer": "A. G cells", "why_correct": "G cells, predominantly in the gastric antrum, secrete gastrin. Gastrin promotes gastric acid secretion and supports gastric mucosal growth.", "exam_trap": "I cells produce CCK; S cells produce secretin; D cells produce somatostatin.", "takeaway": "Gastrin = G cells = gastric acid stimulation.", "source": "[GH14]."},
  {"id": "MAK-183", "subject": "GI physiology & metabolism", "topic": "Secretin", "title": "Secretin", "stem": "Acidic chyme enters the duodenum. Which gastrointestinal hormone is released predominantly in response to this stimulus?", "options": {"A": "Gastrin", "B": "Secretin", "C": "CCK", "D": "Motilin", "E": "Somatostatin"}, "correct_letter": "B", "correct_answer": "B. Secretin", "why_correct": "Secretin is released by duodenal S cells in response particularly to acidic chyme. It promotes pancreatic and biliary bicarbonate secretion, helping neutralise duodenal acid.", "exam_trap": "CCK is strongly associated with fatty acids and amino acids rather than being the principal response to luminal acid.", "takeaway": "Acid in duodenum → secretin → bicarbonate.", "source": "[GH14]."},
  {"id": "MAK-184", "subject": "GI physiology & metabolism", "topic": "Cholecystokinin", "title": "Cholecystokinin", "stem": "A meal containing a substantial amount of fat reaches the duodenum. Which hormone is most directly associated with gallbladder contraction and pancreatic enzyme secretion?", "options": {"A": "Gastrin", "B": "Secretin", "C": "CCK", "D": "Motilin", "E": "Somatostatin"}, "correct_letter": "C", "correct_answer": "C. CCK", "why_correct": "Cholecystokinin is released from I cells in the duodenum and jejunum in response particularly to fatty acids and amino acids. It stimulates gallbladder contraction and pancreatic enzyme secretion.", "exam_trap": "Secretin is more strongly associated with pancreatic bicarbonate secretion.", "takeaway": "Fat/protein in duodenum → CCK → gallbladder contraction + pancreatic enzymes.", "source": "[GH14]."},
  {"id": "MAK-185", "subject": "GI physiology & metabolism", "topic": "Pancreatic bicarbonate", "title": "Pancreatic bicarbonate", "stem": "Why does the exocrine pancreas secrete bicarbonate-rich fluid into the duodenum?", "options": {"A": "To activate pepsin", "B": "To neutralise gastric acid", "C": "To stimulate gastrin release", "D": "To digest triglycerides", "E": "To increase gastric acid secretion"}, "correct_letter": "B", "correct_answer": "B. To neutralise gastric acid", "why_correct": "Pancreatic bicarbonate helps raise the pH of duodenal contents after acidic gastric chyme enters the small bowel. This provides a suitable environment for pancreatic and intestinal enzymes.", "exam_trap": "Pancreatic lipase digests fat; bicarbonate does not digest nutrients itself.", "takeaway": "Pancreatic bicarbonate = neutralisation of gastric acid.", "source": "[GH14]."},
  {"id": "MAK-186", "subject": "GI physiology & metabolism", "topic": "Pancreatic enzyme activation", "title": "Pancreatic enzyme activation", "stem": "A pancreatic protease is secreted in an inactive form and subsequently activated in the small intestine. Which intestinal enzyme initiates this process?", "options": {"A": "Pepsin", "B": "Enteropeptidase", "C": "Amylase", "D": "Lipase", "E": "Trypsin inhibitor"}, "correct_letter": "B", "correct_answer": "B. Enteropeptidase", "why_correct": "Enteropeptidase on the duodenal brush border converts trypsinogen to trypsin. Trypsin then activates several other pancreatic zymogens.", "exam_trap": "Trypsin activates other pancreatic enzymes, but enteropeptidase initiates the cascade.", "takeaway": "Enteropeptidase → trypsinogen → trypsin → activation of pancreatic zymogens.", "source": "[GH14]."},
  {"id": "MAK-187", "subject": "GI physiology & metabolism", "topic": "Bile salts", "title": "Bile salts", "stem": "A patient has severe cholestasis and subsequently develops difficulty absorbing dietary fat. Which substance is primarily responsible for facilitating intestinal absorption of lipid by forming micelles?", "options": {"A": "Bilirubin", "B": "Bile salts", "C": "Bicarbonate", "D": "Intrinsic factor", "E": "Gastrin"}, "correct_letter": "B", "correct_answer": "B. Bile salts", "why_correct": "Bile salts emulsify dietary lipids and form micelles that facilitate delivery of lipid digestion products to the intestinal brush border.", "exam_trap": "Bilirubin is a product of haem breakdown and is excreted in bile; it is not the principal molecule responsible for micelle formation.", "takeaway": "Bile salts are essential for effective intestinal fat absorption.", "source": "[GH14]."},
  {"id": "MAK-188", "subject": "GI physiology & metabolism", "topic": "Enterohepatic circulation", "title": "Enterohepatic circulation", "stem": "Which substance undergoes substantial enterohepatic circulation?", "options": {"A": "Bile salts", "B": "Haemoglobin", "C": "Albumin", "D": "Insulin", "E": "Urea"}, "correct_letter": "A", "correct_answer": "A. Bile salts", "why_correct": "Bile salts are secreted into the intestine, reabsorbed predominantly in the terminal ileum and returned to the liver through the portal circulation.", "exam_trap": "Terminal ileal disease or resection can therefore impair bile salt recycling and contribute to bile acid malabsorption.", "takeaway": "Terminal ileum → bile salt reabsorption → portal vein → liver.", "source": "[GH14]."},
  {"id": "MAK-189", "subject": "GI physiology & metabolism", "topic": "Vitamin B12 absorption", "title": "Vitamin B12 absorption", "stem": "A patient develops vitamin B12 deficiency after extensive terminal ileal resection. Which explanation is most appropriate?", "options": {"A": "Loss of gastric chief cells", "B": "Loss of pancreatic amylase", "C": "Loss of intrinsic factor secretion from the stomach", "D": "Loss of the principal site of intrinsic-factor–B12 absorption", "E": "Loss of duodenal iron absorption"}, "correct_letter": "D", "correct_answer": "D. Loss of the principal site of intrinsic-factor–B12 absorption", "why_correct": "Vitamin B12 binds intrinsic factor and is absorbed in the terminal ileum. Terminal ileal disease or resection can therefore cause B12 deficiency.", "exam_trap": "Intrinsic factor is produced by gastric parietal cells, but the intrinsic-factor–B12 complex is absorbed in the terminal ileum.", "takeaway": "B12 + intrinsic factor → terminal ileum.", "source": "[GH14]."},
  {"id": "MAK-190", "subject": "GI physiology & metabolism", "topic": "Iron absorption", "title": "Iron absorption", "stem": "Where is dietary iron predominantly absorbed?", "options": {"A": "Stomach", "B": "Duodenum and proximal jejunum", "C": "Terminal ileum", "D": "Caecum", "E": "Rectum"}, "correct_letter": "B", "correct_answer": "B. Duodenum and proximal jejunum", "why_correct": "The duodenum and proximal small intestine are the major sites of dietary iron absorption.", "exam_trap": "Do not associate all micronutrient absorption with the terminal ileum. B12 is the classic terminal-ileal example.", "takeaway": "Iron → mainly duodenum/proximal jejunum; B12 → terminal ileum.", "source": "[GH14]."},
  {"id": "MAK-191", "subject": "GI physiology & metabolism", "topic": "Glucose absorption", "title": "Glucose absorption", "stem": "A patient has normal pancreatic function but impaired intestinal glucose absorption due to inhibition of the principal sodium-dependent glucose transporter on the intestinal brush border. Which transporter is affected?", "options": {"A": "GLUT1", "B": "GLUT2", "C": "GLUT4", "D": "SGLT1", "E": "Na+/K+ ATPase"}, "correct_letter": "D", "correct_answer": "D. SGLT1", "why_correct": "SGLT1 mediates sodium-dependent uptake of glucose and galactose across the intestinal brush border. The Na+/K+ ATPase maintains the sodium gradient that drives this secondary active transport.", "exam_trap": "GLUT4 is the insulin-responsive glucose transporter in skeletal muscle and adipose tissue.", "takeaway": "Gut lumen → SGLT1 → enterocyte; basolateral exit → GLUT2.", "source": "[GH14]."},
  {"id": "MAK-192", "subject": "GI physiology & metabolism", "topic": "Colonic water absorption", "title": "Colonic water absorption", "stem": "A patient has extensive colonic disease and develops increased stool water losses. Which physiological function of the colon has been impaired?", "options": {"A": "Major protein digestion", "B": "Absorption of water and electrolytes", "C": "Bile production", "D": "Intrinsic-factor secretion", "E": "Pancreatic enzyme activation"}, "correct_letter": "B", "correct_answer": "B. Absorption of water and electrolytes", "why_correct": "The colon plays an important role in recovering water and electrolytes from intestinal contents.", "exam_trap": "Most nutrient absorption occurs in the small intestine, but the colon remains important for fluid and electrolyte handling.", "takeaway": "Colon = water and electrolyte recovery.", "source": "[GH14]."},
  {"id": "MAK-193", "subject": "GI physiology & metabolism", "topic": "Portal circulation", "title": "Portal circulation", "stem": "Which vessel carries nutrient-rich blood from the gastrointestinal tract to the liver?", "options": {"A": "Hepatic artery", "B": "Hepatic vein", "C": "Portal vein", "D": "Inferior vena cava", "E": "Splenic artery"}, "correct_letter": "C", "correct_answer": "C. Portal vein", "why_correct": "Venous blood from much of the gastrointestinal tract, spleen and associated organs reaches the liver through the portal venous system.", "exam_trap": "", "takeaway": "Gut → portal vein → liver → systemic circulation.", "source": "[GH14]."},
  {"id": "MAK-194", "subject": "GI physiology & metabolism", "topic": "Hepatic synthetic function", "title": "Hepatic synthetic function", "stem": "A patient with severe chronic liver disease develops hypoalbuminaemia. Which hepatic function is impaired?", "options": {"A": "Urea filtration", "B": "Albumin synthesis", "C": "Insulin secretion", "D": "Bile salt absorption", "E": "Renal ammonium excretion"}, "correct_letter": "B", "correct_answer": "B. Albumin synthesis", "why_correct": "The liver synthesises albumin and many plasma proteins, including several coagulation factors.", "exam_trap": "Low albumin can also occur through other mechanisms, including inflammation, renal loss and gastrointestinal loss. In severe liver disease, impaired hepatic synthesis is an important mechanism.", "takeaway": "Liver = major plasma protein synthesis.", "source": "[GH14]."},
  {"id": "MAK-195", "subject": "GI physiology & metabolism", "topic": "Urea cycle", "title": "Urea cycle", "stem": "A patient with severe hepatic dysfunction develops hyperammonaemia. Which hepatic metabolic process is directly impaired?", "options": {"A": "Conversion of ammonia to urea", "B": "Conversion of glucose to glycogen", "C": "Conversion of lactate to pyruvate only", "D": "Conversion of cholesterol to bile salts", "E": "Conversion of fatty acids to triglycerides"}, "correct_letter": "A", "correct_answer": "A. Conversion of ammonia to urea", "why_correct": "The liver converts toxic ammonia into urea through the urea cycle. Severe hepatic dysfunction can therefore contribute to hyperammonaemia.", "exam_trap": "Do not confuse the urea cycle with renal excretion. The kidney excretes urea, but hepatic conversion of ammonia to urea occurs first.", "takeaway": "Liver converts ammonia → urea; kidney excretes urea.", "source": "[GH14]."},
  {"id": "MAK-196", "subject": "GI physiology & metabolism", "topic": "Insulin and glucose uptake", "title": "Insulin and glucose uptake", "stem": "Following a carbohydrate-rich meal, insulin secretion increases. Which tissue demonstrates insulin-stimulated translocation of GLUT4 to the cell membrane?", "options": {"A": "Skeletal muscle", "B": "Intestinal lumen", "C": "Hepatocytes only", "D": "Red blood cells", "E": "Renal glomerular endothelium"}, "correct_letter": "A", "correct_answer": "A. Skeletal muscle", "why_correct": "Insulin promotes GLUT4 translocation particularly in skeletal muscle and adipose tissue, increasing glucose uptake.", "exam_trap": "The liver uses GLUT2, which is not dependent on insulin-mediated GLUT4 translocation.", "takeaway": "Insulin → GLUT4 → skeletal muscle/adipose glucose uptake.", "source": "[GH14]."},
  {"id": "MAK-197", "subject": "GI physiology & metabolism", "topic": "Glucagon", "title": "Glucagon", "stem": "During fasting, which hormone is most important in promoting hepatic glycogenolysis and gluconeogenesis?", "options": {"A": "Insulin", "B": "Glucagon", "C": "Calcitonin", "D": "Aldosterone", "E": "ADH"}, "correct_letter": "B", "correct_answer": "B. Glucagon", "why_correct": "Glucagon rises during fasting and promotes hepatic glucose production through glycogenolysis and gluconeogenesis.", "exam_trap": "Insulin has broadly opposing metabolic effects and is dominant in the fed state.", "takeaway": "Fed state → insulin; fasting state → glucagon.", "source": "[GH14]."},
  {"id": "MAK-198", "subject": "GI physiology & metabolism", "topic": "Early fasting", "title": "Early fasting", "stem": "A healthy adult stops eating but continues to drink water. During the early fasting period, which process becomes increasingly important for maintaining blood glucose?", "options": {"A": "Hepatic glycogenolysis", "B": "Intestinal glucose absorption", "C": "Increased insulin secretion", "D": "Increased glycogen synthesis", "E": "Increased glucose uptake by adipose tissue"}, "correct_letter": "A", "correct_answer": "A. Hepatic glycogenolysis", "why_correct": "During early fasting, hepatic glycogen stores are mobilised to maintain blood glucose. As fasting continues, gluconeogenesis becomes increasingly important.", "exam_trap": "Do not apply the metabolic pattern of prolonged starvation to the first few hours of fasting.", "takeaway": "Early fasting → glycogenolysis; prolonged fasting → increasing gluconeogenesis and ketogenesis.", "source": "[GH14]."},
  {"id": "MAK-199", "subject": "GI physiology & metabolism", "topic": "Prolonged starvation", "title": "Prolonged starvation", "stem": "During prolonged starvation, which fuel becomes increasingly important for the brain?", "options": {"A": "Free fatty acids directly", "B": "Ketone bodies", "C": "Glycogen", "D": "Lactate only", "E": "Amino acids only"}, "correct_letter": "B", "correct_answer": "B. Ketone bodies", "why_correct": "During prolonged starvation, increased hepatic ketogenesis provides ketone bodies that can be used by the brain, reducing its dependence on glucose and helping conserve body protein.", "exam_trap": "The brain cannot simply switch to using circulating free fatty acids as its principal alternative fuel because long-chain fatty acids cross the blood–brain barrier poorly.", "takeaway": "Prolonged starvation → hepatic ketogenesis → increased cerebral ketone utilisation.", "source": "[GH14]."},
  {"id": "MAK-200", "subject": "Perioperative medicine & nutrition", "topic": "Refeeding syndrome", "title": "Refeeding syndrome", "stem": "A severely malnourished patient has had negligible nutritional intake for 12 days. Nutrition is restarted rapidly. Two days later the patient develops weakness, oedema and cardiac instability. Which biochemical abnormality is classically associated with refeeding syndrome?", "options": {"A": "Hyperphosphataemia", "B": "Hypophosphataemia", "C": "Hypercalcaemia", "D": "Hypermagnesaemia", "E": "Hyperkalaemia"}, "correct_letter": "B", "correct_answer": "B. Hypophosphataemia", "why_correct": "Refeeding increases insulin secretion and drives phosphate, potassium and magnesium intracellularly. Hypophosphataemia is a characteristic biochemical feature of refeeding syndrome. NICE identifies prolonged poor intake and low phosphate, potassium or magnesium among important risk features and recommends cautious introduction of nutrition in high-risk patients.", "exam_trap": "The problem is not simply \"giving too many calories\"; the metabolic shift after reintroduction of nutrition is central.", "takeaway": "Refeeding → insulin surge → intracellular phosphate shift → hypophosphataemia.", "source": "NICE CG32 (2017)."},
  {"id": "MAK-201", "subject": "GI physiology & metabolism", "topic": "Lactate", "title": "Lactate", "stem": "During severe tissue hypoperfusion, anaerobic glycolysis increases. What is the principal immediate metabolic fate of pyruvate under these conditions?", "options": {"A": "Conversion to lactate", "B": "Conversion to urea", "C": "Conversion to ketone bodies in skeletal muscle", "D": "Conversion to bilirubin", "E": "Conversion to cholesterol"}, "correct_letter": "A", "correct_answer": "A. Conversion to lactate", "why_correct": "When oxidative metabolism is insufficient, pyruvate is converted to lactate, allowing regeneration of NAD+ and continued glycolysis.", "exam_trap": "An elevated lactate is a marker of disturbed metabolism/perfusion but is not synonymous with hypoxia in every clinical circumstance.", "takeaway": "Pyruvate + impaired oxidative metabolism → lactate.", "source": "[GH14]."},
  {"id": "MAK-202", "subject": "Physiology", "topic": "Anion gap", "title": "Anion gap", "stem": "A patient has the following results: Na+ = 140 mmol/L Cl− = 104 mmol/L HCO3− = 16 mmol/L What is the approximate anion gap using the conventional formula Na+ − (Cl− + HCO3−)?", "options": {"A": "8 mmol/L", "B": "12 mmol/L", "C": "20 mmol/L", "D": "28 mmol/L", "E": "36 mmol/L"}, "correct_letter": "C", "correct_answer": "C. 20 mmol/L", "why_correct": "Anion gap = 140 − (104 + 16) = 140 − 120 = 20 mmol/L. This indicates an increased anion gap in the appropriate clinical context.", "exam_trap": "Calculate rather than guessing from the bicarbonate value alone.", "takeaway": "Anion gap = Na+ − (Cl− + HCO3−).", "source": "[GH14]."},
  {"id": "MAK-203", "subject": "Physiology", "topic": "Compensation for metabolic acidosis", "title": "Compensation for metabolic acidosis", "stem": "A patient develops an acute metabolic acidosis. Which physiological response occurs most rapidly to compensate?", "options": {"A": "Increased renal bicarbonate generation", "B": "Increased renal ammonium excretion", "C": "Increased alveolar ventilation", "D": "Increased erythropoiesis", "E": "Increased aldosterone secretion only"}, "correct_letter": "C", "correct_answer": "C. Increased alveolar ventilation", "why_correct": "Respiratory compensation for metabolic acidosis occurs rapidly through increased ventilation, reducing PaCO2. Renal compensation takes longer.", "exam_trap": "Do not choose renal bicarbonate handling as the immediate response.", "takeaway": "Metabolic acidosis → hyperventilation → ↓PaCO2.", "source": "[GH14]."},
  {"id": "MAK-204", "subject": "Physiology", "topic": "Respiratory acidosis", "title": "Respiratory acidosis", "stem": "A patient develops hypoventilation from severe opioid toxicity. Which primary acid–base disturbance is expected?", "options": {"A": "Metabolic acidosis", "B": "Metabolic alkalosis", "C": "Respiratory acidosis", "D": "Respiratory alkalosis", "E": "Mixed alkalosis only"}, "correct_letter": "C", "correct_answer": "C. Respiratory acidosis", "why_correct": "Hypoventilation causes carbon dioxide retention. Increased PaCO2 produces respiratory acidosis.", "exam_trap": "", "takeaway": "Hypoventilation → CO2 retention → respiratory acidosis.", "source": "[GH14]."},
  {"id": "MAK-205", "subject": "Physiology", "topic": "Respiratory alkalosis", "title": "Respiratory alkalosis", "stem": "A patient is acutely hyperventilating because of severe anxiety. Which initial biochemical change is expected?", "options": {"A": "Increased PaCO2", "B": "Reduced PaCO2", "C": "Increased bicarbonate due to immediate renal compensation", "D": "Increased lactate as the primary acid–base change", "E": "Increased chloride as the primary event"}, "correct_letter": "B", "correct_answer": "B. Reduced PaCO2", "why_correct": "Acute hyperventilation removes CO2 from the blood, producing respiratory alkalosis.", "exam_trap": "Renal compensation occurs over a longer period and does not explain the immediate fall in PaCO2.", "takeaway": "Hyperventilation → ↓CO2 → respiratory alkalosis.", "source": "[GH14]."},
  {"id": "MAK-206", "subject": "Physiology", "topic": "Bicarbonate and carbon dioxide", "title": "Bicarbonate and carbon dioxide", "stem": "Which pair forms the principal extracellular buffer system involved in regulation of blood pH?", "options": {"A": "Sodium and chloride", "B": "Bicarbonate and carbon dioxide", "C": "Potassium and phosphate only", "D": "Calcium and albumin only", "E": "Lactate and pyruvate"}, "correct_letter": "B", "correct_answer": "B. Bicarbonate and carbon dioxide", "why_correct": "The bicarbonate/CO2 buffer system is central to extracellular acid–base regulation. The lungs regulate CO2 while the kidneys regulate bicarbonate and acid excretion.", "exam_trap": "Think of acid–base regulation as a lung–kidney system rather than an isolated blood chemistry value.", "takeaway": "Lungs control CO2; kidneys control bicarbonate and net acid excretion.", "source": "[GH14]."},
  {"id": "MAK-207", "subject": "Physiology", "topic": "Fever", "title": "Fever", "stem": "A patient develops fever during an acute infection. Which physiological change best explains the development of the raised temperature?", "options": {"A": "Destruction of the hypothalamus", "B": "A raised hypothalamic temperature set point", "C": "Failure of peripheral vasoconstriction", "D": "Permanent increase in basal metabolic rate", "E": "Direct heating of the blood by inflammatory cells"}, "correct_letter": "B", "correct_answer": "B. A raised hypothalamic temperature set point", "why_correct": "Endogenous pyrogens and inflammatory mediators can increase the hypothalamic set point. The body then activates mechanisms such as vasoconstriction and shivering to raise core temperature toward the new set point.", "exam_trap": "Fever is regulated elevation of the set point; hyperthermia is different because the set point is not necessarily raised.", "takeaway": "Fever = raised hypothalamic set point.", "source": "[GH14]."},
  {"id": "MAK-208", "subject": "Physiology", "topic": "Heat loss", "title": "Heat loss", "stem": "A patient in a hot environment is sweating heavily. Which mechanism allows sweat to reduce core temperature?", "options": {"A": "Conduction", "B": "Radiation", "C": "Evaporation", "D": "Vasoconstriction", "E": "Shivering"}, "correct_letter": "C", "correct_answer": "C. Evaporation", "why_correct": "Evaporation of sweat from the skin removes heat from the body.", "exam_trap": "Sweating itself does not guarantee effective cooling; in very humid environments, evaporation becomes less effective.", "takeaway": "Sweat cools principally through evaporation.", "source": "[GH14]."},
  {"id": "MAK-209", "subject": "Physiology", "topic": "Shivering", "title": "Shivering", "stem": "A patient exposed to cold develops involuntary rhythmic skeletal muscle contractions. What is the principal physiological purpose?", "options": {"A": "Reduce metabolic heat production", "B": "Increase heat production", "C": "Increase evaporative heat loss", "D": "Reduce sympathetic activity", "E": "Increase gastrointestinal absorption"}, "correct_letter": "B", "correct_answer": "B. Increase heat production", "why_correct": "Shivering consists of involuntary skeletal muscle activity that increases metabolic heat production.", "exam_trap": "", "takeaway": "Cold → shivering → increased heat production.", "source": "[GH14]."},
  {"id": "MAK-210", "subject": "Perioperative medicine & nutrition", "topic": "Nitrogen balance", "title": "Nitrogen balance", "stem": "A patient with severe sepsis has prolonged catabolic illness and is losing skeletal muscle despite adequate fluid resuscitation. Which metabolic state is most likely?", "options": {"A": "Positive nitrogen balance", "B": "Negative nitrogen balance", "C": "Zero nitrogen balance", "D": "Increased protein synthesis exceeding breakdown", "E": "Complete suppression of proteolysis"}, "correct_letter": "B", "correct_answer": "B. Negative nitrogen balance", "why_correct": "During severe catabolic illness, protein breakdown can exceed protein synthesis, resulting in net nitrogen loss and muscle wasting.", "exam_trap": "\"Nutrition provided\" does not automatically mean positive nitrogen balance. Severe inflammation, infection and physiological stress can drive substantial catabolism.", "takeaway": "Catabolic surgical illness → protein breakdown > synthesis → negative nitrogen balance.", "source": "[GH14]; NICE CG32, Nutrition support for adults."},
  {"id": "MAK-211", "subject": "Pathology: inflammation & wound healing", "topic": "Acute inflammation", "title": "Acute inflammation", "stem": "A patient develops an acutely inflamed wound. Which leukocyte is normally the predominant cell during the early phase of acute inflammation?", "options": {"A": "Neutrophil", "B": "Plasma cell", "C": "Lymphocyte", "D": "Macrophage", "E": "Eosinophil"}, "correct_letter": "A", "correct_answer": "A. Neutrophil", "why_correct": "Neutrophils are typically the predominant early inflammatory leukocytes in acute inflammation. Monocytes subsequently migrate into tissues and differentiate into macrophages.", "exam_trap": "Macrophages are important later in the inflammatory response and in tissue repair, but they are not normally the first predominant leukocyte in acute inflammation.", "takeaway": "Acute inflammation → neutrophils early → macrophages later.", "source": "[RBP10]."},
  {"id": "MAK-212", "subject": "Pathology: inflammation & wound healing", "topic": "Histamine", "title": "Histamine", "stem": "A patient develops immediate local swelling and erythema following tissue injury. Which mediator is particularly important in producing early vasodilatation and increased vascular permeability?", "options": {"A": "Histamine", "B": "Insulin", "C": "Albumin", "D": "Haemoglobin", "E": "Erythropoietin"}, "correct_letter": "A", "correct_answer": "A. Histamine", "why_correct": "Histamine released principally from mast cells contributes to vasodilatation and increased vascular permeability during the early inflammatory response.", "exam_trap": "Do not confuse histamine-mediated vascular changes with later leukocyte-mediated tissue responses.", "takeaway": "Histamine → early vascular changes of inflammation.", "source": "[RBP10]."},
  {"id": "MAK-213", "subject": "Pathology: inflammation & wound healing", "topic": "Complement", "title": "Complement", "stem": "A patient has activation of the complement system during an acute bacterial infection. Which complement component is an important opsonin?", "options": {"A": "C1", "B": "C3b", "C": "C5", "D": "C7", "E": "C9"}, "correct_letter": "B", "correct_answer": "B. C3b", "why_correct": "C3b binds to microbial surfaces and facilitates recognition and phagocytosis by phagocytes.", "exam_trap": "C5a is strongly associated with chemotaxis and inflammatory signalling; C3b is the classic complement opsonin.", "takeaway": "C3b = opsonisation.", "source": "[RBP10]."},
  {"id": "MAK-214", "subject": "Pathology: inflammation & wound healing", "topic": "Complement and chemotaxis", "title": "Complement and chemotaxis", "stem": "Which complement-derived molecule has an important role in attracting neutrophils to an area of inflammation?", "options": {"A": "C3b", "B": "C5a", "C": "C1 inhibitor", "D": "C8", "E": "C9"}, "correct_letter": "B", "correct_answer": "B. C5a", "why_correct": "C5a is a potent inflammatory mediator and chemoattractant for neutrophils.", "exam_trap": "C3b and C5a have different principal functions: C3b is strongly associated with opsonisation, whereas C5a promotes chemotaxis.", "takeaway": "C3b → opsonisation; C5a → chemotaxis.", "source": "[RBP10]."},
  {"id": "MAK-215", "subject": "Pathology: inflammation & wound healing", "topic": "Chronic inflammation", "title": "Chronic inflammation", "stem": "A patient has a chronic inflammatory condition with a tissue infiltrate predominantly composed of macrophages and lymphocytes. Which description best fits the process?", "options": {"A": "Acute inflammation", "B": "Chronic inflammation", "C": "Immediate hypersensitivity only", "D": "Haemostasis", "E": "Primary intention healing"}, "correct_letter": "B", "correct_answer": "B. Chronic inflammation", "why_correct": "Chronic inflammation is characterised by persistent inflammatory cell infiltration, particularly macrophages and lymphocytes, together with ongoing tissue injury and repair.", "exam_trap": "Chronic inflammation is not simply \"longer acute inflammation\"; the cellular pattern and tissue effects differ.", "takeaway": "Chronic inflammation → macrophages + lymphocytes + ongoing tissue injury/repair.", "source": "[RBP10]."},
  {"id": "MAK-216", "subject": "Pathology: inflammation & wound healing", "topic": "Granuloma", "title": "Granuloma", "stem": "A patient with persistent intracellular infection develops discrete collections of activated macrophages with surrounding lymphocytes. What pathological structure is most likely?", "options": {"A": "Abscess", "B": "Granuloma", "C": "Haematoma", "D": "Seroma", "E": "Keloid"}, "correct_letter": "B", "correct_answer": "B. Granuloma", "why_correct": "A granuloma is an organised collection of activated macrophages, often with surrounding lymphocytes, formed in response to persistent inflammatory stimuli.", "exam_trap": "", "takeaway": "Persistent stimulus → macrophage aggregation → granuloma.", "source": "[RBP10]."},
  {"id": "MAK-217", "subject": "Pathology: inflammation & wound healing", "topic": "Caseous necrosis", "title": "Caseous necrosis", "stem": "A biopsy from a chronic granulomatous lesion shows soft, friable, cheese-like necrotic material. Which type of necrosis is classically associated with this appearance?", "options": {"A": "Coagulative", "B": "Liquefactive", "C": "Caseous", "D": "Fat", "E": "Fibrinoid"}, "correct_letter": "C", "correct_answer": "C. Caseous", "why_correct": "Caseous necrosis is classically associated with granulomatous infections such as tuberculosis.", "exam_trap": "Do not automatically select liquefactive necrosis whenever necrotic tissue is described as soft. The \"cheese-like\" description is a classic clue to caseous necrosis.", "takeaway": "Caseous necrosis → think granulomatous infection, classically tuberculosis.", "source": "[RBP10]."},
  {"id": "MAK-218", "subject": "Pathology: inflammation & wound healing", "topic": "Coagulative necrosis", "title": "Coagulative necrosis", "stem": "A patient develops an infarction of the kidney. Which type of necrosis is most characteristic of the resulting tissue injury?", "options": {"A": "Liquefactive", "B": "Caseous", "C": "Coagulative", "D": "Fat", "E": "Fibrinoid"}, "correct_letter": "C", "correct_answer": "C. Coagulative", "why_correct": "Ischaemic infarction of most solid organs produces coagulative necrosis, with preservation of the basic tissue architecture for a period despite cell death.", "exam_trap": "The brain is the major exception: cerebral infarction classically produces liquefactive necrosis.", "takeaway": "Solid-organ infarction → coagulative necrosis; brain infarction → liquefactive necrosis.", "source": "[RBP10]."},
  {"id": "MAK-220", "subject": "Pathology: inflammation & wound healing", "topic": "Apoptosis", "title": "Apoptosis", "stem": "Which statement best describes apoptosis?", "options": {"A": "It invariably causes extensive surrounding inflammation", "B": "It is uncontrolled tissue destruction", "C": "It involves programmed cell death", "D": "It always follows severe ischaemia", "E": "It occurs only in malignant cells"}, "correct_letter": "C", "correct_answer": "C. It involves programmed cell death", "why_correct": "Apoptosis is regulated programmed cell death that removes unwanted or damaged cells with relatively little surrounding inflammation.", "exam_trap": "Apoptosis is a normal physiological process as well as a mechanism of pathological cell removal.", "takeaway": "Apoptosis = regulated cell deletion, usually with limited inflammation.", "source": "[RBP10]."},
  {"id": "MAK-221", "subject": "Pathology: inflammation & wound healing", "topic": "Reversible cell injury", "title": "Reversible cell injury", "stem": "A cell exposed to a temporary reduction in oxygen develops cellular swelling but recovers after restoration of perfusion. What does this represent?", "options": {"A": "Irreversible cell injury", "B": "Reversible cell injury", "C": "Apoptosis only", "D": "Caseous necrosis", "E": "Metastasis"}, "correct_letter": "B", "correct_answer": "B. Reversible cell injury", "why_correct": "Cellular swelling is a classic early manifestation of reversible cell injury. If the insult is removed before irreversible mitochondrial and membrane damage develops, the cell can recover.", "exam_trap": "", "takeaway": "Early injury + removal of insult → potentially reversible cellular damage.", "source": "[RBP10]."},
  {"id": "MAK-222", "subject": "Pathology: inflammation & wound healing", "topic": "proliferative phase", "title": "Wound healing: proliferative phase", "stem": "Which cell is principally responsible for producing new collagen during the proliferative phase of wound healing?", "options": {"A": "Neutrophil", "B": "Fibroblast", "C": "Platelet", "D": "Red blood cell", "E": "Osteoclast"}, "correct_letter": "B", "correct_answer": "B. Fibroblast", "why_correct": "Fibroblasts migrate into the wound and synthesise extracellular matrix, including collagen, during the proliferative phase.", "exam_trap": "Macrophages are important coordinators of healing, but fibroblasts are the key collagen-producing cells.", "takeaway": "Fibroblast → collagen and extracellular matrix production.", "source": "[RBP10]."},
  {"id": "MAK-223", "subject": "Pathology: inflammation & wound healing", "topic": "Collagen maturation", "title": "Collagen maturation", "stem": "A patient has impaired collagen cross-linking. Which nutrient deficiency is classically associated with impaired collagen maturation and poor wound healing?", "options": {"A": "Vitamin A", "B": "Vitamin B12", "C": "Vitamin C", "D": "Vitamin D", "E": "Vitamin K"}, "correct_letter": "C", "correct_answer": "C. Vitamin C", "why_correct": "Vitamin C is required for hydroxylation of proline and lysine residues during collagen synthesis. Deficiency impairs collagen maturation and wound healing.", "exam_trap": "Vitamin K is associated with coagulation-factor activation rather than collagen hydroxylation.", "takeaway": "Vitamin C → collagen hydroxylation → normal wound healing.", "source": "[RBP10]."},
  {"id": "MAK-224", "subject": "Pathology: inflammation & wound healing", "topic": "Wound healing and oxygen", "title": "Wound healing and oxygen", "stem": "A patient with peripheral vascular disease has a poorly healing lower-limb wound. Which factor is most directly impaired by reduced tissue perfusion?", "options": {"A": "Oxygen delivery to the wound", "B": "Intrinsic factor production", "C": "Bile salt recycling", "D": "Cerebrospinal fluid production", "E": "Thyroid hormone synthesis"}, "correct_letter": "A", "correct_answer": "A. Oxygen delivery to the wound", "why_correct": "Adequate oxygen delivery is essential for cellular metabolism, collagen synthesis, fibroblast function and host defence during wound healing.", "exam_trap": "", "takeaway": "Poor perfusion → poor oxygen delivery → impaired wound healing.", "source": "[RBP10]."},
  {"id": "MAK-225", "subject": "Pathology: inflammation & wound healing", "topic": "primary intention", "title": "Wound healing: primary intention", "stem": "A clean surgical incision is closed immediately with accurately opposed wound edges. What type of healing is this?", "options": {"A": "Secondary intention", "B": "Tertiary intention", "C": "Primary intention", "D": "Granulomatous healing", "E": "Fibrotic necrosis"}, "correct_letter": "C", "correct_answer": "C. Primary intention", "why_correct": "Primary intention occurs when clean wound edges are directly approximated, producing relatively little granulation tissue and a smaller scar.", "exam_trap": "A contaminated or infected wound deliberately left open to heal by granulation is not primary intention.", "takeaway": "Clean, closely apposed wound → primary intention.", "source": "[RBP10]."},
  {"id": "MAK-226", "subject": "Pathology: inflammation & wound healing", "topic": "secondary intention", "title": "Wound healing: secondary intention", "stem": "A large contaminated wound is left open and gradually fills with granulation tissue before contracting and epithelialising. Which process is occurring?", "options": {"A": "Primary intention", "B": "Secondary intention", "C": "Immediate regeneration", "D": "Apoptosis", "E": "Caseous healing"}, "correct_letter": "B", "correct_answer": "B. Secondary intention", "why_correct": "Secondary intention occurs when wound edges cannot be directly approximated. Healing involves granulation tissue formation, contraction and epithelialisation, usually producing a larger scar.", "exam_trap": "", "takeaway": "Open wound → granulation + contraction + larger scar = secondary intention.", "source": "[RBP10]."},
  {"id": "MAK-227", "subject": "Pathology: inflammation & wound healing", "topic": "Myofibroblasts", "title": "Myofibroblasts", "stem": "Which cell is particularly important in wound contraction?", "options": {"A": "Myofibroblast", "B": "Neutrophil", "C": "Eosinophil", "D": "Osteoblast", "E": "Chondrocyte"}, "correct_letter": "A", "correct_answer": "A. Myofibroblast", "why_correct": "Myofibroblasts possess contractile properties and contribute significantly to wound contraction.", "exam_trap": "Fibroblasts produce extracellular matrix; myofibroblasts are particularly associated with contraction.", "takeaway": "Myofibroblast → wound contraction.", "source": "[RBP10]."},
  {"id": "MAK-228", "subject": "Pathology: inflammation & wound healing", "topic": "Hypertrophic scar", "title": "Hypertrophic scar", "stem": "A patient develops a raised scar after surgery that remains confined to the original wound boundaries. Which diagnosis is most appropriate?", "options": {"A": "Keloid scar", "B": "Hypertrophic scar", "C": "Desmoid tumour", "D": "Fibrosarcoma", "E": "Granuloma"}, "correct_letter": "B", "correct_answer": "B. Hypertrophic scar", "why_correct": "A hypertrophic scar is raised but remains within the original wound boundaries. A keloid extends beyond them.", "exam_trap": "The relationship to the original wound margins is the key discriminator.", "takeaway": "Hypertrophic scar = stays within wound; keloid = extends beyond wound.", "source": "[RBP10]."},
  {"id": "MAK-230", "subject": "Pathology: oncology & haematology", "topic": "Metastatic spread", "title": "Metastatic spread", "stem": "A patient with a malignant solid tumour develops tumour deposits in the liver. Which route commonly allows tumour cells from many abdominal and gastrointestinal primaries to reach the liver?", "options": {"A": "Portal venous circulation", "B": "Pulmonary artery", "C": "Thoracic duct only", "D": "Coronary circulation", "E": "Cerebral venous system"}, "correct_letter": "A", "correct_answer": "A. Portal venous circulation", "why_correct": "Tumour cells from organs draining into the portal venous system can reach the liver through portal venous blood.", "exam_trap": "", "takeaway": "Many GI/abdominal tumours → portal venous drainage → liver metastases.", "source": "[RBP10]."},
  {"id": "MAK-231", "subject": "Pathology: oncology & haematology", "topic": "Tumour grading", "title": "Tumour grading", "stem": "A histopathology report describes a tumour as \"high grade\". What does grading primarily assess?", "options": {"A": "Anatomical tumour spread", "B": "Histological differentiation and biological aggressiveness", "C": "Presence of distant metastases only", "D": "Patient's age", "E": "Surgical margin status"}, "correct_letter": "B", "correct_answer": "B. Histological differentiation and biological aggressiveness", "why_correct": "Tumour grade reflects histological characteristics such as differentiation and mitotic activity and provides information about tumour biology.", "exam_trap": "Grade and stage are different concepts. Stage describes the extent of disease.", "takeaway": "Grade = tumour biology; stage = anatomical extent.", "source": "[RBP10]."},
  {"id": "MAK-232", "subject": "Pathology: oncology & haematology", "topic": "Tumour staging", "title": "Tumour staging", "stem": "Which feature is primarily assessed by tumour staging?", "options": {"A": "Histological resemblance to the tissue of origin", "B": "Anatomical extent of disease", "C": "Cellular morphology alone", "D": "Degree of collagen production", "E": "Apoptotic rate alone"}, "correct_letter": "B", "correct_answer": "B. Anatomical extent of disease", "why_correct": "Staging describes the extent of a malignancy, including local invasion, regional nodal involvement and distant metastasis where applicable.", "exam_trap": "", "takeaway": "Stage = where the cancer has spread; grade = what the cancer looks/behaves like microscopically.", "source": "[RBP10]."},
  {"id": "MAK-233", "subject": "Pathology: oncology & haematology", "topic": "Tumour suppressor genes", "title": "Tumour suppressor genes", "stem": "Loss of function of a tumour suppressor gene generally contributes to cancer development by:", "options": {"A": "Increasing the removal of abnormal cells", "B": "Removing a restraint on cell proliferation", "C": "Preventing DNA replication entirely", "D": "Increasing normal apoptosis", "E": "Blocking angiogenesis in all tumours"}, "correct_letter": "B", "correct_answer": "B. Removing a restraint on cell proliferation", "why_correct": "Tumour suppressor genes normally help regulate cell proliferation, DNA integrity and/or cell survival. Loss of their function can facilitate uncontrolled growth.", "exam_trap": "Tumour suppressor genes are generally described as the \"brakes\"; oncogenes function more like an accelerator.", "takeaway": "Tumour suppressor loss → loss of growth restraint.", "source": "[RBP10]."},
  {"id": "MAK-234", "subject": "Pathology: oncology & haematology", "topic": "Oncogenes", "title": "Oncogenes", "stem": "Activation of an oncogene most directly promotes malignant transformation by:", "options": {"A": "Permanently inhibiting cell proliferation", "B": "Promoting inappropriate cellular growth or survival", "C": "Preventing angiogenesis", "D": "Increasing DNA repair in all circumstances", "E": "Increasing normal tissue differentiation"}, "correct_letter": "B", "correct_answer": "B. Promoting inappropriate cellular growth or survival", "why_correct": "Oncogenes arise from altered or abnormally activated genes that promote proliferation or survival.", "exam_trap": "Do not reverse the roles of oncogenes and tumour suppressor genes.", "takeaway": "Oncogene activation → inappropriate growth/survival signalling.", "source": "[RBP10]."},
  {"id": "MAK-235", "subject": "Pathology: inflammation & wound healing", "topic": "Hypersensitivity type I", "title": "Hypersensitivity type I", "stem": "A patient develops urticaria, bronchospasm and hypotension within minutes of exposure to an allergen. Which immunological mechanism is most characteristic?", "options": {"A": "IgE-mediated hypersensitivity", "B": "IgG-mediated immune complex disease only", "C": "T-cell-mediated delayed hypersensitivity", "D": "Direct complement deficiency", "E": "Autoantibody destruction of red cells"}, "correct_letter": "A", "correct_answer": "A. IgE-mediated hypersensitivity", "why_correct": "Immediate hypersensitivity reactions are mediated by allergen-specific IgE bound to mast cells and basophils. Cross-linking triggers mediator release.", "exam_trap": "Do not confuse immediate IgE-mediated reactions with delayed T-cell-mediated hypersensitivity.", "takeaway": "Immediate allergy/anaphylaxis → IgE + mast-cell mediator release.", "source": "[REI13]."},
  {"id": "MAK-236", "subject": "Pathology: inflammation & wound healing", "topic": "Type IV hypersensitivity", "title": "Type IV hypersensitivity", "stem": "A patient develops a delayed skin reaction approximately 48 hours after exposure to an antigen. Which mechanism is most characteristic?", "options": {"A": "IgE-mediated mast-cell degranulation", "B": "T-cell-mediated hypersensitivity", "C": "Immune-complex deposition only", "D": "Direct red-cell haemolysis", "E": "IgM-mediated complement activation only"}, "correct_letter": "B", "correct_answer": "B. T-cell-mediated hypersensitivity", "why_correct": "Type IV hypersensitivity is cell-mediated rather than antibody-mediated and typically develops over a delayed time course.", "exam_trap": "\"Delayed\" is the major clue.", "takeaway": "Type IV hypersensitivity → T cells → delayed reaction.", "source": "[REI13]."},
  {"id": "MAK-237", "subject": "Pathology: inflammation & wound healing", "topic": "Autoimmune disease", "title": "Autoimmune disease", "stem": "Which immunological failure most directly permits development of autoimmune disease?", "options": {"A": "Loss of self-tolerance", "B": "Increased oxygen delivery", "C": "Increased erythropoiesis", "D": "Increased platelet production", "E": "Reduced gastric acid secretion"}, "correct_letter": "A", "correct_answer": "A. Loss of self-tolerance", "why_correct": "Autoimmunity occurs when immune responses are directed against self-antigens because mechanisms maintaining self-tolerance have failed.", "exam_trap": "", "takeaway": "Autoimmunity = immune response against self → failure of tolerance.", "source": "[REI13]."},
  {"id": "MAK-238", "subject": "Pathology: oncology & haematology", "topic": "microcytosis", "title": "Anaemia: microcytosis", "stem": "A patient has fatigue and the following blood results: Hb: low MCV: low MCH: low Which diagnosis is most consistent with this red-cell pattern?", "options": {"A": "Iron-deficiency anaemia", "B": "Acute blood loss before physiological compensation", "C": "Vitamin B12 deficiency", "D": "Folate deficiency", "E": "Aplastic anaemia"}, "correct_letter": "A", "correct_answer": "A. Iron-deficiency anaemia", "why_correct": "Iron deficiency classically produces a microcytic, hypochromic anaemia.", "exam_trap": "Vitamin B12 and folate deficiency characteristically produce macrocytosis rather than microcytosis.", "takeaway": "Iron deficiency → microcytic/hypochromic anaemia.", "source": "[HEH7]."},
  {"id": "MAK-239", "subject": "Pathology: oncology & haematology", "topic": "macrocytosis", "title": "Anaemia: macrocytosis", "stem": "A patient has anaemia with a markedly increased MCV. Which deficiency is classically associated with megaloblastic macrocytic anaemia?", "options": {"A": "Iron", "B": "Vitamin B12", "C": "Vitamin C", "D": "Vitamin K", "E": "Calcium"}, "correct_letter": "B", "correct_answer": "B. Vitamin B12", "why_correct": "Vitamin B12 deficiency can cause megaloblastic macrocytic anaemia due to impaired DNA synthesis. Folate deficiency produces a similar megaloblastic pattern.", "exam_trap": "Do not assume that every macrocytic anaemia is due to B12 deficiency; alcohol excess, liver disease, hypothyroidism and other causes can also produce macrocytosis.", "takeaway": "B12/folate deficiency → impaired DNA synthesis → megaloblastic macrocytosis.", "source": "[HEH7]."},
  {"id": "MAK-240", "subject": "Pathology: oncology & haematology", "topic": "Platelet function", "title": "Platelet function", "stem": "A patient has recurrent mucosal bleeding and easy bruising. Platelet count is normal, but platelet function is abnormal. Which bleeding pattern is most characteristic of a primary haemostatic defect?", "options": {"A": "Deep muscle haematomas", "B": "Haemarthroses", "C": "Mucosal bleeding and petechiae", "D": "Retroperitoneal bleeding only", "E": "Delayed bleeding several days after surgery only"}, "correct_letter": "C", "correct_answer": "C. Mucosal bleeding and petechiae", "why_correct": "Primary haemostasis depends principally on platelet plug formation. Platelet disorders typically produce mucocutaneous bleeding such as petechiae, epistaxis and gum bleeding. By contrast, coagulation-factor disorders more typically cause deep tissue bleeding and haemarthroses.", "exam_trap": "Use the bleeding phenotype: Platelets → mucocutaneous. Coagulation factors → deep tissue/joint bleeding.", "takeaway": "Mucosal bleeding + petechiae → think platelet/primary haemostasis problem.", "source": "[HEH7]."},
  {"id": "MAK-241", "subject": "Pathology: oncology & haematology", "topic": "Extrinsic coagulation pathway", "title": "Extrinsic coagulation pathway", "stem": "A patient has an isolated prolonged prothrombin time (PT) with a normal activated partial thromboplastin time (APTT). Which pathway is most specifically being assessed by the PT?", "options": {"A": "Intrinsic pathway", "B": "Extrinsic pathway", "C": "Fibrinolytic pathway", "D": "Platelet adhesion pathway", "E": "Complement pathway"}, "correct_letter": "B", "correct_answer": "B. Extrinsic pathway", "why_correct": "The PT primarily assesses the extrinsic and common coagulation pathways and is particularly sensitive to factor VII.", "exam_trap": "APTT assesses the intrinsic and common pathways.", "takeaway": "PT → extrinsic + common pathway. APTT → intrinsic + common pathway.", "source": "[HEH7]."},
  {"id": "MAK-242", "subject": "Pathology: oncology & haematology", "topic": "Activated partial thromboplastin time", "title": "Activated partial thromboplastin time", "stem": "A patient has an isolated prolonged APTT with a normal PT. Which group of coagulation factors is being assessed predominantly?", "options": {"A": "Extrinsic pathway factors only", "B": "Intrinsic and common pathway factors", "C": "Platelet receptors only", "D": "Fibrinolytic factors only", "E": "Red-cell membrane proteins"}, "correct_letter": "B", "correct_answer": "B. Intrinsic and common pathway factors", "why_correct": "APTT assesses the intrinsic and common coagulation pathways.", "exam_trap": "", "takeaway": "APTT → intrinsic + common pathway.", "source": "[HEH7]."},
  {"id": "MAK-243", "subject": "Pathology: oncology & haematology", "topic": "Fibrinogen", "title": "Fibrinogen", "stem": "During coagulation, fibrinogen is converted into fibrin. Which enzyme catalyses this conversion?", "options": {"A": "Plasmin", "B": "Thrombin", "C": "Factor VII", "D": "Protein C", "E": "Antithrombin"}, "correct_letter": "B", "correct_answer": "B. Thrombin", "why_correct": "Thrombin converts soluble fibrinogen into insoluble fibrin, which forms the structural framework of the clot.", "exam_trap": "Plasmin performs the opposite major task: fibrin degradation during fibrinolysis.", "takeaway": "Thrombin → fibrinogen → fibrin.", "source": "[HEH7]."},
  {"id": "MAK-244", "subject": "Pathology: oncology & haematology", "topic": "Factor XIII", "title": "Factor XIII", "stem": "A patient has recurrent bleeding despite normal PT and APTT. Which coagulation abnormality should be considered?", "options": {"A": "Factor VII deficiency", "B": "Factor VIII deficiency", "C": "Factor XIII deficiency", "D": "Factor X deficiency", "E": "Factor V deficiency"}, "correct_letter": "C", "correct_answer": "C. Factor XIII deficiency", "why_correct": "Factor XIII stabilises fibrin by cross-linking fibrin strands. Because it acts after the fibrin clot has formed, routine PT and APTT may be normal in factor XIII deficiency.", "exam_trap": "A normal PT/APTT does not exclude every coagulation disorder.", "takeaway": "Factor XIII = fibrin stabilisation; deficiency can have normal PT/APTT.", "source": "[HEH7]."},
  {"id": "MAK-245", "subject": "Pathology: oncology & haematology", "topic": "Vitamin K-dependent coagulation factors", "title": "Vitamin K-dependent coagulation factors", "stem": "Which group consists predominantly of vitamin K-dependent coagulation factors?", "options": {"A": "II, VII, IX and X", "B": "I, V, VIII and XIII", "C": "III, V, XI and XII", "D": "VIII, IX, XI and XII", "E": "I, II, V and VIII"}, "correct_letter": "A", "correct_answer": "A. II, VII, IX and X", "why_correct": "Factors II, VII, IX and X are vitamin K dependent. Protein C and protein S are also vitamin K-dependent anticoagulant proteins.", "exam_trap": "Factor VIII is not vitamin K dependent.", "takeaway": "Vitamin K → II, VII, IX, X + proteins C and S.", "source": "[HEH7]."},
  {"id": "MAK-246", "subject": "Pathology: oncology & haematology", "topic": "Disseminated intravascular coagulation", "title": "Disseminated intravascular coagulation", "stem": "A critically ill patient develops widespread bleeding. Blood tests show prolonged PT and APTT, thrombocytopenia and a markedly reduced fibrinogen concentration. Which diagnosis best explains this pattern?", "options": {"A": "Isolated haemophilia A", "B": "Disseminated intravascular coagulation", "C": "Immune thrombocytopenia", "D": "Isolated vitamin B12 deficiency", "E": "Factor XIII deficiency"}, "correct_letter": "B", "correct_answer": "B. Disseminated intravascular coagulation", "why_correct": "DIC involves widespread activation of coagulation, consumption of platelets and coagulation factors, and secondary fibrinolysis. Patients can therefore develop both thrombosis and bleeding.", "exam_trap": "DIC is a systemic consumptive process rather than an isolated platelet disorder.", "takeaway": "DIC → consumption of platelets/factors → thrombosis + bleeding.", "source": "[HEH7]."},
  {"id": "MAK-247", "subject": "Pathology: oncology & haematology", "topic": "D-dimer", "title": "D-dimer", "stem": "Which substance is measured by the D-dimer test?", "options": {"A": "Intact fibrinogen", "B": "Cross-linked fibrin degradation products", "C": "Platelet membrane glycoprotein", "D": "Free haemoglobin", "E": "Factor VIII concentration"}, "correct_letter": "B", "correct_answer": "B. Cross-linked fibrin degradation products", "why_correct": "D-dimer is generated when cross-linked fibrin is broken down by fibrinolysis.", "exam_trap": "", "takeaway": "D-dimer = breakdown product of cross-linked fibrin.", "source": "NICE NG158, Venous thromboembolic diseases; updated 2023."},
  {"id": "MAK-249", "subject": "Major trauma & fluids", "topic": "Acute haemorrhage", "title": "Acute haemorrhage", "stem": "A patient develops sudden major blood loss. Which physiological response occurs early to help maintain arterial pressure?", "options": {"A": "Reduced sympathetic activity", "B": "Increased vagal activity", "C": "Increased sympathetic activity", "D": "Immediate increase in erythrocyte mass", "E": "Immediate increase in albumin synthesis"}, "correct_letter": "C", "correct_answer": "C. Increased sympathetic activity", "why_correct": "Acute blood loss reduces effective circulating volume and arterial pressure. Baroreceptor-mediated sympathetic activation increases heart rate, contractility and peripheral vasoconstriction.", "exam_trap": "New red-cell production takes much longer and cannot compensate immediately.", "takeaway": "Acute blood loss → sympathetic response first; haematological replacement is later.", "source": "[GH14]."},
  {"id": "MAK-250", "subject": "Major trauma & fluids", "topic": "Hypovolaemic shock", "title": "Hypovolaemic shock", "stem": "Which finding is most characteristic of significant hypovolaemic shock?", "options": {"A": "Warm peripheries with marked bradycardia", "B": "Reduced sympathetic tone", "C": "Peripheral vasoconstriction", "D": "Increased urine output", "E": "Increased venous capacitance with no compensatory response"}, "correct_letter": "C", "correct_answer": "C. Peripheral vasoconstriction", "why_correct": "Sympathetic activation causes peripheral vasoconstriction in an attempt to preserve arterial pressure and perfusion of vital organs.", "exam_trap": "", "takeaway": "Hypovolaemia → sympathetic vasoconstriction → preservation of central perfusion.", "source": "[GH14]."},
  {"id": "MAK-251", "subject": "Major trauma & fluids", "topic": "Cardiogenic shock", "title": "Cardiogenic shock", "stem": "A patient develops profound hypotension following extensive myocardial infarction. Cardiac output is markedly reduced despite adequate circulating volume. Which type of shock is most appropriate?", "options": {"A": "Hypovolaemic shock", "B": "Cardiogenic shock", "C": "Obstructive shock", "D": "Neurogenic shock", "E": "Distributive shock"}, "correct_letter": "B", "correct_answer": "B. Cardiogenic shock", "why_correct": "Cardiogenic shock occurs when the heart cannot generate sufficient cardiac output to maintain tissue perfusion, despite adequate intravascular volume.", "exam_trap": "", "takeaway": "Pump failure + inadequate cardiac output → cardiogenic shock.", "source": "[GH14]."},
  {"id": "MAK-252", "subject": "Major trauma & fluids", "topic": "Obstructive shock", "title": "Obstructive shock", "stem": "A trauma patient develops sudden hypotension, distended neck veins and severe respiratory compromise. Which category of shock should be considered?", "options": {"A": "Hypovolaemic", "B": "Cardiogenic", "C": "Obstructive", "D": "Endocrine", "E": "Anaemic"}, "correct_letter": "C", "correct_answer": "C. Obstructive", "why_correct": "Obstructive shock results from mechanical obstruction to cardiac filling or output. Important causes include massive pulmonary embolism and cardiac tamponade; tension pneumothorax can also produce obstructive physiology.", "exam_trap": "Do not assume every shocked trauma patient is simply hypovolaemic.", "takeaway": "Mechanical obstruction to circulation → obstructive shock.", "source": "[GH14]."},
  {"id": "MAK-253", "subject": "Major trauma & fluids", "topic": "Septic shock physiology", "title": "Septic shock physiology", "stem": "A patient with severe infection becomes hypotensive despite apparently adequate intravascular volume. Which haemodynamic abnormality is particularly characteristic of early distributive septic shock?", "options": {"A": "Markedly increased systemic vascular resistance", "B": "Reduced systemic vascular resistance", "C": "Complete absence of cardiac output", "D": "Increased blood viscosity as the primary mechanism", "E": "Mechanical obstruction of venous return"}, "correct_letter": "B", "correct_answer": "B. Reduced systemic vascular resistance", "why_correct": "Sepsis can cause profound vasodilatation and reduced systemic vascular resistance, producing distributive shock.", "exam_trap": "", "takeaway": "Septic/distributive shock → vasodilatation → ↓SVR.", "source": "[GH14]."},
  {"id": "MAK-254", "subject": "Major trauma & fluids", "topic": "Oxygen delivery", "title": "Oxygen delivery", "stem": "Which equation best describes systemic oxygen delivery?", "options": {"A": "Cardiac output × arterial oxygen content", "B": "Heart rate × venous oxygen content", "C": "Stroke volume × venous oxygen saturation", "D": "Blood pressure × respiratory rate", "E": "Cardiac output × carbon dioxide content"}, "correct_letter": "A", "correct_answer": "A. Cardiac output × arterial oxygen content", "why_correct": "Systemic oxygen delivery (DO2) depends principally on cardiac output and arterial oxygen content.", "exam_trap": "", "takeaway": "DO2 = cardiac output × arterial oxygen content.", "source": "[GH14]."},
  {"id": "MAK-255", "subject": "Major trauma & fluids", "topic": "red cells", "title": "Blood transfusion: red cells", "stem": "A stable adult undergoing elective surgery has anaemia but no active bleeding or acute coronary syndrome. According to NICE transfusion guidance, what restrictive haemoglobin threshold is generally considered for red-cell transfusion?", "options": {"A": "50 g/L", "B": "60 g/L", "C": "70 g/L", "D": "90 g/L", "E": "110 g/L"}, "correct_letter": "C", "correct_answer": "C. 70 g/L", "why_correct": "NICE NG24 recommends a restrictive red-cell transfusion threshold of 70 g/L for patients who require transfusion and do not have major haemorrhage or acute coronary syndrome, with a post-transfusion target of 70–90 g/L.", "exam_trap": "This threshold does not apply indiscriminately to major haemorrhage or every clinical circumstance.", "takeaway": "Stable adult, no major haemorrhage/ACS → restrictive RBC threshold around 70 g/L.", "source": "NICE NG24."},
  {"id": "MAK-256", "subject": "Major trauma & fluids", "topic": "Single-unit transfusion", "title": "Single-unit transfusion", "stem": "A stable adult with no active bleeding is judged to need a red-cell transfusion. What does NICE recommend considering?", "options": {"A": "Automatically transfuse four units", "B": "Give one unit and reassess", "C": "Give two units regardless of response", "D": "Avoid haemoglobin reassessment", "E": "Give platelets simultaneously"}, "correct_letter": "B", "correct_answer": "B. Give one unit and reassess", "why_correct": "NICE recommends considering single-unit red-cell transfusion in adults who are not actively bleeding, followed by clinical reassessment and haemoglobin measurement before giving further units if needed.", "exam_trap": "", "takeaway": "No active bleeding → one unit → reassess → further blood only if required.", "source": "NICE NG24."},
  {"id": "MAK-257", "subject": "Major trauma & fluids", "topic": "Fresh frozen plasma", "title": "Fresh frozen plasma", "stem": "A patient is actively bleeding and has a significant coagulation abnormality. Which blood component provides multiple coagulation factors?", "options": {"A": "Red cells", "B": "Platelets", "C": "Fresh frozen plasma", "D": "Albumin", "E": "Cryoprecipitate only"}, "correct_letter": "C", "correct_answer": "C. Fresh frozen plasma", "why_correct": "Fresh frozen plasma contains multiple coagulation factors and may be considered in clinically significant bleeding when coagulation tests are abnormal. NICE advises against using FFP simply to correct abnormal coagulation tests in patients who are not bleeding and are not undergoing an invasive procedure with significant bleeding risk.", "exam_trap": "FFP is not a general-purpose treatment for an abnormal INR in a clinically well, non-bleeding patient.", "takeaway": "FFP → multiple coagulation factors; use requires clinical context.", "source": "NICE NG24."},
  {"id": "MAK-258", "subject": "Major trauma & fluids", "topic": "Cryoprecipitate", "title": "Cryoprecipitate", "stem": "A patient with major bleeding has a critically low fibrinogen concentration. Which blood component is particularly rich in fibrinogen?", "options": {"A": "Red cells", "B": "Platelets", "C": "Fresh frozen plasma", "D": "Cryoprecipitate", "E": "Albumin"}, "correct_letter": "D", "correct_answer": "D. Cryoprecipitate", "why_correct": "Cryoprecipitate contains concentrated fibrinogen along with other proteins including factor VIII, von Willebrand factor and factor XIII. NICE recommends considering cryoprecipitate in clinically significant bleeding when fibrinogen is below 1.5 g/L in patients without major haemorrhage; major haemorrhage protocols require separate consideration.", "exam_trap": "", "takeaway": "Low fibrinogen + clinically significant bleeding → consider cryoprecipitate.", "source": "NICE NG24."},
  {"id": "MAK-259", "subject": "Major trauma & fluids", "topic": "Platelet transfusion", "title": "Platelet transfusion", "stem": "A patient with thrombocytopenia requires surgery with a substantial risk of bleeding. Which platelet count is the commonly used NICE threshold below which prophylactic platelet transfusion is considered for invasive procedures or surgery?", "options": {"A": "10 × 10⁹/L", "B": "20 × 10⁹/L", "C": "30 × 10⁹/L", "D": "50 × 10⁹/L", "E": "150 × 10⁹/L"}, "correct_letter": "D", "correct_answer": "D. 50 × 10⁹/L", "why_correct": "NICE recommends considering prophylactic platelet transfusion to raise the platelet count above 50 × 10⁹/L for patients undergoing invasive procedures or surgery, with higher thresholds for certain critical sites.", "exam_trap": "The threshold is not identical for every procedure; critical-site surgery may require a higher target.", "takeaway": "Surgery/invasive procedure → commonly target platelets >50 × 10⁹/L; critical sites may require higher.", "source": "NICE NG24."},
  {"id": "MAK-260", "subject": "Major trauma & fluids", "topic": "Transfusion reaction", "title": "Transfusion reaction", "stem": "A patient develops fever, chills, back pain and hypotension shortly after a blood transfusion. Which complication must be treated as a possible acute haemolytic transfusion reaction?", "options": {"A": "Delayed iron deficiency", "B": "Acute haemolytic transfusion reaction", "C": "Chronic anaemia", "D": "Uncomplicated dilutional anaemia", "E": "Physiological haemodilution only"}, "correct_letter": "B", "correct_answer": "B. Acute haemolytic transfusion reaction", "why_correct": "Acute haemolysis after transfusion is a medical emergency. Fever, rigors, pain, hypotension and haemoglobinuria can occur. The transfusion should be stopped and the patient assessed and managed urgently according to the local transfusion-reaction protocol.", "exam_trap": "", "takeaway": "Suspected acute haemolytic reaction → stop transfusion + urgent assessment.", "source": "NICE NG24; British Society for Haematology (BSH) guidelines on the management of acute transfusion reactions."},
  {"id": "MAK-261", "subject": "Genetics", "topic": "Autosomal dominant inheritance", "title": "Autosomal dominant inheritance", "stem": "A patient has a genetic disorder. One affected parent is heterozygous and the other parent is unaffected and does not carry the pathogenic variant. What is the approximate probability that each child will inherit the variant?", "options": {"A": "0%", "B": "10%", "C": "25%", "D": "50%", "E": "100%"}, "correct_letter": "D", "correct_answer": "D. 50%", "why_correct": "In a typical autosomal dominant disorder, a heterozygous affected parent has one normal and one pathogenic allele. Each pregnancy has an independent 50% probability of inheriting the pathogenic allele.", "exam_trap": "The probability applies independently to each pregnancy; previous unaffected children do not alter the probability for the next pregnancy.", "takeaway": "Heterozygous autosomal dominant × unaffected → 50% risk per pregnancy.", "source": "[TTG8]."},
  {"id": "MAK-262", "subject": "Genetics", "topic": "Autosomal recessive inheritance", "title": "Autosomal recessive inheritance", "stem": "Two unaffected parents are known carriers of the same autosomal recessive pathogenic variant. What is the probability that a child will be affected?", "options": {"A": "0%", "B": "10%", "C": "25%", "D": "50%", "E": "100%"}, "correct_letter": "C", "correct_answer": "C. 25%", "why_correct": "For two heterozygous carriers, each pregnancy has: 25% affected, 50% carrier, 25% unaffected non-carrier.", "exam_trap": "", "takeaway": "Carrier × carrier → 25% affected per pregnancy.", "source": "[TTG8]."},
  {"id": "MAK-263", "subject": "Genetics", "topic": "X-linked recessive inheritance", "title": "X-linked recessive inheritance", "stem": "A woman is a carrier of an X-linked recessive disorder and the father is unaffected. What is the probability that an individual son will inherit the pathogenic X chromosome from his mother?", "options": {"A": "0%", "B": "25%", "C": "50%", "D": "75%", "E": "100%"}, "correct_letter": "C", "correct_answer": "C. 50%", "why_correct": "A son receives his X chromosome from his mother and Y chromosome from his father. A carrier mother has a 50% probability of passing the pathogenic X chromosome to each son.", "exam_trap": "Do not confuse \"probability that a son is affected\" with the probability that any child is affected.", "takeaway": "Carrier mother → each son has a 50% chance of inheriting the affected X.", "source": "[TTG8]."},
  {"id": "MAK-264", "subject": "Genetics", "topic": "Penetrance", "title": "Penetrance", "stem": "A pathogenic genetic variant is present in several family members, but not every carrier develops the associated disease. Which term describes this phenomenon?", "options": {"A": "Complete penetrance", "B": "Incomplete penetrance", "C": "Codominance", "D": "Anticipation", "E": "Genetic anticipation only"}, "correct_letter": "B", "correct_answer": "B. Incomplete penetrance", "why_correct": "Penetrance refers to the proportion of individuals carrying a particular genotype who express the associated phenotype. If not all carriers manifest the condition, penetrance is incomplete.", "exam_trap": "", "takeaway": "Penetrance = whether the phenotype appears.", "source": "[TTG8]."},
  {"id": "MAK-265", "subject": "Genetics", "topic": "Variable expressivity", "title": "Variable expressivity", "stem": "Two people carry the same pathogenic variant and both have the associated disorder, but one has mild disease while the other has severe disease. Which concept best describes this?", "options": {"A": "Incomplete penetrance", "B": "Variable expressivity", "C": "Nondisjunction", "D": "Anticipation", "E": "Homozygosity"}, "correct_letter": "B", "correct_answer": "B. Variable expressivity", "why_correct": "Variable expressivity means that individuals with the same disease-associated genotype can manifest different degrees or patterns of phenotype.", "exam_trap": "", "takeaway": "Penetrance = whether disease appears. Expressivity = how strongly/differently it appears.", "source": "[TTG8]."},
  {"id": "MAK-266", "subject": "Research methods & screening", "topic": "Sensitivity", "title": "Sensitivity", "stem": "A diagnostic test is used to identify a disease. Of 100 patients who truly have the disease, 90 have a positive test. What is the sensitivity?", "options": {"A": "10%", "B": "50%", "C": "80%", "D": "90%", "E": "100%"}, "correct_letter": "D", "correct_answer": "D. 90%", "why_correct": "Sensitivity = true positives / all people who actually have the disease. 90 / 100 = 90%. NICE defines sensitivity as the probability that the test is positive in a person who has the condition.", "exam_trap": "", "takeaway": "Sensitivity asks: \"Of those who HAVE disease, how many test positive?\"", "source": "[CEBM]."},
  {"id": "MAK-267", "subject": "Research methods & screening", "topic": "Specificity", "title": "Specificity", "stem": "A diagnostic test is used in 200 patients who do not have a disease. Of these, 180 test negative. What is the specificity?", "options": {"A": "10%", "B": "20%", "C": "80%", "D": "90%", "E": "100%"}, "correct_letter": "D", "correct_answer": "D. 90%", "why_correct": "Specificity = true negatives / all people who do not have the disease. 180 / 200 = 90%. NICE defines specificity as the probability that a test is negative in a person who does not have the condition.", "exam_trap": "", "takeaway": "Specificity asks: \"Of those who DON'T have disease, how many test negative?\"", "source": "[CEBM]."},
  {"id": "MAK-268", "subject": "Research methods & screening", "topic": "Positive predictive value", "title": "Positive predictive value", "stem": "A disease has a low prevalence in the population. A diagnostic test has high sensitivity and specificity, but many positive results are false positives. Which measure is particularly affected by the low prevalence?", "options": {"A": "Positive predictive value", "B": "Sensitivity only", "C": "Specificity only", "D": "Relative risk", "E": "Hazard ratio"}, "correct_letter": "A", "correct_answer": "A. Positive predictive value", "why_correct": "Positive predictive value is the proportion of positive test results that represent true disease. It depends strongly on disease prevalence. When prevalence falls, PPV can fall even when sensitivity and specificity remain unchanged. NICE distinguishes predictive values from sensitivity and specificity and notes the importance of prevalence when applying diagnostic-test results.", "exam_trap": "", "takeaway": "PPV depends heavily on prevalence.", "source": "[CEBM]."},
  {"id": "MAK-269", "subject": "Research methods & screening", "topic": "Positive likelihood ratio", "title": "Positive likelihood ratio", "stem": "A diagnostic test has a positive likelihood ratio (LR+) substantially greater than 1. What does this indicate?", "options": {"A": "A positive result makes the disease less likely", "B": "A positive result has no diagnostic information", "C": "A positive result increases the probability of disease", "D": "The test must have 100% sensitivity", "E": "The disease prevalence must be 50%"}, "correct_letter": "C", "correct_answer": "C. A positive result increases the probability of disease", "why_correct": "An LR+ greater than 1 indicates that a positive result is more likely in people with the disease than in those without it and therefore increases the post-test probability of disease. NICE describes LR+ as indicating how much more likely a positive finding is in people with the condition than people without it.", "exam_trap": "", "takeaway": "LR+ >1 → positive result moves probability upward.", "source": "[CEBM]."},
  {"id": "MAK-270", "subject": "Research methods & screening", "topic": "Randomised controlled trial", "title": "Randomised controlled trial", "stem": "Researchers want to determine whether a new peri-operative intervention causes better patient outcomes than standard care. Patients are randomly allocated to receive either the new intervention or standard care. What study design is this?", "options": {"A": "Case-control study", "B": "Cross-sectional study", "C": "Randomised controlled trial", "D": "Ecological study", "E": "Case report"}, "correct_letter": "C", "correct_answer": "C. Randomised controlled trial", "why_correct": "Random allocation of participants to intervention and comparison groups characterises a randomised controlled trial. Randomisation aims to reduce confounding and create groups that are comparable at baseline, although the quality of a trial also depends on factors such as allocation concealment, blinding where appropriate, follow-up and analysis.", "exam_trap": "", "takeaway": "Random allocation + intervention/comparator → RCT.", "source": "[RCSEng] candidate information; evidence-based practice and research domains. Updated January 2020."},
  {"id": "MAK-271", "subject": "Research methods & screening", "topic": "Incidence", "title": "Incidence", "stem": "A surgical department records 30 new cases of a particular complication among 1,000 patients at risk during a defined 12-month period. Which epidemiological measure is being described?", "options": {"A": "Prevalence", "B": "Incidence", "C": "Case fatality", "D": "Odds ratio", "E": "Positive predictive value"}, "correct_letter": "B", "correct_answer": "B. Incidence", "why_correct": "Incidence describes the occurrence of new cases in a defined population over a specified period.", "exam_trap": "Prevalence refers to existing cases at a particular point or over a specified period, rather than specifically new cases.", "takeaway": "Incidence = NEW cases over time.", "source": "[CEBM]."},
  {"id": "MAK-272", "subject": "Research methods & screening", "topic": "Prevalence", "title": "Prevalence", "stem": "A survey assesses 5,000 people on a single day and finds that 250 currently have a particular disease. Which epidemiological measure is most directly represented?", "options": {"A": "Incidence", "B": "Point prevalence", "C": "Relative risk", "D": "Case fatality rate", "E": "Hazard ratio"}, "correct_letter": "B", "correct_answer": "B. Point prevalence", "why_correct": "Point prevalence describes the proportion of a population with a condition at a particular point in time.", "exam_trap": "", "takeaway": "Prevalence = existing disease burden at a specified time.", "source": "[CEBM]."},
  {"id": "MAK-273", "subject": "Statistics & evidence-based medicine", "topic": "Relative risk", "title": "Relative risk", "stem": "A cohort study reports the following outcome rates: Treatment group: 10% Control group: 20% What is the relative risk of the outcome with treatment?", "options": {"A": "0.25", "B": "0.5", "C": "1", "D": "2", "E": "10"}, "correct_letter": "B", "correct_answer": "B. 0.5", "why_correct": "Relative risk = risk in exposed/intervention group ÷ risk in control group. RR = 0.10 / 0.20 = 0.5. An RR of 0.5 means the observed risk in the treatment group is half that in the control group.", "exam_trap": "Do not confuse relative risk with absolute risk reduction.", "takeaway": "RR = EER / CER.", "source": "[GRP6]."},
  {"id": "MAK-274", "subject": "Statistics & evidence-based medicine", "topic": "Absolute risk reduction", "title": "Absolute risk reduction", "stem": "A trial reports a complication rate of 15% in the control group and 9% in the intervention group. What is the absolute risk reduction?", "options": {"A": "3%", "B": "6%", "C": "9%", "D": "15%", "E": "60%"}, "correct_letter": "B", "correct_answer": "B. 6%", "why_correct": "ARR = control event rate − experimental event rate. ARR = 15% − 9% = 6%.", "exam_trap": "", "takeaway": "ARR tells you the absolute difference in event rates.", "source": "[GRP6]."},
  {"id": "MAK-275", "subject": "Statistics & evidence-based medicine", "topic": "Number needed to treat", "title": "Number needed to treat", "stem": "A treatment reduces an adverse outcome from 20% to 10%. What is the approximate number needed to treat?", "options": {"A": "2", "B": "5", "C": "10", "D": "20", "E": "100"}, "correct_letter": "C", "correct_answer": "C. 10", "why_correct": "ARR = 0.20 − 0.10 = 0.10. NNT = 1 / ARR = 1 / 0.10 = 10. Oxford CEBM defines NNT as the number of patients who need treatment to prevent one additional adverse outcome and gives NNT = 1/ARR.", "exam_trap": "Use the absolute risk reduction, not the relative risk reduction.", "takeaway": "NNT = 1 / ARR.", "source": "[GRP6]."},
  {"id": "MAK-276", "subject": "Statistics & evidence-based medicine", "topic": "Number needed to harm", "title": "Number needed to harm", "stem": "A new treatment increases an adverse event from 4% to 9%. What is the approximate number needed to harm?", "options": {"A": "5", "B": "10", "C": "15", "D": "20", "E": "25"}, "correct_letter": "D", "correct_answer": "D. 20", "why_correct": "Absolute risk increase = 9% − 4% = 5% = 0.05. NNH = 1 / 0.05 = 20.", "exam_trap": "", "takeaway": "NNH = 1 / absolute risk increase.", "source": "[GRP6]."},
  {"id": "MAK-277", "subject": "Statistics & evidence-based medicine", "topic": "Odds ratio", "title": "Odds ratio", "stem": "A case-control study investigates an exposure associated with postoperative infection. Which effect measure is particularly appropriate for a case-control study?", "options": {"A": "Odds ratio", "B": "Incidence rate only", "C": "Absolute risk in the exposed cohort", "D": "NNT", "E": "Case fatality rate only"}, "correct_letter": "A", "correct_answer": "A. Odds ratio", "why_correct": "Case-control studies begin with outcome status and look retrospectively at exposure. The odds ratio is the standard association measure used in this design.", "exam_trap": "Relative risk is naturally calculated from incidence in cohort studies; it cannot generally be calculated directly from a conventional case-control study because the investigator fixes the numbers of cases and controls.", "takeaway": "Case-control → odds ratio.", "source": "[GRP6]."},
  {"id": "MAK-278", "subject": "Research methods & screening", "topic": "Cohort study", "title": "Cohort study", "stem": "Researchers identify patients exposed to a particular occupational risk and follow them for 10 years to compare the incidence of cancer with that in an unexposed group. What study design is this?", "options": {"A": "Case-control", "B": "Cross-sectional", "C": "Cohort", "D": "Case report", "E": "Ecological"}, "correct_letter": "C", "correct_answer": "C. Cohort", "why_correct": "Participants are classified according to exposure and followed over time to observe outcomes.", "exam_trap": "", "takeaway": "Exposure first → follow forward → cohort study.", "source": "[CEBM]."},
  {"id": "MAK-279", "subject": "Research methods & screening", "topic": "Case-control study", "title": "Case-control study", "stem": "Researchers identify 300 patients with a rare postoperative complication and 600 patients without it. Previous exposure to a suspected risk factor is then compared between the two groups. What study design is being used?", "options": {"A": "Cohort", "B": "Case-control", "C": "Randomised controlled trial", "D": "Cross-sectional", "E": "Ecological"}, "correct_letter": "B", "correct_answer": "B. Case-control", "why_correct": "Participants are selected according to outcome status and previous exposures are compared.", "exam_trap": "", "takeaway": "Outcome first → look back for exposure → case-control.", "source": "[CEBM]."},
  {"id": "MAK-280", "subject": "Research methods & screening", "topic": "Cross-sectional study", "title": "Cross-sectional study", "stem": "Researchers measure smoking status and prevalence of chronic respiratory disease in 20,000 people during one survey period. Which study design is this?", "options": {"A": "Cross-sectional", "B": "Cohort", "C": "Case-control", "D": "Randomised controlled trial", "E": "Prospective interventional study"}, "correct_letter": "A", "correct_answer": "A. Cross-sectional", "why_correct": "Exposure and outcome are measured at approximately the same point in time.", "exam_trap": "A cross-sectional study can identify associations but generally cannot establish the temporal sequence needed to demonstrate causation.", "takeaway": "Exposure + outcome measured at one time → cross-sectional study.", "source": "[CEBM]."},
  {"id": "MAK-281", "subject": "Research methods & screening", "topic": "Selection bias", "title": "Selection bias", "stem": "A study investigating postoperative complications recruits participants only from a specialist private hospital, while the target population is intended to represent all NHS surgical patients. Which problem could this introduce?", "options": {"A": "Selection bias", "B": "Recall bias only", "C": "Observer bias only", "D": "Lead-time bias", "E": "Publication bias only"}, "correct_letter": "A", "correct_answer": "A. Selection bias", "why_correct": "The recruited population may systematically differ from the intended target population, affecting the validity and generalisability of the results.", "exam_trap": "", "takeaway": "Who gets into the study matters → selection bias.", "source": "[CEBM]."},
  {"id": "MAK-282", "subject": "Research methods & screening", "topic": "Recall bias", "title": "Recall bias", "stem": "In a case-control study, patients with a disease are asked to remember exposures from 15 years earlier. Patients with the disease provide much more detailed exposure histories than controls. Which bias is particularly concerning?", "options": {"A": "Recall bias", "B": "Lead-time bias", "C": "Publication bias", "D": "Attrition bias", "E": "Spectrum bias"}, "correct_letter": "A", "correct_answer": "A. Recall bias", "why_correct": "Participants may remember or report previous exposures differently depending on whether they have the outcome.", "exam_trap": "", "takeaway": "Retrospective self-report + different memory between groups → recall bias.", "source": "[CEBM]."},
  {"id": "MAK-283", "subject": "Statistics & evidence-based medicine", "topic": "Confounding", "title": "Confounding", "stem": "A study finds that coffee consumption is associated with cardiovascular disease. Further analysis shows that smoking is much more common among coffee drinkers and is independently associated with cardiovascular disease. What statistical problem might smoking represent?", "options": {"A": "Confounding", "B": "Randomisation", "C": "Blinding", "D": "Precision", "E": "External validity only"}, "correct_letter": "A", "correct_answer": "A. Confounding", "why_correct": "A confounder is associated with both the exposure and outcome and can distort the apparent relationship between them.", "exam_trap": "", "takeaway": "Confounder = third factor distorting exposure–outcome relationship.", "source": "[CEBM]."},
  {"id": "MAK-284", "subject": "Statistics & evidence-based medicine", "topic": "Effect modification", "title": "Effect modification", "stem": "A treatment appears highly effective in younger patients but has little effect in older patients, and this difference persists after appropriate analysis. Which concept describes a genuine difference in treatment effect between subgroups?", "options": {"A": "Confounding", "B": "Effect modification", "C": "Recall bias", "D": "Selection bias", "E": "Measurement error"}, "correct_letter": "B", "correct_answer": "B. Effect modification", "why_correct": "Effect modification occurs when the effect of an exposure or intervention genuinely differs according to the level of another variable.", "exam_trap": "Confounding is a distortion that should be controlled; effect modification can represent a real difference that should be reported rather than simply eliminated.", "takeaway": "Different true effects in subgroups → effect modification.", "source": "[CEBM]."},
  {"id": "MAK-285", "subject": "Research methods & screening", "topic": "Allocation concealment", "title": "Allocation concealment", "stem": "In a randomised trial, the investigator enrolling the next participant can see which treatment allocation will be assigned before deciding whether to enrol them. What important methodological protection has been compromised?", "options": {"A": "Allocation concealment", "B": "Blinding of outcome assessors", "C": "Intention-to-treat analysis", "D": "External validity", "E": "Publication of the protocol"}, "correct_letter": "A", "correct_answer": "A. Allocation concealment", "why_correct": "Allocation concealment prevents those recruiting participants from knowing the upcoming assignment and selectively influencing recruitment.", "exam_trap": "Allocation concealment occurs before/during enrolment. Blinding generally concerns knowledge of treatment after allocation.", "takeaway": "Conceal the next allocation from recruiters → reduce selection bias.", "source": "[CEBM]."},
  {"id": "MAK-286", "subject": "Research methods & screening", "topic": "Blinding", "title": "Blinding", "stem": "In a clinical trial, participants and investigators are unaware of which treatment each participant receives. What methodological feature is being described?", "options": {"A": "Randomisation", "B": "Blinding", "C": "Allocation concealment", "D": "Stratification", "E": "Intention-to-treat analysis"}, "correct_letter": "B", "correct_answer": "B. Blinding", "why_correct": "Blinding prevents knowledge of treatment assignment from influencing participant behaviour, treatment delivery or outcome assessment, depending on who is blinded.", "exam_trap": "", "takeaway": "Not knowing treatment allocation → blinding.", "source": "[CEBM]."},
  {"id": "MAK-287", "subject": "Research methods & screening", "topic": "Intention-to-treat analysis", "title": "Intention-to-treat analysis", "stem": "In a randomised controlled trial, several participants assigned to the intervention stop taking it and switch to standard treatment. For the primary analysis, they remain analysed in their originally allocated group. What principle is being used?", "options": {"A": "Per-protocol analysis", "B": "Intention-to-treat analysis", "C": "As-treated analysis", "D": "Subgroup analysis", "E": "Interim analysis"}, "correct_letter": "B", "correct_answer": "B. Intention-to-treat analysis", "why_correct": "Intention-to-treat analysis retains participants in the groups to which they were originally randomised, regardless of treatment changes, preserving the benefits of randomisation. Oxford CEBM defines intention-to-treat in this way.", "exam_trap": "", "takeaway": "Analyse according to original allocation → intention to treat.", "source": "[CEBM]."},
  {"id": "MAK-288", "subject": "Research methods & screening", "topic": "Attrition bias", "title": "Attrition bias", "stem": "A randomised trial begins with equal groups, but 30% of participants in the intervention arm are lost to follow-up compared with 5% in the control arm. What problem is most concerning?", "options": {"A": "Attrition bias", "B": "Recall bias", "C": "Lead-time bias", "D": "Spectrum bias", "E": "Publication bias"}, "correct_letter": "A", "correct_answer": "A. Attrition bias", "why_correct": "Unequal loss to follow-up can distort the comparison between groups, particularly if losses are related to treatment or outcome.", "exam_trap": "", "takeaway": "Unequal loss to follow-up → attrition bias.", "source": "[CEBM]."},
  {"id": "MAK-289", "subject": "Research methods & screening", "topic": "Publication bias", "title": "Publication bias", "stem": "A systematic review finds mainly positive studies supporting an intervention, but investigators suspect that several negative studies were never published. What form of bias is this?", "options": {"A": "Publication bias", "B": "Recall bias", "C": "Selection bias within a cohort", "D": "Measurement bias", "E": "Spectrum bias"}, "correct_letter": "A", "correct_answer": "A. Publication bias", "why_correct": "Studies with positive or statistically significant findings may be more likely to be published than studies with negative or inconclusive results. CEBM identifies funnel plots as one method used to explore whether results in a systematic review may have been affected by publication bias.", "exam_trap": "", "takeaway": "Missing negative studies → publication bias.", "source": "[CEBM]."},
  {"id": "MAK-290", "subject": "Statistics & evidence-based medicine", "topic": "P value", "title": "P value", "stem": "A trial reports p = 0.03 for the difference between two treatments. Which interpretation is most accurate?", "options": {"A": "There is a 3% probability that the null hypothesis is true", "B": "There is a 97% probability that the treatment works", "C": "If the null hypothesis were true, results at least this extreme would have a probability of approximately 3%", "D": "The treatment effect is clinically important", "E": "The result is free from bias"}, "correct_letter": "C", "correct_answer": "C. If the null hypothesis were true, results at least this extreme would have a probability of approximately 3%", "why_correct": "A p-value describes the probability of observing a result at least as extreme as the observed result under the assumption that the null hypothesis is true. It does NOT give the probability that the null hypothesis is true or that the treatment is effective. CEBM explicitly warns against interpreting a p-value as the probability that a result is right or wrong.", "exam_trap": "", "takeaway": "p-value ≠ probability that the hypothesis is true.", "source": "[CEBM]."},
  {"id": "MAK-291", "subject": "Statistics & evidence-based medicine", "topic": "Statistical versus clinical significance", "title": "Statistical versus clinical significance", "stem": "A trial finds a statistically significant reduction in hospital stay of 0.1 days with a new intervention. The p-value is <0.001. Which statement is most appropriate?", "options": {"A": "The intervention must be clinically important", "B": "Statistical significance automatically establishes clinical importance", "C": "The result may be statistically significant without representing a clinically important benefit", "D": "The result proves absence of bias", "E": "The intervention should automatically replace standard care"}, "correct_letter": "C", "correct_answer": "C. The result may be statistically significant without representing a clinically important benefit", "why_correct": "Statistical significance does not determine whether the magnitude of an effect is clinically meaningful. The clinical importance of an effect must be interpreted in context, including its size, confidence interval, harms, costs and patient relevance. CEBM specifically distinguishes statistical significance from clinical importance.", "exam_trap": "", "takeaway": "Statistically significant ≠ clinically important.", "source": "[CEBM]."},
  {"id": "MAK-292", "subject": "Statistics & evidence-based medicine", "topic": "Confidence interval", "title": "Confidence interval", "stem": "A trial reports a relative risk of 0.80 with a 95% confidence interval of 0.60–1.10. Which conclusion is most appropriate regarding statistical significance at the conventional 5% level?", "options": {"A": "Statistically significant benefit is demonstrated", "B": "Statistically significant harm is demonstrated", "C": "The confidence interval includes the null value, so statistical significance is not demonstrated", "D": "The treatment definitely has no effect", "E": "The treatment definitely reduces risk by 20%"}, "correct_letter": "C", "correct_answer": "C. The confidence interval includes the null value, so statistical significance is not demonstrated", "why_correct": "For a ratio measure such as relative risk, the null value is 1. Because the 95% CI crosses 1, the result is not statistically significant at the conventional 5% level.", "exam_trap": "Do not say the treatment \"has no effect\". The study may simply be insufficiently precise to exclude clinically important effects.", "takeaway": "RR/OR/HR → null value = 1.", "source": "[CEBM]."},
  {"id": "MAK-293", "subject": "Statistics & evidence-based medicine", "topic": "Confidence interval for an absolute difference", "title": "Confidence interval for an absolute difference", "stem": "A trial reports an absolute reduction in complications of 4%, with a 95% confidence interval from −1% to 9%. What does this indicate?", "options": {"A": "The treatment definitely reduces complications", "B": "The treatment definitely increases complications", "C": "The confidence interval includes no difference, so a statistically significant benefit is not demonstrated", "D": "The treatment has exactly a 4% benefit in every patient", "E": "The study proves equivalence"}, "correct_letter": "C", "correct_answer": "C. The confidence interval includes no difference, so a statistically significant benefit is not demonstrated", "why_correct": "For an absolute difference, the null value is 0. Because the CI spans zero, the data are compatible with benefit, no difference and a small degree of harm.", "exam_trap": "", "takeaway": "Difference measure → null = 0. Ratio measure → null = 1.", "source": "[CEBM]."},
  {"id": "MAK-294", "subject": "Statistics & evidence-based medicine", "topic": "Precision", "title": "Precision", "stem": "Two studies estimate the effect of the same treatment. Study A: RR 0.80 (95% CI 0.78–0.82) Study B: RR 0.80 (95% CI 0.50–1.30) Which study provides the more precise estimate?", "options": {"A": "Study A", "B": "Study B", "C": "Both are equally precise", "D": "Precision cannot be assessed from a confidence interval", "E": "Neither provides an estimate"}, "correct_letter": "A", "correct_answer": "A. Study A", "why_correct": "Study A has a much narrower confidence interval and therefore provides a more precise estimate of the effect. CEBM notes that a wide confidence interval indicates greater uncertainty around the estimated effect.", "exam_trap": "", "takeaway": "Narrow CI → greater precision. Wide CI → greater uncertainty.", "source": "[CEBM]."},
  {"id": "MAK-295", "subject": "Statistics & evidence-based medicine", "topic": "Type I error", "title": "Type I error", "stem": "A researcher concludes that a new treatment is effective when, in reality, there is no true treatment effect. What type of statistical error has occurred?", "options": {"A": "Type I error", "B": "Type II error", "C": "Selection bias", "D": "Recall bias", "E": "Confounding"}, "correct_letter": "A", "correct_answer": "A. Type I error", "why_correct": "A Type I error is a false-positive conclusion: rejecting the null hypothesis when it is actually true.", "exam_trap": "", "takeaway": "Type I = false positive.", "source": "[CEBM]."},
  {"id": "MAK-296", "subject": "Statistics & evidence-based medicine", "topic": "Type II error", "title": "Type II error", "stem": "A study fails to detect a genuine treatment effect. Which statistical error may have occurred?", "options": {"A": "Type I error", "B": "Type II error", "C": "Publication bias", "D": "Recall bias", "E": "Spectrum bias"}, "correct_letter": "B", "correct_answer": "B. Type II error", "why_correct": "A Type II error is a false-negative conclusion: failing to reject the null hypothesis when a real effect exists.", "exam_trap": "", "takeaway": "Type II = false negative.", "source": "[CEBM]."},
  {"id": "MAK-297", "subject": "Statistics & evidence-based medicine", "topic": "Statistical power", "title": "Statistical power", "stem": "Which change generally increases the statistical power of a clinical study, assuming other factors remain appropriate?", "options": {"A": "Smaller sample size", "B": "Larger sample size", "C": "Greater measurement error", "D": "Greater loss to follow-up", "E": "Increased variability without increasing sample size"}, "correct_letter": "B", "correct_answer": "B. Larger sample size", "why_correct": "Increasing sample size generally reduces random error and increases the ability of a study to detect a true effect.", "exam_trap": "", "takeaway": "More participants generally → greater statistical power.", "source": "[CEBM]."},
  {"id": "MAK-298", "subject": "Research methods & screening", "topic": "Audit cycle", "title": "Audit cycle", "stem": "A surgical department discovers that only 65% of eligible patients received VTE assessment within the locally agreed standard. The team introduces a change in practice and subsequently measures compliance again. What part of the audit cycle is the repeat measurement?", "options": {"A": "Identifying the topic", "B": "Setting the standard", "C": "Implementing change", "D": "Re-audit", "E": "Writing the research hypothesis"}, "correct_letter": "D", "correct_answer": "D. Re-audit", "why_correct": "Clinical audit involves measuring current practice against a defined standard, implementing improvement where necessary, and then repeating measurement to determine whether practice has improved.", "exam_trap": "", "takeaway": "Measure → compare with standard → change → re-measure = audit cycle.", "source": "[RCSEng] MRCS candidate information: clinical audit and governance."},
  {"id": "MAK-299", "subject": "Research methods & screening", "topic": "Audit versus research", "title": "Audit versus research", "stem": "A surgical team measures whether current practice meets an established national standard and introduces changes if compliance is poor. What is the primary purpose?", "options": {"A": "Generate entirely new generalisable knowledge", "B": "Determine whether current practice meets a predefined standard", "C": "Conduct a randomised experiment", "D": "Establish disease incidence in the population", "E": "Perform a laboratory experiment"}, "correct_letter": "B", "correct_answer": "B. Determine whether current practice meets a predefined standard", "why_correct": "Clinical audit evaluates current practice against agreed standards and aims to improve quality. Research primarily seeks to generate new knowledge.", "exam_trap": "An audit may generate useful information, but its defining purpose is improvement against a standard rather than discovery of entirely new knowledge.", "takeaway": "Audit = \"Are we doing what we should?\" Research = \"What new knowledge can we generate?\"", "source": "[RCSEng], MRCS candidate information: clinical audit and research."},
  {"id": "MAK-300", "subject": "Research methods & screening", "topic": "Systematic review", "title": "Systematic review", "stem": "Researchers identify all relevant studies addressing a focused clinical question using a predefined search strategy and explicit inclusion criteria. They critically appraise the studies and synthesise their findings. What type of evidence synthesis is this?", "options": {"A": "Case report", "B": "Narrative opinion", "C": "Systematic review", "D": "Cross-sectional survey", "E": "Case-control study"}, "correct_letter": "C", "correct_answer": "C. Systematic review", "why_correct": "A systematic review uses a predefined and reproducible approach to identify, select and critically appraise relevant evidence addressing a focused question. A meta-analysis may additionally statistically combine results from individual studies when appropriate, but not every systematic review contains a meta-analysis.", "exam_trap": "Systematic review ≠ automatically meta-analysis.", "takeaway": "Systematic review = systematic identification + selection + appraisal + synthesis of evidence.", "source": "[CEBM]."},
  {"id": "MAK-301", "subject": "Research methods & screening", "topic": "Qualitative versus quantitative research", "title": "Qualitative versus quantitative research", "stem": "A surgical team wants to explore why some patients decline elective colorectal cancer surgery despite being offered the same information. Which research approach is most appropriate if the primary aim is to understand patients’ experiences and reasons in depth?", "options": {"A": "Randomised controlled trial", "B": "Qualitative research", "C": "Case-control study", "D": "Cohort study", "E": "Ecological study"}, "correct_letter": "B", "correct_answer": "B. Qualitative research", "why_correct": "Qualitative research explores experiences, perceptions, beliefs, attitudes and reasons, commonly using interviews, focus groups or thematic analysis. WHY THE OTHERS ARE WRONG: A. RCTs assess effects of interventions. C. Case-control studies investigate associations between exposures and outcomes. D. Cohort studies follow groups over time to assess associations. E. Ecological studies use population-level rather than individual-level data.", "exam_trap": "Do not assume every clinical research question requires numerical outcome data.", "takeaway": "“Why?” and “What is the experience?” → think qualitative research.", "source": "RCS England, MRCS Candidate Information Pack, research and evidence-based practice content, January 2020."},
  {"id": "MAK-302", "subject": "Statistics & evidence-based medicine", "topic": "Null hypothesis", "title": "Null hypothesis", "stem": "A randomised trial compares two postoperative analgesic regimens. The investigators state that there is no difference in mean postoperative pain score between the two groups. What does this statement represent?", "options": {"A": "Alternative hypothesis", "B": "Null hypothesis", "C": "Type II error", "D": "Confidence interval", "E": "Effect modification"}, "correct_letter": "B", "correct_answer": "B. Null hypothesis", "why_correct": "The null hypothesis generally states that there is no difference or no association between the groups being compared.", "exam_trap": "The null hypothesis is not “the treatment does not work” in every circumstance; it is the formal hypothesis of no difference/effect under the statistical model.", "takeaway": "Null hypothesis = “no difference/no association.”", "source": "[CEBM]."},
  {"id": "MAK-303", "subject": "Research methods & screening", "topic": "Primary outcome", "title": "Primary outcome", "stem": "A randomised trial is designed to determine whether a new surgical dressing reduces surgical-site infection. The protocol specifies surgical-site infection at 30 days as the main outcome used to determine the trial's principal conclusion. What is this outcome?", "options": {"A": "Surrogate outcome", "B": "Secondary outcome", "C": "Primary outcome", "D": "Composite confounder", "E": "Exploratory variable"}, "correct_letter": "C", "correct_answer": "C. Primary outcome", "why_correct": "The primary outcome is the prespecified main outcome used to address the principal research question.", "exam_trap": "Do not choose an outcome because it is clinically interesting after seeing the results. Primary outcomes should be specified in advance.", "takeaway": "Primary outcome = the trial's prespecified principal endpoint.", "source": "[GRP6]."},
  {"id": "MAK-304", "subject": "Research methods & screening", "topic": "Surrogate endpoint", "title": "Surrogate endpoint", "stem": "A cardiovascular trial assesses whether a drug reduces LDL cholesterol but does not directly assess myocardial infarction, stroke or cardiovascular mortality. LDL cholesterol is being used as what type of endpoint?", "options": {"A": "Hard clinical endpoint", "B": "Surrogate endpoint", "C": "Composite endpoint", "D": "Safety endpoint", "E": "Patient-reported endpoint"}, "correct_letter": "B", "correct_answer": "B. Surrogate endpoint", "why_correct": "A surrogate endpoint is a biological or laboratory measure used as a substitute for a clinically meaningful outcome.", "exam_trap": "A surrogate improving does not automatically prove that patients have better clinical outcomes.", "takeaway": "Biomarker used instead of a patient-important outcome → surrogate endpoint.", "source": "[GRP6]."},
  {"id": "MAK-305", "subject": "Research methods & screening", "topic": "Composite endpoint", "title": "Composite endpoint", "stem": "A trial defines its primary endpoint as the first occurrence of myocardial infarction, stroke or cardiovascular death. What type of endpoint is this?", "options": {"A": "Surrogate endpoint", "B": "Composite endpoint", "C": "Continuous endpoint", "D": "Laboratory endpoint", "E": "Per-protocol endpoint"}, "correct_letter": "B", "correct_answer": "B. Composite endpoint", "why_correct": "A composite endpoint combines two or more individual outcomes into a single outcome measure.", "exam_trap": "A statistically significant composite result does not necessarily mean that every component is significantly affected.", "takeaway": "Several clinically defined events combined into one endpoint = composite endpoint.", "source": "[GRP6]."},
  {"id": "MAK-306", "subject": "Statistics & evidence-based medicine", "topic": "Sample size and clinically important difference", "title": "Sample size and clinically important difference", "stem": "Investigators are planning a randomised trial. Which factor generally influences the sample size required when comparing two treatment groups?", "options": {"A": "Only the study title", "B": "The expected variability and clinically important difference", "C": "Whether the investigators prefer a larger sample", "D": "The colour of the intervention packaging", "E": "Whether the study is single-centre"}, "correct_letter": "B", "correct_answer": "B. The expected variability and clinically important difference", "why_correct": "Sample-size calculations depend on factors including the anticipated effect size or clinically important difference, variability, desired power and significance level.", "exam_trap": "A statistically significant difference is not the same as a clinically important difference.", "takeaway": "Smaller expected differences generally require larger samples to detect reliably.", "source": "[GRP6]."},
  {"id": "MAK-307", "subject": "Research methods & screening", "topic": "Stratified randomisation", "title": "Stratified randomisation", "stem": "A multicentre trial is concerned that an important prognostic factor, such as tumour stage, may become unevenly distributed between treatment groups. Which randomisation strategy can help ensure balance for that factor?", "options": {"A": "Stratified randomisation", "B": "Historical control allocation", "C": "Convenience sampling", "D": "Case matching after treatment", "E": "Ecological allocation"}, "correct_letter": "A", "correct_answer": "A. Stratified randomisation", "why_correct": "Stratified randomisation separates participants into predefined strata based on important characteristics and randomises within those strata.", "exam_trap": "Stratification is performed as part of the allocation strategy; it is not the same as retrospectively adjusting an observational study.", "takeaway": "Important prognostic factor → consider stratification during randomisation.", "source": "[GRP6]."},
  {"id": "MAK-308", "subject": "Research methods & screening", "topic": "Crossover trial", "title": "Crossover trial", "stem": "Patients with a stable chronic condition are randomly allocated to treatment A or treatment B and subsequently receive the alternative treatment after a defined period. Each participant therefore receives both interventions. What type of design is this?", "options": {"A": "Parallel-group trial", "B": "Crossover trial", "C": "Case-control study", "D": "Ecological study", "E": "Diagnostic accuracy study"}, "correct_letter": "B", "correct_answer": "B. Crossover trial", "why_correct": "In a crossover trial, participants receive more than one intervention sequentially, allowing each participant to act as their own comparator.", "exam_trap": "Crossover designs are unsuitable when the first intervention has a lasting effect that could influence the subsequent treatment period.", "takeaway": "Same patient receives A and B sequentially → crossover trial.", "source": "[GRP6]."},
  {"id": "MAK-309", "subject": "Research methods & screening", "topic": "Cluster randomised trial", "title": "Cluster randomised trial", "stem": "A study randomises entire general practices to either an educational intervention or usual care rather than randomising individual patients. What type of trial is this?", "options": {"A": "Crossover trial", "B": "Cluster randomised trial", "C": "Case-control study", "D": "Case series", "E": "Diagnostic cohort study"}, "correct_letter": "B", "correct_answer": "B. Cluster randomised trial", "why_correct": "The unit of randomisation is a group or cluster, such as a practice, hospital or geographical area, rather than an individual participant.", "exam_trap": "The individual patients may provide the outcome data, but the allocation occurred at cluster level.", "takeaway": "Randomised by practice/hospital/group → cluster randomised trial.", "source": "[GRP6]."},
  {"id": "MAK-310", "subject": "Research methods & screening", "topic": "Non-inferiority trial", "title": "Non-inferiority trial", "stem": "A new surgical technique is expected to be cheaper and quicker than the standard technique. Investigators want to determine whether its clinical effectiveness is not unacceptably worse than the standard technique. What type of trial is most appropriate?", "options": {"A": "Superiority trial", "B": "Non-inferiority trial", "C": "Case-control study", "D": "Diagnostic accuracy study", "E": "Ecological study"}, "correct_letter": "B", "correct_answer": "B. Non-inferiority trial", "why_correct": "A non-inferiority trial tests whether a new intervention is not worse than the comparator by more than a prespecified clinically acceptable margin.", "exam_trap": "“Not statistically different” is not automatically equivalent to proving non-inferiority.", "takeaway": "New treatment expected to have other advantages but must not be clinically unacceptably worse → non-inferiority design.", "source": "[GRP6]."},
  {"id": "MAK-311", "subject": "Research methods & screening", "topic": "Screening versus diagnosis", "title": "Screening versus diagnosis", "stem": "Which statement best describes screening?", "options": {"A": "It is performed only after symptoms develop", "B": "It identifies apparently healthy people who may have an increased chance of a condition", "C": "It always establishes a definitive diagnosis", "D": "It eliminates false-positive results", "E": "It is only appropriate for hospital inpatients"}, "correct_letter": "B", "correct_answer": "B. It identifies apparently healthy people who may have an increased chance of a condition", "why_correct": "The UK National Screening Committee defines screening as identifying apparently healthy people who may have an increased chance of disease or another condition, followed by further assessment where appropriate.", "exam_trap": "A positive screening result is not necessarily a diagnosis.", "takeaway": "Screening identifies increased chance; diagnostic testing establishes or excludes disease.", "source": "[UKNSC], Principles of screening, updated 11 July 2025."},
  {"id": "MAK-312", "subject": "Research methods & screening", "topic": "Appropriate screening programme", "title": "Appropriate screening programme", "stem": "Which feature would support consideration of a population screening programme?", "options": {"A": "The disease has no effective intervention", "B": "The screening test is unreliable", "C": "Earlier detection improves outcomes", "D": "Screening causes substantial harm with no measurable benefit", "E": "No diagnostic pathway exists after a positive result"}, "correct_letter": "C", "correct_answer": "C. Earlier detection improves outcomes", "why_correct": "UK NSC criteria require evidence that earlier intervention at a presymptomatic stage provides better outcomes than usual care, together with an appropriate test, diagnostic pathway and treatment.", "exam_trap": "A disease being serious alone is insufficient justification for screening.", "takeaway": "Screening needs a complete pathway: condition → test → diagnosis → effective intervention → overall benefit.", "source": "[UKNSC], criteria for population screening, updated 29 September 2022."},
  {"id": "MAK-313", "subject": "Research methods & screening", "topic": "Lead-time bias", "title": "Lead-time bias", "stem": "A screening programme detects cancer earlier. Patients subsequently appear to survive for longer from the date of diagnosis, but mortality has not changed. Which bias could explain this apparent improvement?", "options": {"A": "Recall bias", "B": "Lead-time bias", "C": "Selection bias", "D": "Observer bias", "E": "Publication bias"}, "correct_letter": "B", "correct_answer": "B. Lead-time bias", "why_correct": "Earlier diagnosis can increase measured survival time from diagnosis without actually delaying death. Example: Without screening: Diagnosis at year 8 → death at year 10 = 2-year measured survival. With screening: Diagnosis at year 6 → death at year 10 = 4-year measured survival. The patient has not lived longer, but measured survival after diagnosis has increased.", "exam_trap": "Improved post-diagnosis survival does not automatically demonstrate reduced mortality.", "takeaway": "Earlier diagnosis + unchanged death time → lead-time bias.", "source": "[UKNSC] guidance discusses lead-time bias in interpretation of screening outcomes; NHS screening standards updated 2025."},
  {"id": "MAK-314", "subject": "Research methods & screening", "topic": "Length-time bias", "title": "Length-time bias", "stem": "A cancer screening programme disproportionately detects slow-growing tumours, which naturally have a better prognosis than rapidly growing tumours. What phenomenon can contribute to this apparent improvement in outcomes?", "options": {"A": "Lead-time bias", "B": "Length-time bias", "C": "Recall bias", "D": "Attrition bias", "E": "Performance bias"}, "correct_letter": "B", "correct_answer": "B. Length-time bias", "why_correct": "Slow-growing tumours generally have a longer preclinical detectable period and are therefore more likely to be identified by periodic screening.", "exam_trap": "Lead-time bias concerns advancing the time of diagnosis; length-time bias concerns preferential detection of slower-growing disease.", "takeaway": "Slow-growing disease is more likely to enter the screening window → length-time bias.", "source": "UK government screening methodology describes length-time bias as a source of apparent improvement in survival."},
  {"id": "MAK-315", "subject": "Research methods & screening", "topic": "Overdiagnosis", "title": "Overdiagnosis", "stem": "A screening programme detects a tumour that would never have caused symptoms or affected the patient's health during their lifetime. What is this phenomenon called?", "options": {"A": "False negative", "B": "Lead-time bias", "C": "Overdiagnosis", "D": "Recall bias", "E": "Under-treatment"}, "correct_letter": "C", "correct_answer": "C. Overdiagnosis", "why_correct": "Overdiagnosis is detection of a condition that would not have caused clinically important disease during the person's lifetime.", "exam_trap": "Overdiagnosis is different from a false-positive result: the detected abnormality is real, but it would not have caused harm.", "takeaway": "Real disease that would never have caused harm → overdiagnosis.", "source": "[UKNSC]: criteria for appraising the viability, effectiveness and appropriateness of a screening programme."},
  {"id": "MAK-316", "subject": "Research methods & screening", "topic": "Harm from screening", "title": "Harm from screening", "stem": "Which is a recognised potential harm of a screening programme?", "options": {"A": "False-positive results", "B": "Guaranteed reduction in mortality", "C": "Elimination of unnecessary investigations", "D": "Removal of all diagnostic uncertainty", "E": "Prevention of every future case of disease"}, "correct_letter": "A", "correct_answer": "A. False-positive results", "why_correct": "Screening can produce false-positive results, false reassurance, overdiagnosis, overtreatment and unnecessary follow-up.", "exam_trap": "A screening programme must be judged on the whole pathway, including its harms, rather than only the number of diseases detected.", "takeaway": "Screening can help and harm; benefit must outweigh harm.", "source": "[UKNSC], Principles of screening, updated 11 July 2025."},
  {"id": "MAK-317", "subject": "Research methods & screening", "topic": "Informed choice in screening", "title": "Informed choice in screening", "stem": "A healthy person is invited to participate in a screening programme. Which approach is most consistent with UK National Screening Committee principles?", "options": {"A": "Screening should be compulsory", "B": "The patient should receive balanced information about benefits and harms before deciding", "C": "The clinician should conceal false-positive rates to encourage attendance", "D": "A positive screen should be described as a confirmed diagnosis", "E": "Declining screening should automatically result in removal from routine care"}, "correct_letter": "B", "correct_answer": "B. The patient should receive balanced information about benefits and harms before deciding", "why_correct": "The UK NSC describes personal informed choice as a decision based on accessible, accurate, evidence-based information about the benefits and risks of screening.", "exam_trap": "High uptake is not a justification for withholding information about potential harms.", "takeaway": "Screening invitation → evidence-based information → personal informed choice.", "source": "[UKNSC], Informed choice, updated 11 July 2025."},
  {"id": "MAK-318", "subject": "Statistics & evidence-based medicine", "topic": "Forest plot", "title": "Forest plot", "stem": "In a meta-analysis, individual studies are represented by squares with horizontal lines, while the pooled estimate is represented by a diamond. What type of figure is being described?", "options": {"A": "Kaplan-Meier curve", "B": "Forest plot", "C": "Funnel plot", "D": "ROC curve", "E": "Scatter plot"}, "correct_letter": "B", "correct_answer": "B. Forest plot", "why_correct": "Forest plots display effect estimates and their confidence intervals for individual studies and often a pooled estimate.", "exam_trap": "The horizontal line usually represents the confidence interval, not the range of raw patient measurements.", "takeaway": "Squares + horizontal confidence intervals + pooled diamond → forest plot.", "source": "Standard evidence-based medicine methodology; MRCS evidence-based practice syllabus."},
  {"id": "MAK-319", "subject": "Statistics & evidence-based medicine", "topic": "Heterogeneity in meta-analysis", "title": "Heterogeneity in meta-analysis", "stem": "A meta-analysis combines several studies, but the study results vary substantially in their direction or magnitude of effect. What does this suggest?", "options": {"A": "Heterogeneity", "B": "Blinding", "C": "Allocation concealment", "D": "Randomisation", "E": "External validity"}, "correct_letter": "A", "correct_answer": "A. Heterogeneity", "why_correct": "Heterogeneity refers to differences between studies that may arise from differences in populations, interventions, outcomes, methodology or other factors.", "exam_trap": "Statistical pooling does not automatically make clinically different studies directly interchangeable.", "takeaway": "Studies differ materially → assess heterogeneity before interpreting the pooled estimate.", "source": "Evidence-based medicine and systematic-review methodology; MRCS evidence-based practice syllabus."},
  {"id": "MAK-320", "subject": "Statistics & evidence-based medicine", "topic": "I² statistic", "title": "I² statistic", "stem": "A meta-analysis reports an I² statistic of 0%. What does this indicate?", "options": {"A": "All participants were blinded", "B": "No observed variability exists between the studies", "C": "No observed statistical heterogeneity is detected", "D": "The treatment is ineffective", "E": "The pooled estimate is statistically significant"}, "correct_letter": "C", "correct_answer": "C. No observed statistical heterogeneity is detected", "why_correct": "I² estimates the proportion of observed variability in effect estimates that is attributable to heterogeneity rather than sampling error. An I² of 0% indicates no observed statistical heterogeneity by this measure.", "exam_trap": "I² does not tell you whether an intervention works.", "takeaway": "I² assesses heterogeneity, not treatment efficacy.", "source": "Standard meta-analysis methodology; MRCS evidence-based practice syllabus."},
  {"id": "MAK-321", "subject": "Statistics & evidence-based medicine", "topic": "Internal validity", "title": "Internal validity", "stem": "A trial is well randomised, has minimal loss to follow-up and uses appropriate outcome measurement. The investigators are primarily assessing whether the study's results are likely to be valid for the participants actually studied. What concept is being assessed?", "options": {"A": "Internal validity", "B": "External validity", "C": "Generalisability", "D": "Cost-effectiveness", "E": "Ecological validity"}, "correct_letter": "A", "correct_answer": "A. Internal validity", "why_correct": "Internal validity concerns whether the study has been conducted sufficiently well to provide a trustworthy estimate for the population actually studied.", "exam_trap": "A study can have good internal validity but limited generalisability.", "takeaway": "“Is the study result trustworthy in its own participants?” → internal validity.", "source": "MRCS evidence-based practice and critical-appraisal principles."},
  {"id": "MAK-322", "subject": "Statistics & evidence-based medicine", "topic": "External validity", "title": "External validity", "stem": "A clinical trial is methodologically rigorous but only included highly selected young patients. Investigators question whether its findings apply to elderly patients with multiple comorbidities. Which concept is being questioned?", "options": {"A": "Internal validity", "B": "External validity", "C": "Randomisation", "D": "Allocation concealment", "E": "Statistical power"}, "correct_letter": "B", "correct_answer": "B. External validity", "why_correct": "External validity concerns whether study findings can reasonably be generalised to other populations, settings or clinical circumstances.", "exam_trap": "A highly controlled trial may have excellent internal validity but limited generalisability.", "takeaway": "“Can I apply this result to my patient?” → external validity.", "source": "MRCS evidence-based practice and critical-appraisal principles."},
  {"id": "MAK-323", "subject": "Statistics & evidence-based medicine", "topic": "Statistical versus clinical significance", "title": "Statistical versus clinical significance", "stem": "A very large trial finds that a new postoperative intervention reduces mean pain by 0.2 points on a 10-point scale with p<0.001. Which statement is most appropriate?", "options": {"A": "The result is statistically significant, but its clinical importance may be limited", "B": "The result cannot be statistically significant", "C": "Statistical significance proves the effect is clinically important", "D": "The treatment must replace standard care", "E": "A p-value determines clinical importance"}, "correct_letter": "A", "correct_answer": "A. The result is statistically significant, but its clinical importance may be limited", "why_correct": "A small difference can become statistically significant in a large sample. Clinical importance depends on the magnitude of benefit and its relevance to patients.", "exam_trap": "p<0.05 does not automatically mean “clinically important.”", "takeaway": "Statistical significance ≠ clinical significance.", "source": "Greenhalgh, How to Read a Paper, 6th edition (2019), chapter on statistics for the non-statistician; CEBM (Oxford), Statistical significance vs clinical significance."},
  {"id": "MAK-324", "subject": "Statistics & evidence-based medicine", "topic": "Absolute versus relative effect", "title": "Absolute versus relative effect", "stem": "A treatment reduces an event rate from 10% to 8%. Which statement correctly describes the absolute risk reduction?", "options": {"A": "0.2%", "B": "2 percentage points", "C": "20 percentage points", "D": "20%", "E": "80%"}, "correct_letter": "B", "correct_answer": "B. 2 percentage points", "why_correct": "ARR = control event rate − treatment event rate = 10% − 8% = 2 percentage points. The relative risk reduction is 20%.", "exam_trap": "Do not confuse a 20% relative reduction with a 2 percentage-point absolute reduction.", "takeaway": "10% → 8% = ARR 2 percentage points; RRR 20%.", "source": "CEBM (Oxford), Explanation of the EBM glossary: absolute risk reduction, relative risk reduction and NNT; Greenhalgh, How to Read a Paper, 6th edition (2019)."},
  {"id": "MAK-325", "subject": "Statistics & evidence-based medicine", "topic": "Relative risk interpretation", "title": "Relative risk interpretation", "stem": "A trial reports a relative risk of 0.75 for postoperative infection in the intervention group compared with controls. Which interpretation is correct?", "options": {"A": "The intervention group has 75% more infections", "B": "The risk in the intervention group is 75% of the control risk", "C": "The absolute risk is 75%", "D": "75 patients must be treated", "E": "The intervention reduces risk by 75 percentage points"}, "correct_letter": "B", "correct_answer": "B. The risk in the intervention group is 75% of the control risk", "why_correct": "RR = risk in intervention group / risk in control group. RR 0.75 means the intervention group's risk is 75% of the control risk, corresponding to a relative risk reduction of 25%.", "exam_trap": "RR 0.75 does not mean a 75% reduction in risk.", "takeaway": "RR below 1 → lower relative risk in the intervention group.", "source": "CEBM (Oxford), Explanation of the EBM glossary: absolute risk reduction, relative risk reduction and NNT; Greenhalgh, How to Read a Paper, 6th edition (2019)."},
  {"id": "MAK-326", "subject": "Statistics & evidence-based medicine", "topic": "Generalisability and eligibility criteria", "title": "Generalisability and eligibility criteria", "stem": "A trial excludes patients with renal impairment, advanced age and multiple comorbidities. Which issue should a clinician consider most carefully before applying its findings to a frail older patient with renal impairment?", "options": {"A": "External validity", "B": "Allocation concealment", "C": "Blinding", "D": "Random sequence generation", "E": "Type I error"}, "correct_letter": "A", "correct_answer": "A. External validity", "why_correct": "The patient differs substantially from the population studied, raising concerns about generalisability.", "exam_trap": "A statistically convincing trial can still have limited applicability to a particular patient.", "takeaway": "Compare your patient with the trial population before applying the result.", "source": "MRCS evidence-based practice and critical-appraisal principles."},
  {"id": "MAK-327", "subject": "Research methods & screening", "topic": "Research consent", "title": "Research consent", "stem": "A competent adult is invited to participate in a clinical research study. Which statement best describes valid research consent?", "options": {"A": "It must be obtained under pressure to ensure recruitment", "B": "It should be voluntary and informed", "C": "It is valid if the patient signs without reading the information", "D": "It cannot be withdrawn", "E": "It is unnecessary if the research is scientifically important"}, "correct_letter": "B", "correct_answer": "B. It should be voluntary and informed", "why_correct": "UK research policy requires explicit consent, where consent is sought, to be voluntary and informed. Participants who refuse or withdraw should not face reprisal.", "exam_trap": "A signed form alone does not make consent ethically valid if the participant has not been appropriately informed.", "takeaway": "Research consent = informed + voluntary + appropriately documented.", "source": "[HRA], UK Policy Framework for Health and Social Care Research; HRA consent guidance, updated 2026."},
  {"id": "MAK-328", "subject": "Research methods & screening", "topic": "Research Ethics Committee", "title": "Research Ethics Committee", "stem": "A research team proposes a study involving human participants. Which body has the role of reviewing the ethical acceptability of relevant health and social care research proposals in the UK?", "options": {"A": "Research Ethics Committee", "B": "General Medical Council", "C": "Care Quality Commission", "D": "National Institute for Health and Care Excellence", "E": "Royal College examination board"}, "correct_letter": "A", "correct_answer": "A. Research Ethics Committee", "why_correct": "Research Ethics Committees review research proposals and give an opinion on their ethical acceptability, with the aim of safeguarding participants' rights, safety, dignity and wellbeing.", "exam_trap": "An REC is not responsible for deciding whether a treatment should be recommended clinically.", "takeaway": "Human research → appropriate research governance and ethical review.", "source": "[HRA], Research Ethics Committees overview, updated 7 May 2026."},
  {"id": "MAK-329", "subject": "Research methods & screening", "topic": "Participant withdrawal", "title": "Participant withdrawal", "stem": "A participant who previously consented to a research study informs the research team that they no longer wish to participate. What is the most appropriate general principle?", "options": {"A": "Participation must continue because consent was originally signed", "B": "The participant's decision to withdraw should be respected", "C": "Withdrawal should result in loss of routine clinical care", "D": "The investigator should conceal the withdrawal", "E": "The participant must provide a medical reason"}, "correct_letter": "B", "correct_answer": "B. The participant's decision to withdraw should be respected", "why_correct": "Research participation is voluntary. UK research policy states that where consent is refused or withdrawn, this should occur without reprisal.", "exam_trap": "Clinical treatment and research participation are separate decisions.", "takeaway": "Research participation is voluntary; withdrawal should not result in punishment or loss of appropriate care.", "source": "[HRA], UK Policy Framework for Health and Social Care Research (2017, updated 2022)."},
  {"id": "MAK-330", "subject": "Research methods & screening", "topic": "Research Ethics and equipoise", "title": "Research Ethics and equipoise", "stem": "A randomised trial is proposed comparing two accepted surgical strategies. The investigators genuinely do not know which strategy produces better patient outcomes. What ethical concept describes this state of genuine uncertainty?", "options": {"A": "Equipoise", "B": "Confounding", "C": "Selection bias", "D": "Attrition", "E": "Publication bias"}, "correct_letter": "A", "correct_answer": "A. Equipoise", "why_correct": "Clinical equipoise describes genuine uncertainty within the relevant clinical community about which intervention is preferable. It provides an important ethical basis for randomised comparison of alternative treatments.", "exam_trap": "The individual investigator does not need to believe that both treatments are identical; the key issue is genuine uncertainty about which is superior.", "takeaway": "Genuine clinical uncertainty between treatments → equipoise.", "source": "Research ethics principles and standard clinical-trial methodology; MRCS evidence-based practice syllabus."},
  {"id": "MAK-331", "subject": "Statistics & evidence-based medicine", "topic": "Quality-adjusted life year", "title": "Quality-adjusted life year", "stem": "A new treatment gives a patient an additional year of life at a health-related quality of life utility of 0.8. Approximately how many QALYs does this represent?", "options": {"A": "0.2", "B": "0.5", "C": "0.8", "D": "1.0", "E": "1.8"}, "correct_letter": "C", "correct_answer": "C. 0.8", "why_correct": "A QALY combines length of life with quality of life. QALYs = years of life × utility 1 × 0.8 = 0.8 QALYs.", "exam_trap": "A utility of 1 represents full health; 0 generally represents a state equivalent to death for the purpose of the conventional QALY scale.", "takeaway": "QALY = quantity of life × quality of life.", "source": "NICE Health Technology Evaluations: The Manual (process and methods guide PMG36, January 2022)."},
  {"id": "MAK-332", "subject": "Statistics & evidence-based medicine", "topic": "Incremental cost-effectiveness ratio", "title": "Incremental cost-effectiveness ratio", "stem": "A new treatment costs £30,000 more per patient than standard treatment and provides an additional 1.5 QALYs. What is the incremental cost-effectiveness ratio?", "options": {"A": "£10,000/QALY", "B": "£15,000/QALY", "C": "£20,000/QALY", "D": "£30,000/QALY", "E": "£45,000/QALY"}, "correct_letter": "C", "correct_answer": "C. £20,000/QALY", "why_correct": "ICER = incremental cost ÷ incremental health benefit = £30,000 ÷ 1.5 = £20,000 per QALY gained.", "exam_trap": "The ICER uses the incremental difference between the interventions, not the total treatment cost.", "takeaway": "ICER = extra cost ÷ extra benefit.", "source": "NICE health technology evaluation methodology."},
  {"id": "MAK-333", "subject": "Statistics & evidence-based medicine", "topic": "NICE cost-effectiveness range", "title": "NICE cost-effectiveness range", "stem": "When considering cost-effectiveness in NICE technology evaluation methodology, which range is commonly used when discussing the acceptability of interventions in terms of cost per QALY?", "options": {"A": "£100–£500/QALY", "B": "£1,000–£5,000/QALY", "C": "£5,000–£10,000/QALY", "D": "£20,000–£30,000/QALY", "E": "£100,000–£200,000/QALY"}, "correct_letter": "D", "correct_answer": "D. £20,000–£30,000/QALY", "why_correct": "NICE methodology uses £20,000 and £30,000 per QALY as important reference values in technology evaluation. Decisions are not determined by the ICER alone and may consider uncertainty and other relevant factors.", "exam_trap": "Do not describe £30,000/QALY as an absolute automatic rejection threshold.", "takeaway": "NICE cost-effectiveness decisions are not simply “above £30k = reject.”", "source": "NICE health technology evaluations manual."},
  {"id": "MAK-334", "subject": "Statistics & evidence-based medicine", "topic": "Opportunity cost", "title": "Opportunity cost", "stem": "An NHS organisation uses limited resources to fund a new treatment. As a result, resources are unavailable for another potentially beneficial treatment. What economic concept describes the benefit forgone from the alternative use?", "options": {"A": "Marginal utility", "B": "Opportunity cost", "C": "Relative risk", "D": "Economies of scale", "E": "External validity"}, "correct_letter": "B", "correct_answer": "B. Opportunity cost", "why_correct": "Opportunity cost is the benefit lost when resources are used for one option rather than the next best alternative.", "exam_trap": "It is not simply the monetary price of the chosen treatment.", "takeaway": "Limited resources → choosing A means giving up benefits from another option → opportunity cost.", "source": "NICE Health Technology Evaluations: The Manual (process and methods guide PMG36, January 2022)."},
  {"id": "MAK-335", "subject": "Statistics & evidence-based medicine", "topic": "Dominated intervention", "title": "Dominated intervention", "stem": "Treatment A costs more than treatment B and produces fewer QALYs. What is the economic relationship between the two treatments?", "options": {"A": "A dominates B", "B": "B dominates A", "C": "A and B are cost-neutral", "D": "They are necessarily equivalent", "E": "No comparison is possible"}, "correct_letter": "B", "correct_answer": "B. B dominates A", "why_correct": "An intervention is dominated when another option is both less costly and more effective. Here, B is cheaper and produces more QALYs, so B dominates A.", "exam_trap": "Dominance requires comparison of both cost and outcome.", "takeaway": "Cheaper + better → dominates.", "source": "NICE economic-evaluation methodology."},
  {"id": "MAK-336", "subject": "Statistics & evidence-based medicine", "topic": "Sensitivity versus specificity trade-off", "title": "Sensitivity versus specificity trade-off", "stem": "A diagnostic test threshold is changed so that more patients are classified as positive. Which change is generally expected?", "options": {"A": "Sensitivity decreases and specificity increases", "B": "Sensitivity increases and specificity decreases", "C": "Both must increase", "D": "Both must decrease", "E": "Neither can change"}, "correct_letter": "B", "correct_answer": "B. Sensitivity increases and specificity decreases", "why_correct": "Lowering the threshold generally captures more people with disease, increasing sensitivity, but also classifies more people without disease as positive, reducing specificity.", "exam_trap": "The exact direction depends on how the threshold is changed, but the classic trade-off is sensitivity versus specificity.", "takeaway": "More permissive positive threshold → usually ↑ sensitivity, ↓ specificity.", "source": "NICE diagnostic-test methodology."},
  {"id": "MAK-337", "subject": "Statistics & evidence-based medicine", "topic": "ROC curve", "title": "ROC curve", "stem": "A researcher wants to assess the performance of a diagnostic test across a range of possible thresholds. Which graphical method is most appropriate?", "options": {"A": "Kaplan-Meier curve", "B": "Forest plot", "C": "ROC curve", "D": "Funnel plot", "E": "Bland-Altman plot"}, "correct_letter": "C", "correct_answer": "C. ROC curve", "why_correct": "A receiver operating characteristic curve illustrates the trade-off between sensitivity and specificity across different diagnostic thresholds.", "exam_trap": "A ROC curve is not a survival analysis graph.", "takeaway": "Diagnostic threshold performance → ROC curve.", "source": "NICE diagnostic accuracy methodology includes ROC curves and area under the ROC curve as measures of diagnostic-test accuracy."},
  {"id": "MAK-338", "subject": "Statistics & evidence-based medicine", "topic": "Area under the ROC curve", "title": "Area under the ROC curve", "stem": "Two diagnostic tests are assessed using ROC curves. Test A has an AUC of 0.92 and Test B has an AUC of 0.68. What does the AUC primarily describe?", "options": {"A": "Disease prevalence", "B": "Overall discriminatory ability across thresholds", "C": "Positive predictive value at one fixed prevalence", "D": "Treatment effectiveness", "E": "Mortality reduction"}, "correct_letter": "B", "correct_answer": "B. Overall discriminatory ability across thresholds", "why_correct": "The area under the ROC curve provides a summary of the test's ability to discriminate between patients with and without the target condition across thresholds.", "exam_trap": "AUC is not the same as sensitivity or specificity at one chosen threshold.", "takeaway": "ROC AUC → overall discrimination.", "source": "NICE diagnostic accuracy methodology."},
  {"id": "MAK-339", "subject": "Statistics & evidence-based medicine", "topic": "Spectrum bias in diagnostic testing", "title": "Spectrum bias in diagnostic testing", "stem": "A diagnostic test appears extremely accurate when studied in a specialist centre containing patients with obvious disease and healthy controls, but performs less well in routine practice where patients have milder disease and overlapping conditions. What problem may this illustrate?", "options": {"A": "Spectrum bias", "B": "Recall bias", "C": "Publication bias", "D": "Attrition bias", "E": "Lead-time bias"}, "correct_letter": "A", "correct_answer": "A. Spectrum bias", "why_correct": "Diagnostic accuracy can vary according to the spectrum of disease severity and characteristics of the people being tested. A highly selected study population may make a test appear more accurate than it is in routine practice.", "exam_trap": "Diagnostic accuracy is not necessarily transferable from an idealised study population to a real-world undifferentiated population.", "takeaway": "Diagnostic test accuracy depends partly on who is being tested.", "source": "NICE diagnostic-test evidence methodology; diagnostic accuracy critical-appraisal principles."},
  {"id": "MAK-340", "subject": "Statistics & evidence-based medicine", "topic": "Reference standard", "title": "Reference standard", "stem": "A study evaluates a new diagnostic test for suspected appendicitis. The researchers compare its results with the definitive diagnosis established using an accepted reference method. What is the purpose of the reference standard?", "options": {"A": "To determine treatment cost", "B": "To provide the comparator against which diagnostic accuracy is assessed", "C": "To calculate hospital bed occupancy", "D": "To determine randomisation", "E": "To establish patient satisfaction"}, "correct_letter": "B", "correct_answer": "B. To provide the comparator against which diagnostic accuracy is assessed", "why_correct": "Diagnostic accuracy studies compare the index test with an appropriate reference standard to determine how well the test identifies the target condition.", "exam_trap": "A poor reference standard can distort estimates of diagnostic accuracy.", "takeaway": "Index test → compare against appropriate reference standard.", "source": "NICE diagnostic-test evidence methodology and QUADAS-2 principles."},
  {"id": "MAK-341", "subject": "Statistics & evidence-based medicine", "topic": "Verification bias", "title": "Verification bias", "stem": "In a diagnostic study, only patients with a positive screening test undergo the definitive reference test. Many patients with a negative screening test never receive the reference test. What type of bias can this introduce?", "options": {"A": "Verification bias", "B": "Recall bias", "C": "Lead-time bias", "D": "Publication bias", "E": "Length-time bias"}, "correct_letter": "A", "correct_answer": "A. Verification bias", "why_correct": "If verification with the reference standard depends on the result of the index test, estimates of sensitivity and specificity can be biased.", "exam_trap": "Ideally, interpretation of the index test should not determine whether an appropriate reference standard is applied when this would introduce bias.", "takeaway": "Reference standard applied selectively according to index-test result → verification bias.", "source": "NICE diagnostic accuracy critical-appraisal methodology."},
  {"id": "MAK-342", "subject": "Statistics & evidence-based medicine", "topic": "QUADAS-2", "title": "QUADAS-2", "stem": "A systematic review is assessing the risk of bias in diagnostic accuracy studies. Which tool is specifically designed for this purpose?", "options": {"A": "CONSORT", "B": "PRISMA", "C": "QUADAS-2", "D": "STROBE", "E": "CARE"}, "correct_letter": "C", "correct_answer": "C. QUADAS-2", "why_correct": "QUADAS-2 is designed to assess risk of bias and applicability concerns in diagnostic accuracy studies.", "exam_trap": "PRISMA concerns reporting of systematic reviews; it is not the principal risk-of-bias tool for diagnostic accuracy studies.", "takeaway": "Diagnostic accuracy study → QUADAS-2.", "source": "NICE guideline methodology identifies QUADAS-2 for appraisal of diagnostic-test accuracy studies."},
  {"id": "MAK-343", "subject": "Research methods & screening", "topic": "PDSA cycle", "title": "PDSA cycle", "stem": "A surgical department introduces a new checklist on one ward, monitors the results, and then decides whether to modify or expand the intervention. Which quality-improvement approach best describes this process?", "options": {"A": "PDSA cycle", "B": "Case-control study", "C": "Randomised controlled trial", "D": "Meta-analysis", "E": "Cross-sectional survey"}, "correct_letter": "A", "correct_answer": "A. PDSA cycle", "why_correct": "PDSA means Plan, Do, Study, Act and provides an iterative method for testing and refining changes in real clinical settings.", "exam_trap": "Quality improvement and research can overlap, but a PDSA cycle is specifically an improvement method.", "takeaway": "Plan → Do → Study → Act → repeat.", "source": "NHS England, Plan-Do-Study-Act (PDSA) cycles guidance, Online Library of Quality, Service Improvement and Redesign (QSIR) tools."},
  {"id": "MAK-344", "subject": "Research methods & screening", "topic": "Quality improvement measurement", "title": "Quality improvement measurement", "stem": "A department introduces a new system intended to reduce delays in administration of antibiotics. Which feature is essential to determine whether the intervention has actually produced improvement?", "options": {"A": "Measuring outcomes before and after the change", "B": "Changing the intervention repeatedly without measurement", "C": "Relying solely on staff opinion", "D": "Measuring only after the intervention", "E": "Avoiding predefined measures"}, "correct_letter": "A", "correct_answer": "A. Measuring outcomes before and after the change", "why_correct": "Quality improvement requires measurement to determine whether a change is associated with improvement.", "exam_trap": "Implementing a change without measuring its effect is not sufficient to demonstrate improvement.", "takeaway": "No measurement → no reliable demonstration of improvement.", "source": "NHS England quality-improvement methodology."},
  {"id": "MAK-345", "subject": "Research methods & screening", "topic": "Run chart", "title": "Run chart", "stem": "A surgical team plots the weekly rate of postoperative infections over 12 months to examine whether a quality-improvement intervention is associated with a change over time. What type of chart is most appropriate?", "options": {"A": "Run chart", "B": "Pie chart", "C": "Forest plot", "D": "ROC curve", "E": "Funnel plot"}, "correct_letter": "A", "correct_answer": "A. Run chart", "why_correct": "A run chart displays data sequentially over time and is useful for monitoring changes in a process.", "exam_trap": "A cross-sectional bar chart does not show the temporal pattern of a process.", "takeaway": "QI data plotted sequentially over time → run chart.", "source": "NHS quality-improvement methodology."},
  {"id": "MAK-346", "subject": "Research methods & screening", "topic": "Control chart", "title": "Control chart", "stem": "A department wants to distinguish normal variation in a clinical process from unusual variation that may indicate a significant change in the system. Which tool is specifically designed for this purpose?", "options": {"A": "Control chart", "B": "Pie chart", "C": "Forest plot", "D": "Kaplan-Meier curve", "E": "ROC curve"}, "correct_letter": "A", "correct_answer": "A. Control chart", "why_correct": "Control charts display measurements over time with statistically derived control limits to help identify unusual process variation.", "exam_trap": "A run chart shows trends over time; a control chart adds control limits to help assess process stability.", "takeaway": "Process variation + control limits → control chart.", "source": "NHS quality-improvement methodology."},
  {"id": "MAK-347", "subject": "Research methods & screening", "topic": "Audit standard", "title": "Audit standard", "stem": "A surgical department audits whether VTE assessments are completed according to a national guideline. What should provide the benchmark against which performance is compared?", "options": {"A": "The personal preference of the auditor", "B": "A predefined evidence-based standard", "C": "The previous week's result only", "D": "The number of available beds", "E": "A random percentage selected after data collection"}, "correct_letter": "B", "correct_answer": "B. A predefined evidence-based standard", "why_correct": "Clinical audit compares current practice against explicit standards derived from evidence, guidance, legislation or agreed best practice.", "exam_trap": "An audit is not simply collecting interesting clinical data.", "takeaway": "Audit = measure practice against a predefined standard.", "source": "MRCS candidate guidance includes clinical audit and evidence-based practice within the examination syllabus."},
  {"id": "MAK-348", "subject": "Research methods & screening", "topic": "Audit cycle", "title": "Audit cycle", "stem": "A department identifies poor compliance with a clinical standard, introduces a change, and subsequently measures compliance again. What is the purpose of the second measurement?", "options": {"A": "To establish disease prevalence", "B": "To determine whether practice improved after intervention", "C": "To randomise patients", "D": "To calculate diagnostic sensitivity", "E": "To establish a case-control ratio"}, "correct_letter": "B", "correct_answer": "B. To determine whether practice improved after intervention", "why_correct": "Re-audit assesses whether the changes introduced after the initial audit have resulted in improvement against the predefined standard.", "exam_trap": "Completing the first data collection alone does not complete the improvement cycle.", "takeaway": "Audit → identify gap → change practice → re-audit.", "source": "MRCS clinical-audit syllabus content."},
  {"id": "MAK-349", "subject": "Research methods & screening", "topic": "Process measure", "title": "Process measure", "stem": "A hospital introduces a new sepsis pathway. Investigators measure the proportion of eligible patients who receive the required assessment within the specified timeframe. What type of measure is this?", "options": {"A": "Process measure", "B": "Mortality outcome only", "C": "Economic utility", "D": "Diagnostic likelihood ratio", "E": "Prevalence measure"}, "correct_letter": "A", "correct_answer": "A. Process measure", "why_correct": "A process measure assesses whether a defined element of care was delivered. Examples include: •\tcompletion of an assessment •\tadministration of an intervention •\tdocumentation of a required step.", "exam_trap": "Process measures are different from patient outcomes such as mortality or complications.", "takeaway": "“What was done?” → process measure.", "source": "NHS quality-improvement methodology."},
  {"id": "MAK-350", "subject": "Research methods & screening", "topic": "Outcome measure", "title": "Outcome measure", "stem": "A quality-improvement project aims to reduce postoperative complications. Which is an outcome measure?", "options": {"A": "Percentage of staff completing training", "B": "Percentage of patients receiving a checklist", "C": "Rate of postoperative wound infection", "D": "Number of meetings held", "E": "Number of posters displayed"}, "correct_letter": "C", "correct_answer": "C. Rate of postoperative wound infection", "why_correct": "An outcome measure assesses the effect of care on patients.", "exam_trap": "Completing a checklist is a process measure; whether patient outcomes improve is an outcome measure.", "takeaway": "“What happened to the patient?” → outcome measure.", "source": "NHS quality-improvement methodology."},
  {"id": "MAK-351", "subject": "Research methods & screening", "topic": "Balancing measure", "title": "Balancing measure", "stem": "A hospital introduces a policy intended to reduce inpatient length of stay. Which measure would be most useful as a balancing measure?", "options": {"A": "Number of staff meetings", "B": "Readmission rate", "C": "Number of policy pages", "D": "Percentage of staff who read the policy", "E": "Number of posters displayed"}, "correct_letter": "B", "correct_answer": "B. Readmission rate", "why_correct": "A balancing measure checks whether improving one outcome unintentionally causes problems elsewhere. For example, reducing length of stay could potentially increase early readmissions if patients are discharged inappropriately early.", "exam_trap": "A quality-improvement project should not focus on one metric while ignoring possible unintended consequences.", "takeaway": "Improvement in one area + possible harm elsewhere → use a balancing measure.", "source": "NHS quality-improvement principles."},
  {"id": "MAK-352", "subject": "Research methods & screening", "topic": "Patient safety incident", "title": "Patient safety incident", "stem": "A patient receives the wrong medication because an incorrect drug was selected during prescribing. The patient is not harmed. How should this generally be regarded within the NHS patient-safety framework?", "options": {"A": "It cannot be a patient-safety incident because no harm occurred", "B": "It may constitute a patient-safety incident because an unsafe event occurred even without harm", "C": "It is automatically professional misconduct", "D": "It is necessarily negligence", "E": "It must always be treated as a criminal offence"}, "correct_letter": "B", "correct_answer": "B. It may constitute a patient-safety incident because an unsafe event occurred even without harm", "why_correct": "The NHS Patient Safety Incident Response Framework defines patient safety incidents as unintended or unexpected events, including omissions, where care could have or did cause harm.", "exam_trap": "Patient safety reporting and professional disciplinary or legal processes are distinct.", "takeaway": "No harm does not necessarily mean no patient-safety event.", "source": "NHS England Patient Safety Incident Response Framework, updated September 2025."},
  {"id": "MAK-353", "subject": "Research methods & screening", "topic": "System-based approach to safety", "title": "System-based approach to safety", "stem": "A medication error occurs repeatedly in different wards. Investigation identifies confusing electronic prescribing interfaces, interruptions and staffing pressures as contributing factors. Which approach is most consistent with the current NHS patient-safety framework?", "options": {"A": "Focus exclusively on blaming the individual", "B": "Examine system and contributory factors", "C": "Ignore the incident because no patient died", "D": "Automatically dismiss the prescriber", "E": "Assume one individual is always the sole cause"}, "correct_letter": "B", "correct_answer": "B. Examine system and contributory factors", "why_correct": "PSIRF promotes system-based approaches to understanding how incidents happen and identifying contributory factors rather than assuming a single linear cause.", "exam_trap": "A system-based approach does not mean individual professional accountability is never relevant; different processes have different purposes.", "takeaway": "Patient safety learning → understand the system and contributory factors.", "source": "NHS England PSIRF, updated September 2025."},
  {"id": "MAK-354", "subject": "Research methods & screening", "topic": "PSIRF", "title": "PSIRF", "stem": "Which framework currently sets out the NHS approach in England to responding to patient-safety incidents for learning and improvement?", "options": {"A": "Serious Incident Framework 2015", "B": "Patient Safety Incident Response Framework", "C": "Francis Framework", "D": "National Audit Framework", "E": "Hospital Episode Statistics Framework"}, "correct_letter": "B", "correct_answer": "B. Patient Safety Incident Response Framework", "why_correct": "PSIRF replaced the Serious Incident Framework and provides the current NHS approach to patient-safety incident response.", "exam_trap": "Do not use the old “Serious Incident Framework” as though it remains the current overarching approach.", "takeaway": "Current NHS England incident-response framework → PSIRF.", "source": "NHS England PSIRF, current page updated September 2025; supporting standards updated January 2026."},
  {"id": "MAK-355", "subject": "Research methods & screening", "topic": "PSIRF and blame", "title": "PSIRF and blame", "stem": "Which statement best reflects the purpose of PSIRF?", "options": {"A": "To determine individual criminal liability for every incident", "B": "To identify a person to blame for every incident", "C": "To promote learning and improvement from patient-safety incidents", "D": "To replace professional regulation", "E": "To determine compensation in civil litigation"}, "correct_letter": "C", "correct_answer": "C. To promote learning and improvement from patient-safety incidents", "why_correct": "PSIRF is designed around learning and improvement, with system-based approaches and proportionate responses.", "exam_trap": "Patient-safety learning, professional regulation, employment processes and legal investigations can have different remits.", "takeaway": "PSIRF = learning and improvement, not a universal blame-allocation process.", "source": "NHS England PSIRF, updated September 2025."},
  {"id": "MAK-356", "subject": "Research methods & screening", "topic": "Root-cause oversimplification", "title": "Root-cause oversimplification", "stem": "A surgical complication occurs. An investigation concludes that the only cause was “the surgeon made an error” without examining workload, equipment, communication, training or environmental factors. What is the main limitation of this approach?", "options": {"A": "It is too focused on system factors", "B": "It may oversimplify a complex system event", "C": "It automatically establishes causation", "D": "It proves the complication was unavoidable", "E": "It is a form of randomisation"}, "correct_letter": "B", "correct_answer": "B. It may oversimplify a complex system event", "why_correct": "Modern patient-safety approaches recognise that incidents can involve multiple interacting contributory factors.", "exam_trap": "Identifying an individual action may be relevant, but stopping there can prevent understanding of system vulnerabilities.", "takeaway": "Safety investigation → ask “how did the system allow this to happen?”", "source": "NHS England PSIRF and system-based learning-response methodology."},
  {"id": "MAK-357", "subject": "Statistics & evidence-based medicine", "topic": "Clinical guideline applicability", "title": "Clinical guideline applicability", "stem": "A NICE guideline recommends an intervention for a defined patient population. A clinician considers applying it to a patient with characteristics explicitly outside the guideline scope. What is the most appropriate approach?", "options": {"A": "Apply the recommendation automatically", "B": "Recognise that the recommendation may not directly apply and use clinical judgement and other relevant evidence", "C": "Ignore all guidelines permanently", "D": "Assume the recommendation is legally mandatory in every circumstance", "E": "Treat the guideline as a substitute for individual assessment"}, "correct_letter": "B", "correct_answer": "B. Recognise that the recommendation may not directly apply and use clinical judgement and other relevant evidence", "why_correct": "Guideline recommendations apply within their defined populations, settings and circumstances. Clinical decisions require consideration of the individual patient and relevant evidence.", "exam_trap": "A guideline is not automatically applicable to every patient.", "takeaway": "Before applying a recommendation → check its population and scope.", "source": "NICE guideline methodology and scope principles."},
  {"id": "MAK-358", "subject": "Statistics & evidence-based medicine", "topic": "Guideline recommendation versus evidence certainty", "title": "Guideline recommendation versus evidence certainty", "stem": "A clinical guideline makes a recommendation, but the underlying evidence is limited and uncertain. Which statement is most appropriate?", "options": {"A": "The recommendation automatically proves the treatment is effective", "B": "The existence of a recommendation means uncertainty has disappeared", "C": "The recommendation should be interpreted in the context of the evidence and the guideline committee's judgement", "D": "Evidence quality is irrelevant once a guideline exists", "E": "Guidelines cannot contain recommendations based on uncertain evidence"}, "correct_letter": "C", "correct_answer": "C. The recommendation should be interpreted in the context of the evidence and the guideline committee's judgement", "why_correct": "Guidelines integrate evidence with structured judgement and other considerations. A recommendation does not necessarily mean that the underlying evidence is certain.", "exam_trap": "“Recommended” does not mean “supported by perfect evidence.”", "takeaway": "Guideline recommendation ≠ evidence certainty.", "source": "NICE guideline methods and evidence-review methodology."},
  {"id": "MAK-359", "subject": "Statistics & evidence-based medicine", "topic": "Applicability of diagnostic evidence", "title": "Applicability of diagnostic evidence", "stem": "A diagnostic test has excellent sensitivity and specificity in a specialist research population. Before using the published estimates in general surgical practice, what should the clinician consider?", "options": {"A": "Only the sample size", "B": "Whether the study population and setting resemble the intended clinical population", "C": "Only the p-value", "D": "Only the cost of the test", "E": "Whether the article has a colourful graph"}, "correct_letter": "B", "correct_answer": "B. Whether the study population and setting resemble the intended clinical population", "why_correct": "Diagnostic accuracy estimates may not transfer directly between populations with different disease prevalence, severity, comorbidity and spectrum.", "exam_trap": "A technically excellent diagnostic study can still have limited applicability to a different clinical population.", "takeaway": "Diagnostic evidence → assess applicability, not just accuracy.", "source": "NICE diagnostic evidence methodology and QUADAS-2 principles."},
  {"id": "MAK-360", "subject": "Statistics & evidence-based medicine", "topic": "Evidence-informed clinical decision-making", "title": "Evidence-informed clinical decision-making", "stem": "A surgeon is deciding whether to adopt a new intervention. Which combination best represents evidence-informed clinical decision-making?", "options": {"A": "Research evidence alone", "B": "Personal experience alone", "C": "Patient preferences alone", "D": "Best available evidence, clinical expertise and patient values/circumstances", "E": "Social-media opinion alone"}, "correct_letter": "D", "correct_answer": "D. Best available evidence, clinical expertise and patient values/circumstances", "why_correct": "Evidence-informed clinical practice integrates the best available evidence with clinical expertise and the individual patient's circumstances, preferences and values.", "exam_trap": "Evidence-based medicine does not mean blindly following research results without considering the patient.", "takeaway": "Best evidence + clinical expertise + patient values/context.", "source": "MRCS evidence-based practice syllabus and established evidence-based medicine principles."},
  {"id": "MAK-361", "subject": "Physiology", "topic": "CT attenuation", "title": "CT attenuation", "stem": "On a CT scan, which tissue would normally have the highest attenuation?", "options": {"A": "Air", "B": "Fat", "C": "Water", "D": "Skeletal muscle", "E": "Cortical bone"}, "correct_letter": "E", "correct_answer": "E. Cortical bone", "why_correct": "CT attenuation reflects the degree to which tissues attenuate X-rays. Dense cortical bone has substantially higher attenuation than soft tissues, while air has very low attenuation.", "exam_trap": "CT brightness is not equivalent to “how much blood is present” or “how vascular the tissue is.”", "takeaway": "CT attenuation broadly increases from air → fat → water/soft tissue → bone.", "source": "Standard radiological imaging principles; MRCS Applied Basic Science syllabus."},
  {"id": "MAK-362", "subject": "Physiology", "topic": "MRI and ionising radiation", "title": "MRI and ionising radiation", "stem": "Which statement about conventional MRI is correct?", "options": {"A": "It uses ionising radiation", "B": "It uses X-rays", "C": "It uses a strong magnetic field and radiofrequency energy", "D": "It uses gamma radiation", "E": "It requires radioactive contrast in all examinations"}, "correct_letter": "C", "correct_answer": "C. It uses a strong magnetic field and radiofrequency energy", "why_correct": "MRI does not use ionising radiation. It uses a magnetic field and radiofrequency pulses to generate images.", "exam_trap": "MRI contrast agents such as gadolinium-based agents are not radioactive.", "takeaway": "MRI ≠ X-ray radiation.", "source": "Standard MRI physics; MRCS Applied Basic Science syllabus."},
  {"id": "MAK-363", "subject": "Physiology", "topic": "Ultrasound principle", "title": "Ultrasound principle", "stem": "Which physical phenomenon is primarily used to generate diagnostic ultrasound images?", "options": {"A": "X-ray attenuation", "B": "Radioactive decay", "C": "Reflection of high-frequency sound waves", "D": "Nuclear magnetic resonance", "E": "Gamma-ray emission"}, "correct_letter": "C", "correct_answer": "C. Reflection of high-frequency sound waves", "why_correct": "Ultrasound transducers emit high-frequency sound waves and detect returning echoes generated at tissue interfaces.", "exam_trap": "Ultrasound does not use ionising radiation.", "takeaway": "Ultrasound = sound waves + returning echoes.", "source": "Standard diagnostic ultrasound principles; MRCS Applied Basic Science syllabus."},
  {"id": "MAK-364", "subject": "Physiology", "topic": "Doppler ultrasound", "title": "Doppler ultrasound", "stem": "A Doppler ultrasound examination is used to assess blood flow through a vessel. Which physical phenomenon provides the basis for this technique?", "options": {"A": "Doppler frequency shift", "B": "Radioactive decay", "C": "Photoelectric absorption only", "D": "Nuclear spin relaxation", "E": "Magnetic susceptibility only"}, "correct_letter": "A", "correct_answer": "A. Doppler frequency shift", "why_correct": "The frequency of reflected ultrasound changes when the reflecting blood cells are moving relative to the transducer.", "exam_trap": "", "takeaway": "Doppler → movement → frequency shift → blood-flow assessment.", "source": "Standard diagnostic ultrasound physics; MRCS Applied Basic Science syllabus."},
  {"id": "MAK-365", "subject": "Physiology", "topic": "Plain radiograph projection", "title": "Plain radiograph projection", "stem": "A patient undergoes a standard chest radiograph in the posteroanterior (PA) projection. Which statement is correct?", "options": {"A": "X-rays enter the anterior chest and exit posteriorly", "B": "X-rays enter posteriorly and exit anteriorly", "C": "X-rays are replaced by ultrasound waves", "D": "No ionising radiation is used", "E": "The patient must always be anaesthetised"}, "correct_letter": "B", "correct_answer": "B. X-rays enter posteriorly and exit anteriorly", "why_correct": "In a PA projection, the X-ray beam passes from posterior to anterior.", "exam_trap": "PA describes beam direction, not the position of the patient's heart.", "takeaway": "PA = posterior → anterior.", "source": "Standard radiographic imaging principles."},
  {"id": "MAK-366", "subject": "Physiology", "topic": "Chest radiograph magnification", "title": "Chest radiograph magnification", "stem": "Why is a PA chest radiograph generally preferred to an AP chest radiograph when assessing cardiac size in an ambulant patient?", "options": {"A": "PA radiographs use ultrasound", "B": "AP positioning can magnify the heart because of its greater distance from the detector", "C": "AP radiographs contain no radiation", "D": "PA radiographs always produce higher radiation doses", "E": "Cardiac size cannot be assessed on either projection"}, "correct_letter": "B", "correct_answer": "B. AP positioning can magnify the heart because of its greater distance from the detector", "why_correct": "When the heart is farther from the detector, magnification can make the cardiac silhouette appear larger. AP portable films therefore require caution when interpreting apparent cardiomegaly.", "exam_trap": "Apparent cardiomegaly on an AP portable film does not necessarily indicate true enlargement.", "takeaway": "AP portable chest → beware cardiac magnification.", "source": "Standard chest-radiography principles."},
  {"id": "MAK-367", "subject": "Physiology", "topic": "Contrast media and renal function", "title": "Contrast media and renal function", "stem": "A patient is being considered for an imaging examination involving iodinated contrast. Which patient factor is particularly relevant when assessing the risk of contrast-associated kidney injury?", "options": {"A": "Renal function", "B": "Hair colour", "C": "Dominant hand", "D": "ABO blood group alone", "E": "Height alone"}, "correct_letter": "A", "correct_answer": "A. Renal function", "why_correct": "Renal function is an important factor when assessing patients before iodinated contrast administration, particularly in patients at increased risk of acute kidney injury.", "exam_trap": "Do not equate every rise in creatinine after contrast with definite causation by contrast.", "takeaway": "Iodinated contrast assessment → check renal function and the clinical context.", "source": "Current UK radiology/contrast safety principles; MRCS Applied Basic Science syllabus."},
  {"id": "MAK-368", "subject": "Physiology", "topic": "MRI safety", "title": "MRI safety", "stem": "Which implanted device characteristic is particularly important before an MRI examination?", "options": {"A": "Whether the device is MR-safe/MR-conditional", "B": "Whether the patient is left- or right-handed", "C": "Whether the patient has eaten breakfast", "D": "The patient's ABO blood group", "E": "The patient's skin colour"}, "correct_letter": "A", "correct_answer": "A. Whether the device is MR-safe/MR-conditional", "why_correct": "The strong magnetic field can interact dangerously with some implants and devices. Device-specific MRI compatibility must therefore be established.", "exam_trap": "“Metal present” does not automatically mean “MRI impossible”; device characteristics and MRI conditions matter.", "takeaway": "Before MRI → identify implants and establish their MRI status.", "source": "Standard MRI safety principles; MRCS imaging syllabus."},
  {"id": "MAK-369", "subject": "Physiology", "topic": "Ionising radiation", "title": "Ionising radiation", "stem": "Which imaging modality uses ionising radiation?", "options": {"A": "MRI", "B": "Ultrasound", "C": "Plain radiography", "D": "Conventional optical endoscopy", "E": "Clinical examination"}, "correct_letter": "C", "correct_answer": "C. Plain radiography", "why_correct": "Plain radiography uses X-rays, which are ionising radiation. MRI and ultrasound do not use ionising radiation.", "exam_trap": "“Radiation” is not synonymous with “ionising radiation”; MRI uses electromagnetic fields but not ionising radiation.", "takeaway": "X-ray and CT → ionising radiation.", "source": "GOV.UK, Ionising Radiation (Medical Exposure) Regulations 2017 guidance, updated 4 September 2024."},
  {"id": "MAK-370", "subject": "Physiology", "topic": "CT and ionising radiation", "title": "CT and ionising radiation", "stem": "Which statement about CT is correct?", "options": {"A": "CT uses ionising radiation", "B": "CT uses only sound waves", "C": "CT uses only magnetic fields", "D": "CT never involves contrast", "E": "CT produces images without X-rays"}, "correct_letter": "A", "correct_answer": "A. CT uses ionising radiation", "why_correct": "CT uses X-rays to acquire multiple projections that are reconstructed into cross-sectional images.", "exam_trap": "CT is not equivalent to MRI simply because both provide cross-sectional images.", "takeaway": "CT = X-rays + computer reconstruction.", "source": "GOV.UK, medical radiation safety framework; IR(ME)R 2017 guidance updated September 2024."},
  {"id": "MAK-371", "subject": "Physiology", "topic": "Justification of medical exposure", "title": "Justification of medical exposure", "stem": "Under the UK framework governing medical exposures to ionising radiation, which principle is fundamental before an individual medical exposure is undertaken?", "options": {"A": "The exposure must be justified", "B": "Every exposure must be performed regardless of clinical indication", "C": "Radiation exposure has no associated risk", "D": "CT is always preferable to MRI", "E": "The patient must always receive the highest possible dose"}, "correct_letter": "A", "correct_answer": "A. The exposure must be justified", "why_correct": "IR(ME)R requires individual medical exposures to be justified so that the benefits outweigh the potential detriment of the radiation exposure.", "exam_trap": "“Justified” does not mean that the exposure must produce a positive finding.", "takeaway": "Before ionising-radiation exposure → justify the exposure.", "source": "GOV.UK, IR(ME)R 2017 guidance, updated 4 September 2024."},
  {"id": "MAK-372", "subject": "Physiology", "topic": "Optimisation of radiation dose", "title": "Optimisation of radiation dose", "stem": "Under IR(ME)R, which principle applies to optimisation of diagnostic medical exposures?", "options": {"A": "Use the highest possible radiation dose", "B": "Keep exposure as low as reasonably practicable for the intended diagnostic purpose", "C": "Avoid all imaging regardless of benefit", "D": "Use identical doses for every patient", "E": "Optimisation is unnecessary in children"}, "correct_letter": "B", "correct_answer": "B. Keep exposure as low as reasonably practicable for the intended diagnostic purpose", "why_correct": "The regulations require optimisation of medical exposures, with diagnostic doses kept as low as reasonably practicable for the intended clinical purpose.", "exam_trap": "Optimisation does not mean using the lowest conceivable dose if image quality becomes inadequate.", "takeaway": "Radiation safety = justified exposure + optimised dose.", "source": "GOV.UK, IR(ME)R 2017 guidance."},
  {"id": "MAK-373", "subject": "Physiology", "topic": "Pregnancy and ionising radiation", "title": "Pregnancy and ionising radiation", "stem": "A patient who may be pregnant requires an urgent CT examination. Which principle is most appropriate?", "options": {"A": "Pregnancy automatically prohibits all ionising-radiation imaging", "B": "The exposure should be appropriately justified, taking pregnancy and urgency into account", "C": "The patient should never undergo imaging", "D": "Pregnancy makes CT completely risk-free", "E": "Pregnancy status is irrelevant"}, "correct_letter": "B", "correct_answer": "B. The exposure should be appropriately justified, taking pregnancy and urgency into account", "why_correct": "IR(ME)R specifically requires particular attention where pregnancy cannot be excluded, especially for abdominal or pelvic exposures. Urgency is also relevant to justification.", "exam_trap": "Pregnancy is not an absolute prohibition against clinically necessary imaging.", "takeaway": "Pregnancy + urgent imaging → don't reflexively cancel; assess justification and risk.", "source": "GOV.UK, IR(ME)R 2017 guidance, updated 4 September 2024."},
  {"id": "MAK-374", "subject": "Physiology", "topic": "Medical Physics Expert", "title": "Medical Physics Expert", "stem": "Under IR(ME)R, what is the role of a Medical Physics Expert?", "options": {"A": "To replace the surgeon during operations", "B": "To provide specialist advice concerning radiation protection, dosimetry and equipment", "C": "To make every clinical diagnosis", "D": "To prescribe antibiotics", "E": "To determine all surgical indications"}, "correct_letter": "B", "correct_answer": "B. To provide specialist advice concerning radiation protection, dosimetry and equipment", "why_correct": "IR(ME)R requires employers to ensure appropriate involvement of a Medical Physics Expert in matters including radiation protection, dosimetry, equipment and optimisation.", "exam_trap": "The MPE is a specialist radiation/physics adviser, not the clinician who makes every decision about patient treatment.", "takeaway": "MPE → radiation physics, dosimetry, optimisation and equipment safety.", "source": "IR(ME)R 2017 and GOV.UK guidance."},
  {"id": "MAK-375", "subject": "Physiology", "topic": "Diagnostic reference level", "title": "Diagnostic reference level", "stem": "What is the primary purpose of a diagnostic reference level (DRL)?", "options": {"A": "To define a mandatory radiation dose for every individual patient", "B": "To help identify unusually high typical doses for imaging procedures and support optimisation", "C": "To determine whether a patient has cancer", "D": "To replace clinical justification", "E": "To determine surgical mortality"}, "correct_letter": "B", "correct_answer": "B. To help identify unusually high typical doses for imaging procedures and support optimisation", "why_correct": "Diagnostic reference levels are used as investigation/optimisation tools for typical radiation doses associated with imaging procedures.", "exam_trap": "A DRL is not a patient-specific dose limit.", "takeaway": "DRL = optimisation benchmark, not an individual dose limit.", "source": "GOV.UK medical radiation framework and UK national diagnostic reference levels."},
  {"id": "MAK-376", "subject": "Pathology: inflammation & wound healing", "topic": "Apoptosis versus necrosis", "title": "Apoptosis versus necrosis", "stem": "Which feature is most characteristic of apoptosis rather than uncontrolled necrotic cell death?", "options": {"A": "Cell swelling with membrane rupture", "B": "Programmed cell death with cellular fragmentation", "C": "Extensive surrounding inflammation as the defining feature", "D": "Immediate release of intracellular contents", "E": "Tissue liquefaction in all cases"}, "correct_letter": "B", "correct_answer": "B. Programmed cell death with cellular fragmentation", "why_correct": "Apoptosis is regulated cell death characterised by cellular shrinkage, nuclear fragmentation and formation of apoptotic bodies, generally without the marked inflammatory response associated with necrosis.", "exam_trap": "Apoptosis is not simply “less severe necrosis.”", "takeaway": "Apoptosis = regulated cellular deletion.", "source": "Standard pathology; MRCS Applied Basic Science syllabus."},
  {"id": "MAK-377", "subject": "Pathology: inflammation & wound healing", "topic": "Free-radical injury", "title": "Free-radical injury", "stem": "Which molecule is an example of a reactive oxygen species capable of contributing to cellular injury?", "options": {"A": "Superoxide", "B": "Sodium chloride", "C": "Albumin", "D": "Glucose", "E": "Urea"}, "correct_letter": "A", "correct_answer": "A. Superoxide", "why_correct": "Reactive oxygen species include molecules such as superoxide and hydroxyl radicals. Excessive oxidative stress can damage lipids, proteins and DNA.", "exam_trap": "Reactive oxygen species are not synonymous with all oxygen-containing molecules.", "takeaway": "Oxidative stress → reactive oxygen species → cellular damage.", "source": "Standard pathology and cellular injury principles."},
  {"id": "MAK-378", "subject": "Pathology: inflammation & wound healing", "topic": "Ischaemia-reperfusion injury", "title": "Ischaemia-reperfusion injury", "stem": "A limb has prolonged ischaemia followed by restoration of blood flow. Which mechanism can contribute to additional tissue injury after reperfusion?", "options": {"A": "Reactive oxygen species generation", "B": "Permanent absence of oxygen", "C": "Complete suppression of inflammation", "D": "Elimination of neutrophil activity", "E": "Immediate disappearance of intracellular calcium"}, "correct_letter": "A", "correct_answer": "A. Reactive oxygen species generation", "why_correct": "Reperfusion can generate reactive oxygen species and trigger inflammatory pathways, contributing to tissue injury.", "exam_trap": "Restoring blood flow is essential, but reperfusion itself can contribute to cellular injury after prolonged ischaemia.", "takeaway": "Ischaemia → reperfusion → ROS + inflammatory injury.", "source": "Standard pathology; MRCS Applied Basic Science syllabus."},
  {"id": "MAK-379", "subject": "Pathology: oncology & haematology", "topic": "Tumour suppressor gene", "title": "Tumour suppressor gene", "stem": "Which statement best describes the normal function of a tumour suppressor gene?", "options": {"A": "It promotes uncontrolled cellular proliferation", "B": "It helps restrain cell proliferation or maintain genomic integrity", "C": "It always encodes a bacterial toxin", "D": "It prevents all apoptosis", "E": "It is necessarily located on the mitochondrial genome"}, "correct_letter": "B", "correct_answer": "B. It helps restrain cell proliferation or maintain genomic integrity", "why_correct": "Tumour suppressor genes encode proteins involved in controlling proliferation, DNA repair, cell-cycle checkpoints or apoptosis.", "exam_trap": "Loss of tumour-suppressor function can promote malignancy.", "takeaway": "Tumour suppressor loss → loss of growth restraint.", "source": "Standard molecular pathology; MRCS Applied Basic Science syllabus."},
  {"id": "MAK-380", "subject": "Pathology: oncology & haematology", "topic": "Oncogene activation", "title": "Oncogene activation", "stem": "A mutation causes a proto-oncogene to become constitutively active, promoting cell proliferation. What has occurred?", "options": {"A": "Activation of an oncogenic pathway", "B": "Inactivation of all tumour suppressors", "C": "Physiological apoptosis", "D": "Loss of mitochondrial DNA only", "E": "Normal cell-cycle arrest"}, "correct_letter": "A", "correct_answer": "A. Activation of an oncogenic pathway", "why_correct": "Proto-oncogenes normally participate in regulated growth and survival signalling. Activating mutations can convert them into oncogenes that promote inappropriate proliferation.", "exam_trap": "Oncogenes are generally activated by gain-of-function mechanisms, whereas tumour-suppressor genes are commonly inactivated by loss-of-function mechanisms.", "takeaway": "Proto-oncogene gain of function → oncogenic signalling.", "source": "Standard molecular oncology; MRCS Applied Basic Science syllabus."},
  {"id": "MAK-381", "subject": "Genetics", "topic": "Autosomal dominant mutation", "title": "Autosomal dominant mutation", "stem": "A pathogenic variant causing an autosomal dominant disorder is present in a heterozygous parent. Assuming complete penetrance and an unaffected partner, what is the probability that each pregnancy inherits the variant?", "options": {"A": "0%", "B": "10%", "C": "25%", "D": "50%", "E": "100%"}, "correct_letter": "D", "correct_answer": "D. 50%", "why_correct": "A heterozygous affected parent can transmit either the normal or pathogenic allele.", "exam_trap": "This is the probability per pregnancy; previous children do not alter the probability for the next pregnancy.", "takeaway": "Autosomal dominant, one affected heterozygous parent → 50% risk per pregnancy, regardless of prior outcomes.", "source": "Standard medical genetics; MRCS Applied Basic Science syllabus."},
  {"id": "MAK-382", "subject": "Genetics", "topic": "Mitochondrial inheritance", "title": "Mitochondrial inheritance", "stem": "A pathogenic mitochondrial DNA variant is present in a mother. Which inheritance pattern is characteristic of mitochondrial disorders?", "options": {"A": "Transmission exclusively from fathers", "B": "Maternal inheritance", "C": "Y-linked inheritance", "D": "X-linked dominant inheritance only", "E": "Autosomal recessive inheritance only"}, "correct_letter": "B", "correct_answer": "B. Maternal inheritance", "why_correct": "Mitochondria are predominantly inherited through the oocyte, so mitochondrial DNA variants are transmitted maternally.", "exam_trap": "Mitochondrial inheritance is not the same as autosomal dominant inheritance.", "takeaway": "Mitochondrial DNA → maternal transmission.", "source": "Standard medical genetics; MRCS Applied Basic Science syllabus."},
  {"id": "MAK-383", "subject": "Microbiology & surgical infection", "topic": "Antigen presentation via MHC class I", "title": "Antigen presentation via MHC class I", "stem": "MHC class I molecules primarily present endogenous intracellular peptides to which cells?", "options": {"A": "CD8 T cells", "B": "CD4 T cells", "C": "B cells only", "D": "Neutrophils", "E": "Eosinophils"}, "correct_letter": "A", "correct_answer": "A. CD8 T cells", "why_correct": "MHC class I presents intracellular peptides to CD8 cytotoxic T lymphocytes.", "exam_trap": "MHC class II is classically associated with presentation to CD4 T helper cells.", "takeaway": "MHC I → intracellular antigen → CD8.", "source": "Standard immunology; MRCS Applied Basic Science syllabus."},
  {"id": "MAK-384", "subject": "Microbiology & surgical infection", "topic": "MHC class II", "title": "MHC class II", "stem": "MHC class II molecules primarily present extracellularly derived antigen to which cells?", "options": {"A": "CD8 T cells", "B": "CD4 T cells", "C": "Red blood cells", "D": "Platelets", "E": "Neutrophils only"}, "correct_letter": "B", "correct_answer": "B. CD4 T cells", "why_correct": "Professional antigen-presenting cells process extracellular antigens and present peptide fragments via MHC class II to CD4 T cells.", "exam_trap": "", "takeaway": "MHC II → extracellular antigen → CD4.", "source": "Standard immunology; MRCS Applied Basic Science syllabus."},
  {"id": "MAK-385", "subject": "Microbiology & surgical infection", "topic": "Complement membrane attack complex", "title": "Complement membrane attack complex", "stem": "Which complement complex directly forms pores in susceptible target cell membranes?", "options": {"A": "C1 complex", "B": "C3 convertase", "C": "C5a", "D": "Membrane attack complex", "E": "C-reactive protein"}, "correct_letter": "D", "correct_answer": "D. Membrane attack complex", "why_correct": "The terminal complement pathway forms the membrane attack complex, which creates membrane pores.", "exam_trap": "C3b is particularly important for opsonisation, while C5a has major chemotactic and inflammatory effects.", "takeaway": "MAC → membrane pores.", "source": "Standard immunology; MRCS Applied Basic Science syllabus."},
  {"id": "MAK-386", "subject": "Microbiology & surgical infection", "topic": "IgA", "title": "IgA", "stem": "Which immunoglobulin is particularly important in mucosal secretions?", "options": {"A": "IgA", "B": "IgD", "C": "IgE", "D": "IgG only", "E": "IgM only"}, "correct_letter": "A", "correct_answer": "A. IgA", "why_correct": "Secretory IgA is an important component of mucosal immune defence, including the respiratory and gastrointestinal tracts.", "exam_trap": "IgE is associated particularly with type I hypersensitivity and helminth responses, not the principal mucosal secretory immunoglobulin.", "takeaway": "Mucosal immunity → think IgA.", "source": "Standard immunology; MRCS Applied Basic Science syllabus."},
  {"id": "MAK-387", "subject": "Microbiology & surgical infection", "topic": "IgE and mast cells", "title": "IgE and mast cells", "stem": "Which immunoglobulin is classically involved in immediate type I hypersensitivity through interaction with mast cells?", "options": {"A": "IgA", "B": "IgD", "C": "IgE", "D": "IgG4 only", "E": "IgM"}, "correct_letter": "C", "correct_answer": "C. IgE", "why_correct": "IgE binds high-affinity Fcε receptors on mast cells and basophils. Cross-linking can trigger mediator release.", "exam_trap": "IgE-mediated reactions can occur rapidly after re-exposure but the clinical presentation depends on the allergen and tissue involved.", "takeaway": "Type I hypersensitivity → IgE + mast cells.", "source": "Standard immunology; MRCS Applied Basic Science syllabus."},
  {"id": "MAK-388", "subject": "Microbiology & surgical infection", "topic": "Neutrophils in bacterial infection", "title": "Neutrophils in bacterial infection", "stem": "Which leukocyte is particularly important in the early innate immune response to many acute bacterial infections?", "options": {"A": "Neutrophil", "B": "Eosinophil", "C": "Plasma cell", "D": "Memory B cell", "E": "Megakaryocyte"}, "correct_letter": "A", "correct_answer": "A. Neutrophil", "why_correct": "Neutrophils are rapid innate immune responders that migrate toward sites of acute inflammation and can phagocytose and kill microorganisms.", "exam_trap": "A raised neutrophil count is not specific for bacterial infection; many inflammatory and physiological conditions can cause neutrophilia.", "takeaway": "Acute bacterial inflammation → neutrophils are key early responders.", "source": "Standard immunology/pathology; MRCS Applied Basic Science syllabus."},
  {"id": "MAK-389", "subject": "Microbiology & surgical infection", "topic": "Anaerobic infection", "title": "Anaerobic infection", "stem": "Which organism is classically associated with anaerobic infection and toxin-mediated myonecrosis?", "options": {"A": "Clostridium perfringens", "B": "Mycoplasma pneumoniae", "C": "Neisseria meningitidis", "D": "Bordetella pertussis", "E": "Chlamydia trachomatis"}, "correct_letter": "A", "correct_answer": "A. Clostridium perfringens", "why_correct": "C. perfringens is an anaerobic, spore-forming Gram-positive bacillus associated with gas gangrene/myonecrosis.", "exam_trap": "Not all wound infections producing gas are caused by C. perfringens; mixed anaerobic infections can also produce gas.", "takeaway": "Rapid myonecrosis + gas → think clostridial infection.", "source": "Standard microbiology and surgical infection principles; MRCS Applied Basic Science syllabus."},
  {"id": "MAK-390", "subject": "Microbiology & surgical infection", "topic": "Biofilm", "title": "Biofilm", "stem": "Why can bacterial biofilms make some infections difficult to eradicate?", "options": {"A": "They prevent all bacterial replication", "B": "They can provide a protected community with altered bacterial physiology and reduced susceptibility to antimicrobial and host responses", "C": "They contain only viruses", "D": "They occur only in the bloodstream", "E": "They make bacteria incapable of adhesion"}, "correct_letter": "B", "correct_answer": "B. They can provide a protected community with altered bacterial physiology and reduced susceptibility to antimicrobial and host responses", "why_correct": "Biofilms are structured microbial communities attached to surfaces and embedded within an extracellular matrix. They are important in infections involving implanted devices and other surfaces.", "exam_trap": "Biofilm-associated reduced antimicrobial susceptibility is not simply the same as genetically determined antibiotic resistance.", "takeaway": "Device-associated persistent infection → think biofilm.", "source": "Standard microbiology and surgical infection principles; MRCS Applied Basic Science syllabus."},
  {"id": "MAK-391", "subject": "Cardiorespiratory physiology", "topic": "Functional residual capacity", "title": "Functional residual capacity", "stem": "Which lung volume represents the amount of air remaining in the lungs at the end of a normal, passive expiration?", "options": {"A": "Residual volume", "B": "Functional residual capacity", "C": "Inspiratory reserve volume", "D": "Vital capacity", "E": "Total lung capacity"}, "correct_letter": "B", "correct_answer": "B. Functional residual capacity", "why_correct": "Functional residual capacity (FRC) is the volume remaining in the lungs at the end of normal expiration. FRC = expiratory reserve volume + residual volume.", "exam_trap": "Residual volume is the air remaining after maximal forced expiration, not normal expiration.", "takeaway": "End of quiet expiration → FRC.", "source": "Standard respiratory physiology; MRCS Applied Basic Science syllabus."},
  {"id": "MAK-392", "subject": "Cardiorespiratory physiology", "topic": "Closing capacity", "title": "Closing capacity", "stem": "What happens when closing capacity exceeds functional residual capacity?", "options": {"A": "Small airways are more likely to close during normal tidal breathing", "B": "Alveolar ventilation necessarily increases", "C": "Residual volume becomes zero", "D": "Airway resistance becomes zero", "E": "Diffusion becomes independent of lung volume"}, "correct_letter": "A", "correct_answer": "A. Small airways are more likely to close during normal tidal breathing", "why_correct": "If closing capacity rises above FRC, dependent small airways may close during normal expiration, causing ventilation-perfusion mismatch and impaired oxygenation. This is more likely with increasing age and can be worsened perioperatively.", "exam_trap": "Closing capacity is a volume threshold; it is not synonymous with residual volume.", "takeaway": "Closing capacity > FRC → airway closure during tidal breathing.", "source": "Standard respiratory physiology; perioperative physiology principles."},
  {"id": "MAK-393", "subject": "Cardiorespiratory physiology", "topic": "Functional residual capacity after anaesthesia", "title": "Functional residual capacity after anaesthesia", "stem": "What commonly happens to functional residual capacity following induction of general anaesthesia?", "options": {"A": "It increases substantially", "B": "It decreases", "C": "It becomes equal to total lung capacity", "D": "It becomes zero", "E": "It is unaffected in all patients"}, "correct_letter": "B", "correct_answer": "B. It decreases", "why_correct": "General anaesthesia reduces FRC, partly because of changes in respiratory muscle tone and chest-wall/lung mechanics. A reduction in FRC can promote dependent airway closure and worsen ventilation-perfusion mismatch.", "exam_trap": "A fall in FRC does not mean the lungs have lost all residual volume.", "takeaway": "General anaesthesia → ↓ FRC → greater risk of airway closure/atelectasis.", "source": "Standard anaesthetic and respiratory physiology."},
  {"id": "MAK-394", "subject": "Cardiorespiratory physiology", "topic": "Lung compliance", "title": "Lung compliance", "stem": "Which statement best describes lung compliance?", "options": {"A": "Change in pressure divided by change in volume", "B": "Change in volume divided by change in pressure", "C": "Airflow divided by resistance", "D": "Pressure divided by oxygen saturation", "E": "Oxygen content divided by haemoglobin"}, "correct_letter": "B", "correct_answer": "B. Change in volume divided by change in pressure", "why_correct": "Compliance describes the ease with which the respiratory system changes volume in response to a pressure change. Compliance = ΔV / ΔP.", "exam_trap": "Elastance is the inverse concept: the tendency to return to the resting configuration.", "takeaway": "Compliance = ΔV/ΔP.", "source": "Standard respiratory physiology."},
  {"id": "MAK-395", "subject": "Cardiorespiratory physiology", "topic": "Pulmonary fibrosis and compliance", "title": "Pulmonary fibrosis and compliance", "stem": "A patient with pulmonary fibrosis has stiff lungs. Which change would be expected?", "options": {"A": "Increased lung compliance", "B": "Reduced lung compliance", "C": "No change in elastic properties", "D": "Absent airway resistance", "E": "Increased residual volume as the defining feature"}, "correct_letter": "B", "correct_answer": "B. Reduced lung compliance", "why_correct": "Fibrotic lung tissue is stiff and requires greater pressure to produce a given change in volume.", "exam_trap": "Obstructive and restrictive diseases affect mechanics differently. Fibrosis is classically associated with reduced compliance.", "takeaway": "Fibrosis → stiff lungs → ↓ compliance.", "source": "Standard respiratory physiology/pathophysiology."},
  {"id": "MAK-396", "subject": "Cardiorespiratory physiology", "topic": "Emphysema and compliance", "title": "Emphysema and compliance", "stem": "Which mechanical change is characteristic of emphysema?", "options": {"A": "Reduced lung compliance", "B": "Increased lung compliance", "C": "Complete loss of residual volume", "D": "Increased elastic recoil", "E": "Complete absence of airway resistance"}, "correct_letter": "B", "correct_answer": "B. Increased lung compliance", "why_correct": "Destruction of elastic tissue reduces elastic recoil and makes the lungs more compliant.", "exam_trap": "Increased compliance does not mean improved respiratory function. Reduced elastic recoil contributes to expiratory airflow limitation.", "takeaway": "Emphysema → ↑ compliance + ↓ elastic recoil.", "source": "Standard respiratory physiology/pathophysiology."},
  {"id": "MAK-397", "subject": "Cardiorespiratory physiology", "topic": "Airway resistance", "title": "Airway resistance", "stem": "Where is the greatest proportion of total airway resistance normally generated?", "options": {"A": "The smallest individual bronchioles only", "B": "Medium-sized airways", "C": "The alveoli", "D": "The pulmonary capillaries", "E": "The pleural space"}, "correct_letter": "B", "correct_answer": "B. Medium-sized airways", "why_correct": "Although small bronchioles have narrow individual lumens, they are arranged extensively in parallel. Their combined cross-sectional area is large, reducing their contribution to total resistance.", "exam_trap": "The narrowest individual airway is not necessarily the site of greatest total resistance.", "takeaway": "Total airway resistance is influenced strongly by medium-sized conducting airways.", "source": "Standard respiratory physiology."},
  {"id": "MAK-398", "subject": "Cardiorespiratory physiology", "topic": "Poiseuille's relationship", "title": "Poiseuille's relationship", "stem": "If the radius of a cylindrical airway is reduced by half, what happens to laminar flow resistance, assuming all other factors remain constant?", "options": {"A": "It falls by half", "B": "It doubles", "C": "It increases approximately 4-fold", "D": "It increases approximately 16-fold", "E": "It remains unchanged"}, "correct_letter": "D", "correct_answer": "D. It increases approximately 16-fold", "why_correct": "For laminar flow, resistance is inversely proportional to the fourth power of radius: R ∝ 1/r⁴. Halving the radius therefore increases resistance by: 1/(0.5⁴) = 16.", "exam_trap": "The relationship is to the fourth power, not simply proportional to radius.", "takeaway": "Small decrease in airway radius → very large increase in resistance.", "source": "Standard respiratory physiology."},
  {"id": "MAK-399", "subject": "Cardiorespiratory physiology", "topic": "Work of breathing", "title": "Work of breathing", "stem": "Which situation increases the elastic work of breathing?", "options": {"A": "Increased lung stiffness", "B": "Reduced elastic recoil only", "C": "Reduced airway resistance", "D": "Increased airway diameter", "E": "Reduced respiratory rate alone"}, "correct_letter": "A", "correct_answer": "A. Increased lung stiffness", "why_correct": "Stiff lungs require greater pressure generation to produce a given volume change, increasing elastic work.", "exam_trap": "Airway obstruction primarily increases resistive work, whereas restrictive stiffness increases elastic work.", "takeaway": "Stiff lungs → ↑ elastic work.", "source": "[GH14]."},
  {"id": "MAK-400", "subject": "Cardiorespiratory physiology", "topic": "V/Q mismatch and hypoxaemia", "title": "V/Q mismatch and hypoxaemia", "stem": "Which mechanism is a common cause of hypoxaemia in patients with lung disease?", "options": {"A": "Ventilation-perfusion mismatch", "B": "Increased haemoglobin concentration alone", "C": "Increased inspired oxygen concentration", "D": "Increased cardiac output alone", "E": "Increased plasma albumin"}, "correct_letter": "A", "correct_answer": "A. Ventilation-perfusion mismatch", "why_correct": "Uneven matching of ventilation and pulmonary perfusion is a major mechanism of hypoxaemia in many pulmonary disorders.", "exam_trap": "V/Q mismatch is distinct from a true anatomical right-to-left shunt, although both can cause hypoxaemia.", "takeaway": "Many pulmonary diseases → V/Q mismatch → hypoxaemia.", "source": "Standard respiratory physiology."},
  {"id": "MAK-401", "subject": "Cardiorespiratory physiology", "topic": "Dead space ventilation", "title": "Dead space ventilation", "stem": "A patient has a large proportion of each breath ventilating alveoli that receive little or no pulmonary blood flow. What happens to physiological dead-space ventilation?", "options": {"A": "It increases", "B": "It decreases", "C": "It becomes zero", "D": "It is unaffected", "E": "It becomes identical to shunt fraction"}, "correct_letter": "A", "correct_answer": "A. It increases", "why_correct": "Ventilation of areas with little or no perfusion contributes to dead-space ventilation.", "exam_trap": "Dead space is wasted ventilation; shunt represents perfusion of poorly or non-ventilated regions.", "takeaway": "Ventilation without adequate perfusion → dead space.", "source": "Standard respiratory physiology."},
  {"id": "MAK-403", "subject": "Cardiorespiratory physiology", "topic": "Systemic versus pulmonary vascular response", "title": "Systemic versus pulmonary vascular response", "stem": "Which vascular response distinguishes pulmonary circulation from most systemic vascular beds?", "options": {"A": "Alveolar hypoxia causes pulmonary vasoconstriction", "B": "Alveolar hypoxia always causes pulmonary vasodilation", "C": "Carbon dioxide has no effect on pulmonary vessels", "D": "Pulmonary vessels never respond to oxygen", "E": "Pulmonary circulation has no resistance"}, "correct_letter": "A", "correct_answer": "A. Alveolar hypoxia causes pulmonary vasoconstriction", "why_correct": "Hypoxic pulmonary vasoconstriction is an important mechanism for matching perfusion to ventilation.", "exam_trap": "", "takeaway": "Systemic hypoxia often dilates vessels; alveolar hypoxia constricts pulmonary arterioles.", "source": "Standard cardiovascular/respiratory physiology."},
  {"id": "MAK-404", "subject": "Perioperative medicine & nutrition", "topic": "Fluid assessment", "title": "Fluid assessment", "stem": "According to NICE guidance for adult hospital patients requiring IV fluids, which approach should be used when initially assessing fluid status?", "options": {"A": "Blood pressure alone", "B": "ABCDE assessment combined with clinical context and trends", "C": "Serum sodium alone", "D": "Urine colour alone", "E": "Body weight alone"}, "correct_letter": "B", "correct_answer": "B. ABCDE assessment combined with clinical context and trends", "why_correct": "NICE recommends assessing fluid status using an ABCDE approach alongside clinical examination, trends and relevant context.", "exam_trap": "No single observation reliably establishes volume status in every patient.", "takeaway": "Fluid assessment = clinical picture + trends + investigations, not one number.", "source": "NICE CG174, Intravenous fluid therapy in adults in hospital."},
  {"id": "MAK-405", "subject": "Perioperative medicine & nutrition", "topic": "IV fluid prescription", "title": "IV fluid prescription", "stem": "When prescribing intravenous fluids for an adult inpatient, which information should be explicitly specified?", "options": {"A": "Fluid type only", "B": "Fluid rate only", "C": "Fluid type, rate and volume", "D": "Brand of cannula only", "E": "Patient's blood group only"}, "correct_letter": "C", "correct_answer": "C. Fluid type, rate and volume", "why_correct": "NICE recommends that IV fluid prescriptions specify the type of fluid and the rate and volume to be administered.", "exam_trap": "Writing “IV fluids” without specifying the prescription is inadequate.", "takeaway": "IV prescription → what fluid + how fast + how much.", "source": "NICE CG174, recommendation 1.5.11."},
  {"id": "MAK-406", "subject": "Perioperative medicine & nutrition", "topic": "Maintenance fluid versus resuscitation", "title": "Maintenance fluid versus resuscitation", "stem": "A stable postoperative patient is unable to drink but has no evidence of shock or major ongoing losses. What category of IV-fluid therapy is most relevant?", "options": {"A": "Fluid resuscitation", "B": "Routine maintenance", "C": "Massive transfusion", "D": "Plasma exchange", "E": "Hypertonic rescue therapy"}, "correct_letter": "B", "correct_answer": "B. Routine maintenance", "why_correct": "Maintenance therapy provides the patient's expected physiological fluid and electrolyte requirements when these cannot be met orally or enterally.", "exam_trap": "Maintenance fluids are not a substitute for treating hypovolaemic shock.", "takeaway": "No shock + cannot maintain intake → think maintenance.", "source": "NICE CG174."},
  {"id": "MAK-407", "subject": "Perioperative medicine & nutrition", "topic": "Ongoing abnormal losses", "title": "Ongoing abnormal losses", "stem": "A patient has a high-output stoma with ongoing fluid and electrolyte losses. Which principle is most appropriate?", "options": {"A": "Give standard maintenance fluid only and ignore the losses", "B": "Assess and replace ongoing abnormal losses in addition to maintenance requirements", "C": "Stop all fluid replacement", "D": "Replace every loss with blood", "E": "Use glucose alone regardless of the composition of losses"}, "correct_letter": "B", "correct_answer": "B. Assess and replace ongoing abnormal losses in addition to maintenance requirements", "why_correct": "NICE separates routine maintenance from replacement of ongoing abnormal losses. Examples include gastrointestinal losses, stoma losses, fistula losses and ongoing urinary losses.", "exam_trap": "Maintenance requirements do not automatically compensate for major pathological losses.", "takeaway": "Maintenance ≠ replacement of abnormal losses.", "source": "NICE CG174."},
  {"id": "MAK-408", "subject": "Perioperative medicine & nutrition", "topic": "Enteral route for maintenance", "title": "Enteral route for maintenance", "stem": "A patient requires prolonged fluid and nutritional support but has a functioning gastrointestinal tract. Which principle is generally preferred when feasible?", "options": {"A": "Long-term IV maintenance regardless of gastrointestinal function", "B": "Oral or enteral provision where appropriate", "C": "No fluid provision", "D": "IV fluids permanently", "E": "Blood products as maintenance"}, "correct_letter": "B", "correct_answer": "B. Oral or enteral provision where appropriate", "why_correct": "NICE recommends assessing whether fluid and electrolyte needs can be met orally or enterally before prescribing IV maintenance.", "exam_trap": "IV fluids are a treatment modality, not automatically the preferred long-term route.", "takeaway": "Functional gut → use oral/enteral routes when clinically appropriate.", "source": "NICE CG174."},
  {"id": "MAK-409", "subject": "Perioperative medicine & nutrition", "topic": "Fluid overload", "title": "Fluid overload", "stem": "A postoperative patient develops increasing peripheral oedema, rising weight and pulmonary crackles while receiving IV fluids. What should this prompt?", "options": {"A": "Automatic increase in IV fluid rate", "B": "Reassessment for fluid excess and review of ongoing fluid prescriptions", "C": "Automatic administration of more crystalloid", "D": "Ignoring the findings because oedema is expected after surgery", "E": "Routine blood transfusion"}, "correct_letter": "B", "correct_answer": "B. Reassessment for fluid excess and review of ongoing fluid prescriptions", "why_correct": "NICE emphasises repeated clinical and laboratory assessment and recognition of fluid excess.", "exam_trap": "Postoperative fluid requirements can change rapidly; a prescription should not continue automatically without reassessment.", "takeaway": "New oedema/crackles + IV fluids → reassess balance before giving more.", "source": "NICE CG174."},
  {"id": "MAK-410", "subject": "Perioperative medicine & nutrition", "topic": "Perioperative hypothermia", "title": "Perioperative hypothermia", "stem": "Why is perioperative hypothermia clinically important?", "options": {"A": "It has no physiological consequences", "B": "It can affect coagulation, drug metabolism and postoperative recovery", "C": "It always causes hyperglycaemia only", "D": "It prevents infection", "E": "It increases oxygen delivery in every patient"}, "correct_letter": "B", "correct_answer": "B. It can affect coagulation, drug metabolism and postoperative recovery", "why_correct": "Hypothermia can impair coagulation, alter pharmacokinetics and contribute to adverse perioperative outcomes.", "exam_trap": "Temperature management is part of perioperative physiological care, not simply patient comfort.", "takeaway": "Hypothermia → think coagulation + drug handling + recovery.", "source": "Standard perioperative physiology and UK perioperative-care principles."},
  {"id": "MAK-411", "subject": "Perioperative medicine & nutrition", "topic": "Shivering and oxygen consumption", "title": "Shivering and oxygen consumption", "stem": "A patient develops significant postoperative shivering. Which physiological effect may occur?", "options": {"A": "Increased oxygen consumption", "B": "Complete cessation of metabolism", "C": "Reduced skeletal-muscle activity", "D": "Guaranteed reduction in cardiac workload", "E": "Elimination of heat production"}, "correct_letter": "A", "correct_answer": "A. Increased oxygen consumption", "why_correct": "Shivering is an involuntary thermogenic response involving skeletal-muscle activity and can substantially increase metabolic and oxygen requirements.", "exam_trap": "Shivering is not simply a sign of discomfort; it has measurable physiological consequences.", "takeaway": "Shivering → ↑ metabolic demand → ↑ oxygen consumption.", "source": "Standard thermoregulatory physiology."},
  {"id": "MAK-412", "subject": "Physiology", "topic": "Thyroid hormone", "title": "Thyroid hormone", "stem": "Which thyroid hormone is biologically more active at the tissue level?", "options": {"A": "T4", "B": "T3", "C": "Reverse T3 only", "D": "Thyroglobulin", "E": "Thyroid-stimulating hormone"}, "correct_letter": "B", "correct_answer": "B. T3", "why_correct": "T3 has greater biological activity than T4. Much circulating T3 is generated by peripheral conversion of T4.", "exam_trap": "The thyroid gland secretes predominantly T4, but T3 is the more biologically active hormone.", "takeaway": "T4 = major circulating precursor; T3 = greater biological activity.", "source": "Standard endocrine physiology."},
  {"id": "MAK-413", "subject": "Physiology", "topic": "Thyroid-stimulating hormone", "title": "Thyroid-stimulating hormone", "stem": "Which pituitary hormone stimulates thyroid hormone production by the thyroid gland?", "options": {"A": "ACTH", "B": "TSH", "C": "FSH", "D": "LH", "E": "Growth hormone"}, "correct_letter": "B", "correct_answer": "B. TSH", "why_correct": "TSH from the anterior pituitary stimulates thyroid follicular cells to synthesise and release thyroid hormones. The hypothalamus-pituitary-thyroid axis operates through negative feedback.", "exam_trap": "TSH is pituitary-derived; TRH is hypothalamic.", "takeaway": "Hypothalamus TRH → pituitary TSH → thyroid T3/T4.", "source": "Standard endocrine physiology."},
  {"id": "MAK-414", "subject": "Physiology", "topic": "Thyroid hormone and metabolism", "title": "Thyroid hormone and metabolism", "stem": "Which effect is associated with thyroid hormone?", "options": {"A": "Reduction in basal metabolic activity", "B": "Increase in basal metabolic rate", "C": "Complete inhibition of catecholamine effects", "D": "Suppression of mitochondrial activity", "E": "Elimination of heat production"}, "correct_letter": "B", "correct_answer": "B. Increase in basal metabolic rate", "why_correct": "Thyroid hormones increase metabolic activity and oxygen consumption in many tissues and contribute to thermogenesis.", "exam_trap": "Thyroid hormone has widespread metabolic effects rather than acting solely on heart rate.", "takeaway": "Thyroid hormone → ↑ metabolic activity and thermogenesis.", "source": "Standard endocrine physiology."},
  {"id": "MAK-415", "subject": "Physiology", "topic": "Growth hormone and IGF-1", "title": "Growth hormone and IGF-1", "stem": "Which hormone mediates many of the growth-promoting effects of growth hormone?", "options": {"A": "IGF-1", "B": "Aldosterone", "C": "Calcitonin", "D": "TSH", "E": "Insulin only"}, "correct_letter": "A", "correct_answer": "A. IGF-1", "why_correct": "Growth hormone stimulates production of insulin-like growth factor 1 (IGF-1), particularly in the liver, which mediates many growth-promoting effects.", "exam_trap": "Growth hormone has direct metabolic actions as well as indirect effects through IGF-1.", "takeaway": "GH → IGF-1 → growth-promoting effects.", "source": "Standard endocrine physiology."},
  {"id": "MAK-416", "subject": "Physiology", "topic": "Growth hormone and glucose", "title": "Growth hormone and glucose", "stem": "Which metabolic effect is associated with growth hormone?", "options": {"A": "Increased insulin sensitivity in all tissues", "B": "Promotion of lipolysis and reduced peripheral glucose uptake", "C": "Complete suppression of lipolysis", "D": "Direct conversion into insulin", "E": "Elimination of hepatic glucose production"}, "correct_letter": "B", "correct_answer": "B. Promotion of lipolysis and reduced peripheral glucose uptake", "why_correct": "Growth hormone has anti-insulin effects on glucose metabolism and promotes lipolysis.", "exam_trap": "Growth hormone is not simply an anabolic hormone; its metabolic actions include diabetogenic effects.", "takeaway": "GH → growth effects + lipolysis + anti-insulin metabolic effects.", "source": "Standard endocrine physiology."},
  {"id": "MAK-417", "subject": "Physiology", "topic": "Parathyroid hormone and phosphate", "title": "Parathyroid hormone and phosphate", "stem": "What is the principal effect of parathyroid hormone on renal phosphate handling?", "options": {"A": "Increased phosphate reabsorption in the proximal tubule", "B": "Reduced phosphate reabsorption in the proximal tubule", "C": "Complete elimination of phosphate filtration", "D": "Increased gastrointestinal phosphate secretion", "E": "No effect on phosphate handling"}, "correct_letter": "B", "correct_answer": "B. Reduced phosphate reabsorption in the proximal tubule", "why_correct": "PTH reduces proximal tubular phosphate reabsorption, increasing urinary phosphate excretion. This helps raise serum calcium while limiting the rise in calcium-phosphate product.", "exam_trap": "PTH increases renal calcium reabsorption but decreases phosphate reabsorption.", "takeaway": "PTH → retain calcium, excrete phosphate.", "source": "Standard endocrine physiology."},
  {"id": "MAK-418", "subject": "Physiology", "topic": "Cortisol and stress", "title": "Cortisol and stress", "stem": "Which effect of cortisol is particularly relevant during physiological stress?", "options": {"A": "Promotion of gluconeogenesis", "B": "Complete suppression of vascular responsiveness to catecholamines", "C": "Elimination of protein catabolism", "D": "Permanent inhibition of lipolysis", "E": "Complete blockade of immune activity"}, "correct_letter": "A", "correct_answer": "A. Promotion of gluconeogenesis", "why_correct": "Cortisol supports the stress response partly by promoting gluconeogenesis and modifying protein and lipid metabolism. It also contributes to maintenance of vascular responsiveness to catecholamines.", "exam_trap": "Cortisol is not simply an “anti-inflammatory hormone”; it has important metabolic and cardiovascular effects.", "takeaway": "Stress + cortisol → glucose availability + vascular support + immune modulation.", "source": "Standard endocrine physiology."},
  {"id": "MAK-419", "subject": "Physiology", "topic": "Adrenal insufficiency and cortisol", "title": "Adrenal insufficiency and cortisol", "stem": "A patient with severe adrenal insufficiency becomes acutely unwell during physiological stress. Why can inadequate cortisol be particularly dangerous?", "options": {"A": "Cortisol is unnecessary during stress", "B": "Cortisol supports vascular responsiveness and metabolic adaptation to stress", "C": "Cortisol is only required for digestion", "D": "Cortisol exclusively regulates calcium", "E": "Cortisol is required only during sleep"}, "correct_letter": "B", "correct_answer": "B. Cortisol supports vascular responsiveness and metabolic adaptation to stress", "why_correct": "During major physiological stress, increased cortisol availability supports vascular tone and metabolic responses. Adrenal insufficiency can therefore become clinically critical during acute illness.", "exam_trap": "The importance of cortisol becomes especially apparent when physiological demand rises.", "takeaway": "Stress → increased cortisol requirement.", "source": "Standard endocrine physiology and perioperative medicine."},
  {"id": "MAK-420", "subject": "Cardiorespiratory physiology", "topic": "Oxygen delivery and haemoglobin", "title": "Oxygen delivery and haemoglobin", "stem": "Which change would most directly reduce arterial oxygen content in an otherwise stable patient?", "options": {"A": "Severe anaemia", "B": "Mild isolated tachycardia", "C": "Increased plasma sodium", "D": "Increased albumin", "E": "Increased body temperature alone"}, "correct_letter": "A", "correct_answer": "A. Severe anaemia", "why_correct": "Most oxygen in arterial blood is carried bound to haemoglobin. A major reduction in haemoglobin concentration therefore substantially reduces arterial oxygen content even if oxygen saturation is normal.", "exam_trap": "A normal SpO₂ does not guarantee normal oxygen delivery when haemoglobin concentration is severely reduced.", "takeaway": "Normal saturation + severe anaemia ≠ normal oxygen content.", "source": "Standard cardiovascular/respiratory physiology; MRCS Applied Basic Science syllabus."},
  {"id": "MAK-421", "subject": "Perioperative medicine & nutrition", "topic": "Surgical stress response", "title": "Surgical stress response", "stem": "Which hormonal change is characteristic of the physiological response to major surgery?", "options": {"A": "Reduced catecholamine release", "B": "Reduced cortisol secretion", "C": "Increased catecholamine and cortisol activity", "D": "Complete suppression of glucagon", "E": "Complete inhibition of inflammatory mediators"}, "correct_letter": "C", "correct_answer": "C. Increased catecholamine and cortisol activity", "why_correct": "Major surgery produces a neuroendocrine stress response involving catecholamines, cortisol, glucagon and inflammatory mediators. This promotes mobilisation of energy substrates and cardiovascular adaptation.", "exam_trap": "The surgical stress response is not simply an inflammatory response; neuroendocrine and metabolic components are important.", "takeaway": "Major surgery → stress hormones + inflammation + catabolism.", "source": "Standard surgical physiology; MRCS Principles of Surgery in General."},
  {"id": "MAK-422", "subject": "Perioperative medicine & nutrition", "topic": "Postoperative insulin resistance", "title": "Postoperative insulin resistance", "stem": "Why can blood glucose rise after major surgery even in a patient without pre-existing diabetes?", "options": {"A": "Surgery always destroys pancreatic beta cells", "B": "The stress response can produce postoperative insulin resistance", "C": "Surgery permanently eliminates glucagon", "D": "Cortisol always causes hypoglycaemia", "E": "Insulin secretion necessarily becomes zero"}, "correct_letter": "B", "correct_answer": "B. The stress response can produce postoperative insulin resistance", "why_correct": "Catecholamines, cortisol, growth hormone and inflammatory mediators contribute to insulin resistance and increased hepatic glucose availability during surgical stress.", "exam_trap": "Postoperative hyperglycaemia does not automatically establish previously undiagnosed diabetes.", "takeaway": "Surgery → stress response → insulin resistance + hyperglycaemia.", "source": "Standard perioperative physiology."},
  {"id": "MAK-423", "subject": "Perioperative medicine & nutrition", "topic": "Catabolism after major surgery", "title": "Catabolism after major surgery", "stem": "Which metabolic change commonly occurs after major surgery?", "options": {"A": "Positive nitrogen balance without nutritional support", "B": "Increased protein catabolism", "C": "Complete inhibition of lipolysis", "D": "Permanent suppression of hepatic glucose production", "E": "Elimination of energy requirements"}, "correct_letter": "B", "correct_answer": "B. Increased protein catabolism", "why_correct": "The postoperative stress response promotes catabolism, including breakdown of protein to provide substrates for gluconeogenesis and tissue repair.", "exam_trap": "A patient can lose lean body mass even when receiving substantial carbohydrate calories.", "takeaway": "Major surgery → catabolic state → nitrogen loss unless recovery/nutrition counteract it.", "source": "Standard surgical metabolism."},
  {"id": "MAK-424", "subject": "Perioperative medicine & nutrition", "topic": "Malnutrition and wound healing", "title": "Malnutrition and wound healing", "stem": "Which nutritional problem can impair collagen synthesis and wound healing?", "options": {"A": "Protein deficiency", "B": "Mild isolated hyperchloraemia", "C": "Increased water intake", "D": "Normal iron stores", "E": "Normal vitamin intake"}, "correct_letter": "A", "correct_answer": "A. Protein deficiency", "why_correct": "Adequate protein and energy availability are important for immune function, fibroblast activity and collagen production.", "exam_trap": "Malnutrition can be present despite a patient not appearing markedly underweight.", "takeaway": "Poor nutrition → impaired immunity + impaired collagen formation + poorer healing.", "source": "NICE CG32, Nutrition support for adults."},
  {"id": "MAK-425", "subject": "Perioperative medicine & nutrition", "topic": "Malnutrition screening", "title": "Malnutrition screening", "stem": "Which combination is particularly relevant when screening an adult surgical patient for malnutrition?", "options": {"A": "BMI and unintentional weight loss", "B": "Blood group and pulse rate only", "C": "Height alone", "D": "Serum sodium alone", "E": "Age alone"}, "correct_letter": "A", "correct_answer": "A. BMI and unintentional weight loss", "why_correct": "NICE recommends that nutritional screening considers BMI, percentage unintentional weight loss and the duration/reduction of nutritional intake.", "exam_trap": "A normal BMI does not exclude clinically important recent weight loss.", "takeaway": "Nutrition screen → BMI + weight loss + intake history.", "source": "NICE CG32, current recommendations."},
  {"id": "MAK-426", "subject": "Perioperative medicine & nutrition", "topic": "Enteral nutrition", "title": "Enteral nutrition", "stem": "A malnourished postoperative patient cannot safely maintain oral intake but has a functioning gastrointestinal tract. Which route is generally preferred when appropriate?", "options": {"A": "Enteral feeding", "B": "Long-term intravenous crystalloid only", "C": "Blood transfusion", "D": "No nutritional support", "E": "Intramuscular feeding"}, "correct_letter": "A", "correct_answer": "A. Enteral feeding", "why_correct": "NICE recommends considering enteral tube feeding for patients who are malnourished or at risk, have inadequate or unsafe oral intake and have a functional, accessible gastrointestinal tract.", "exam_trap": "A functioning gut is an important reason to consider enteral rather than parenteral nutrition.", "takeaway": "If the gut works and oral intake is inadequate → think enteral.", "source": "NICE CG32."},
  {"id": "MAK-427", "subject": "Perioperative medicine & nutrition", "topic": "Enteral versus parenteral nutrition", "title": "Enteral versus parenteral nutrition", "stem": "A patient requires nutritional support and has a functioning gastrointestinal tract. Which principle is most appropriate?", "options": {"A": "Prefer parenteral nutrition in all surgical patients", "B": "Use enteral nutrition when oral intake is inadequate or unsafe and the gut is functional", "C": "Avoid enteral nutrition after surgery", "D": "Give IV glucose as complete nutritional support", "E": "Nutritional support is unnecessary during prolonged illness"}, "correct_letter": "B", "correct_answer": "B. Use enteral nutrition when oral intake is inadequate or unsafe and the gut is functional", "why_correct": "Enteral nutrition uses the gastrointestinal tract and is appropriate when the gut is accessible and functional.", "exam_trap": "“Postoperative” does not automatically mean “nil by mouth for prolonged periods.”", "takeaway": "Functional GI tract → enteral route when clinically indicated.", "source": "NICE CG32."},
  {"id": "MAK-428", "subject": "Perioperative medicine & nutrition", "topic": "Early postoperative oral intake", "title": "Early postoperative oral intake", "stem": "A patient has undergone abdominal surgery, can swallow safely and has no specific concern about gastrointestinal function or integrity. What does NICE recommend considering?", "options": {"A": "Avoiding oral intake for several weeks", "B": "Some oral intake within 24 hours", "C": "Mandatory parenteral nutrition", "D": "Permanent nasogastric feeding", "E": "Oral intake only after bowel sounds return"}, "correct_letter": "B", "correct_answer": "B. Some oral intake within 24 hours", "why_correct": "NICE recommends considering some oral intake within 24 hours after abdominal surgery in patients who can swallow safely and have no specific concern about gut function or integrity.", "exam_trap": "Waiting for the return of bowel sounds is not an absolute prerequisite for postoperative oral intake.", "takeaway": "Uncomplicated abdominal surgery + safe swallowing + functioning gut → early oral intake can be considered.", "source": "NICE CG32."},
  {"id": "MAK-429", "subject": "Perioperative medicine & nutrition", "topic": "Refeeding syndrome", "title": "Refeeding syndrome", "stem": "A severely malnourished patient starts nutritional support and subsequently develops profound hypophosphataemia. What complication should be considered?", "options": {"A": "Refeeding syndrome", "B": "Hyperthyroidism", "C": "Primary polycythaemia", "D": "Acute appendicitis", "E": "Isolated iron deficiency"}, "correct_letter": "A", "correct_answer": "A. Refeeding syndrome", "why_correct": "Reintroduction of nutrition after prolonged undernutrition can produce marked metabolic shifts, particularly involving phosphate, potassium and magnesium.", "exam_trap": "The risk relates to nutritional repletion after undernutrition; it is not simply “low phosphate from poor diet.”", "takeaway": "Malnutrition + feeding + falling phosphate → think refeeding syndrome.", "source": "NICE CG32; refeeding-risk recommendations."},
  {"id": "MAK-430", "subject": "Microbiology & surgical infection", "topic": "Surgical site infection prevention", "title": "Surgical site infection prevention", "stem": "Which principle is appropriate when preventing surgical site infection?", "options": {"A": "Antibiotics can compensate for poor surgical technique", "B": "Appropriate aseptic technique and perioperative measures are important", "C": "Every surgical wound requires prolonged postoperative antibiotics", "D": "Skin preparation is unnecessary", "E": "Hand hygiene is irrelevant in theatre"}, "correct_letter": "B", "correct_answer": "B. Appropriate aseptic technique and perioperative measures are important", "why_correct": "Prevention of surgical site infection is multifactorial and includes appropriate aseptic technique, patient preparation, antibiotic prophylaxis where indicated and good perioperative practice.", "exam_trap": "Antibiotic prophylaxis does not replace sterile/aseptic technique.", "takeaway": "SSI prevention = bundle, not antibiotics alone.", "source": "NICE NG125."},
  {"id": "MAK-431", "subject": "Microbiology & surgical infection", "topic": "Surgical antibiotic prophylaxis", "title": "Surgical antibiotic prophylaxis", "stem": "What is the principal purpose of prophylactic antibiotics given around an operation?", "options": {"A": "To sterilise the entire patient's body", "B": "To reduce the risk of surgical site infection when indicated", "C": "To treat every postoperative fever", "D": "To replace surgical source control", "E": "To eliminate all postoperative bacterial colonisation"}, "correct_letter": "B", "correct_answer": "B. To reduce the risk of surgical site infection when indicated", "why_correct": "Antimicrobial prophylaxis is used for selected procedures where reducing microbial contamination can reduce surgical site infection.", "exam_trap": "Prophylaxis is not the same as treatment of an established infection.", "takeaway": "Prophylaxis = prevention, not treatment.", "source": "NICE NG125."},
  {"id": "MAK-432", "subject": "Microbiology & surgical infection", "topic": "Surgical infection and source control", "title": "Surgical infection and source control", "stem": "A patient has an intra-abdominal abscess with systemic illness. Which principle is central to definitive management?", "options": {"A": "Source control", "B": "Antibiotics alone in every case", "C": "Delaying all intervention until fever resolves", "D": "Giving fluids without treating the source", "E": "Avoiding imaging in all cases"}, "correct_letter": "A", "correct_answer": "A. Source control", "why_correct": "An established abscess or other infected collection may require drainage or operative intervention in addition to appropriate antimicrobial therapy.", "exam_trap": "Antibiotics may not adequately treat a walled-off collection without source control.", "takeaway": "Surgical sepsis → antibiotics + resuscitation + source control where required.", "source": "Standard surgical infection principles; NICE antimicrobial and surgical infection guidance."},
  {"id": "MAK-433", "subject": "Pathology: inflammation & wound healing", "topic": "Wound dehiscence", "title": "Wound dehiscence", "stem": "A patient develops sudden serosanguineous discharge from a laparotomy wound several days after surgery. What complication should be considered?", "options": {"A": "Wound dehiscence", "B": "Keloid formation", "C": "Chronic hypertrophic scar", "D": "Primary skin closure", "E": "Immediate complete wound healing"}, "correct_letter": "A", "correct_answer": "A. Wound dehiscence", "why_correct": "Sudden serosanguineous discharge from a recent abdominal wound can precede or accompany fascial dehiscence.", "exam_trap": "Do not dismiss sudden “pink” wound discharge as normal postoperative ooze when it occurs in the appropriate timeframe.", "takeaway": "Sudden serosanguineous wound discharge → think fascial dehiscence.", "source": "Standard postoperative surgical principles."},
  {"id": "MAK-434", "subject": "Acute abdomen & GI surgery", "topic": "Incisional hernia", "title": "Incisional hernia", "stem": "What is an incisional hernia?", "options": {"A": "Herniation through a previous abdominal surgical incision", "B": "Herniation through the oesophageal hiatus only", "C": "A congenital inguinal defect", "D": "A femoral hernia", "E": "A diaphragmatic rupture"}, "correct_letter": "A", "correct_answer": "A. Herniation through a previous abdominal surgical incision", "why_correct": "An incisional hernia develops through weakness at a previous operative incision. Risk factors include impaired healing, wound infection, obesity and increased intra-abdominal pressure.", "exam_trap": "An incisional hernia is acquired and related to a previous surgical access site.", "takeaway": "Previous abdominal incision + later abdominal wall bulge → incisional hernia.", "source": "Standard general surgical principles."},
  {"id": "MAK-435", "subject": "Acute abdomen & GI surgery", "topic": "Postoperative ileus", "title": "Postoperative ileus", "stem": "Which feature is characteristic of postoperative ileus?", "options": {"A": "Functional reduction in intestinal motility without a mechanical obstruction", "B": "Always caused by an obstructing tumour", "C": "Always associated with a strangulated hernia", "D": "Mandatory bowel perforation", "E": "Increased coordinated peristalsis"}, "correct_letter": "A", "correct_answer": "A. Functional reduction in intestinal motility without a mechanical obstruction", "why_correct": "Postoperative ileus is a transient impairment of gastrointestinal motility following surgery and other systemic insults.", "exam_trap": "Ileus and mechanical bowel obstruction can present similarly, so the clinical context and investigation matter.", "takeaway": "Postoperative distension + reduced bowel function → consider ileus, but exclude mechanical obstruction when indicated.", "source": "Standard postoperative surgical principles."},
  {"id": "MAK-436", "subject": "Acute abdomen & GI surgery", "topic": "Anastomotic leak", "title": "Anastomotic leak", "stem": "Which postoperative finding should raise concern for an anastomotic leak after gastrointestinal surgery?", "options": {"A": "New unexplained systemic deterioration", "B": "Normal recovery with improving observations", "C": "Return of appetite alone", "D": "Mobilising independently", "E": "Normal wound appearance alone"}, "correct_letter": "A", "correct_answer": "A. New unexplained systemic deterioration", "why_correct": "Anastomotic leakage can present with systemic deterioration, abdominal pain, fever, tachycardia, inflammatory response or other signs of intra-abdominal sepsis.", "exam_trap": "A leak may present without dramatic abdominal findings, particularly in an altered postoperative patient.", "takeaway": "Unexpected postoperative deterioration after GI anastomosis → consider leak and sepsis.", "source": "Standard postoperative surgical principles."},
  {"id": "MAK-437", "subject": "Perioperative medicine & nutrition", "topic": "Postoperative pulmonary atelectasis", "title": "Postoperative pulmonary atelectasis", "stem": "What is atelectasis?", "options": {"A": "Collapse or incomplete expansion of alveolar units", "B": "Pulmonary artery thrombosis", "C": "Pleural infection only", "D": "Bronchial carcinoma", "E": "Increased alveolar ventilation"}, "correct_letter": "A", "correct_answer": "A. Collapse or incomplete expansion of alveolar units", "why_correct": "Atelectasis involves loss of aeration in part of the lung and is common in the postoperative setting, particularly when ventilation is impaired.", "exam_trap": "Atelectasis is not synonymous with pneumonia.", "takeaway": "Postoperative reduced aeration/collapse → atelectasis.", "source": "Standard respiratory and perioperative medicine."},
  {"id": "MAK-438", "subject": "Perioperative medicine & nutrition", "topic": "Postoperative pneumonia", "title": "Postoperative pneumonia", "stem": "Which factor increases the risk of postoperative chest infection?", "options": {"A": "Impaired cough and poor mobilisation", "B": "Early mobilisation", "C": "Effective analgesia", "D": "Adequate physiotherapy", "E": "Good hydration where appropriate"}, "correct_letter": "A", "correct_answer": "A. Impaired cough and poor mobilisation", "why_correct": "Pain, sedation, immobility and impaired respiratory mechanics can reduce effective secretion clearance and ventilation.", "exam_trap": "Analgesia itself is not the enemy; inadequate analgesia can prevent effective coughing and mobilisation.", "takeaway": "Postoperative chest risk → pain + immobility + poor secretion clearance.", "source": "Standard perioperative respiratory principles."},
  {"id": "MAK-439", "subject": "Perioperative medicine & nutrition", "topic": "Postoperative urinary retention", "title": "Postoperative urinary retention", "stem": "Which factor can contribute to postoperative urinary retention?", "options": {"A": "Anaesthesia and opioid analgesia", "B": "Increased mobility alone", "C": "Normal bladder sensation", "D": "Increased oral intake alone", "E": "Normal autonomic function"}, "correct_letter": "A", "correct_answer": "A. Anaesthesia and opioid analgesia", "why_correct": "Anaesthetic agents, opioids, pain and perioperative autonomic changes can impair bladder emptying.", "exam_trap": "A patient may have significant urinary retention without initially reporting severe discomfort.", "takeaway": "Postoperative inability to void → consider retention, especially after anaesthesia/opioids.", "source": "Standard perioperative physiology."},
  {"id": "MAK-440", "subject": "Perioperative medicine & nutrition", "topic": "Postoperative delirium", "title": "Postoperative delirium", "stem": "Which statement about postoperative delirium is correct?", "options": {"A": "It is always caused by dementia", "B": "It is an acute disturbance in attention and cognition with a fluctuating course", "C": "It is synonymous with depression", "D": "It is always irreversible", "E": "It occurs only after neurosurgery"}, "correct_letter": "B", "correct_answer": "B. It is an acute disturbance in attention and cognition with a fluctuating course", "why_correct": "Delirium is an acute neuropsychiatric syndrome characterised particularly by impaired attention and fluctuating cognition.", "exam_trap": "Delirium is not synonymous with dementia, although dementia increases risk.", "takeaway": "Acute + fluctuating + impaired attention → think delirium.", "source": "Standard perioperative medicine; NICE delirium guidance."},
  {"id": "MAK-441", "subject": "Perioperative medicine & nutrition", "topic": "VTE risk assessment", "title": "VTE risk assessment", "stem": "According to NICE, what should happen to a surgical patient's VTE and bleeding risk assessment when their clinical condition changes?", "options": {"A": "It should never be revisited", "B": "It should be reassessed", "C": "Only the surgeon's age matters", "D": "VTE prophylaxis should automatically continue unchanged", "E": "Bleeding risk should be ignored"}, "correct_letter": "B", "correct_answer": "B. It should be reassessed", "why_correct": "NICE recommends reassessing surgical and trauma patients for VTE and bleeding risk when their clinical condition changes.", "exam_trap": "VTE risk assessment is dynamic rather than a one-time administrative task.", "takeaway": "Clinical condition changes → reassess VTE + bleeding risk.", "source": "NICE NG89, VTE prevention."},
  {"id": "MAK-442", "subject": "Perioperative medicine & nutrition", "topic": "Mechanical VTE prophylaxis", "title": "Mechanical VTE prophylaxis", "stem": "A patient undergoing abdominal surgery is at increased risk of VTE. Which mechanical intervention is recommended by NICE on admission?", "options": {"A": "Anti-embolism stockings or intermittent pneumatic compression", "B": "Therapeutic warfarin for every patient", "C": "No prophylaxis", "D": "Compression only after discharge", "E": "Aspirin for every abdominal operation"}, "correct_letter": "A", "correct_answer": "A. Anti-embolism stockings or intermittent pneumatic compression", "why_correct": "NICE recommends mechanical VTE prophylaxis on admission for patients undergoing abdominal surgery who are at increased risk.", "exam_trap": "The choice and continuation of prophylaxis depend on individual VTE and bleeding risk.", "takeaway": "Abdominal surgery + increased VTE risk → mechanical prophylaxis on admission.", "source": "NICE NG89."},
  {"id": "MAK-443", "subject": "Perioperative medicine & nutrition", "topic": "VTE prophylaxis and bleeding risk", "title": "VTE prophylaxis and bleeding risk", "stem": "A surgical patient has a high risk of VTE but also a high risk of major bleeding. What principle should guide pharmacological prophylaxis?", "options": {"A": "Give pharmacological prophylaxis regardless of bleeding risk", "B": "Balance VTE risk against bleeding risk", "C": "Ignore VTE risk", "D": "Give therapeutic anticoagulation automatically", "E": "Use the same prophylaxis for every patient"}, "correct_letter": "B", "correct_answer": "B. Balance VTE risk against bleeding risk", "why_correct": "NICE specifically recommends balancing individual VTE risk against bleeding risk when deciding whether to offer pharmacological prophylaxis.", "exam_trap": "Prophylaxis is not synonymous with therapeutic anticoagulation.", "takeaway": "VTE prophylaxis = VTE risk versus bleeding risk.", "source": "NICE NG89."},
  {"id": "MAK-444", "subject": "Perioperative medicine & nutrition", "topic": "Early mobilisation", "title": "Early mobilisation", "stem": "Which postoperative measure helps reduce venous thromboembolic risk?", "options": {"A": "Early mobilisation where clinically appropriate", "B": "Prolonged unnecessary bed rest", "C": "Deliberate dehydration", "D": "Routine immobilisation of both legs", "E": "Avoiding all physiotherapy"}, "correct_letter": "A", "correct_answer": "A. Early mobilisation where clinically appropriate", "why_correct": "NICE recommends encouraging patients to mobilise as soon as possible and avoiding unnecessary dehydration.", "exam_trap": "Mobilisation is part of VTE prevention but does not replace risk-based mechanical or pharmacological prophylaxis when indicated.", "takeaway": "Postoperative VTE prevention → mobilise + hydrate appropriately + risk-assess.", "source": "NICE NG89."},
  {"id": "MAK-445", "subject": "Perioperative medicine & nutrition", "topic": "Postoperative fever", "title": "Postoperative fever", "stem": "A patient develops a fever shortly after surgery. Which principle is most appropriate?", "options": {"A": "Assume wound infection immediately", "B": "Assess the patient clinically and consider the timing, likely causes and severity", "C": "Give prolonged antibiotics without assessment", "D": "Ignore the fever", "E": "Assume an anastomotic leak in every patient"}, "correct_letter": "B", "correct_answer": "B. Assess the patient clinically and consider the timing, likely causes and severity", "why_correct": "Postoperative fever has multiple possible causes, including inflammatory response, pulmonary complications, urinary infection, wound infection, intra-abdominal sepsis, drug reactions and thromboembolic disease.", "exam_trap": "The timing of postoperative fever can help narrow the differential, but timing alone does not establish a diagnosis.", "takeaway": "Postoperative fever → assess, don't automatically label it “wound infection.”", "source": "Standard postoperative assessment principles."},
  {"id": "MAK-446", "subject": "Perioperative medicine & nutrition", "topic": "Surgical drain", "title": "Surgical drain", "stem": "What is an important principle when deciding whether a surgical drain should remain in place?", "options": {"A": "It should remain indefinitely once inserted", "B": "Its ongoing indication and output should be reviewed", "C": "Drains eliminate all postoperative infection", "D": "A drain prevents all anastomotic leaks", "E": "Drain removal is never appropriate"}, "correct_letter": "B", "correct_answer": "B. Its ongoing indication and output should be reviewed", "why_correct": "Drains can provide therapeutic or diagnostic benefits but can also introduce infection, cause discomfort and occasionally damage tissues. Their indication and output should therefore be reviewed.", "exam_trap": "The presence of a drain does not prove that a complication has occurred.", "takeaway": "Drain present → know why it is there + review whether it is still needed.", "source": "Standard surgical postoperative principles."},
  {"id": "MAK-447", "subject": "Perioperative medicine & nutrition", "topic": "Surgical drains and output", "title": "Surgical drains and output", "stem": "A patient has a drain following abdominal surgery. Which change is most concerning?", "options": {"A": "Unexpected change in volume or character of drainage", "B": "Stable low output consistent with the planned postoperative course", "C": "Gradual reduction in output", "D": "Normal serous drainage when expected", "E": "No change in clinical condition"}, "correct_letter": "A", "correct_answer": "A. Unexpected change in volume or character of drainage", "why_correct": "Sudden changes such as enteric, bilious, faeculent, purulent or haemorrhagic output can indicate a postoperative complication depending on the operation and clinical context.", "exam_trap": "Drain interpretation is procedure-specific; not every abnormal-looking fluid means the same complication.", "takeaway": "Drain output = diagnostic information, not just fluid to empty.", "source": "Standard postoperative surgical principles."},
  {"id": "MAK-448", "subject": "Pathology: oncology & haematology", "topic": "margin", "title": "Surgical oncology: margin", "stem": "In oncological surgery, what does an R0 resection generally indicate?", "options": {"A": "Macroscopic residual tumour remains", "B": "Microscopic residual tumour remains", "C": "No residual tumour is identified after resection", "D": "The tumour was never biopsied", "E": "The operation was abandoned"}, "correct_letter": "C", "correct_answer": "C. No residual tumour is identified after resection", "why_correct": "An R0 resection indicates that no residual tumour is identified following resection. R1 generally indicates microscopic residual disease, while R2 indicates macroscopic residual disease.", "exam_trap": "R0 does not mean the patient has zero risk of recurrence.", "takeaway": "R0 = no residual tumour identified.", "source": "[RCPath]: standards and datasets for cancer resection reporting."},
  {"id": "MAK-449", "subject": "Pathology: oncology & haematology", "topic": "lymph-node staging", "title": "Surgical oncology: lymph-node staging", "stem": "What does the “N” component of TNM staging describe?", "options": {"A": "Primary tumour size only", "B": "Regional lymph-node involvement", "C": "Distant metastases", "D": "Patient nutritional status", "E": "Histological grade"}, "correct_letter": "B", "correct_answer": "B. Regional lymph-node involvement", "why_correct": "TNM: T = primary tumour extent, N = regional lymph-node involvement, M = distant metastasis.", "exam_trap": "Tumour grade is different from TNM stage.", "takeaway": "TNM → T tumour, N nodes, M metastases.", "source": "Standard surgical oncology principles."},
  {"id": "MAK-450", "subject": "Pathology: oncology & haematology", "topic": "Cancer and multidisciplinary care", "title": "Cancer and multidisciplinary care", "stem": "What is the principal purpose of a multidisciplinary team (MDT) discussion in cancer care?", "options": {"A": "To allow one clinician to make every treatment decision without discussion", "B": "To integrate relevant specialist perspectives when developing an individualised management plan", "C": "To eliminate the need for patient involvement", "D": "To guarantee cure", "E": "To replace histopathology"}, "correct_letter": "B", "correct_answer": "B. To integrate relevant specialist perspectives when developing an individualised management plan", "why_correct": "Cancer management frequently requires coordinated input from surgery, oncology, radiology, pathology and other relevant disciplines.", "exam_trap": "MDT discussion does not remove the need for informed patient involvement and shared decision-making.", "takeaway": "Cancer MDT → integrate expertise + formulate a patient-specific plan.", "source": "Standard UK multidisciplinary cancer-care principles."},
  {"id": "MAK-451", "subject": "Acute abdomen & GI surgery", "topic": "ACUTE APPENDICITIS", "title": "ACUTE APPENDICITIS", "stem": "A 22-year-old patient develops central abdominal pain that later localises to the right iliac fossa. He has anorexia, nausea and a low-grade fever. Which pathological process most commonly initiates acute appendicitis?", "options": {"A": "Haematogenous bacterial seeding", "B": "Luminal obstruction of the appendix", "C": "Primary autoimmune inflammation", "D": "Ischaemia caused by superior mesenteric artery thrombosis", "E": "Direct spread from the sigmoid colon"}, "correct_letter": "B", "correct_answer": "B. Luminal obstruction of the appendix", "why_correct": "Luminal obstruction, commonly by lymphoid hyperplasia or a faecolith, can cause mucus accumulation, increased intraluminal pressure, venous congestion, bacterial proliferation and progressive inflammation.", "exam_trap": "Do not confuse the vascular supply of the appendix with the initiating mechanism of appendicitis.", "takeaway": "Appendicitis usually begins with appendiceal luminal obstruction → distension → inflammation → possible ischaemia and perforation.", "source": "Standard surgical pathology and MRCS syllabus knowledge; Intercollegiate MRCS syllabus, current examination framework."},
  {"id": "MAK-452", "subject": "Acute abdomen & GI surgery", "topic": "PERFORATED PEPTIC ULCER", "title": "PERFORATED PEPTIC ULCER", "stem": "A patient develops sudden severe epigastric pain followed by generalised abdominal pain and guarding. An erect chest radiograph demonstrates free subdiaphragmatic gas. What is the most likely diagnosis?", "options": {"A": "Acute pancreatitis", "B": "Perforated peptic ulcer", "C": "Acute cholecystitis", "D": "Small bowel obstruction", "E": "Mesenteric infarction"}, "correct_letter": "B", "correct_answer": "B. Perforated peptic ulcer", "why_correct": "Sudden severe abdominal pain with peritonism and free intraperitoneal gas strongly suggests perforation of a hollow viscus. A perforated gastric or duodenal ulcer is a classic cause.", "exam_trap": "A normal initial abdominal examination does not exclude perforation, particularly early in the presentation.", "takeaway": "Sudden pain + peritonism + free intraperitoneal gas = perforated hollow viscus until proven otherwise.", "source": "Standard MRCS acute abdomen knowledge; Intercollegiate MRCS syllabus."},
  {"id": "MAK-453", "subject": "Acute abdomen & GI surgery", "topic": "SMALL BOWEL OBSTRUCTION", "title": "SMALL BOWEL OBSTRUCTION", "stem": "A patient with previous laparotomy presents with colicky abdominal pain, vomiting, abdominal distension and failure to pass flatus. What is the most likely cause of his small bowel obstruction?", "options": {"A": "Colorectal carcinoma", "B": "Adhesions", "C": "Crohn disease", "D": "Volvulus", "E": "Intussusception"}, "correct_letter": "B", "correct_answer": "B. Adhesions", "why_correct": "Postoperative adhesions are a major cause of small bowel obstruction in adults.", "exam_trap": "Do not automatically choose malignancy simply because the patient has bowel obstruction.", "takeaway": "Previous abdominal surgery + small bowel obstruction = adhesions are a key diagnosis.", "source": "Standard MRCS surgical knowledge; Intercollegiate MRCS syllabus."},
  {"id": "MAK-454", "subject": "Acute abdomen & GI surgery", "topic": "STRANGULATED BOWEL", "title": "STRANGULATED BOWEL", "stem": "A patient with bowel obstruction develops continuous severe abdominal pain, fever, tachycardia and increasing tenderness. What complication should be suspected?", "options": {"A": "Simple constipation", "B": "Strangulation with bowel ischaemia", "C": "Functional ileus only", "D": "Uncomplicated adhesions", "E": "Gastroenteritis"}, "correct_letter": "B", "correct_answer": "B. Strangulation with bowel ischaemia", "why_correct": "A transition from intermittent colicky pain to continuous severe pain with systemic deterioration raises concern for compromised bowel blood supply.", "exam_trap": "Pain becoming continuous is an important warning sign in bowel obstruction.", "takeaway": "Obstruction + continuous pain + systemic deterioration = think strangulation/ischaemia.", "source": "Standard MRCS acute surgical abdomen knowledge."},
  {"id": "MAK-455", "subject": "Acute abdomen & GI surgery", "topic": "CLOSED-LOOP OBSTRUCTION", "title": "CLOSED-LOOP OBSTRUCTION", "stem": "A patient has a bowel obstruction caused by obstruction at two points along the same bowel segment. Why is this particularly dangerous?", "options": {"A": "It always causes diarrhoea", "B": "It prevents any bacterial growth", "C": "The isolated segment can rapidly become distended and ischaemic", "D": "It always resolves spontaneously", "E": "It only affects the stomach"}, "correct_letter": "C", "correct_answer": "C. The isolated segment can rapidly become distended and ischaemic", "why_correct": "A closed-loop obstruction traps bowel between two points of obstruction. Increasing pressure can impair venous drainage followed by arterial inflow, producing strangulation and necrosis.", "exam_trap": "The danger is not simply the degree of vomiting; it is compromised bowel perfusion.", "takeaway": "Closed loop = trapped bowel + rising pressure + high risk of strangulation.", "source": "Standard MRCS surgical knowledge."},
  {"id": "MAK-456", "subject": "Acute abdomen & GI surgery", "topic": "LARGE BOWEL OBSTRUCTION", "title": "LARGE BOWEL OBSTRUCTION", "stem": "Which symptom pattern is most characteristic of a large bowel obstruction?", "options": {"A": "Early profuse vomiting with minimal distension", "B": "Marked abdominal distension with altered bowel habit and later vomiting", "C": "Haematemesis", "D": "Isolated epigastric pain", "E": "Painless jaundice"}, "correct_letter": "B", "correct_answer": "B. Marked abdominal distension with altered bowel habit and later vomiting", "why_correct": "Large bowel obstruction commonly produces progressive distension, constipation/obstipation and abdominal pain. Vomiting may occur later than in small bowel obstruction.", "exam_trap": "Clinical features overlap, so distinguish small from large bowel obstruction using the overall pattern rather than one symptom.", "takeaway": "Large bowel obstruction commonly produces prominent distension and obstipation.", "source": "Standard MRCS surgical knowledge."},
  {"id": "MAK-457", "subject": "Acute abdomen & GI surgery", "topic": "LEFT-SIDED COLORECTAL OBSTRUCTION", "title": "LEFT-SIDED COLORECTAL OBSTRUCTION", "stem": "A patient presents with acute left-sided large bowel obstruction caused by a colorectal tumour. Which treatment may be considered in selected patients?", "options": {"A": "Immediate appendicectomy", "B": "Colonic stenting", "C": "ERCP", "D": "Percutaneous nephrostomy", "E": "Splenectomy"}, "correct_letter": "B", "correct_answer": "B. Colonic stenting", "why_correct": "NICE recommends considering stenting for acute left-sided large bowel obstruction when treatment is intended to be palliative. For potentially curative treatment, either stenting or emergency surgery may be considered depending on the circumstances.", "exam_trap": "Do not treat colonic stenting as mandatory in every obstructing colorectal cancer.", "takeaway": "Acute left-sided malignant obstruction → consider stent versus emergency surgery according to intent and clinical circumstances.", "source": "NICE NG151, Colorectal cancer, current recommendations."},
  {"id": "MAK-458", "subject": "Acute abdomen & GI surgery", "topic": "SIGMOID VOLVULUS", "title": "SIGMOID VOLVULUS", "stem": "An elderly patient presents with massive abdominal distension, constipation and colicky abdominal pain. Imaging demonstrates a markedly dilated loop of sigmoid colon with a characteristic coffee-bean appearance. What is the diagnosis?", "options": {"A": "Caecal carcinoma", "B": "Sigmoid volvulus", "C": "Small bowel obstruction", "D": "Toxic megacolon", "E": "Ileus"}, "correct_letter": "B", "correct_answer": "B. Sigmoid volvulus", "why_correct": "Sigmoid volvulus occurs when the sigmoid colon twists around its mesenteric attachment, causing large bowel obstruction and potentially bowel ischaemia.", "exam_trap": "Volvulus can progress from obstruction to strangulation; do not regard it as a simple mechanical obstruction.", "takeaway": "Massive colonic dilatation + coffee-bean appearance = sigmoid volvulus.", "source": "Standard MRCS radiological and surgical knowledge."},
  {"id": "MAK-459", "subject": "Acute abdomen & GI surgery", "topic": "CAECAL VOLVULUS", "title": "CAECAL VOLVULUS", "stem": "Which segment of bowel is twisted in caecal volvulus?", "options": {"A": "Sigmoid colon", "B": "Rectum", "C": "Caecum and ascending colon", "D": "Transverse colon only", "E": "Terminal ileum only"}, "correct_letter": "C", "correct_answer": "C. Caecum and ascending colon", "why_correct": "Caecal volvulus involves abnormal mobility of the caecum, allowing it to twist, often with the terminal ileum and ascending colon.", "exam_trap": "Do not use \"volvulus\" and \"sigmoid volvulus\" interchangeably.", "takeaway": "Sigmoid volvulus and caecal volvulus are distinct anatomical entities.", "source": "Standard MRCS surgical knowledge."},
  {"id": "MAK-460", "subject": "Acute abdomen & GI surgery", "topic": "INCARCERATED VERSUS STRANGULATED HERNIA", "title": "INCARCERATED VERSUS STRANGULATED HERNIA", "stem": "A groin hernia cannot be reduced but the patient has no evidence of bowel ischaemia. Which term best describes the hernia?", "options": {"A": "Reducible", "B": "Incarcerated", "C": "Strangulated", "D": "Recurrent", "E": "Sliding only"}, "correct_letter": "B", "correct_answer": "B. Incarcerated", "why_correct": "An incarcerated hernia is irreducible. Strangulation specifically implies compromised blood supply to the herniated contents.", "exam_trap": "Irreducibility alone does not prove strangulation.", "takeaway": "Incarcerated = irreducible. Strangulated = compromised blood supply.", "source": "Standard MRCS surgical knowledge."},
  {"id": "MAK-461", "subject": "Acute abdomen & GI surgery", "topic": "STRANGULATED HERNIA", "title": "STRANGULATED HERNIA", "stem": "A patient with an irreducible hernia develops severe pain, tenderness, tachycardia and systemic toxicity. What complication must be assumed until excluded?", "options": {"A": "Simple incarceration", "B": "Strangulation", "C": "Hydrocele", "D": "Lipoma", "E": "Varicocele"}, "correct_letter": "B", "correct_answer": "B. Strangulation", "why_correct": "Pain and systemic deterioration in an irreducible hernia suggest compromised bowel or other herniated tissue.", "exam_trap": "Do not repeatedly attempt forceful reduction when strangulation is suspected.", "takeaway": "Painful irreducible hernia + systemic deterioration = emergency assessment for strangulation.", "source": "Standard MRCS surgical knowledge."},
  {"id": "MAK-462", "subject": "Acute abdomen & GI surgery", "topic": "ACUTE MESENTERIC ISCHAEMIA", "title": "ACUTE MESENTERIC ISCHAEMIA", "stem": "A patient with atrial fibrillation develops sudden severe abdominal pain but initially has relatively little abdominal tenderness. What diagnosis should be strongly considered?", "options": {"A": "Acute mesenteric ischaemia", "B": "Acute cholecystitis", "C": "Appendicitis", "D": "Diverticular disease", "E": "Peptic ulcer disease without perforation"}, "correct_letter": "A", "correct_answer": "A. Acute mesenteric ischaemia", "why_correct": "Acute mesenteric ischaemia can initially produce severe abdominal pain out of proportion to physical findings. Embolic arterial occlusion is an important cause, particularly in patients with atrial fibrillation.", "exam_trap": "A relatively benign abdomen does not exclude life-threatening bowel ischaemia early in the disease.", "takeaway": "Pain out of proportion to examination = think mesenteric ischaemia.", "source": "Standard MRCS acute vascular and abdominal surgery knowledge."},
  {"id": "MAK-463", "subject": "Acute abdomen & GI surgery", "topic": "CHRONIC MESENTERIC ISCHAEMIA", "title": "CHRONIC MESENTERIC ISCHAEMIA", "stem": "A patient develops recurrent abdominal pain after meals and has progressively reduced food intake because eating provokes symptoms. What diagnosis should be considered?", "options": {"A": "Chronic mesenteric ischaemia", "B": "Acute appendicitis", "C": "Haemorrhoids", "D": "Acute cholecystitis", "E": "Small bowel volvulus"}, "correct_letter": "A", "correct_answer": "A. Chronic mesenteric ischaemia", "why_correct": "Chronic mesenteric arterial insufficiency can cause postprandial abdominal pain and food avoidance, sometimes producing weight loss.", "exam_trap": "The absence of dramatic abdominal tenderness does not exclude vascular disease.", "takeaway": "Postprandial pain + food avoidance + weight loss = consider chronic mesenteric ischaemia.", "source": "Standard MRCS vascular surgery knowledge."},
  {"id": "MAK-464", "subject": "Acute abdomen & GI surgery", "topic": "DIVERTICULITIS", "title": "DIVERTICULITIS", "stem": "A patient presents with left lower abdominal pain, fever and altered bowel habit. Examination demonstrates localised left iliac fossa tenderness. Which diagnosis is most likely?", "options": {"A": "Acute diverticulitis", "B": "Acute appendicitis", "C": "Acute pancreatitis", "D": "Testicular torsion", "E": "Biliary colic"}, "correct_letter": "A", "correct_answer": "A. Acute diverticulitis", "why_correct": "Left lower abdominal pain with systemic inflammatory features is a classic presentation of acute diverticulitis. Potential complications include abscess, perforation, fistula and obstruction.", "exam_trap": "Do not assume every left iliac fossa pain is diverticulitis; urinary, gynaecological and colorectal pathology can mimic it.", "takeaway": "Left iliac fossa pain + inflammatory features → diverticulitis is a key diagnosis.", "source": "Standard MRCS colorectal surgery knowledge."},
  {"id": "MAK-465", "subject": "Acute abdomen & GI surgery", "topic": "DIVERTICULAR BLEEDING", "title": "DIVERTICULAR BLEEDING", "stem": "A patient develops sudden, painless, large-volume fresh rectal bleeding. Which colonic condition is a common cause of significant lower gastrointestinal bleeding?", "options": {"A": "Diverticular disease", "B": "Acute appendicitis", "C": "Anal fissure", "D": "Small bowel volvulus", "E": "Cholecystitis"}, "correct_letter": "A", "correct_answer": "A. Diverticular disease", "why_correct": "Diverticular bleeding can arise from erosion of vessels associated with diverticula and may be substantial and painless.", "exam_trap": "Do not assume that all rectal bleeding associated with diverticular disease is caused by diverticulitis; diverticular bleeding is often painless.", "takeaway": "Painless significant fresh rectal bleeding → consider diverticular bleeding.", "source": "Standard MRCS colorectal knowledge."},
  {"id": "MAK-466", "subject": "Pathology: oncology & haematology", "topic": "COLORECTAL CANCER AND IRON-DEFICIENCY ANAEMIA", "title": "COLORECTAL CANCER AND IRON-DEFICIENCY ANAEMIA", "stem": "A 68-year-old man develops unexplained iron-deficiency anaemia. Which diagnosis must be considered?", "options": {"A": "Colorectal cancer", "B": "Acute pancreatitis", "C": "Cholelithiasis alone", "D": "Inguinal hernia", "E": "Haemorrhoids only"}, "correct_letter": "A", "correct_answer": "A. Colorectal cancer", "why_correct": "Occult gastrointestinal blood loss from colorectal cancer can present as iron-deficiency anaemia, particularly in older adults.", "exam_trap": "Do not dismiss iron deficiency as dietary without considering gastrointestinal blood loss when clinically appropriate.", "takeaway": "Unexplained iron deficiency in an older adult = investigate for gastrointestinal blood loss, including colorectal cancer.", "source": "NICE NG12/NICE NG151; current UK colorectal cancer guidance."},
  {"id": "MAK-467", "subject": "Genetics", "topic": "FAMILIAL ADENOMATOUS POLYPOSIS", "title": "FAMILIAL ADENOMATOUS POLYPOSIS", "stem": "A patient has hundreds of adenomatous colorectal polyps and a strong family history of colorectal cancer. Which gene is classically associated with familial adenomatous polyposis?", "options": {"A": "APC", "B": "BRCA1", "C": "RET", "D": "MEN1", "E": "VHL"}, "correct_letter": "A", "correct_answer": "A. APC", "why_correct": "Familial adenomatous polyposis is classically caused by pathogenic variants in the APC tumour suppressor gene. Without appropriate management, colorectal cancer risk is extremely high.", "exam_trap": "Do not confuse APC-associated FAP with mismatch-repair-associated Lynch syndrome.", "takeaway": "Hundreds of adenomatous polyps + inherited colorectal cancer syndrome = APC/FAP.", "source": "Standard MRCS genetics and colorectal surgery knowledge."},
  {"id": "MAK-468", "subject": "Genetics", "topic": "LYNCH SYNDROME", "title": "LYNCH SYNDROME", "stem": "Which molecular abnormality is classically associated with Lynch syndrome?", "options": {"A": "DNA mismatch repair deficiency", "B": "CFTR mutation", "C": "APC deletion in every case", "D": "RET activation", "E": "Mitochondrial DNA deletion"}, "correct_letter": "A", "correct_answer": "A. DNA mismatch repair deficiency", "why_correct": "Lynch syndrome is associated with inherited defects in DNA mismatch repair genes, producing microsatellite instability in affected tumours.", "exam_trap": "FAP produces numerous adenomatous polyps; Lynch syndrome does not characteristically produce hundreds of colorectal polyps.", "takeaway": "Lynch = mismatch repair deficiency + inherited colorectal and other cancer susceptibility.", "source": "Standard MRCS genetics and colorectal oncology knowledge."},
  {"id": "MAK-469", "subject": "Pathology: oncology & haematology", "topic": "RECTAL CANCER", "title": "RECTAL CANCER", "stem": "Which imaging modality is particularly important for local staging of rectal cancer?", "options": {"A": "MRI pelvis", "B": "Plain abdominal radiograph", "C": "Non-contrast head CT", "D": "Chest radiograph alone", "E": "Ultrasound of the thyroid"}, "correct_letter": "A", "correct_answer": "A. MRI pelvis", "why_correct": "Pelvic MRI provides detailed assessment of the rectal tumour and surrounding structures and is central to local staging and treatment planning.", "exam_trap": "Do not confuse local staging with assessment for distant metastases.", "takeaway": "Rectal cancer → pelvic MRI is central to local staging.", "source": "NICE NG151, Colorectal cancer."},
  {"id": "MAK-470", "subject": "Pathology: oncology & haematology", "topic": "COLORECTAL CANCER MDT", "title": "COLORECTAL CANCER MDT", "stem": "A patient has newly diagnosed colorectal cancer. Why is multidisciplinary team discussion important?", "options": {"A": "To replace informed consent", "B": "To integrate surgical, oncological, radiological and pathological assessment", "C": "To avoid discussing treatment options with the patient", "D": "To determine treatment using only the CT scan", "E": "To avoid histological diagnosis"}, "correct_letter": "B", "correct_answer": "B. To integrate surgical, oncological, radiological and pathological assessment", "why_correct": "Cancer management often requires integration of pathology, imaging, surgical options, systemic treatment, radiotherapy and patient factors.", "exam_trap": "MDT discussion does not remove the patient's role in treatment decisions.", "takeaway": "Cancer MDT = coordinated multidisciplinary assessment and treatment planning.", "source": "NICE NG151; current colorectal cancer guidance."},
  {"id": "MAK-471", "subject": "Acute abdomen & GI surgery", "topic": "ACUTE CHOLECYSTITIS", "title": "ACUTE CHOLECYSTITIS", "stem": "A patient develops persistent right upper quadrant pain, fever and a positive Murphy sign. Which diagnosis is most likely?", "options": {"A": "Acute cholecystitis", "B": "Acute appendicitis", "C": "Acute diverticulitis", "D": "Mesenteric ischaemia", "E": "Small bowel obstruction"}, "correct_letter": "A", "correct_answer": "A. Acute cholecystitis", "why_correct": "Acute inflammation of the gallbladder commonly presents with persistent right upper quadrant pain, systemic inflammatory features and local tenderness.", "exam_trap": "Biliary colic is typically transient; persistent pain with systemic inflammation suggests cholecystitis.", "takeaway": "Persistent RUQ pain + inflammatory features = acute cholecystitis.", "source": "NICE CG188, Gallstone disease."},
  {"id": "MAK-472", "subject": "Acute abdomen & GI surgery", "topic": "MANAGEMENT OF ACUTE CHOLECYSTITIS", "title": "MANAGEMENT OF ACUTE CHOLECYSTITIS", "stem": "A patient has confirmed acute cholecystitis and is suitable for surgery. What does NICE recommend?", "options": {"A": "Routine delayed cholecystectomy after several years", "B": "Early laparoscopic cholecystectomy", "C": "Total gastrectomy", "D": "ERCP in every patient", "E": "No treatment if gallstones are present"}, "correct_letter": "B", "correct_answer": "B. Early laparoscopic cholecystectomy", "why_correct": "NICE recommends early laparoscopic cholecystectomy for acute cholecystitis, with the guideline specifying that it should be carried out within 1 week of diagnosis.", "exam_trap": "ERCP is primarily used when the common bile duct requires clearance, not as routine treatment for uncomplicated acute cholecystitis.", "takeaway": "Acute cholecystitis → early laparoscopic cholecystectomy when appropriate.", "source": "NICE CG188, Gallstone disease."},
  {"id": "MAK-473", "subject": "Acute abdomen & GI surgery", "topic": "ASCENDING CHOLANGITIS", "title": "ASCENDING CHOLANGITIS", "stem": "A patient has fever, jaundice and right upper quadrant pain. Blood tests show cholestatic liver dysfunction. What diagnosis should be suspected?", "options": {"A": "Ascending cholangitis", "B": "Acute appendicitis", "C": "Acute diverticulitis", "D": "Mesenteric ischaemia", "E": "Incisional hernia"}, "correct_letter": "A", "correct_answer": "A. Ascending cholangitis", "why_correct": "Ascending cholangitis results from infection of an obstructed biliary tree, commonly associated with common bile duct stones.", "exam_trap": "The important concept is infected obstruction; antibiotics alone may not provide definitive source control when obstruction persists.", "takeaway": "Cholangitis = infected obstructed biliary system → antibiotics + assessment for biliary drainage/source control.", "source": "Standard MRCS hepatobiliary surgery knowledge; NICE CG188."},
  {"id": "MAK-474", "subject": "Acute abdomen & GI surgery", "topic": "COMMON BILE DUCT STONES", "title": "COMMON BILE DUCT STONES", "stem": "A patient with symptomatic gallstone disease is found to have a common bile duct stone. Which intervention can be used to clear the bile duct?", "options": {"A": "ERCP", "B": "Appendicectomy", "C": "Colonoscopy alone", "D": "Nephrostomy", "E": "Splenectomy"}, "correct_letter": "A", "correct_answer": "A. ERCP", "why_correct": "ERCP can be used for endoscopic clearance of common bile duct stones. NICE recommends bile duct clearance surgically at the time of laparoscopic cholecystectomy or by ERCP before or at the time of laparoscopic cholecystectomy.", "exam_trap": "A stone confined to the gallbladder does not automatically require ERCP.", "takeaway": "CBD stone → establish a strategy for duct clearance; ERCP is an important endoscopic option.", "source": "NICE CG188, Gallstone disease."},
  {"id": "MAK-475", "subject": "Acute abdomen & GI surgery", "topic": "ACUTE PANCREATITIS", "title": "ACUTE PANCREATITIS", "stem": "Which combination best supports a diagnosis of acute pancreatitis?", "options": {"A": "Epigastric pain plus compatible pancreatic enzyme elevation (amylase/lipase more than 3x the upper limit of normal) and/or characteristic imaging", "B": "Right iliac fossa pain alone", "C": "Painless jaundice alone", "D": "Fresh rectal bleeding alone", "E": "Dysuria alone"}, "correct_letter": "A", "correct_answer": "A. Epigastric pain plus compatible pancreatic enzyme elevation (amylase/lipase more than 3x the upper limit of normal) and/or characteristic imaging", "why_correct": "Acute pancreatitis is diagnosed using the overall clinical, biochemical and imaging picture. The classic presentation is acute upper abdominal/epigastric pain, often radiating to the back, with elevated pancreatic enzymes. Per the revised Atlanta classification, biochemical support for the diagnosis requires amylase or lipase more than 3x the upper limit of normal.", "exam_trap": "An elevated lipase/amylase result should be interpreted in clinical context rather than treated as a diagnosis in isolation; note that the diagnostic threshold is more than 3x the upper limit of normal, not any elevation.", "takeaway": "Acute pancreatitis = compatible clinical picture + biochemical and/or imaging evidence.", "source": "Standard MRCS acute surgical knowledge."},
  {"id": "MAK-476", "subject": "Acute abdomen & GI surgery", "topic": "PANCREATIC HEAD CANCER", "title": "PANCREATIC HEAD CANCER", "stem": "A patient develops progressive painless obstructive jaundice and weight loss. Imaging shows a mass in the head of the pancreas. Which additional finding may occur because of biliary obstruction?", "options": {"A": "Dark urine and pale stools", "B": "Haemoptysis", "C": "Fresh rectal bleeding as the defining feature", "D": "Severe polyuria from diabetes insipidus", "E": "Isolated unilateral leg oedema"}, "correct_letter": "A", "correct_answer": "A. Dark urine and pale stools", "why_correct": "Obstruction of bile flow reduces bilirubin delivery to the intestine, producing pale stools, while conjugated bilirubin can appear in urine.", "exam_trap": "Do not assume all jaundice is hepatocellular; obstructive and hepatocellular patterns differ.", "takeaway": "Painless progressive obstructive jaundice + weight loss → pancreatic head malignancy is an important consideration.", "source": "Standard MRCS hepatobiliary and pancreatic surgery knowledge."},
  {"id": "MAK-477", "subject": "Vascular, endocrine surgery & perioperative care", "topic": "PERIPHERAL ARTERIAL DISEASE", "title": "PERIPHERAL ARTERIAL DISEASE", "stem": "A patient has exertional calf pain that reliably occurs after walking a certain distance and settles with rest. What is the most likely diagnosis?", "options": {"A": "Intermittent claudication", "B": "Acute limb ischaemia", "C": "Cellulitis", "D": "Deep vein thrombosis", "E": "Compartment syndrome"}, "correct_letter": "A", "correct_answer": "A. Intermittent claudication", "why_correct": "Intermittent claudication is exertional limb muscle pain caused by inadequate arterial blood flow, typically relieved by rest. NICE recommends assessment including symptoms, examination of pulses and ankle-brachial pressure index.", "exam_trap": "Claudication is reproducible with exercise; acute limb ischaemia is a sudden vascular emergency.", "takeaway": "Predictable exertional limb pain relieved by rest = intermittent claudication.", "source": "NICE CG147, Peripheral arterial disease."},
  {"id": "MAK-478", "subject": "Vascular, endocrine surgery & perioperative care", "topic": "ANKLE-BRACHIAL PRESSURE INDEX", "title": "ANKLE-BRACHIAL PRESSURE INDEX", "stem": "How is the ankle-brachial pressure index calculated?", "options": {"A": "Lowest ankle systolic pressure ÷ lowest arm systolic pressure", "B": "Highest ankle systolic pressure ÷ highest arm systolic pressure", "C": "Highest arm pressure ÷ highest ankle pressure", "D": "Mean arterial pressure ÷ heart rate", "E": "Diastolic ankle pressure ÷ systolic arm pressure"}, "correct_letter": "B", "correct_answer": "B. Highest ankle systolic pressure ÷ highest arm systolic pressure", "why_correct": "NICE specifies calculating ABPI using the highest ankle pressure divided by the highest arm pressure, with Doppler measurement preferred.", "exam_trap": "Do not reverse the numerator and denominator.", "takeaway": "ABPI = highest ankle systolic pressure / highest brachial systolic pressure.", "source": "NICE CG147, Peripheral arterial disease."},
  {"id": "MAK-479", "subject": "Vascular, endocrine surgery & perioperative care", "topic": "ABDOMINAL AORTIC ANEURYSM", "title": "ABDOMINAL AORTIC ANEURYSM", "stem": "A 72-year-old man presents with sudden abdominal and back pain, hypotension and collapse. What vascular emergency should be considered immediately?", "options": {"A": "Ruptured abdominal aortic aneurysm", "B": "Chronic venous insufficiency", "C": "Intermittent claudication", "D": "Varicose veins", "E": "Uncomplicated inguinal hernia"}, "correct_letter": "A", "correct_answer": "A. Ruptured abdominal aortic aneurysm", "why_correct": "NICE specifically advises considering ruptured AAA in people with new abdominal and/or back pain, cardiovascular collapse or loss of consciousness, particularly when risk factors are present.", "exam_trap": "Do not wait for the classic triad of abdominal pain, hypotension and a palpable pulsatile mass.", "takeaway": "Sudden abdominal/back pain + collapse in an at-risk patient = ruptured AAA until excluded.", "source": "NICE NG156."},
  {"id": "MAK-480", "subject": "Vascular, endocrine surgery & perioperative care", "topic": "AAA REPAIR THRESHOLD", "title": "AAA REPAIR THRESHOLD", "stem": "An otherwise suitable patient is found to have an asymptomatic abdominal aortic aneurysm measuring 5.6 cm on ultrasound. Which statement is consistent with NICE guidance?", "options": {"A": "Repair should never be considered for an asymptomatic AAA", "B": "Repair should be considered because the aneurysm is at or above the NICE threshold", "C": "Immediate chemotherapy is indicated", "D": "ERCP is required", "E": "The finding is treated as peripheral arterial disease"}, "correct_letter": "B", "correct_answer": "B. Repair should be considered because the aneurysm is at or above the NICE threshold", "why_correct": "NICE recommends considering repair of an asymptomatic AAA when it is 5.5 cm or larger, measured using the specified ultrasound methodology. Symptomatic aneurysms and rapidly expanding aneurysms are also indications for consideration of repair.", "exam_trap": "Do not confuse the threshold for considering repair with a statement that every patient must automatically undergo surgery; individual circumstances and shared decision-making remain important.", "takeaway": "Asymptomatic AAA ≥5.5 cm → consider repair and refer for specialist vascular assessment.", "source": "NICE NG156."},
  {"id": "MAK-481", "subject": "Breast surgery", "topic": "AXILLARY ASSESSMENT", "title": "BREAST CANCER: AXILLARY ASSESSMENT", "stem": "A woman has a newly diagnosed invasive breast cancer. Which investigation is recommended as part of pretreatment assessment of the axilla?", "options": {"A": "Routine CT head", "B": "Axillary ultrasound", "C": "Routine PET-CT in every patient", "D": "Diagnostic laparoscopy", "E": "Bone marrow biopsy"}, "correct_letter": "B", "correct_answer": "B. Axillary ultrasound", "why_correct": "NICE recommends pretreatment ultrasound assessment of the axilla in people being investigated for early and locally advanced invasive breast cancer. If abnormal nodes are identified, ultrasound-guided needle sampling should be performed.", "exam_trap": "Do not jump directly to axillary clearance without appropriate assessment.", "takeaway": "Invasive breast cancer → assess the axilla with ultrasound.", "source": "NICE NG101; updated recommendations reviewed through 2025."},
  {"id": "MAK-482", "subject": "Breast surgery", "topic": "SENTINEL NODE BIOPSY", "title": "BREAST CANCER: SENTINEL NODE BIOPSY", "stem": "A patient has invasive breast cancer with no evidence of axillary lymph-node involvement on ultrasound. What is the usual surgical method for axillary staging?", "options": {"A": "Routine complete axillary clearance", "B": "Sentinel lymph node biopsy", "C": "Total thyroidectomy", "D": "PET-CT-guided lymph-node excision", "E": "No assessment of the axilla"}, "correct_letter": "B", "correct_answer": "B. Sentinel lymph node biopsy", "why_correct": "NICE recommends sentinel lymph node biopsy rather than axillary lymph-node clearance for axillary staging in invasive breast cancer when there is no evidence of nodal involvement on ultrasound, or when ultrasound-guided needle biopsy is negative.", "exam_trap": "Sentinel-node biopsy is staging; it is not synonymous with therapeutic axillary clearance.", "takeaway": "Clinically node-negative invasive breast cancer → SLNB is the key axillary staging procedure.", "source": "NICE NG101."},
  {"id": "MAK-483", "subject": "Breast surgery", "topic": "DCIS AND SENTINEL NODE BIOPSY", "title": "DCIS AND SENTINEL NODE BIOPSY", "stem": "A patient has ductal carcinoma in situ and is undergoing breast-conserving surgery. Which statement is correct?", "options": {"A": "Sentinel node biopsy is mandatory in every case", "B": "Sentinel node biopsy is never appropriate", "C": "Sentinel node biopsy is not routinely performed unless there is high risk of invasive disease", "D": "Axillary clearance is mandatory", "E": "The axilla must always be biopsied with CT guidance"}, "correct_letter": "C", "correct_answer": "C. Sentinel node biopsy is not routinely performed unless there is high risk of invasive disease", "why_correct": "NICE advises against routine SLNB for DCIS treated with breast-conserving surgery unless there is high risk of invasive disease, such as a palpable mass or extensive microcalcifications.", "exam_trap": "DCIS and invasive breast cancer have different axillary management principles.", "takeaway": "DCIS + breast-conserving surgery → no routine SLNB unless specific high-risk features exist.", "source": "NICE NG101."},
  {"id": "MAK-484", "subject": "Breast surgery", "topic": "DCIS AND MASTECTOMY", "title": "DCIS AND MASTECTOMY", "stem": "A patient with extensive DCIS is undergoing mastectomy. Which axillary procedure should be offered?", "options": {"A": "No axillary assessment", "B": "Sentinel lymph node biopsy", "C": "Routine bilateral axillary clearance", "D": "PET-guided axillary biopsy", "E": "Axillary radiotherapy only"}, "correct_letter": "B", "correct_answer": "B. Sentinel lymph node biopsy", "why_correct": "NICE recommends offering SLNB to people undergoing mastectomy for DCIS because subsequent sentinel-node assessment may not be feasible after the breast has been removed.", "exam_trap": "The answer differs from DCIS treated with breast-conserving surgery.", "takeaway": "DCIS + mastectomy → offer SLNB.", "source": "NICE NG101."},
  {"id": "MAK-485", "subject": "Breast surgery", "topic": "BREAST MRI", "title": "BREAST MRI", "stem": "A patient has biopsy-proven invasive breast cancer. Clinical examination, mammography and ultrasound clearly define the extent of disease. Which statement about breast MRI is most accurate?", "options": {"A": "MRI is routinely mandatory before every breast operation", "B": "MRI is never useful in breast cancer", "C": "MRI is not routinely required when conventional assessment adequately defines the disease", "D": "MRI replaces histological diagnosis", "E": "MRI replaces mammography in all patients"}, "correct_letter": "C", "correct_answer": "C. MRI is not routinely required when conventional assessment adequately defines the disease", "why_correct": "NICE does not recommend routine breast MRI as part of preoperative assessment for biopsy-proven invasive breast cancer or DCIS. MRI has selected indications, including uncertainty about disease extent or difficult mammographic assessment.", "exam_trap": "\"More imaging\" does not automatically mean \"better staging.\"", "takeaway": "Breast MRI = selective problem-solving investigation, not routine imaging for every breast cancer.", "source": "NICE NG101."},
  {"id": "MAK-486", "subject": "Vascular, endocrine surgery & perioperative care", "topic": "INITIAL IMAGING", "title": "THYROID NODULE: INITIAL IMAGING", "stem": "A patient is found to have a thyroid nodule requiring investigation for malignancy. What is the recommended initial diagnostic imaging test?", "options": {"A": "CT chest", "B": "PET-CT", "C": "Greyscale ultrasound using an established grading system", "D": "MRI brain", "E": "Plain radiograph"}, "correct_letter": "C", "correct_answer": "C. Greyscale ultrasound using an established grading system", "why_correct": "NICE recommends greyscale ultrasound with an established system for grading ultrasound appearance as the initial diagnostic test when investigating thyroid nodules for malignancy.", "exam_trap": "Do not proceed directly to CT simply because a thyroid nodule has been discovered.", "takeaway": "Thyroid nodule → ultrasound first.", "source": "NICE NG230, Thyroid cancer: assessment and management."},
  {"id": "MAK-487", "subject": "Vascular, endocrine surgery & perioperative care", "topic": "FNAC", "title": "THYROID NODULE: FNAC", "stem": "A thyroid nodule has an ultrasound appearance that reaches the threshold for cytological assessment. What should be offered?", "options": {"A": "Fine-needle aspiration cytology", "B": "Immediate total thyroidectomy in every case", "C": "ERCP", "D": "Colonoscopy", "E": "Bone marrow biopsy"}, "correct_letter": "A", "correct_answer": "A. Fine-needle aspiration cytology", "why_correct": "NICE recommends FNAC for thyroid nodules meeting the threshold based on an established ultrasound grading system. Ultrasound guidance should be used when performing FNAC.", "exam_trap": "Not every thyroid nodule requires FNAC; ultrasound risk stratification helps determine which nodules require sampling.", "takeaway": "Thyroid ultrasound risk assessment → FNAC when the threshold is met.", "source": "NICE NG230."},
  {"id": "MAK-488", "subject": "Vascular, endocrine surgery & perioperative care", "topic": "FOLLICULAR THYROID NEOPLASM", "title": "FOLLICULAR THYROID NEOPLASM", "stem": "A thyroid FNAC result is reported as Thy3f, suggesting a follicular neoplasm. Which management option may be considered?", "options": {"A": "Diagnostic hemithyroidectomy", "B": "Immediate chemotherapy in every case", "C": "ERCP", "D": "Axillary clearance", "E": "Appendicectomy"}, "correct_letter": "A", "correct_answer": "A. Diagnostic hemithyroidectomy", "why_correct": "NICE recommends considering diagnostic hemithyroidectomy for Thy3f cytology, which suggests a follicular neoplasm.", "exam_trap": "Cytology cannot reliably distinguish follicular adenoma from follicular carcinoma because capsular or vascular invasion requires histological assessment.", "takeaway": "Follicular-pattern thyroid lesion → remember that invasion is a histological diagnosis.", "source": "NICE NG230."},
  {"id": "MAK-489", "subject": "Vascular, endocrine surgery & perioperative care", "topic": "CALCITONIN", "title": "THYROID CANCER: CALCITONIN", "stem": "A patient has a thyroid nodule. Which statement regarding calcitonin testing is correct?", "options": {"A": "It should be measured routinely in every thyroid nodule", "B": "It should never be measured", "C": "It should be considered when medullary thyroid cancer is suspected", "D": "It replaces ultrasound", "E": "It establishes papillary thyroid cancer"}, "correct_letter": "C", "correct_answer": "C. It should be considered when medullary thyroid cancer is suspected", "why_correct": "NICE advises against routine calcitonin testing for thyroid nodules unless there is a reason to suspect medullary thyroid cancer, such as a relevant family history or suspicious ultrasound appearance.", "exam_trap": "Calcitonin is associated particularly with medullary thyroid carcinoma, not as a universal thyroid-nodule marker.", "takeaway": "Suspected medullary thyroid cancer → calcitonin becomes relevant.", "source": "NICE NG230."},
  {"id": "MAK-490", "subject": "Urology", "topic": "FIRST-LINE MRI", "title": "PROSTATE CANCER: FIRST-LINE MRI", "stem": "A man has suspected clinically localised prostate cancer. According to NICE, what is the first-line investigation?", "options": {"A": "Bone scan", "B": "Multiparametric MRI", "C": "Diagnostic laparoscopy", "D": "CT colonography", "E": "PET-CT in every patient"}, "correct_letter": "B", "correct_answer": "B. Multiparametric MRI", "why_correct": "NICE recommends multiparametric MRI as the first-line investigation for people with suspected clinically localised prostate cancer.", "exam_trap": "Do not automatically proceed directly from an elevated PSA to biopsy.", "takeaway": "Suspected clinically localised prostate cancer → mpMRI first.", "source": "NICE NG131, Prostate cancer: diagnosis and management."},
  {"id": "MAK-491", "subject": "Urology", "topic": "PROSTATE MRI AND BIOPSY", "title": "PROSTATE MRI AND BIOPSY", "stem": "A patient's prostate MRI has a Likert score of 4. What is the next investigation recommended by NICE?", "options": {"A": "No further investigation", "B": "MRI-influenced prostate biopsy", "C": "Immediate radical prostatectomy without tissue diagnosis", "D": "Colonoscopy", "E": "TURBT"}, "correct_letter": "B", "correct_answer": "B. MRI-influenced prostate biopsy", "why_correct": "NICE recommends MRI-influenced prostate biopsy for people whose multiparametric MRI has a Likert score of 3 or more.", "exam_trap": "MRI identifies suspicious areas but does not itself provide histological confirmation.", "takeaway": "Prostate mpMRI Likert ≥3 → MRI-influenced biopsy.", "source": "NICE NG131."},
  {"id": "MAK-492", "subject": "Urology", "topic": "LOW-RISK PROSTATE MRI", "title": "LOW-RISK PROSTATE MRI", "stem": "A patient with suspected clinically localised prostate cancer has a multiparametric MRI Likert score of 2. Which statement is most accurate?", "options": {"A": "Biopsy is mandatory in every patient", "B": "Biopsy can never be performed", "C": "Biopsy may be omitted after discussion of risks and benefits and shared decision-making", "D": "Radical prostatectomy is mandatory", "E": "Chemotherapy is mandatory"}, "correct_letter": "C", "correct_answer": "C. Biopsy may be omitted after discussion of risks and benefits and shared decision-making", "why_correct": "NICE allows consideration of omitting biopsy in people with Likert 1 or 2, provided risks and benefits are discussed and a shared decision is reached.", "exam_trap": "A low-risk MRI does not mean that clinically significant cancer is impossible.", "takeaway": "Low-risk MRI can support biopsy avoidance in selected patients, but shared decision-making remains important.", "source": "NICE NG131."},
  {"id": "MAK-493", "subject": "Urology", "topic": "ACUTE URINARY RETENTION", "title": "ACUTE URINARY RETENTION", "stem": "An elderly man with lower urinary tract symptoms develops painful inability to pass urine with a palpable distended bladder. What is the immediate treatment?", "options": {"A": "Urinary catheterisation", "B": "Immediate nephrectomy", "C": "ERCP", "D": "Colonoscopy", "E": "TURBT without initial bladder decompression"}, "correct_letter": "A", "correct_answer": "A. Urinary catheterisation", "why_correct": "Acute urinary retention requires prompt bladder decompression, usually with urethral catheterisation unless contraindicated or unsuccessful.", "exam_trap": "Do not delay bladder decompression while investigating the underlying cause.", "takeaway": "Painful retention + palpable bladder → decompress first, investigate cause second.", "source": "Standard MRCS urological surgery knowledge."},
  {"id": "MAK-494", "subject": "Urology", "topic": "TESTICULAR TORSION", "title": "TESTICULAR TORSION", "stem": "A 17-year-old develops sudden severe unilateral scrotal pain and nausea. The affected testis is high-riding. What is the priority?", "options": {"A": "Reassurance and outpatient review", "B": "Emergency surgical assessment for testicular torsion", "C": "Routine antibiotics only", "D": "Elective ultrasound in several weeks", "E": "Colonoscopy"}, "correct_letter": "B", "correct_answer": "B. Emergency surgical assessment for testicular torsion", "why_correct": "Testicular torsion is a time-critical surgical emergency. Delay can result in testicular ischaemia and infarction.", "exam_trap": "A normal inflammatory marker does not exclude torsion.", "takeaway": "Sudden severe testicular pain in an adolescent = torsion until proven otherwise.", "source": "Standard MRCS urology knowledge."},
  {"id": "MAK-495", "subject": "Urology", "topic": "RENAL COLIC", "title": "RENAL COLIC", "stem": "A patient develops sudden severe flank pain radiating towards the groin with microscopic haematuria. What is the most likely diagnosis?", "options": {"A": "Ureteric stone", "B": "Acute appendicitis", "C": "Acute cholecystitis", "D": "Diverticulitis", "E": "Inguinal hernia"}, "correct_letter": "A", "correct_answer": "A. Ureteric stone", "why_correct": "Renal/ureteric colic classically causes severe flank pain that may radiate towards the groin and is commonly associated with haematuria.", "exam_trap": "Renal colic is typically colicky and causes the patient to move around seeking a comfortable position; peritonitis has a different clinical pattern.", "takeaway": "Flank-to-groin colicky pain + haematuria = ureteric stone.", "source": "NICE NG118"},
  {"id": "MAK-496", "subject": "Urology", "topic": "OBSTRUCTED INFECTED KIDNEY", "title": "OBSTRUCTED INFECTED KIDNEY", "stem": "A patient has fever, rigors, flank pain and imaging demonstrates an obstructed urinary system due to a ureteric stone. What is the key management principle?", "options": {"A": "Antibiotics alone are always sufficient", "B": "Urgent urinary drainage is required alongside treatment of infection", "C": "Ignore the obstruction", "D": "Immediate elective stone surgery only after several months", "E": "No treatment if creatinine is normal"}, "correct_letter": "B", "correct_answer": "B. Urgent urinary drainage is required alongside treatment of infection", "why_correct": "An infected obstructed urinary tract can deteriorate rapidly. Antibiotics treat infection, but source control requires decompression of the obstructed system.", "exam_trap": "Do not treat infected obstruction as uncomplicated renal colic.", "takeaway": "Infected + obstructed urinary system = antibiotics + urgent drainage/source control.", "source": "Standard MRCS urological emergency knowledge."},
  {"id": "MAK-497", "subject": "Major trauma & fluids", "topic": "AIRWAY", "title": "MAJOR TRAUMA: AIRWAY", "stem": "A patient with major trauma cannot maintain their airway or ventilation. What is the definitive method of securing the airway according to NICE?", "options": {"A": "Oxygen by mask alone", "B": "Drug-assisted rapid sequence induction and intubation", "C": "Nasogastric tube", "D": "Observation only", "E": "Immediate CT before airway management"}, "correct_letter": "B", "correct_answer": "B. Drug-assisted rapid sequence induction and intubation", "why_correct": "NICE recommends drug-assisted RSI and intubation as the definitive airway method in major trauma patients who cannot maintain their airway and/or ventilation.", "exam_trap": "Imaging does not take priority over an immediately threatened airway.", "takeaway": "Major trauma + failed airway/ventilation → definitive airway control with RSI.", "source": "NICE NG39, Major trauma: assessment and initial management."},
  {"id": "MAK-498", "subject": "Major trauma & fluids", "topic": "TENSION PNEUMOTHORAX", "title": "TENSION PNEUMOTHORAX", "stem": "A trauma patient develops severe respiratory compromise and haemodynamic instability with clinical features of tension pneumothorax. What should happen?", "options": {"A": "Wait for CT before decompression", "B": "Perform chest decompression before imaging", "C": "Give oral antibiotics only", "D": "Perform spirometry", "E": "Observe without intervention"}, "correct_letter": "B", "correct_answer": "B. Perform chest decompression before imaging", "why_correct": "NICE recommends chest decompression before imaging in tension pneumothorax when there is haemodynamic instability or severe respiratory compromise. In hospital, NICE recommends open thoracostomy followed by chest drain where appropriate expertise is available.", "exam_trap": "Do not delay life-saving decompression for imaging in an unstable patient.", "takeaway": "Tension physiology + instability/severe respiratory compromise → decompress before imaging.", "source": "NICE NG39."},
  {"id": "MAK-499", "subject": "Major trauma & fluids", "topic": "EXTERNAL HAEMORRHAGE", "title": "MAJOR TRAUMA: EXTERNAL HAEMORRHAGE", "stem": "A patient has life-threatening bleeding from a traumatic limb wound. Direct pressure fails to control the haemorrhage. What should be considered?", "options": {"A": "Tourniquet", "B": "Immediate plaster cast only", "C": "Observation", "D": "Oral iron", "E": "Compression stockings"}, "correct_letter": "A", "correct_answer": "A. Tourniquet", "why_correct": "NICE recommends a tourniquet for major limb trauma when direct pressure has failed to control life-threatening haemorrhage.", "exam_trap": "A tourniquet is not the first step for every minor bleeding wound; direct pressure is recommended initially.", "takeaway": "Life-threatening limb haemorrhage + failed direct pressure → tourniquet.", "source": "NICE NG39."},
  {"id": "MAK-500", "subject": "Major trauma & fluids", "topic": "TRANEXAMIC ACID", "title": "MAJOR TRAUMA: TRANEXAMIC ACID", "stem": "A patient has major trauma with active or suspected active bleeding. What does NICE recommend regarding intravenous tranexamic acid?", "options": {"A": "Give it as soon as possible", "B": "Give it only after 48 hours", "C": "Never use it in trauma", "D": "Give it only after definitive surgery", "E": "Give it only if the haemoglobin is normal"}, "correct_letter": "A", "correct_answer": "A. Give it as soon as possible", "why_correct": "NICE recommends intravenous tranexamic acid as soon as possible in patients with major trauma and active or suspected active bleeding. NICE also advises against giving it more than 3 hours after injury unless there is evidence of hyperfibrinolysis.", "exam_trap": "Do not interpret tranexamic acid as something that should be delayed until laboratory confirmation of bleeding.", "takeaway": "Major trauma + active/suspected bleeding → early IV tranexamic acid.", "source": "NICE NG39."},
  {"id": "MAK-501", "subject": "Major trauma & fluids", "topic": "PELVIC BLEEDING", "title": "MAJOR TRAUMA: PELVIC BLEEDING", "stem": "A patient sustains blunt high-energy pelvic trauma and active bleeding from a pelvic fracture is suspected. What immediate mechanical intervention is recommended?", "options": {"A": "Pelvic binder", "B": "Knee immobiliser", "C": "Cervical collar only", "D": "Abdominal massage", "E": "Immediate mobilisation"}, "correct_letter": "A", "correct_answer": "A. Pelvic binder", "why_correct": "NICE recommends applying a purpose-made pelvic binder when active bleeding is suspected from a pelvic fracture following blunt high-energy trauma.", "exam_trap": "The purpose is haemorrhage control, not simply immobilisation of every suspected pelvic fracture.", "takeaway": "High-energy pelvic trauma + suspected active bleeding → pelvic binder.", "source": "NICE NG39 and NG37."},
  {"id": "MAK-502", "subject": "Major trauma & fluids", "topic": "PELVIC FRACTURE AND INTERVENTIONAL RADIOLOGY", "title": "PELVIC FRACTURE AND INTERVENTIONAL RADIOLOGY", "stem": "A patient has active arterial pelvic haemorrhage but does not require immediate laparotomy for another abdominal injury. Which treatment is recommended as first-line invasive management?", "options": {"A": "Interventional radiology", "B": "Elective colonoscopy", "C": "Appendicectomy", "D": "ERCP", "E": "Nephrectomy"}, "correct_letter": "A", "correct_answer": "A. Interventional radiology", "why_correct": "NICE recommends interventional radiology for active arterial pelvic bleeding when emergency laparotomy is not required for abdominal injuries.", "exam_trap": "The presence of pelvic bleeding does not automatically mean laparotomy is the definitive haemorrhage-control procedure.", "takeaway": "Active arterial pelvic bleeding without need for laparotomy → interventional radiology.", "source": "NICE NG37/NG39."},
  {"id": "MAK-503", "subject": "Major trauma & fluids", "topic": "TRANSPORT DESTINATION", "title": "MAJOR TRAUMA: TRANSPORT DESTINATION", "stem": "Where should patients with major trauma usually be managed?", "options": {"A": "Major trauma centre", "B": "Any available outpatient clinic", "C": "Community pharmacy", "D": "Rehabilitation centre before assessment", "E": "GP surgery only"}, "correct_letter": "A", "correct_answer": "A. Major trauma centre", "why_correct": "NICE states that the optimal destination for patients with major trauma is usually a major trauma centre, although regional trauma-network arrangements may determine exceptions.", "exam_trap": "Do not interpret \"major trauma centre\" as meaning every patient must bypass all local emergency care regardless of circumstances.", "takeaway": "Major trauma → major trauma centre is generally the definitive trauma destination.", "source": "NICE NG39."},
  {"id": "MAK-504", "subject": "Major trauma & fluids", "topic": "WHOLE-BODY CT", "title": "MAJOR TRAUMA: WHOLE-BODY CT", "stem": "An adult has blunt major trauma with suspected multiple injuries and is haemodynamically suitable for CT. What imaging strategy does NICE recommend?", "options": {"A": "Whole-body CT", "B": "MRI of every body region", "C": "Ultrasound only", "D": "Plain radiographs only", "E": "No imaging"}, "correct_letter": "A", "correct_answer": "A. Whole-body CT", "why_correct": "NICE recommends whole-body CT in adults aged 16 or over with blunt major trauma and suspected multiple injuries.", "exam_trap": "The recommendation is for the specified major-trauma population; it should not be extrapolated to every minor trauma presentation.", "takeaway": "Adult blunt major trauma + suspected multiple injuries → whole-body CT when appropriate.", "source": "NICE NG39/NG37."},
  {"id": "MAK-505", "subject": "Major trauma & fluids", "topic": "NEGATIVE FAST", "title": "MAJOR TRAUMA: NEGATIVE FAST", "stem": "A haemodynamically stable trauma patient has a negative FAST scan. Which statement is correct?", "options": {"A": "A negative FAST excludes all intra-abdominal bleeding", "B": "A negative FAST excludes retroperitoneal bleeding", "C": "A negative FAST does not exclude intra-abdominal or retroperitoneal haemorrhage", "D": "No further assessment is ever required", "E": "The patient must have no significant injury"}, "correct_letter": "C", "correct_answer": "C. A negative FAST does not exclude intra-abdominal or retroperitoneal haemorrhage", "why_correct": "NICE explicitly states that a negative FAST does not exclude intraperitoneal or retroperitoneal haemorrhage.", "exam_trap": "FAST is not a universal rule-out test for haemorrhage.", "takeaway": "Negative FAST ≠ no bleeding.", "source": "NICE NG39."},
  {"id": "MAK-506", "subject": "Major trauma & fluids", "topic": "DAMAGE CONTROL SURGERY", "title": "MAJOR TRAUMA: DAMAGE CONTROL SURGERY", "stem": "A patient with major trauma remains haemodynamically unstable despite volume resuscitation. Which surgical strategy does NICE recommend?", "options": {"A": "Damage control surgery", "B": "Elective definitive reconstruction only", "C": "Delay all surgery for 72 hours", "D": "Colonoscopy", "E": "No operative intervention"}, "correct_letter": "A", "correct_answer": "A. Damage control surgery", "why_correct": "NICE recommends damage control surgery in patients with haemodynamic instability who are not responding to volume resuscitation.", "exam_trap": "The aim is rapid control of life-threatening injury rather than prolonged definitive reconstruction in a physiologically unstable patient.", "takeaway": "Unstable despite resuscitation → damage control rather than prolonged definitive surgery.", "source": "NICE NG39."},
  {"id": "MAK-507", "subject": "Major trauma & fluids", "topic": "DEFINITIVE SURGERY", "title": "MAJOR TRAUMA: DEFINITIVE SURGERY", "stem": "A patient with major trauma has a normal haemodynamic status. Which surgical approach is recommended when surgery is required?", "options": {"A": "Definitive surgery", "B": "Damage control surgery in every case", "C": "No surgery under any circumstances", "D": "Diagnostic colonoscopy", "E": "Immediate transfer to rehabilitation"}, "correct_letter": "A", "correct_answer": "A. Definitive surgery", "why_correct": "NICE recommends definitive surgery for patients whose haemodynamic status is normal.", "exam_trap": "Damage control is driven by physiological instability, not simply by the fact that the patient has multiple injuries.", "takeaway": "Stable physiology → definitive surgery can be undertaken when indicated.", "source": "NICE NG39."},
  {"id": "MAK-508", "subject": "Vascular & fracture complications", "topic": "COMPARTMENT SYNDROME", "title": "COMPARTMENT SYNDROME", "stem": "A patient with a high-energy limb injury develops severe escalating pain, particularly with passive stretch of the affected muscles. What diagnosis must be considered?", "options": {"A": "Acute compartment syndrome", "B": "Simple bruising", "C": "Chronic venous insufficiency", "D": "Cellulitis only", "E": "Osteoarthritis"}, "correct_letter": "A", "correct_answer": "A. Acute compartment syndrome", "why_correct": "Acute compartment syndrome is caused by increased pressure within a closed fascial compartment, compromising tissue perfusion. Severe pain, particularly pain on passive stretch, is an important clinical warning sign.", "exam_trap": "Do not wait for absent pulses before considering compartment syndrome.", "takeaway": "Severe escalating pain + pain on passive stretch after limb trauma → compartment syndrome until excluded.", "source": "NICE NG37, Complex fractures: assessment and management."},
  {"id": "MAK-509", "subject": "Vascular & fracture complications", "topic": "OPEN FRACTURE", "title": "OPEN FRACTURE", "stem": "A patient sustains an open long-bone fracture. Which management principle is important?", "options": {"A": "Delay antibiotics until definitive surgery", "B": "Give prophylactic antibiotics as soon as possible", "C": "Close the wound immediately in the emergency department regardless of contamination", "D": "Ignore the soft-tissue injury", "E": "Treat only with oral analgesia"}, "correct_letter": "B", "correct_answer": "B. Give prophylactic antibiotics as soon as possible", "why_correct": "NICE recommends prophylactic antibiotic treatment for open fractures as soon as possible, preferably within 1 hour of injury.", "exam_trap": "Open fractures are contaminated injuries and require coordinated management of both bone and soft tissue.", "takeaway": "Open fracture → early antibiotics + urgent specialist orthoplastic management.", "source": "NICE NG37/NG40."},
  {"id": "MAK-510", "subject": "Major trauma & fluids", "topic": "ACTIVE BLEEDING AND FLUIDS", "title": "MAJOR TRAUMA: ACTIVE BLEEDING AND FLUIDS", "stem": "A patient with major trauma has active bleeding. Which approach is consistent with NICE hospital guidance?", "options": {"A": "Large-volume crystalloid replacement as the sole strategy", "B": "Rapid haemorrhage control with restrictive volume resuscitation", "C": "Delay haemorrhage control until normal haemoglobin is achieved", "D": "Give only oral fluids", "E": "Wait for CT before treating haemorrhage"}, "correct_letter": "B", "correct_answer": "B. Rapid haemorrhage control with restrictive volume resuscitation", "why_correct": "NICE recommends a restrictive approach to volume resuscitation in active bleeding until definitive early control of bleeding is achieved. In hospital, NICE advises against using crystalloids for patients with active bleeding and recommends blood-component-based resuscitation.", "exam_trap": "The goal is not to normalise the blood pressure with large volumes before haemorrhage control.", "takeaway": "Major haemorrhage → control bleeding early + avoid unnecessary crystalloid loading.", "source": "NICE NG39, Major trauma: assessment and initial management."},
  {"id": "MAK-511", "subject": "Perioperative medicine & nutrition", "topic": "PREOPERATIVE CHEST X-RAY", "title": "PREOPERATIVE CHEST X-RAY", "stem": "A healthy 45-year-old patient is scheduled for uncomplicated elective surgery. There are no respiratory or cardiac symptoms. Which statement about routine preoperative chest X-ray is correct?", "options": {"A": "It should be performed in every patient", "B": "It should routinely replace clinical assessment", "C": "It should not be routinely offered", "D": "It is mandatory before general anaesthesia", "E": "It is required before every abdominal operation"}, "correct_letter": "C", "correct_answer": "C. It should not be routinely offered", "why_correct": "NICE recommends against routine preoperative chest X-rays. Testing should be guided by the patient's clinical circumstances and type of surgery.", "exam_trap": "\"General anaesthesia\" does not automatically mean \"routine chest X-ray.\"", "takeaway": "Routine elective surgery ≠ routine chest X-ray.", "source": "NICE NG45, Routine preoperative tests for elective surgery."},
  {"id": "MAK-512", "subject": "Perioperative medicine & nutrition", "topic": "PREOPERATIVE ECHOCARDIOGRAPHY", "title": "PREOPERATIVE ECHOCARDIOGRAPHY", "stem": "A patient is being assessed before surgery and has a cardiac murmur associated with exertional breathlessness. What investigation may be appropriate?", "options": {"A": "Routine chest X-ray only", "B": "Resting echocardiography", "C": "Colonoscopy", "D": "Abdominal ultrasound", "E": "D-dimer"}, "correct_letter": "B", "correct_answer": "B. Resting echocardiography", "why_correct": "NICE recommends considering resting echocardiography in a patient with a heart murmur plus cardiac symptoms such as breathlessness, syncope or chest pain, or with signs or symptoms of heart failure.", "exam_trap": "Echocardiography is not routinely indicated before surgery in an otherwise asymptomatic patient.", "takeaway": "Murmur + cardiac symptoms → consider echo.", "source": "NICE NG45."},
  {"id": "MAK-513", "subject": "Perioperative medicine & nutrition", "topic": "PREOPERATIVE ECG", "title": "PREOPERATIVE ECG", "stem": "A 70-year-old patient with ASA grade 2 status is being assessed before major surgery. Which investigation is NICE guidance consistent with offering?", "options": {"A": "ECG", "B": "Routine chest X-ray only", "C": "Routine echocardiogram in every patient", "D": "Routine arterial blood gas", "E": "Routine spirometry"}, "correct_letter": "A", "correct_answer": "A. ECG", "why_correct": "NICE recommends an ECG for people having major or complex surgery who are ASA grade 2 or 3/4. For ASA 1 patients aged over 65, ECG should be considered if there is no ECG result from the previous 12 months.", "exam_trap": "Preoperative testing depends on the operation and patient risk rather than age alone.", "takeaway": "Major surgery + significant comorbidity → targeted preoperative ECG is appropriate.", "source": "NICE NG45."},
  {"id": "MAK-514", "subject": "Perioperative medicine & nutrition", "topic": "PREOPERATIVE HbA1c", "title": "PREOPERATIVE HbA1c", "stem": "A patient with diabetes is being assessed for elective surgery. Their HbA1c was last measured 8 months ago. What does NICE recommend?", "options": {"A": "No further HbA1c measurement is ever required", "B": "Offer HbA1c testing", "C": "Perform an oral glucose tolerance test instead", "D": "Perform a glucose tolerance test immediately before anaesthesia", "E": "Cancel all surgery permanently"}, "correct_letter": "B", "correct_answer": "B. Offer HbA1c testing", "why_correct": "NICE recommends offering HbA1c testing to people with diabetes having surgery if they have not been tested within the previous 3 months.", "exam_trap": "Do not confuse HbA1c assessment with an acute glucose measurement.", "takeaway": "Diabetes + surgery + no HbA1c within 3 months → offer HbA1c.", "source": "NICE NG45."},
  {"id": "MAK-515", "subject": "Perioperative medicine & nutrition", "topic": "PREOPERATIVE URINE TESTING", "title": "PREOPERATIVE URINE TESTING", "stem": "A patient without urinary symptoms is undergoing elective surgery. Which statement about routine urine dipstick testing is correct?", "options": {"A": "It is mandatory", "B": "It should routinely be performed", "C": "It should not routinely be offered", "D": "It replaces clinical assessment for UTI", "E": "It is required before every operation"}, "correct_letter": "C", "correct_answer": "C. It should not routinely be offered", "why_correct": "NICE recommends against routine urine dipstick testing before surgery. Urine microscopy and culture may be considered when the presence of a UTI would influence the decision to operate.", "exam_trap": "Routine screening for asymptomatic bacteriuria is not the same as investigating suspected UTI.", "takeaway": "No urinary indication → no routine preoperative urine dipstick.", "source": "NICE NG45."},
  {"id": "MAK-516", "subject": "Perioperative medicine & nutrition", "topic": "PREGNANCY AND ELECTIVE SURGERY", "title": "PREGNANCY AND ELECTIVE SURGERY", "stem": "A woman of childbearing potential is due to undergo surgery. What should happen on the day of surgery?", "options": {"A": "Pregnancy status should never be discussed", "B": "She should sensitively be asked whether there is any possibility she could be pregnant", "C": "Pregnancy testing is mandatory regardless of circumstances", "D": "Surgery must automatically be cancelled", "E": "Only the patient's partner should be asked"}, "correct_letter": "B", "correct_answer": "B. She should sensitively be asked whether there is any possibility she could be pregnant", "why_correct": "NICE recommends sensitively asking women of childbearing potential on the day of surgery whether there is any possibility of pregnancy and discussing fetal risks of anaesthesia and the procedure where relevant.", "exam_trap": "Asking about pregnancy is not equivalent to automatically performing a pregnancy test.", "takeaway": "Before surgery → sensitively establish whether pregnancy is possible and discuss testing appropriately.", "source": "NICE NG45."},
  {"id": "MAK-517", "subject": "Perioperative medicine & nutrition", "topic": "PREOPERATIVE ANAEMIA", "title": "PREOPERATIVE ANAEMIA", "stem": "A patient scheduled for major elective surgery is found to have iron-deficiency anaemia. Which principle is most appropriate?", "options": {"A": "Ignore it because surgery is already booked", "B": "Identify and manage the anaemia where appropriate before surgery", "C": "Give erythropoietin routinely to every surgical patient", "D": "Transfuse every anaemic patient immediately", "E": "Cancel all future surgery"}, "correct_letter": "B", "correct_answer": "B. Identify and manage the anaemia where appropriate before surgery", "why_correct": "Preoperative anaemia is associated with poorer postoperative outcomes and should prompt assessment and appropriate management. NICE recommends oral iron for iron-deficiency anaemia before and after surgery, with IV iron considered in selected circumstances.", "exam_trap": "Preoperative anaemia does not automatically mean preoperative blood transfusion.", "takeaway": "Elective surgery + anaemia → diagnose the cause and optimise where possible.", "source": "NICE NG24."},
  {"id": "MAK-518", "subject": "Perioperative medicine & nutrition", "topic": "TRANEXAMIC ACID IN SURGERY", "title": "TRANEXAMIC ACID IN SURGERY", "stem": "An adult is undergoing major surgery where expected blood loss is greater than 500 mL. Which treatment should be considered?", "options": {"A": "Tranexamic acid", "B": "Routine recombinant factor VIIa", "C": "Routine platelet transfusion", "D": "Routine FFP", "E": "No blood-conservation strategy"}, "correct_letter": "A", "correct_answer": "A. Tranexamic acid", "why_correct": "NICE recommends offering tranexamic acid to adults undergoing surgery where at least moderate blood loss, defined in the guideline as greater than 500 mL, is expected.", "exam_trap": "Tranexamic acid is an antifibrinolytic; it is not a replacement for surgical haemostasis.", "takeaway": "Expected moderate/major surgical blood loss → consider early TXA.", "source": "NICE NG24."},
  {"id": "MAK-519", "subject": "Perioperative medicine & nutrition", "topic": "CELL SALVAGE", "title": "CELL SALVAGE", "stem": "A patient is expected to lose a very large volume of blood during complex surgery. Which blood-conservation strategy may be considered?", "options": {"A": "Intraoperative cell salvage with tranexamic acid", "B": "Routine cell salvage alone in every operation", "C": "No blood-conservation strategy", "D": "Routine FFP before incision", "E": "Routine platelet transfusion before surgery"}, "correct_letter": "A", "correct_answer": "A. Intraoperative cell salvage with tranexamic acid", "why_correct": "NICE recommends considering intraoperative cell salvage with tranexamic acid when very high blood loss is expected.", "exam_trap": "Cell salvage is not routinely required for every operation.", "takeaway": "Very high expected blood loss → consider cell salvage + TXA.", "source": "NICE NG24."},
  {"id": "MAK-520", "subject": "Microbiology & surgical infection", "topic": "HAIR REMOVAL", "title": "SURGICAL SITE INFECTION: HAIR REMOVAL", "stem": "Hair needs to be removed from the operative field before surgery. Which method is recommended?", "options": {"A": "Razor shaving several days beforehand", "B": "Electric clippers with a single-use head on the day of surgery", "C": "Chemical depilation in every patient", "D": "Routine waxing", "E": "No consideration of timing"}, "correct_letter": "B", "correct_answer": "B. Electric clippers with a single-use head on the day of surgery", "why_correct": "NICE advises against routine hair removal. If hair must be removed, electric clippers with a single-use head should be used on the day of surgery. Razors increase SSI risk.", "exam_trap": "The correct answer is not \"shave the night before.\"", "takeaway": "Hair removal only when necessary → clippers, on the day, not a razor.", "source": "NICE NG125, Surgical site infections."},
  {"id": "MAK-521", "subject": "Microbiology & surgical infection", "topic": "SKIN PREPARATION", "title": "SURGICAL SITE INFECTION: SKIN PREPARATION", "stem": "During preparation of the surgical site with an alcohol-based antiseptic, diathermy will be used. What is important?", "options": {"A": "Allow the preparation to pool beneath the patient", "B": "Allow the preparation to dry by evaporation and avoid pooling", "C": "Ignite the solution deliberately", "D": "Cover the wet solution with a drape immediately", "E": "Apply additional alcohol during diathermy"}, "correct_letter": "B", "correct_answer": "B. Allow the preparation to dry by evaporation and avoid pooling", "why_correct": "NICE specifically advises allowing antiseptic skin preparations to dry by evaporation and avoiding pooling of alcohol-based preparations when diathermy is used.", "exam_trap": "A wet alcohol-based preparation plus an ignition source creates a fire hazard.", "takeaway": "Alcohol-based skin prep + diathermy → dry completely and prevent pooling.", "source": "NICE NG125."},
  {"id": "MAK-522", "subject": "Microbiology & surgical infection", "topic": "OXYGENATION", "title": "SURGICAL SITE INFECTION: OXYGENATION", "stem": "Which perioperative measure is recommended by NICE to reduce factors associated with surgical site infection?", "options": {"A": "Deliberately reduce oxygen saturation", "B": "Maintain adequate oxygenation, particularly during major surgery and recovery", "C": "Avoid oxygen completely", "D": "Use hyperglycaemia deliberately", "E": "Allow hypothermia"}, "correct_letter": "B", "correct_answer": "B. Maintain adequate oxygenation, particularly during major surgery and recovery", "why_correct": "NICE recommends maintaining optimal oxygenation during surgery and sufficient oxygen during major surgery and recovery to maintain haemoglobin saturation above 95%.", "exam_trap": "Oxygenation is part of maintaining physiological homeostasis; it is not a substitute for antibiotics or sterile technique.", "takeaway": "SSI prevention includes maintaining oxygenation, perfusion and temperature.", "source": "NICE NG125."},
  {"id": "MAK-523", "subject": "Microbiology & surgical infection", "topic": "WOUND IRRIGATION", "title": "SURGICAL SITE INFECTION: WOUND IRRIGATION", "stem": "Which statement about routine wound irrigation to prevent surgical site infection is correct?", "options": {"A": "It should always be performed", "B": "It is mandatory after every contaminated operation", "C": "NICE does not recommend wound irrigation specifically to reduce SSI", "D": "It replaces antibiotic prophylaxis", "E": "It replaces skin antisepsis"}, "correct_letter": "C", "correct_answer": "C. NICE does not recommend wound irrigation specifically to reduce SSI", "why_correct": "NICE recommends against using wound irrigation specifically to reduce the risk of surgical site infection.", "exam_trap": "Irrigation may have other clinical roles; this question asks specifically about routine SSI prevention.", "takeaway": "Do not confuse \"may be used clinically\" with \"recommended routinely to prevent SSI.\"", "source": "NICE NG125."},
  {"id": "MAK-524", "subject": "Microbiology & surgical infection", "topic": "INTRACAVITY LAVAGE", "title": "SURGICAL SITE INFECTION: INTRACAVITY LAVAGE", "stem": "Which statement is consistent with NICE guidance regarding intracavity lavage?", "options": {"A": "It should routinely be used to prevent SSI", "B": "It should replace antibiotic prophylaxis", "C": "It should not be used specifically to reduce SSI risk", "D": "It is mandatory after every abdominal operation", "E": "It is required after every anastomosis"}, "correct_letter": "C", "correct_answer": "C. It should not be used specifically to reduce SSI risk", "why_correct": "NICE advises against intracavity lavage for the specific purpose of reducing surgical site infection.", "exam_trap": "Do not confuse lavage with source control of an established intra-abdominal infection.", "takeaway": "Established contamination/source control is different from routine lavage as SSI prevention.", "source": "NICE NG125."},
  {"id": "MAK-525", "subject": "Microbiology & surgical infection", "topic": "PATIENT TEMPERATURE", "title": "SURGICAL SITE INFECTION: PATIENT TEMPERATURE", "stem": "Which perioperative physiological abnormality should be actively avoided because NICE recommends maintaining patient temperature appropriately?", "options": {"A": "Hypothermia", "B": "Normothermia", "C": "Normal oxygenation", "D": "Adequate perfusion", "E": "Appropriate glucose management"}, "correct_letter": "A", "correct_answer": "A. Hypothermia", "why_correct": "NICE recommends maintaining patient temperature in line with its guidance on prevention and management of hypothermia during surgery.", "exam_trap": "Do not think of temperature as an anaesthetic issue only; maintaining physiological homeostasis is part of SSI prevention.", "takeaway": "During surgery → maintain normothermia.", "source": "NICE NG125."},
  {"id": "MAK-526", "subject": "Microbiology & surgical infection", "topic": "BLOOD GLUCOSE", "title": "SURGICAL SITE INFECTION: BLOOD GLUCOSE", "stem": "Which statement is correct regarding insulin in patients without diabetes undergoing surgery?", "options": {"A": "Routine insulin should be given to all patients to prevent SSI", "B": "Insulin should never be used under any circumstances", "C": "NICE does not recommend routine insulin in people without diabetes solely to optimise postoperative glucose and reduce SSI", "D": "Hyperglycaemia should deliberately be induced", "E": "Glucose monitoring is prohibited"}, "correct_letter": "C", "correct_answer": "C. NICE does not recommend routine insulin in people without diabetes solely to optimise postoperative glucose and reduce SSI", "why_correct": "NICE specifically advises against routinely giving insulin to patients without diabetes for this purpose.", "exam_trap": "This does not mean clinically significant hyperglycaemia should be ignored.", "takeaway": "Do not give routine insulin to non-diabetic surgical patients solely as an SSI-prevention strategy.", "source": "NICE NG125."},
  {"id": "MAK-527", "subject": "Perioperative medicine & nutrition", "topic": "VTE RISK ASSESSMENT", "title": "VTE RISK ASSESSMENT", "stem": "A patient is admitted for emergency abdominal surgery. What should happen regarding VTE risk?", "options": {"A": "VTE risk is assessed only after discharge", "B": "VTE and bleeding risk should be assessed as soon as possible", "C": "Only age determines prophylaxis", "D": "Bleeding risk can be ignored", "E": "Every patient automatically receives anticoagulation"}, "correct_letter": "B", "correct_answer": "B. VTE and bleeding risk should be assessed as soon as possible", "why_correct": "NICE recommends assessing all surgical and trauma patients for VTE and bleeding risk as soon as possible after admission or by first consultant review.", "exam_trap": "VTE prophylaxis is not simply \"give LMWH to everyone.\"", "takeaway": "Every surgical admission → assess both thrombosis and bleeding risk.", "source": "NICE NG89, VTE prevention."},
  {"id": "MAK-528", "subject": "Perioperative medicine & nutrition", "topic": "VTE PROPHYLAXIS AND BLEEDING RISK", "title": "VTE PROPHYLAXIS AND BLEEDING RISK", "stem": "A surgical patient has a very high bleeding risk and a relatively low VTE risk. What principle should guide prophylaxis?", "options": {"A": "Give pharmacological prophylaxis regardless", "B": "Balance VTE risk against bleeding risk", "C": "Never use any prophylaxis", "D": "Give therapeutic anticoagulation", "E": "Give thrombolysis"}, "correct_letter": "B", "correct_answer": "B. Balance VTE risk against bleeding risk", "why_correct": "NICE specifically recommends balancing individual VTE risk against bleeding risk when deciding whether to use pharmacological prophylaxis.", "exam_trap": "\"High-risk operation\" does not automatically mean pharmacological prophylaxis is appropriate immediately.", "takeaway": "VTE prevention = thrombosis risk versus bleeding risk.", "source": "NICE NG89."},
  {"id": "MAK-529", "subject": "Perioperative medicine & nutrition", "topic": "MECHANICAL VTE PROPHYLAXIS", "title": "ABDOMINAL SURGERY: MECHANICAL VTE PROPHYLAXIS", "stem": "A patient is admitted for abdominal surgery and is at increased risk of VTE. Which mechanical prophylaxis should be started?", "options": {"A": "On admission", "B": "Only after discharge", "C": "Six weeks after surgery", "D": "Only after a DVT develops", "E": "Only if the patient becomes hypotensive"}, "correct_letter": "A", "correct_answer": "A. On admission", "why_correct": "NICE recommends mechanical VTE prophylaxis on admission for people undergoing abdominal surgery. Options include anti-embolism stockings or intermittent pneumatic compression, according to the patient's circumstances.", "exam_trap": "Do not wait for surgery to finish before considering mechanical prophylaxis.", "takeaway": "Abdominal surgery + increased VTE risk → mechanical prophylaxis from admission.", "source": "NICE NG89."},
  {"id": "MAK-530", "subject": "Perioperative medicine & nutrition", "topic": "MAJOR ABDOMINAL CANCER SURGERY", "title": "MAJOR ABDOMINAL CANCER SURGERY", "stem": "A patient undergoes major abdominal cancer surgery. The risk of VTE remains significant after discharge. What duration of pharmacological prophylaxis should be considered?", "options": {"A": "24 hours only", "B": "3 days", "C": "7 days only in every case", "D": "Up to 28 days postoperatively", "E": "Lifelong anticoagulation in every patient"}, "correct_letter": "D", "correct_answer": "D. Up to 28 days postoperatively", "why_correct": "NICE recommends considering extending pharmacological VTE prophylaxis to 28 days after major cancer surgery in the abdomen.", "exam_trap": "This is an extended prophylaxis recommendation, not therapeutic anticoagulation for established VTE.", "takeaway": "Major abdominal cancer surgery → consider extended prophylaxis to 28 days.", "source": "NICE NG89."},
  {"id": "MAK-531", "subject": "Perioperative medicine & nutrition", "topic": "EARLY MOBILISATION", "title": "EARLY MOBILISATION", "stem": "A postoperative patient is medically stable. Which intervention is an important general measure for reducing hospital-associated VTE risk?", "options": {"A": "Prolonged bed rest", "B": "Mobilise as soon as possible", "C": "Avoid all oral fluids", "D": "Keep the patient fasting indefinitely", "E": "Routine therapeutic anticoagulation"}, "correct_letter": "B", "correct_answer": "B. Mobilise as soon as possible", "why_correct": "NICE advises encouraging patients to mobilise as soon as possible and avoiding dehydration unless clinically indicated.", "exam_trap": "Mobilisation complements rather than automatically replaces indicated pharmacological or mechanical prophylaxis.", "takeaway": "Postoperative care → mobilise early and maintain appropriate hydration.", "source": "NICE NG89."},
  {"id": "MAK-532", "subject": "Perioperative medicine & nutrition", "topic": "ELECTIVE SURGERY AND OESTROGEN", "title": "ELECTIVE SURGERY AND OESTROGEN", "stem": "A patient taking an oestrogen-containing combined oral contraceptive is planning elective surgery. What does NICE advise?", "options": {"A": "Automatically continue it without assessment", "B": "Consider stopping it 4 weeks before elective surgery and provide alternative contraception if stopped", "C": "Stop it permanently", "D": "Replace it with therapeutic anticoagulation", "E": "Stop it only after surgery"}, "correct_letter": "B", "correct_answer": "B. Consider stopping it 4 weeks before elective surgery and provide alternative contraception if stopped", "why_correct": "NICE advises people to consider stopping oestrogen-containing oral contraceptives or HRT 4 weeks before elective surgery, with alternative contraception advice where appropriate.", "exam_trap": "This is a risk-management recommendation, not an instruction to permanently discontinue hormonal therapy.", "takeaway": "Oestrogen-containing therapy + elective surgery → consider VTE implications and the 4-week recommendation.", "source": "NICE NG89."},
  {"id": "MAK-533", "subject": "Perioperative medicine & nutrition", "topic": "SPINAL SURGERY AND VTE", "title": "SPINAL SURGERY AND VTE", "stem": "A patient undergoes elective spinal surgery. Which mechanical prophylaxis is recommended on admission?", "options": {"A": "Anti-embolism stockings or intermittent pneumatic compression", "B": "Therapeutic-dose anticoagulation in every patient", "C": "Thrombolysis", "D": "No prophylaxis under any circumstances", "E": "Aspirin in every patient regardless of risk"}, "correct_letter": "A", "correct_answer": "A. Anti-embolism stockings or intermittent pneumatic compression", "why_correct": "NICE recommends mechanical VTE prophylaxis on admission for elective spinal surgery. Pharmacological prophylaxis requires consideration of VTE risk, bleeding risk and surgical factors.", "exam_trap": "Spinal surgery has particular bleeding consequences, so prophylaxis must be individualised.", "takeaway": "Elective spinal surgery → mechanical prophylaxis on admission; pharmacological prophylaxis is risk-dependent.", "source": "NICE NG89."},
  {"id": "MAK-534", "subject": "Perioperative medicine & nutrition", "topic": "CRANIAL SURGERY AND ANTICOAGULATION", "title": "CRANIAL SURGERY AND ANTICOAGULATION", "stem": "A patient has undergone cranial surgery. When pharmacological VTE prophylaxis is appropriate, when does NICE generally recommend starting LMWH?", "options": {"A": "Immediately before skin incision in every patient", "B": "24–48 hours after surgery", "C": "One week before surgery", "D": "Only after discharge", "E": "Only after a confirmed DVT"}, "correct_letter": "B", "correct_answer": "B. 24–48 hours after surgery", "why_correct": "NICE recommends considering LMWH 24–48 hours after cranial surgery when VTE risk outweighs bleeding risk, with duration determined according to the guideline.", "exam_trap": "Intracranial bleeding risk means pharmacological prophylaxis cannot simply be treated like routine abdominal surgery.", "takeaway": "Cranial surgery → mechanical prophylaxis early; LMWH requires careful bleeding-risk assessment.", "source": "NICE NG89."},
  {"id": "MAK-535", "subject": "Perioperative medicine & nutrition", "topic": "INTRACRANIAL HAEMORRHAGE AND VTE PROPHYLAXIS", "title": "INTRACRANIAL HAEMORRHAGE AND VTE PROPHYLAXIS", "stem": "A patient has an intracranial haemorrhage. What is the appropriate principle regarding pharmacological VTE prophylaxis?", "options": {"A": "Give LMWH immediately to everyone", "B": "Do not offer pharmacological prophylaxis until the lesion has been secured or the condition has stabilised", "C": "Give therapeutic anticoagulation", "D": "Give thrombolysis", "E": "Give warfarin immediately"}, "correct_letter": "B", "correct_answer": "B. Do not offer pharmacological prophylaxis until the lesion has been secured or the condition has stabilised", "why_correct": "NICE specifically advises against pharmacological VTE prophylaxis in intracranial haemorrhage until the lesion has been secured or the condition has stabilised.", "exam_trap": "A high VTE risk does not override an uncontrolled intracranial bleeding risk.", "takeaway": "Intracranial haemorrhage → stabilise/secure bleeding before pharmacological VTE prophylaxis.", "source": "NICE NG89."},
  {"id": "MAK-536", "subject": "Cardiorespiratory physiology", "topic": "CAPNOGRAPHY", "title": "ANAESTHETIC MONITORING: CAPNOGRAPHY", "stem": "During general anaesthesia, which monitoring method provides continuous information about exhaled carbon dioxide?", "options": {"A": "Pulse oximetry", "B": "Capnography", "C": "ECG", "D": "Non-invasive blood pressure", "E": "Temperature probe"}, "correct_letter": "B", "correct_answer": "B. Capnography", "why_correct": "Capnography measures exhaled CO₂ and provides information about ventilation and airway integrity.", "exam_trap": "Pulse oximetry assesses oxygenation, not ventilation directly.", "takeaway": "SpO₂ = oxygenation. Capnography = ventilation/expired CO₂.", "source": "Standard MRCS anaesthesia and physiology knowledge."},
  {"id": "MAK-537", "subject": "Cardiorespiratory physiology", "topic": "END-TIDAL CO₂ AND INTUBATION", "title": "END-TIDAL CO₂ AND INTUBATION", "stem": "Immediately after attempted tracheal intubation, which monitoring finding provides strong evidence that the tube is in the trachea and that pulmonary gas exchange is occurring?", "options": {"A": "Persistent waveform capnography", "B": "Pulse rate alone", "C": "Blood pressure alone", "D": "Skin colour alone", "E": "Chest X-ray before any ventilation"}, "correct_letter": "A", "correct_answer": "A. Persistent waveform capnography", "why_correct": "Continuous waveform capnography provides objective confirmation of exhaled CO₂ and is an essential method for confirming tracheal intubation in an appropriately ventilated patient.", "exam_trap": "Chest movement and auscultation are useful but should not replace objective capnography.", "takeaway": "After intubation → confirm and continuously monitor with waveform capnography.", "source": "[AoA]: guidelines for capnography."},
  {"id": "MAK-538", "subject": "Cardiorespiratory physiology", "topic": "PULSE OXIMETRY LIMITATION", "title": "PULSE OXIMETRY LIMITATION", "stem": "A patient receiving supplemental oxygen has a normal oxygen saturation but is becoming progressively drowsy and hypoventilating. Which statement is correct?", "options": {"A": "Normal SpO₂ excludes ventilatory failure", "B": "Pulse oximetry directly measures PaCO₂", "C": "Hypercapnia can occur despite apparently normal SpO₂", "D": "SpO₂ measures cardiac output", "E": "Capnography is irrelevant"}, "correct_letter": "C", "correct_answer": "C. Hypercapnia can occur despite apparently normal SpO₂", "why_correct": "Supplemental oxygen can maintain oxygen saturation despite inadequate ventilation and rising CO₂.", "exam_trap": "Oxygenation and ventilation are different physiological variables.", "takeaway": "Normal SpO₂ does not guarantee adequate ventilation.", "source": "Standard MRCS anaesthesia and respiratory physiology knowledge."},
  {"id": "MAK-539", "subject": "Pharmacology", "topic": "MALIGNANT HYPERTHERMIA", "title": "MALIGNANT HYPERTHERMIA", "stem": "During general anaesthesia, a patient develops rapidly increasing end-tidal CO₂, tachycardia, muscle rigidity and rapidly rising temperature. What diagnosis should be suspected?", "options": {"A": "Malignant hyperthermia", "B": "Simple postoperative fever", "C": "Hypoglycaemia", "D": "Pulmonary embolism alone", "E": "Acute appendicitis"}, "correct_letter": "A", "correct_answer": "A. Malignant hyperthermia", "why_correct": "Rapidly increasing CO₂ production, tachycardia, muscle rigidity and hyperthermia during anaesthesia are classic warning features of malignant hyperthermia.", "exam_trap": "The earliest and most important clue may be rapidly rising end-tidal CO₂ rather than fever.", "takeaway": "Anaesthesia + rising ETCO₂ + rigidity + hyperthermia → malignant hyperthermia emergency.", "source": "Standard MRCS anaesthesia knowledge."},
  {"id": "MAK-540", "subject": "Pharmacology", "topic": "TRIGGER", "title": "MALIGNANT HYPERTHERMIA: TRIGGER", "stem": "Which class of anaesthetic drug is classically associated with triggering malignant hyperthermia?", "options": {"A": "Volatile inhalational anaesthetics", "B": "Local anaesthetics", "C": "Paracetamol", "D": "Opioids", "E": "Antibiotics"}, "correct_letter": "A", "correct_answer": "A. Volatile inhalational anaesthetics", "why_correct": "Volatile anaesthetic agents are established triggers of malignant hyperthermia. Succinylcholine is also a recognised trigger, although it is not an inhalational agent.", "exam_trap": "Do not confuse the triggering drugs with dantrolene, which is used in treatment.", "takeaway": "Malignant hyperthermia triggers → volatile anaesthetics and succinylcholine.", "source": "Standard MRCS anaesthesia knowledge."},
  {"id": "MAK-541", "subject": "Perioperative medicine & nutrition", "topic": "NEWS2 HIGH-RISK CATEGORY", "title": "SEPSIS: NEWS2 HIGH-RISK CATEGORY", "stem": "A 68-year-old patient with suspected infection has a NEWS2 score of 8. According to current NICE guidance, how should this patient be classified?", "options": {"A": "Very low risk of severe illness or death from sepsis", "B": "Low risk", "C": "Moderate risk", "D": "High risk", "E": "No sepsis risk can be assigned"}, "correct_letter": "D", "correct_answer": "D. High risk", "why_correct": "NICE defines a person aged 16 or over with suspected or confirmed infection and a NEWS2 score of 7 or above as being at high risk of severe illness or death from sepsis.", "exam_trap": "Do not use the older blanket \"all suspected sepsis = 1-hour antibiotics\" rule. Current NICE guidance stratifies antibiotic timing by risk.", "takeaway": "NEWS2 ≥7 + suspected infection → high-risk sepsis pathway.", "source": "NICE NG253, Suspected sepsis, current recommendations."},
  {"id": "MAK-542", "subject": "Perioperative medicine & nutrition", "topic": "MODERATE-RISK NEWS2", "title": "SEPSIS: MODERATE-RISK NEWS2", "stem": "A patient with suspected infection has a NEWS2 score of 5. There are no additional features suggesting a higher risk category. Which classification applies?", "options": {"A": "Very low risk", "B": "Low risk", "C": "Moderate risk", "D": "High risk", "E": "Sepsis cannot be assessed using NEWS2"}, "correct_letter": "C", "correct_answer": "C. Moderate risk", "why_correct": "NICE defines suspected or confirmed infection with NEWS2 of 5 or 6 as moderate risk, unless other clinical factors require management as a higher-risk patient.", "exam_trap": "NEWS2 is a risk-stratification tool, not a diagnosis of sepsis by itself.", "takeaway": "NEWS2 5–6 → moderate-risk pathway, subject to clinical judgement.", "source": "NICE NG253."},
  {"id": "MAK-543", "subject": "Perioperative medicine & nutrition", "topic": "HIGH-RISK ANTIBIOTIC TIMING", "title": "SEPSIS: HIGH-RISK ANTIBIOTIC TIMING", "stem": "A patient aged 16 or over is assessed in the emergency department with suspected infection and a NEWS2 score of 8. No antibiotics have yet been given. When should broad-spectrum IV antibiotics be given according to NICE?", "options": {"A": "Within 1 hour of calculating the NEWS2 score", "B": "Within 6 hours", "C": "After microbiology results return", "D": "The following day", "E": "Only if the patient becomes hypotensive"}, "correct_letter": "A", "correct_answer": "A. Within 1 hour of calculating the NEWS2 score", "why_correct": "For adults at high risk of severe illness or death from sepsis, NICE recommends broad-spectrum IV antibiotics within 1 hour of calculating the initial NEWS2 score.", "exam_trap": "Do not wait for a positive blood culture before starting treatment in a high-risk patient.", "takeaway": "High-risk sepsis → IV broad-spectrum antibiotics within 1 hour.", "source": "NICE NG253."},
  {"id": "MAK-544", "subject": "Perioperative medicine & nutrition", "topic": "MODERATE-RISK ANTIBIOTIC TIMING", "title": "SEPSIS: MODERATE-RISK ANTIBIOTIC TIMING", "stem": "A patient with suspected infection has a NEWS2 score of 5 and is assessed as moderate risk. There is diagnostic uncertainty and no evidence of hypoperfusion. What does NICE allow the clinician to consider?", "options": {"A": "Deferring broad-spectrum antibiotics for up to 3 hours while clarifying the diagnosis", "B": "Automatically withholding antibiotics for 24 hours", "C": "Waiting for blood cultures to become positive", "D": "Giving antibiotics only after surgery", "E": "Never giving antibiotics"}, "correct_letter": "A", "correct_answer": "A. Deferring broad-spectrum antibiotics for up to 3 hours while clarifying the diagnosis", "why_correct": "For moderate-risk patients, NICE allows a clinician with appropriate acute-care competencies to consider deferring broad-spectrum antibiotics for up to 3 hours to gather information for a more specific diagnosis and discuss the case with a senior decision maker. Once the decision to give antibiotics is made, administration should not be delayed further.", "exam_trap": "The 3-hour period is a maximum timeframe, not a target to deliberately delay treatment.", "takeaway": "Moderate risk → diagnostic clarification may occur within the permitted window, but once antibiotics are indicated, give them promptly.", "source": "NICE NG253."},
  {"id": "MAK-545", "subject": "Perioperative medicine & nutrition", "topic": "LOW-RISK ANTIBIOTIC TIMING", "title": "SEPSIS: LOW-RISK ANTIBIOTIC TIMING", "stem": "A patient with suspected infection has a NEWS2 score of 3 and is assessed as low risk. What does NICE allow a clinician to consider?", "options": {"A": "Deferring broad-spectrum antibiotics for up to 6 hours while seeking a more specific diagnosis", "B": "Mandatory antibiotics within 15 minutes", "C": "Waiting several days", "D": "Antibiotics only if a blood culture is positive", "E": "No reassessment is required"}, "correct_letter": "A", "correct_answer": "A. Deferring broad-spectrum antibiotics for up to 6 hours while seeking a more specific diagnosis", "why_correct": "For adults assessed as low risk, NICE allows consideration of deferring broad-spectrum antibiotics for up to 6 hours while obtaining more diagnostic information. If antibiotics are decided upon, they should not then be delayed.", "exam_trap": "Low risk does not mean \"ignore the patient.\"", "takeaway": "Low-risk sepsis assessment → diagnostic clarification may be prioritised, with reassessment.", "source": "NICE NG253."},
  {"id": "MAK-546", "subject": "Perioperative medicine & nutrition", "topic": "LACTATE", "title": "SEPSIS: LACTATE", "stem": "A patient with suspected infection is assessed as moderate risk and has a venous lactate of 3.2 mmol/L. How should this affect management?", "options": {"A": "Treat as high risk", "B": "Discharge immediately", "C": "Ignore the lactate", "D": "Treat as very low risk", "E": "Diagnose chronic liver disease"}, "correct_letter": "A", "correct_answer": "A. Treat as high risk", "why_correct": "NICE states that a moderate-risk patient with evidence of hypoperfusion, such as lactate above 2 mmol/L or evidence of acute kidney injury, should be treated as high risk.", "exam_trap": "Do not interpret lactate merely as a marker of bacterial infection; it is a marker that may indicate impaired perfusion or other serious pathology.", "takeaway": "Moderate-risk sepsis + lactate >2 mmol/L → manage as high risk.", "source": "NICE NG253, amended 2025."},
  {"id": "MAK-547", "subject": "Perioperative medicine & nutrition", "topic": "BLOOD CULTURES", "title": "SEPSIS: BLOOD CULTURES", "stem": "A hospital patient has suspected sepsis and antibiotics are about to be administered. What does NICE recommend regarding microbiological sampling?", "options": {"A": "Take appropriate microbiological and blood samples before antimicrobials", "B": "Always wait for culture results before giving antibiotics", "C": "Do not take cultures", "D": "Take cultures only after antibiotic treatment has finished", "E": "Take only a urine sample in every patient"}, "correct_letter": "A", "correct_answer": "A. Take appropriate microbiological and blood samples before antimicrobials", "why_correct": "NICE recommends taking microbiological and blood samples before giving an antimicrobial when possible, while ensuring treatment is not inappropriately delayed in patients who require urgent antibiotics.", "exam_trap": "\"Take cultures first\" does not mean \"delay life-saving antibiotics.\"", "takeaway": "Cultures before antibiotics where feasible — but never create dangerous treatment delay.", "source": "NICE NG253."},
  {"id": "MAK-548", "subject": "Perioperative medicine & nutrition", "topic": "SOURCE CONTROL", "title": "SEPSIS: SOURCE CONTROL", "stem": "A patient has sepsis caused by an infected obstructed biliary system. Antibiotics are started, but the obstruction remains. What additional principle is essential?", "options": {"A": "Source identification and control", "B": "Stop all antibiotics immediately", "C": "Avoid intervention because antibiotics always provide definitive treatment", "D": "Give only antipyretics", "E": "Wait for the infection to resolve spontaneously"}, "correct_letter": "A", "correct_answer": "A. Source identification and control", "why_correct": "NICE sepsis guidance emphasises finding and controlling the source of infection. In an infected obstructed system, definitive treatment may require drainage or another source-control procedure.", "exam_trap": "Sepsis treatment is not synonymous with antibiotics alone.", "takeaway": "Sepsis = antimicrobial treatment + identify and control the source.", "source": "NICE NG253."},
  {"id": "MAK-549", "subject": "Perioperative medicine & nutrition", "topic": "RENAL REPLACEMENT THERAPY", "title": "AKI: RENAL REPLACEMENT THERAPY", "stem": "A patient with acute kidney injury develops persistent severe hyperkalaemia despite appropriate medical treatment. What should happen?", "options": {"A": "Immediately discuss renal replacement therapy", "B": "Give low-dose dopamine", "C": "Wait for spontaneous recovery", "D": "Stop monitoring potassium", "E": "Give routine loop diuretics solely to treat AKI"}, "correct_letter": "A", "correct_answer": "A. Immediately discuss renal replacement therapy", "why_correct": "NICE recommends immediate referral/discussion for renal replacement therapy when hyperkalaemia is not responding to medical management.", "exam_trap": "Dialysis is not initiated simply because creatinine is high; the clinical context and complications matter.", "takeaway": "AKI + refractory hyperkalaemia → urgent RRT discussion.", "source": "NICE NG148, Acute kidney injury."},
  {"id": "MAK-550", "subject": "Perioperative medicine & nutrition", "topic": "REFRACTORY ACIDOSIS", "title": "AKI: REFRACTORY ACIDOSIS", "stem": "A patient with AKI develops severe metabolic acidosis that does not respond to appropriate medical treatment. Which intervention should be considered urgently?", "options": {"A": "Renal replacement therapy", "B": "Routine low-dose dopamine", "C": "Stop all fluid assessment", "D": "Oral iron", "E": "Elective colonoscopy"}, "correct_letter": "A", "correct_answer": "A. Renal replacement therapy", "why_correct": "NICE lists metabolic acidosis that does not respond to medical management as an indication for immediate referral for renal replacement therapy.", "exam_trap": "Do not treat the bicarbonate number in isolation; consider the patient as a whole.", "takeaway": "AKI + refractory metabolic acidosis → urgent RRT assessment.", "source": "NICE NG148."},
  {"id": "MAK-551", "subject": "Perioperative medicine & nutrition", "topic": "URAEMIC COMPLICATIONS", "title": "AKI: URAEMIC COMPLICATIONS", "stem": "A patient with severe AKI develops uraemic pericarditis despite medical management. What is the appropriate next step?", "options": {"A": "Discuss urgent renal replacement therapy", "B": "Discharge home", "C": "Give routine dopamine", "D": "Ignore the uraemia", "E": "Give prophylactic antibiotics only"}, "correct_letter": "A", "correct_answer": "A. Discuss urgent renal replacement therapy", "why_correct": "NICE specifically lists symptoms or complications of uraemia, including pericarditis and encephalopathy, as indications for immediate RRT when not responding to medical treatment.", "exam_trap": "The indication is the clinically significant uraemic complication, not simply an isolated raised urea.", "takeaway": "AKI + uraemic complication → urgent RRT discussion.", "source": "NICE NG148."},
  {"id": "MAK-552", "subject": "Perioperative medicine & nutrition", "topic": "PULMONARY OEDEMA", "title": "AKI: PULMONARY OEDEMA", "stem": "A patient with AKI develops pulmonary oedema that does not respond adequately to medical treatment. What should be considered?", "options": {"A": "Renal replacement therapy", "B": "Routine dopamine", "C": "No intervention", "D": "Elective surgery", "E": "Oral fluid loading"}, "correct_letter": "A", "correct_answer": "A. Renal replacement therapy", "why_correct": "NICE lists fluid overload and pulmonary oedema that do not respond to medical management as indications for immediate RRT referral.", "exam_trap": "Do not use loop diuretics as a routine treatment for AKI itself.", "takeaway": "AKI + refractory pulmonary oedema → urgent RRT assessment.", "source": "NICE NG148."},
  {"id": "MAK-553", "subject": "Perioperative medicine & nutrition", "topic": "LOOP DIURETICS", "title": "AKI: LOOP DIURETICS", "stem": "Which statement about loop diuretics in acute kidney injury is correct?", "options": {"A": "They should routinely be given to reverse AKI", "B": "They should never be used in a patient with AKI", "C": "They may be considered for fluid overload/oedema in selected circumstances", "D": "They replace renal replacement therapy in all cases", "E": "They improve renal perfusion directly"}, "correct_letter": "C", "correct_answer": "C. They may be considered for fluid overload/oedema in selected circumstances", "why_correct": "NICE does not recommend routine loop diuretics to treat AKI itself. They may be considered for fluid overload or oedema while awaiting RRT or while renal function is recovering.", "exam_trap": "Diuresis is not the same as renal recovery.", "takeaway": "Loop diuretics treat selected fluid overload — they do not \"cure\" AKI.", "source": "NICE NG148."},
  {"id": "MAK-554", "subject": "Perioperative medicine & nutrition", "topic": "ISOLATED CREATININE", "title": "AKI: ISOLATED CREATININE", "stem": "A patient has AKI with a markedly elevated creatinine but no refractory hyperkalaemia, acidosis, uraemic complication, fluid overload or pulmonary oedema. Which statement is most accurate?", "options": {"A": "RRT is automatically required because of the creatinine value alone", "B": "RRT decisions should consider the whole clinical picture", "C": "Dialysis is mandatory whenever creatinine exceeds a fixed value", "D": "Creatinine is irrelevant", "E": "RRT should never be considered"}, "correct_letter": "B", "correct_answer": "B. RRT decisions should consider the whole clinical picture", "why_correct": "NICE explicitly advises basing the decision to start RRT on the overall condition rather than an isolated urea, creatinine or potassium value.", "exam_trap": "Avoid memorising a single creatinine number as a universal dialysis threshold.", "takeaway": "RRT is a clinical decision, not a creatinine-triggered reflex.", "source": "NICE NG148."},
  {"id": "MAK-555", "subject": "Perioperative medicine & nutrition", "topic": "REPOSITIONING", "title": "PRESSURE ULCER PREVENTION: REPOSITIONING", "stem": "A hospitalised adult is assessed as being at high risk of developing a pressure ulcer but can reposition independently. What should be encouraged?", "options": {"A": "Regular repositioning", "B": "Bed rest without repositioning", "C": "Skin rubbing every hour", "D": "Avoiding movement", "E": "Routine IV fluids regardless of hydration"}, "correct_letter": "A", "correct_answer": "A. Regular repositioning", "why_correct": "NICE recommends frequent repositioning for adults at risk of pressure ulcers. For those at high risk, repositioning should occur frequently, with a documented frequency and assistance where needed.", "exam_trap": "Pressure-ulcer prevention is not achieved by simply applying dressings to intact skin.", "takeaway": "Pressure-risk patient → regular repositioning + appropriate equipment.", "source": "NICE CG179, Pressure ulcers."},
  {"id": "MAK-556", "subject": "Perioperative medicine & nutrition", "topic": "SKIN MASSAGE", "title": "PRESSURE ULCERS: SKIN MASSAGE", "stem": "Which intervention should NOT be offered to adults specifically to prevent pressure ulcers?", "options": {"A": "Appropriate repositioning", "B": "Pressure-redistributing equipment", "C": "Skin massage or rubbing", "D": "Risk assessment", "E": "Appropriate nutritional assessment"}, "correct_letter": "C", "correct_answer": "C. Skin massage or rubbing", "why_correct": "NICE specifically recommends against skin massage or rubbing to prevent pressure ulcers.", "exam_trap": "Massage may feel intuitively helpful but can damage vulnerable tissue.", "takeaway": "Do not massage/rub pressure-prone skin as a prevention strategy.", "source": "NICE CG179."},
  {"id": "MAK-557", "subject": "Perioperative medicine & nutrition", "topic": "MATTRESS", "title": "PRESSURE ULCERS: MATTRESS", "stem": "A hospitalised adult is assessed as being at high risk of developing a pressure ulcer. Which equipment should be used?", "options": {"A": "High-specification foam mattress", "B": "Ordinary chair cushion only", "C": "No pressure redistribution", "D": "Water restriction", "E": "Routine plaster cast"}, "correct_letter": "A", "correct_answer": "A. High-specification foam mattress", "why_correct": "NICE recommends a high-specification foam mattress for adults admitted to secondary care who are assessed as being at high risk of pressure ulcer development.", "exam_trap": "A pressure-redistributing mattress complements repositioning; it does not eliminate the need for repositioning.", "takeaway": "High pressure-ulcer risk in hospital → high-specification foam mattress + repositioning plan.", "source": "NICE CG179."},
  {"id": "MAK-558", "subject": "Perioperative medicine & nutrition", "topic": "NUTRITION", "title": "PRESSURE ULCERS: NUTRITION", "stem": "An adult has adequate nutritional intake but is at risk of developing a pressure ulcer. Which statement is correct?", "options": {"A": "Nutritional supplements should automatically be prescribed solely to prevent pressure ulcers", "B": "Nutritional supplements should not be offered specifically for pressure-ulcer prevention when nutritional intake is adequate", "C": "Parenteral nutrition is mandatory", "D": "IV fluids are mandatory", "E": "The patient should be kept fasting"}, "correct_letter": "B", "correct_answer": "B. Nutritional supplements should not be offered specifically for pressure-ulcer prevention when nutritional intake is adequate", "why_correct": "NICE advises against nutritional supplements specifically for pressure-ulcer prevention in adults whose nutritional intake is adequate.", "exam_trap": "This does not mean nutritional assessment is unnecessary in a malnourished patient.", "takeaway": "Assess nutrition properly; do not prescribe supplements automatically simply because pressure-ulcer risk exists.", "source": "NICE CG179."},
  {"id": "MAK-559", "subject": "Perioperative medicine & nutrition", "topic": "POSTOPERATIVE ACUTE RESPIRATORY FAILURE", "title": "POSTOPERATIVE ACUTE RESPIRATORY FAILURE", "stem": "A postoperative patient becomes acutely breathless, hypoxic and increasingly fatigued. What is the most appropriate initial principle?", "options": {"A": "Assess airway, breathing and circulation and identify the cause", "B": "Assume atelectasis without assessment", "C": "Give sedatives", "D": "Ignore oxygen saturation", "E": "Delay assessment until the following day"}, "correct_letter": "A", "correct_answer": "A. Assess airway, breathing and circulation and identify the cause", "why_correct": "Postoperative respiratory deterioration has multiple potentially life-threatening causes, including airway obstruction, aspiration, pneumonia, pulmonary oedema, pulmonary embolism and pneumothorax.", "exam_trap": "Do not label every postoperative respiratory problem \"atelectasis.\"", "takeaway": "Postoperative hypoxia = ABC assessment + identify the cause.", "source": "[RCUK], ABCDE approach to the acutely ill patient."},
  {"id": "MAK-560", "subject": "Perioperative medicine & nutrition", "topic": "POSTOPERATIVE PULMONARY OEDEMA", "title": "POSTOPERATIVE PULMONARY OEDEMA", "stem": "A postoperative patient develops acute severe breathlessness, bilateral crackles and hypoxia shortly after receiving a large fluid load. Which diagnosis should be considered?", "options": {"A": "Pulmonary oedema", "B": "Simple atelectasis only", "C": "Appendicitis", "D": "Testicular torsion", "E": "Incisional hernia"}, "correct_letter": "A", "correct_answer": "A. Pulmonary oedema", "why_correct": "Acute pulmonary oedema can occur after fluid overload or cardiac dysfunction and causes breathlessness, hypoxia and bilateral pulmonary crackles.", "exam_trap": "Do not automatically assume every postoperative hypoxic patient has pneumonia.", "takeaway": "Acute postoperative hypoxia + bilateral crackles + fluid excess → consider pulmonary oedema.", "source": "[AoA] guidance, perioperative fluid management."},
  {"id": "MAK-561", "subject": "Perioperative medicine & nutrition", "topic": "POSTOPERATIVE ASPIRATION", "title": "POSTOPERATIVE ASPIRATION", "stem": "A patient aspirates gastric contents during induction of anaesthesia and subsequently develops respiratory distress. What pulmonary complication is of particular concern?", "options": {"A": "Aspiration pneumonitis/pneumonia", "B": "Chronic emphysema", "C": "Pulmonary fibrosis from smoking", "D": "Primary lung cancer", "E": "Mesothelioma"}, "correct_letter": "A", "correct_answer": "A. Aspiration pneumonitis/pneumonia", "why_correct": "Aspiration of gastric contents can cause chemical pneumonitis and may be followed by bacterial pneumonia.", "exam_trap": "Aspiration pneumonitis and aspiration pneumonia are related but not identical entities.", "takeaway": "Aspiration → assess respiratory compromise and distinguish chemical injury from subsequent infection.", "source": "[AoA] guidance, pulmonary aspiration during anaesthesia."},
  {"id": "MAK-562", "subject": "Perioperative medicine & nutrition", "topic": "POSTOPERATIVE PNEUMOTHORAX", "title": "POSTOPERATIVE PNEUMOTHORAX", "stem": "A patient develops sudden unilateral pleuritic chest pain, respiratory distress and markedly reduced breath sounds after central venous access. What complication should be considered?", "options": {"A": "Iatrogenic pneumothorax", "B": "Acute cholecystitis", "C": "Diverticulitis", "D": "Urinary retention", "E": "Ileus"}, "correct_letter": "A", "correct_answer": "A. Iatrogenic pneumothorax", "why_correct": "Pneumothorax is a recognised complication of procedures involving the thorax, including central venous access depending on the site and technique.", "exam_trap": "If there is haemodynamic instability and severe respiratory compromise with suspected tension physiology, emergency decompression takes priority over waiting for imaging.", "takeaway": "Post-procedure acute unilateral respiratory deterioration → consider pneumothorax.", "source": "[AoA] guidance, safe vascular/central venous access."},
  {"id": "MAK-563", "subject": "Perioperative medicine & nutrition", "topic": "POSTOPERATIVE MYOCARDIAL INJURY", "title": "POSTOPERATIVE MYOCARDIAL INJURY", "stem": "An older patient develops unexplained tachycardia and mild hypotension after major surgery. Which serious complication should remain in the differential even without typical chest pain?", "options": {"A": "Myocardial infarction/myocardial injury", "B": "Constipation only", "C": "Incisional hernia", "D": "Simple wound bruising", "E": "Haemorrhoids"}, "correct_letter": "A", "correct_answer": "A. Myocardial infarction/myocardial injury", "why_correct": "Older and postoperative patients may have atypical or silent myocardial ischaemia. Unexplained haemodynamic or physiological deterioration should prompt consideration of cardiac causes.", "exam_trap": "Absence of classic chest pain does not exclude myocardial injury.", "takeaway": "Unexplained postoperative deterioration → keep silent/atypical MI in the differential even with no chest pain.", "source": "[AoA] guidance, perioperative myocardial injury."},
  {"id": "MAK-564", "subject": "Perioperative medicine & nutrition", "topic": "DRUGS", "title": "POSTOPERATIVE ACUTE KIDNEY INJURY: DRUGS", "stem": "A postoperative patient develops AKI. Which medication group can contribute to kidney injury and should be reviewed?", "options": {"A": "NSAIDs", "B": "Simple emollients", "C": "Topical moisturisers", "D": "Saline nasal spray", "E": "Topical barrier cream"}, "correct_letter": "A", "correct_answer": "A. NSAIDs", "why_correct": "NSAIDs can reduce renal prostaglandin-mediated vasodilation and may precipitate or worsen AKI, particularly in susceptible patients.", "exam_trap": "Medication review is part of AKI management; do not focus only on fluid balance.", "takeaway": "AKI → review potentially nephrotoxic medicines, including NSAIDs.", "source": "NICE NG180, acute kidney injury."},
  {"id": "MAK-565", "subject": "Perioperative medicine & nutrition", "topic": "REJECTION", "title": "RENAL TRANSPLANT: REJECTION", "stem": "A kidney transplant recipient develops worsening renal function without another obvious explanation. Which complication should be considered?", "options": {"A": "Acute rejection", "B": "Acute appendicitis", "C": "Diverticular bleeding", "D": "Gallstone ileus", "E": "Inguinal hernia"}, "correct_letter": "A", "correct_answer": "A. Acute rejection", "why_correct": "NHS Blood and Transplant states that rejection may first be detected through deterioration in transplant function and blood-test abnormalities. Diagnosis may require transplant biopsy.", "exam_trap": "Do not assume every rise in creatinine after transplant is rejection; other causes include obstruction, vascular complications, drug toxicity and infection.", "takeaway": "Transplant dysfunction → consider rejection, but investigate the differential.", "source": "[NHSBT]: guidance on transplant rejection and post-transplant graft dysfunction."},
  {"id": "MAK-566", "subject": "Perioperative medicine & nutrition", "topic": "IMMUNOSUPPRESSION", "title": "RENAL TRANSPLANT: IMMUNOSUPPRESSION", "stem": "Why are immunosuppressive medicines required after kidney transplantation?", "options": {"A": "To prevent the recipient's immune system attacking the transplanted kidney", "B": "To increase red-cell production", "C": "To dissolve renal stones", "D": "To prevent all infections", "E": "To eliminate the need for follow-up"}, "correct_letter": "A", "correct_answer": "A. To prevent the recipient's immune system attacking the transplanted kidney", "why_correct": "Immunosuppressants reduce the immune response responsible for graft rejection. NHS Blood and Transplant emphasises that these medicines are essential after transplantation but increase susceptibility to infection.", "exam_trap": "Immunosuppression reduces rejection risk but does not eliminate rejection and increases infection risk.", "takeaway": "Transplant immunosuppression = protect the graft, but at the cost of increased infection susceptibility.", "source": "[NHSBT]: Organ and Tissue Donation and Transplantation guidelines."},
  {"id": "MAK-567", "subject": "Perioperative medicine & nutrition", "topic": "TACROLIMUS TOXICITY", "title": "RENAL TRANSPLANT: TACROLIMUS TOXICITY", "stem": "A kidney transplant recipient develops worsening renal function while receiving tacrolimus. Which adverse effect should be considered?", "options": {"A": "Tacrolimus nephrotoxicity", "B": "Immediate rejection in every case", "C": "Appendicitis", "D": "Iron deficiency", "E": "Diverticulitis"}, "correct_letter": "A", "correct_answer": "A. Tacrolimus nephrotoxicity", "why_correct": "NHS Blood and Transplant identifies impaired kidney function as a potential adverse effect of high tacrolimus exposure and notes that blood tests are required to ensure appropriate dosing.", "exam_trap": "A rising creatinine after transplantation does not automatically mean rejection.", "takeaway": "Transplant + rising creatinine → distinguish rejection from drug toxicity and other causes.", "source": "[NHSBT]: Organ and Tissue Donation and Transplantation guidelines; [BNF]."},
  {"id": "MAK-568", "subject": "Perioperative medicine & nutrition", "topic": "REJECTION", "title": "LIVER TRANSPLANT: REJECTION", "stem": "A liver transplant recipient develops worsening liver function tests and new jaundice. Which diagnosis should be considered?", "options": {"A": "Liver graft rejection", "B": "Acute appendicitis", "C": "Femoral hernia", "D": "Renal colic", "E": "Diverticulosis"}, "correct_letter": "A", "correct_answer": "A. Liver graft rejection", "why_correct": "NHS Blood and Transplant notes that liver rejection is often first detected through abnormal liver blood tests and may occasionally present with jaundice. Diagnosis usually requires liver biopsy.", "exam_trap": "Not every abnormal liver test after transplantation is rejection; biliary, vascular, infective and drug-related complications also require consideration.", "takeaway": "Liver transplant dysfunction → consider rejection and investigate graft-specific complications.", "source": "[NHSBT]: Organ and Tissue Donation and Transplantation guidelines."},
  {"id": "MAK-569", "subject": "Perioperative medicine & nutrition", "topic": "IMMUNOSUPPRESSION AND INFECTION", "title": "LIVER TRANSPLANT: IMMUNOSUPPRESSION AND INFECTION", "stem": "Why are transplant recipients particularly susceptible to infection?", "options": {"A": "Immunosuppressive treatment reduces immune function", "B": "Transplanted organs cannot become infected", "C": "Immunosuppressants increase neutrophil function", "D": "All infections are caused by rejection", "E": "Transplant recipients have no infection risk after discharge"}, "correct_letter": "A", "correct_answer": "A. Immunosuppressive treatment reduces immune function", "why_correct": "NHS Blood and Transplant explains that immunosuppressive medicines lower immune responses and consequently increase susceptibility to infection.", "exam_trap": "Fever in a transplant recipient should not automatically be attributed to rejection.", "takeaway": "Transplant + immunosuppression → maintain a low threshold for investigating infection.", "source": "[NHSBT]: Organ and Tissue Donation and Transplantation guidelines."},
  {"id": "MAK-570", "subject": "Perioperative medicine & nutrition", "topic": "POSITIVE CROSS-MATCH", "title": "TRANSPLANT: POSITIVE CROSS-MATCH", "stem": "A potential kidney donor-recipient pair has a strongly positive cross-match indicating antibodies that would attack the donor kidney. What does this imply?", "options": {"A": "The transplant can proceed routinely", "B": "The transplant should not proceed because of the risk of immediate rejection", "C": "The recipient needs appendicectomy first", "D": "It confirms chronic rejection", "E": "It proves the donor has an infection"}, "correct_letter": "B", "correct_answer": "B. The transplant should not proceed because of the risk of immediate rejection", "why_correct": "NHS Blood and Transplant explains that a positive cross-match indicates antibodies capable of attacking the donor kidney and means the transplant cannot proceed because of the risk of immediate rejection.", "exam_trap": "HLA matching and cross-matching are related but are not interchangeable concepts.", "takeaway": "Positive cross-match → donor-specific antibodies create a major transplantation barrier.", "source": "[NHSBT]: Organ and Tissue Donation and Transplantation guidelines."},
  {"id": "MAK-571", "subject": "ENT: throat, sleep & nose", "topic": "Sudden sensorineural hearing loss", "title": "Sudden sensorineural hearing loss", "stem": "A 52-year-old man develops sudden unilateral hearing loss over the last 24 hours. Otoscopy is normal and there is no evidence of external or middle-ear disease. What is the most appropriate next step?", "options": {"A": "Routine audiology referral", "B": "Reassurance and review in 4 weeks", "C": "Immediate specialist assessment", "D": "Oral antibiotics", "E": "Tympanostomy tube insertion"}, "correct_letter": "C", "correct_answer": "C. Immediate specialist assessment", "why_correct": "Sudden hearing loss developing over 3 days or less within the preceding 30 days, when not explained by external or middle-ear disease, requires immediate referral so that the patient is seen within 24 hours.", "exam_trap": "Do not treat sudden sensorineural hearing loss as simple earwax or otitis media when otoscopy is normal.", "takeaway": "Sudden hearing loss + normal ear → think sensorineural → urgent ENT assessment.", "source": "NICE NG98, updated October 2023."},
  {"id": "MAK-572", "subject": "ENT: throat, sleep & nose", "topic": "Sudden hearing loss occurring more than 30 days ago", "title": "Sudden hearing loss occurring more than 30 days ago", "stem": "A 61-year-old woman reports sudden unilateral hearing loss that began 6 weeks ago. Otoscopy does not identify an external or middle-ear cause. What is the appropriate referral timeframe?", "options": {"A": "Emergency referral within 1 hour", "B": "Immediate referral within 24 hours", "C": "Urgent specialist assessment within 2 weeks", "D": "Routine review in 6 months", "E": "No referral is required"}, "correct_letter": "C", "correct_answer": "C. Urgent specialist assessment within 2 weeks", "why_correct": "Sudden hearing loss developing more than 30 days previously should be referred urgently for assessment within 2 weeks.", "exam_trap": "The 24-hour pathway applies when sudden loss occurred within the preceding 30 days.", "takeaway": "Sudden ≤3 days + within 30 days → 24 hours. Older sudden loss → within 2 weeks.", "source": "NICE NG98, updated October 2023."},
  {"id": "MAK-573", "subject": "ENT: throat, sleep & nose", "topic": "Rapidly progressive hearing loss", "title": "Rapidly progressive hearing loss", "stem": "A 47-year-old patient has progressive hearing loss that has worsened substantially over 6 weeks. There is no acute external or middle-ear cause. What is the appropriate management?", "options": {"A": "Reassurance only", "B": "Routine review in 12 months", "C": "Urgent ENT or audiovestibular referral", "D": "Oral antibiotics", "E": "Ear irrigation"}, "correct_letter": "C", "correct_answer": "C. Urgent ENT or audiovestibular referral", "why_correct": "Rapid worsening over 4–90 days warrants urgent specialist assessment, generally within 2 weeks.", "exam_trap": "Rapid progression is distinct from slowly progressive age-related hearing loss.", "takeaway": "Rapid hearing deterioration over weeks → urgent specialist assessment.", "source": "NICE NG98, updated October 2023."},
  {"id": "MAK-574", "subject": "ENT: head & neck", "topic": "Hearing loss with facial weakness", "title": "Hearing loss with facial weakness", "stem": "A 70-year-old man develops unilateral hearing loss accompanied by ipsilateral facial drooping and altered facial sensation. What is the appropriate action?", "options": {"A": "Routine audiology referral", "B": "Ear irrigation", "C": "Immediate specialist assessment", "D": "Reassurance", "E": "Hearing-aid fitting without further investigation"}, "correct_letter": "C", "correct_answer": "C. Immediate specialist assessment", "why_correct": "Acquired unilateral hearing loss with ipsilateral altered sensation or facial droop requires immediate assessment within 24 hours. Stroke should also be considered where clinically appropriate.", "exam_trap": "Do not assume that all facial weakness accompanying hearing loss is uncomplicated Bell's palsy.", "takeaway": "Hearing loss + focal neurological signs = immediate assessment.", "source": "NICE NG98, updated October 2023."},
  {"id": "MAK-575", "subject": "ENT: throat, sleep & nose", "topic": "Immunocompromised patient with otalgia and otorrhoea", "title": "Immunocompromised patient with otalgia and otorrhoea", "stem": "A 64-year-old immunocompromised patient has severe ear pain and purulent discharge. Symptoms have not improved after 72 hours of treatment. What is the appropriate next step?", "options": {"A": "Routine audiology", "B": "Immediate ENT referral", "C": "Ear syringing", "D": "Reassurance", "E": "No further assessment"}, "correct_letter": "B", "correct_answer": "B. Immediate ENT referral", "why_correct": "Immunocompromised adults with otalgia and otorrhoea that has not responded to treatment within 72 hours require immediate ENT assessment because of the risk of serious invasive external-ear infection.", "exam_trap": "Persistent severe otalgia in an immunocompromised patient is not routine otitis externa.", "takeaway": "Immunocompromised + persistent otalgia/otorrhoea = urgent ENT safety signal.", "source": "NICE NG98, updated October 2023."},
  {"id": "MAK-576", "subject": "ENT: head & neck", "topic": "Unilateral middle-ear effusion and nasopharyngeal malignancy", "title": "Unilateral middle-ear effusion and nasopharyngeal malignancy", "stem": "A 48-year-old man of Chinese ethnicity develops persistent unilateral middle-ear effusion without a recent upper respiratory tract infection. What diagnosis must particularly be considered?", "options": {"A": "Ménière's disease", "B": "Nasopharyngeal carcinoma", "C": "Otosclerosis", "D": "Presbycusis", "E": "Benign positional vertigo"}, "correct_letter": "B", "correct_answer": "B. Nasopharyngeal carcinoma", "why_correct": "Persistent middle-ear effusion without an upper respiratory tract infection in adults of Chinese or South-East Asian family origin warrants consideration of nasopharyngeal malignancy and ENT assessment.", "exam_trap": "Adult unilateral effusion is not automatically benign Eustachian tube dysfunction.", "takeaway": "Adult unilateral effusion without URTI → look for a nasopharyngeal cause.", "source": "NICE NG98, updated October 2023."},
  {"id": "MAK-577", "subject": "ENT: throat, sleep & nose", "topic": "Asymmetric sensorineural hearing loss", "title": "Asymmetric sensorineural hearing loss", "stem": "An adult has sensorineural hearing loss with an asymmetry of 15 dB at two adjacent frequencies on pure-tone audiometry. Which investigation should be considered?", "options": {"A": "CT chest", "B": "MRI of the internal auditory meati", "C": "Carotid Doppler", "D": "CT abdomen", "E": "Lumbar puncture"}, "correct_letter": "B", "correct_answer": "B. MRI of the internal auditory meati", "why_correct": "NICE recommends considering MRI of the internal auditory meati for sensorineural hearing loss without localising signs when there is an asymmetry of 15 dB or more at any two adjacent test frequencies.", "exam_trap": "The concern is for retrocochlear pathology such as vestibular schwannoma.", "takeaway": "Asymmetric SNHL → think retrocochlear pathology → MRI IAM.", "source": "NICE NG98, updated October 2023."},
  {"id": "MAK-578", "subject": "ENT: head & neck", "topic": "Bell's palsy pattern", "title": "Bell's palsy pattern", "stem": "A 36-year-old woman develops unilateral facial weakness involving the forehead, eye closure and lower face. There are no other neurological abnormalities. Which finding most strongly supports a lower motor neurone facial palsy?", "options": {"A": "Forehead sparing", "B": "Weakness confined to the mouth", "C": "Inability to close the ipsilateral eye", "D": "Contralateral limb weakness", "E": "Isolated tongue deviation"}, "correct_letter": "C", "correct_answer": "C. Inability to close the ipsilateral eye", "why_correct": "A lower motor neurone facial palsy affects the entire ipsilateral face, including forehead movement and eye closure.", "exam_trap": "Forehead sparing suggests an upper motor neurone lesion.", "takeaway": "LMN VII → whole side of face. UMN lesion → forehead relatively spared.", "source": "NICE NG127 (2019)."},
  {"id": "MAK-579", "subject": "ENT: head & neck", "topic": "Eye protection in Bell's palsy", "title": "Eye protection in Bell's palsy", "stem": "A patient with uncomplicated Bell's palsy cannot fully close the affected eye. What is an important component of management?", "options": {"A": "Eye protection", "B": "Eye patching permanently for 6 months", "C": "Immediate facial nerve surgery", "D": "Ear irrigation", "E": "Avoiding all facial movement"}, "correct_letter": "A", "correct_answer": "A. Eye protection", "why_correct": "Incomplete eye closure exposes the cornea to drying and injury. NICE specifically recommends advising adults with Bell's palsy about eye care.", "exam_trap": "The immediate practical issue is corneal protection.", "takeaway": "Bell's palsy + incomplete eye closure → protect the cornea.", "source": "NICE NG127, 2019."},
  {"id": "MAK-580", "subject": "ENT: head & neck", "topic": "Uncomplicated Bell's palsy referral", "title": "Uncomplicated Bell's palsy referral", "stem": "A 42-year-old patient has an isolated unilateral lower motor neurone facial palsy involving the forehead and eye closure. There is no middle-ear disease or other neurological abnormality. What does NICE recommend regarding routine specialist referral?", "options": {"A": "Routine neurosurgical referral", "B": "Routine ENT referral for every patient", "C": "Do not routinely refer", "D": "Immediate MRI for all patients", "E": "Immediate lumbar puncture"}, "correct_letter": "C", "correct_answer": "C. Do not routinely refer", "why_correct": "NICE advises that uncomplicated Bell's palsy without evidence of another medical condition does not routinely require specialist referral.", "exam_trap": "Do not automatically convert every classic Bell's palsy presentation into a neurological referral.", "takeaway": "Classic isolated Bell's palsy → can usually be managed without routine specialist referral.", "source": "NICE NG127, 2019."},
  {"id": "MAK-581", "subject": "ENT: throat, sleep & nose", "topic": "Tinnitus with sudden hearing loss", "title": "Tinnitus with sudden hearing loss", "stem": "A patient develops tinnitus together with sudden unilateral hearing loss over the previous 48 hours. What is the appropriate management?", "options": {"A": "Routine audiology in 6 months", "B": "Reassurance only", "C": "Assessment within 24 hours", "D": "No investigation", "E": "CT abdomen"}, "correct_letter": "C", "correct_answer": "C. Assessment within 24 hours", "why_correct": "Tinnitus accompanied by sudden hearing loss developing over 3 days or less within the previous 30 days requires referral for assessment within 24 hours.", "exam_trap": "The tinnitus itself is not the main emergency; the associated sudden hearing loss is.", "takeaway": "Tinnitus + sudden hearing loss → urgent hearing-loss pathway.", "source": "NICE NG155, 2020; NICE NG98, updated October 2023."},
  {"id": "MAK-582", "subject": "ENT: throat, sleep & nose", "topic": "Tinnitus with acute neurological symptoms", "title": "Tinnitus with acute neurological symptoms", "stem": "A patient presents with tinnitus accompanied by sudden facial weakness. What is the appropriate approach?", "options": {"A": "Routine tinnitus clinic referral", "B": "Immediate specialist assessment", "C": "Reassurance", "D": "Hearing-aid fitting", "E": "Earwax drops only"}, "correct_letter": "B", "correct_answer": "B. Immediate specialist assessment", "why_correct": "Tinnitus associated with sudden significant neurological symptoms such as facial weakness requires immediate assessment, with stroke considered where appropriate.", "exam_trap": "Neurological symptoms override a routine tinnitus pathway.", "takeaway": "Tinnitus + acute neurological deficit = emergency assessment.", "source": "NICE NG155, 2020."},
  {"id": "MAK-583", "subject": "ENT: throat, sleep & nose", "topic": "Unilateral non-pulsatile tinnitus", "title": "Unilateral non-pulsatile tinnitus", "stem": "A 55-year-old man has persistent unilateral non-pulsatile tinnitus but no neurological, audiological or otological abnormality. Which investigation should be considered?", "options": {"A": "MRI of the internal auditory meati", "B": "CT abdomen", "C": "EEG", "D": "Carotid endarterectomy", "E": "No assessment is ever indicated"}, "correct_letter": "A", "correct_answer": "A. MRI of the internal auditory meati", "why_correct": "NICE recommends considering MRI of the internal auditory meati for unilateral or asymmetrical non-pulsatile tinnitus even when no associated signs are present.", "exam_trap": "Bilateral symmetrical tinnitus without associated signs is different.", "takeaway": "Persistent unilateral tinnitus → consider MRI IAM.", "source": "NICE NG155, 2020."},
  {"id": "MAK-584", "subject": "ENT: throat, sleep & nose", "topic": "Pulsatile tinnitus", "title": "Pulsatile tinnitus", "stem": "A 59-year-old patient describes persistent tinnitus synchronised with the heartbeat. What is the appropriate investigation principle?", "options": {"A": "No imaging is required", "B": "Offer imaging", "C": "Treat with antibiotics", "D": "Routine ear irrigation only", "E": "MRI is contraindicated in all tinnitus"}, "correct_letter": "B", "correct_answer": "B. Offer imaging", "why_correct": "NICE recommends imaging for pulsatile tinnitus because vascular and other structural causes may be present.", "exam_trap": "Pulsatile tinnitus is not managed like uncomplicated symmetrical non-pulsatile tinnitus.", "takeaway": "Pulsatile tinnitus → image for an underlying structural/vascular cause.", "source": "NICE NG155, 2020."},
  {"id": "MAK-585", "subject": "ENT: throat, sleep & nose", "topic": "Symmetrical non-pulsatile tinnitus", "title": "Symmetrical non-pulsatile tinnitus", "stem": "A 50-year-old patient has bilateral symmetrical non-pulsatile tinnitus with no neurological, audiological, otological or head-and-neck signs. What does NICE recommend regarding imaging?", "options": {"A": "MRI for everyone", "B": "CT for everyone", "C": "Routine angiography", "D": "Do not offer imaging solely for the tinnitus", "E": "Immediate surgery"}, "correct_letter": "D", "correct_answer": "D. Do not offer imaging solely for the tinnitus", "why_correct": "NICE advises against imaging for symmetrical non-pulsatile tinnitus when there are no associated signs or symptoms.", "exam_trap": "Do not over-investigate uncomplicated symmetrical tinnitus.", "takeaway": "Symmetrical non-pulsatile tinnitus + no red flags → no routine imaging.", "source": "NICE NG155, 2020."},
  {"id": "MAK-586", "subject": "ENT: throat, sleep & nose", "topic": "Acute sinusitis and antibiotics", "title": "Acute sinusitis and antibiotics", "stem": "A 28-year-old patient has facial pressure, nasal discharge and congestion for 7 days. There are no red flags and the patient is not systemically very unwell. What is the most appropriate antimicrobial approach?", "options": {"A": "Immediate broad-spectrum antibiotics", "B": "Immediate IV antibiotics", "C": "Do not offer an antibiotic prescription routinely", "D": "Long-term prophylactic antibiotics", "E": "Emergency sinus surgery"}, "correct_letter": "C", "correct_answer": "C. Do not offer an antibiotic prescription routinely", "why_correct": "NICE advises against antibiotic prescribing for acute sinusitis when symptoms have been present for around 10 days or less in the absence of features requiring another approach.", "exam_trap": "Purulent nasal discharge does not automatically mean bacterial infection requiring antibiotics.", "takeaway": "Acute sinusitis ≤10 days → usually supportive management, not antibiotics.", "source": "NICE NG79, 2017."},
  {"id": "MAK-587", "subject": "ENT: throat, sleep & nose", "topic": "Expected duration of acute sinusitis", "title": "Expected duration of acute sinusitis", "stem": "A patient with uncomplicated acute sinusitis asks how long symptoms usually last. Which timeframe should be given?", "options": {"A": "Usually 24 hours", "B": "Usually 2–3 days", "C": "Usually 2–3 weeks", "D": "Usually 3 months", "E": "Usually 1 year"}, "correct_letter": "C", "correct_answer": "C. Usually 2–3 weeks", "why_correct": "NICE advises that the usual course of acute sinusitis is approximately 2–3 weeks.", "exam_trap": "Persistent symptoms at several days do not automatically represent treatment failure.", "takeaway": "Acute sinusitis commonly lasts 2–3 weeks.", "source": "NICE NG79, 2017."},
  {"id": "MAK-588", "subject": "ENT: throat, sleep & nose", "topic": "Sinusitis with orbital complication", "title": "Sinusitis with orbital complication", "stem": "A patient with acute sinusitis develops severe periorbital swelling, visual disturbance and worsening systemic illness. What is the most appropriate action?", "options": {"A": "Routine GP review in 1 month", "B": "Treat as uncomplicated sinusitis", "C": "Urgent hospital assessment", "D": "Reassurance", "E": "Long-term nasal decongestants only"}, "correct_letter": "C", "correct_answer": "C. Urgent hospital assessment", "why_correct": "Orbital or intracranial complications of sinusitis are serious and require hospital assessment.", "exam_trap": "Visual symptoms in a patient with sinusitis are a complication warning sign.", "takeaway": "Sinusitis + orbital/neurological features → think complication, not routine sinusitis.", "source": "NICE NG79 (2017); urgent hospital referral is standard practice for suspected orbital or intracranial complications."},
  {"id": "MAK-589", "subject": "ENT: throat, sleep & nose", "topic": "Persistent unexplained hoarseness", "title": "Persistent unexplained hoarseness", "stem": "A 49-year-old smoker has persistent unexplained hoarseness. What is the appropriate NICE pathway?", "options": {"A": "Routine review after 12 months", "B": "Suspected cancer pathway referral", "C": "Antibiotics only", "D": "Speech therapy without assessment", "E": "No further investigation"}, "correct_letter": "B", "correct_answer": "B. Suspected cancer pathway referral", "why_correct": "NICE recommends considering a suspected cancer pathway referral for laryngeal cancer in people aged 45 years or over with persistent unexplained hoarseness.", "exam_trap": "Do not dismiss persistent hoarseness as simple laryngitis in an older adult.", "takeaway": "Age ≥45 + persistent unexplained hoarseness → consider 2-week-wait cancer referral.", "source": "NICE NG12, updated 2025."},
  {"id": "MAK-590", "subject": "ENT: head & neck", "topic": "Unexplained neck lump and laryngeal cancer", "title": "Unexplained neck lump and laryngeal cancer", "stem": "A 57-year-old adult presents with a persistent unexplained neck lump. Which diagnosis should be considered in the NICE head-and-neck cancer pathway?", "options": {"A": "Laryngeal cancer", "B": "Appendicitis", "C": "Renal cell carcinoma only", "D": "Osteoarthritis", "E": "Peptic ulcer disease"}, "correct_letter": "A", "correct_answer": "A. Laryngeal cancer", "why_correct": "NICE recommends considering a suspected cancer pathway referral for laryngeal cancer in people aged 45 years or over with an unexplained neck lump.", "exam_trap": "An unexplained adult neck lump should not simply be observed indefinitely.", "takeaway": "Adult unexplained neck lump → investigate for head-and-neck malignancy.", "source": "NICE NG12, updated 2025."},
  {"id": "MAK-591", "subject": "ENT: head & neck", "topic": "Persistent oral ulcer", "title": "Persistent oral ulcer", "stem": "A 61-year-old patient has an unexplained oral ulcer that has persisted for 4 weeks. What is the appropriate management?", "options": {"A": "Reassurance only", "B": "Suspected cancer pathway referral", "C": "Antibiotics for 3 months", "D": "Routine review in 1 year", "E": "No further examination"}, "correct_letter": "B", "correct_answer": "B. Suspected cancer pathway referral", "why_correct": "NICE recommends considering a suspected cancer pathway referral for unexplained oral ulceration lasting more than 3 weeks.", "exam_trap": "The duration matters.", "takeaway": "Unexplained oral ulcer >3 weeks → investigate for oral cancer.", "source": "NICE NG12, updated 2025."},
  {"id": "MAK-592", "subject": "ENT: head & neck", "topic": "Persistent oral cavity lump", "title": "Persistent oral cavity lump", "stem": "A patient presents with an unexplained lump in the oral cavity. Which professional should provide urgent assessment for possible oral cancer when the lesion has not yet been assessed by a dentist?", "options": {"A": "Cardiologist", "B": "Dentist", "C": "Gastroenterologist", "D": "Neurologist", "E": "Physiotherapist"}, "correct_letter": "B", "correct_answer": "B. Dentist", "why_correct": "NICE recommends urgent assessment by a dentist for an unexplained lump on the lip or in the oral cavity.", "exam_trap": "Do not confuse this with the separate suspected cancer pathway recommendation when a dentist has already assessed the lesion as suspicious.", "takeaway": "Unexplained oral/lip lump → urgent dental assessment.", "source": "NICE NG12, updated 2025."},
  {"id": "MAK-593", "subject": "ENT: head & neck", "topic": "Red and white oral lesion", "title": "Red and white oral lesion", "stem": "A 58-year-old patient has a persistent red-and-white patch in the oral cavity. What is the appropriate principle?", "options": {"A": "Ignore it if painless", "B": "Arrange appropriate urgent assessment", "C": "Treat with topical antibiotics indefinitely", "D": "Assume it is candidiasis without examination", "E": "No follow-up is required"}, "correct_letter": "B", "correct_answer": "B. Arrange appropriate urgent assessment", "why_correct": "NICE identifies red or red-and-white oral patches consistent with erythroplakia or erythroleukoplakia as lesions requiring urgent assessment for possible oral cancer.", "exam_trap": "Lack of pain does not exclude significant oral pathology.", "takeaway": "Persistent red/white oral lesion → cancer pathway awareness.", "source": "NICE NG12, updated 2025."},
  {"id": "MAK-594", "subject": "ENT: head & neck", "topic": "Unexplained thyroid lump", "title": "Unexplained thyroid lump", "stem": "A 45-year-old woman is found to have an unexplained thyroid lump. What is the appropriate NICE recommendation?", "options": {"A": "Ignore if euthyroid", "B": "Suspected cancer pathway referral should be considered", "C": "Antibiotics", "D": "Immediate thyroidectomy in primary care", "E": "No assessment is required"}, "correct_letter": "B", "correct_answer": "B. Suspected cancer pathway referral should be considered", "why_correct": "NICE recommends considering a suspected cancer pathway referral for an unexplained thyroid lump.", "exam_trap": "Normal thyroid function does not exclude thyroid malignancy.", "takeaway": "Thyroid lump ≠ benign simply because TSH is normal.", "source": "NICE NG12, updated 2025."},
  {"id": "MAK-595", "subject": "ENT: throat, sleep & nose", "topic": "Otitis media with effusion in a child", "title": "Otitis media with effusion in a child", "stem": "A 6-year-old child has suspected otitis media with effusion and hearing difficulties. Which investigation forms part of the formal assessment?", "options": {"A": "Colonoscopy", "B": "Tympanometry", "C": "Lumbar puncture", "D": "CT abdomen", "E": "Echocardiography"}, "correct_letter": "B", "correct_answer": "B. Tympanometry", "why_correct": "NICE recommends formal assessment of suspected OME including clinical examination, hearing testing and tympanometry.", "exam_trap": "OME is primarily an assessment and hearing problem, not automatically an acute infection.", "takeaway": "Suspected glue ear → otoscopy + hearing assessment + tympanometry.", "source": "NICE NG233, Otitis media with effusion in under 12s, 2023."},
  {"id": "MAK-596", "subject": "ENT: throat, sleep & nose", "topic": "Antibiotics for glue ear", "title": "Antibiotics for glue ear", "stem": "A 5-year-old child has uncomplicated otitis media with effusion without evidence of acute infection. Which treatment should NOT be offered specifically for OME?", "options": {"A": "Hearing assessment", "B": "Supportive listening strategies", "C": "Antibiotics", "D": "Consideration of auto-inflation where appropriate", "E": "Discussion of hearing-related impact"}, "correct_letter": "C", "correct_answer": "C. Antibiotics", "why_correct": "NICE specifically recommends not offering antibiotics to treat OME.", "exam_trap": "OME is middle-ear fluid without the clinical picture of acute bacterial otitis media.", "takeaway": "Glue ear ≠ acute otitis media → antibiotics are not routine treatment.", "source": "NICE NG233, 2023."},
  {"id": "MAK-597", "subject": "ENT: throat, sleep & nose", "topic": "Steroids for otitis media with effusion", "title": "Steroids for otitis media with effusion", "stem": "A child has persistent OME-related hearing loss. Which pharmacological treatment should NOT be offered for OME or OME-related hearing loss?", "options": {"A": "Oral corticosteroids", "B": "Hearing support", "C": "Audiological assessment", "D": "Consideration of grommets in appropriate cases", "E": "Listening-environment modification"}, "correct_letter": "A", "correct_answer": "A. Oral corticosteroids", "why_correct": "NICE recommends against oral or nasal corticosteroids for OME or OME-related hearing loss.", "exam_trap": "Do not extrapolate steroid treatment from other ENT inflammatory conditions.", "takeaway": "OME → no routine oral/nasal steroids.", "source": "NICE NG233, 2023."},
  {"id": "MAK-598", "subject": "ENT: throat, sleep & nose", "topic": "Grommets and OME-related hearing loss", "title": "Grommets and OME-related hearing loss", "stem": "A 7-year-old child has confirmed OME associated with hearing loss despite appropriate assessment and supportive management. Which intervention can be considered?", "options": {"A": "Grommet insertion", "B": "Long-term oral antibiotics", "C": "Long-term systemic steroids", "D": "Immediate cochlear implantation", "E": "No discussion of treatment options"}, "correct_letter": "A", "correct_answer": "A. Grommet insertion", "why_correct": "NICE recommends considering grommets for children with OME-related hearing loss, with benefits and risks discussed as part of shared decision-making.", "exam_trap": "Grommets are not recommended simply because OME exists without hearing loss.", "takeaway": "OME + hearing loss → grommets may be considered after appropriate assessment.", "source": "NICE NG233, 2023."},
  {"id": "MAK-599", "subject": "ENT: throat, sleep & nose", "topic": "OME without hearing loss", "title": "OME without hearing loss", "stem": "A 4-year-old child has OME confirmed on assessment but has no hearing loss. What is the most appropriate management principle?", "options": {"A": "Immediate grommet insertion", "B": "Immediate adenoidectomy", "C": "Reassurance and no treatment specifically for OME", "D": "Long-term antibiotics", "E": "Oral corticosteroids"}, "correct_letter": "C", "correct_answer": "C. Reassurance and no treatment specifically for OME", "why_correct": "NICE advises that children with OME without hearing loss should generally be reassured because OME often resolves spontaneously and no treatment is necessary.", "exam_trap": "The presence of middle-ear fluid alone does not mandate surgery.", "takeaway": "OME without hearing loss → usually observe and support, not operate.", "source": "NICE NG233, 2023."},
  {"id": "MAK-600", "subject": "ENT: throat, sleep & nose", "topic": "OME and adenoidectomy", "title": "OME and adenoidectomy", "stem": "A child with OME-related hearing loss is being considered for grommet insertion. Which additional procedure should be considered when planning grommets, provided there is no abnormality of the palate?", "options": {"A": "Routine tonsillectomy in every child", "B": "Adjuvant adenoidectomy", "C": "Total laryngectomy", "D": "Mastoidectomy in every case", "E": "Cochlear implantation"}, "correct_letter": "B", "correct_answer": "B. Adjuvant adenoidectomy", "why_correct": "NICE recommends considering adjuvant adenoidectomy when planning grommets for OME, unless assessment indicates an abnormality with the palate.", "exam_trap": "This is a conditional recommendation, not an instruction to perform adenoidectomy in every child with OME.", "takeaway": "OME + planned grommets → consider adenoidectomy, but assess the palate first.", "source": "NICE NG233, 2023."},
  {"id": "MAK-601", "subject": "ENT: throat, sleep & nose", "topic": "Benign paroxysmal positional vertigo", "title": "Benign paroxysmal positional vertigo", "stem": "A 63-year-old woman develops brief episodes of rotational vertigo whenever she turns over in bed. Each episode lasts less than a minute. She has no hearing loss or neurological deficit. What is the most appropriate diagnostic bedside test?", "options": {"A": "Romberg test only", "B": "Hallpike manoeuvre", "C": "Weber test", "D": "Rinne test", "E": "Caloric testing in all cases"}, "correct_letter": "B", "correct_answer": "B. Hallpike manoeuvre", "why_correct": "Transient rotational vertigo triggered by head movement is characteristic of BPPV. NICE recommends the Hallpike manoeuvre when performed by someone trained and experienced in its use.", "exam_trap": "Do not confuse brief positional attacks with acute vestibular syndrome.", "takeaway": "Brief positional vertigo → Hallpike.", "source": "NICE NG127, updated October 2023."},
  {"id": "MAK-602", "subject": "ENT: throat, sleep & nose", "topic": "Treatment of BPPV", "title": "Treatment of BPPV", "stem": "A patient has typical BPPV confirmed by a trained clinician. There is no cervical-spine instability. Which treatment should be offered?", "options": {"A": "Long-term antibiotics", "B": "Canalith repositioning manoeuvre", "C": "Immediate cochlear implantation", "D": "Long-term corticosteroids", "E": "Mastoidectomy"}, "correct_letter": "B", "correct_answer": "B. Canalith repositioning manoeuvre", "why_correct": "NICE recommends a canalith repositioning manoeuvre such as the Epley manoeuvre when BPPV is diagnosed and the patient has no unstable cervical spine disease.", "exam_trap": "The Epley manoeuvre is treatment for BPPV; it is not a general treatment for all vertigo.", "takeaway": "Confirmed BPPV → reposition the displaced canaliths.", "source": "NICE NG127, updated October 2023."},
  {"id": "MAK-603", "subject": "ENT: throat, sleep & nose", "topic": "BPPV and unstable cervical spine", "title": "BPPV and unstable cervical spine", "stem": "A patient has classic positional vertigo, but also has unstable cervical spine disease. What is the appropriate approach?", "options": {"A": "Perform a forceful Epley manoeuvre regardless", "B": "Perform Hallpike and Epley repeatedly at home", "C": "Refer according to the local pathway", "D": "Give antibiotics", "E": "Perform immediate mastoid surgery"}, "correct_letter": "C", "correct_answer": "C. Refer according to the local pathway", "why_correct": "NICE advises referral when a trained clinician is not available to perform the manoeuvre or when the patient has unstable cervical spine disease.", "exam_trap": "A correct manoeuvre can still be inappropriate when there is a significant cervical-spine contraindication.", "takeaway": "BPPV + unstable neck → do not force the manoeuvre.", "source": "NICE NG127, updated October 2023."},
  {"id": "MAK-604", "subject": "ENT: throat, sleep & nose", "topic": "Acute vestibular syndrome", "title": "Acute vestibular syndrome", "stem": "A 58-year-old develops sudden persistent vertigo, nausea, vomiting and gait unsteadiness. There is no obvious benign positional trigger. Which clinical assessment can help distinguish a peripheral vestibular disorder from a central cause when performed by an appropriately trained clinician?", "options": {"A": "HINTS examination", "B": "Rinne test alone", "C": "Weber test alone", "D": "Snellen chart", "E": "Whispered voice test"}, "correct_letter": "A", "correct_answer": "A. HINTS examination", "why_correct": "NICE recommends HINTS for adults with sudden-onset acute vestibular syndrome when a healthcare professional with appropriate training and experience is available.", "exam_trap": "HINTS is not a generic dizziness examination for every patient.", "takeaway": "Acute vestibular syndrome → HINTS only in trained hands.", "source": "NICE NG127, updated October 2023."},
  {"id": "MAK-605", "subject": "ENT: throat, sleep & nose", "topic": "HINTS suggesting stroke", "title": "HINTS suggesting stroke", "stem": "A trained clinician performs HINTS in a patient with acute vestibular syndrome. The patient has a normal head-impulse test, direction-changing nystagmus and skew deviation. What should happen next?", "options": {"A": "Routine ENT review", "B": "Reassurance", "C": "Immediate neuroimaging", "D": "Epley manoeuvre", "E": "Ear irrigation"}, "correct_letter": "C", "correct_answer": "C. Immediate neuroimaging", "why_correct": "These are central neurological signs on HINTS and NICE recommends immediate neuroimaging.", "exam_trap": "A normal head impulse test in this context is concerning rather than reassuring.", "takeaway": "Normal head impulse + direction-changing nystagmus/skew → think stroke.", "source": "NICE NG127, updated October 2023."},
  {"id": "MAK-606", "subject": "ENT: throat, sleep & nose", "topic": "HINTS unavailable", "title": "HINTS unavailable", "stem": "A patient has sudden-onset acute vestibular syndrome. No clinician trained in HINTS is available, and BPPV or postural hypotension does not explain the presentation. What is the appropriate management?", "options": {"A": "Discharge with reassurance", "B": "Immediate referral through the stroke pathway", "C": "Routine audiology", "D": "Oral antibiotics", "E": "Ear irrigation"}, "correct_letter": "B", "correct_answer": "B. Immediate referral through the stroke pathway", "why_correct": "NICE recommends immediate referral to exclude posterior-circulation stroke when trained HINTS assessment is unavailable and the presentation is not explained by BPPV or postural hypotension.", "exam_trap": "Lack of HINTS expertise is not a reason to delay assessment.", "takeaway": "Acute vestibular syndrome + no trained HINTS clinician → urgent stroke assessment.", "source": "NICE NG127, updated October 2023."},
  {"id": "MAK-607", "subject": "ENT: throat, sleep & nose", "topic": "Vestibular migraine", "title": "Vestibular migraine", "stem": "A 31-year-old woman has recurrent episodes of dizziness lasting several hours. She has a history of recurrent migraine headaches. Which diagnosis should be considered?", "options": {"A": "Vestibular migraine", "B": "Acute mastoiditis", "C": "Otosclerosis", "D": "Cholesteatoma", "E": "Acute otitis media"}, "correct_letter": "A", "correct_answer": "A. Vestibular migraine", "why_correct": "NICE advises clinicians to consider vestibular migraine in adults with recurrent episodes lasting 5 minutes to 72 hours and a history of recurrent headache.", "exam_trap": "Vestibular migraine can occur even when headache is not present during every vertigo episode.", "takeaway": "Recurrent vertigo 5 min–72 h + migraine history → vestibular migraine.", "source": "NICE NG127, updated October 2023."},
  {"id": "MAK-608", "subject": "ENT: throat, sleep & nose", "topic": "Dizziness after head injury", "title": "Dizziness after head injury", "stem": "A patient develops brief recurrent positional vertigo several days after a head injury. Which diagnosis should be considered?", "options": {"A": "BPPV", "B": "Ménière's disease only", "C": "Otosclerosis", "D": "Nasopharyngeal carcinoma", "E": "Acoustic neuroma as the only possibility"}, "correct_letter": "A", "correct_answer": "A. BPPV", "why_correct": "NICE notes that BPPV is common after head injury.", "exam_trap": "Head trauma can precipitate BPPV; the positional nature and brief attacks remain important.", "takeaway": "Head injury + brief positional vertigo → BPPV is a classic association.", "source": "NICE NG127, updated October 2023."},
  {"id": "MAK-609", "subject": "ENT: throat, sleep & nose", "topic": "Sudden dizziness with new deafness", "title": "Sudden dizziness with new deafness", "stem": "A patient develops sudden severe vertigo with new unilateral deafness and marked unsteadiness. What is the safest initial approach?", "options": {"A": "Assume BPPV", "B": "Immediate assessment for a central neurological cause", "C": "Routine audiology in 6 months", "D": "Ear syringing", "E": "Reassurance"}, "correct_letter": "B", "correct_answer": "B. Immediate assessment for a central neurological cause", "why_correct": "NICE identifies sudden-onset dizziness with new-onset deafness or other focal neurological features as requiring immediate referral when BPPV or postural hypotension does not account for the presentation.", "exam_trap": "New deafness is a neurological red flag in acute dizziness.", "takeaway": "Acute dizziness + new deafness → exclude posterior circulation pathology.", "source": "NICE NG127, updated October 2023."},
  {"id": "MAK-610", "subject": "ENT: throat, sleep & nose", "topic": "expected course", "title": "Acute otitis media: expected course", "stem": "A 4-year-old child has uncomplicated acute otitis media. Which statement about the natural history is most accurate?", "options": {"A": "Symptoms usually last several months", "B": "Most children improve within about 3 days", "C": "All children require antibiotics", "D": "Mastoiditis is expected", "E": "Symptoms always require surgery"}, "correct_letter": "B", "correct_answer": "B. Most children improve within about 3 days", "why_correct": "NICE states that symptoms usually last about 3 days, although they can persist for up to 1 week, and most children improve without antibiotics.", "exam_trap": "Acute otitis media is often self-limiting.", "takeaway": "AOM → usually self-limiting; most improve within ~3 days.", "source": "NICE NG91, updated March 2022."},
  {"id": "MAK-611", "subject": "ENT: throat, sleep & nose", "topic": "Acute otitis media and analgesia", "title": "Acute otitis media and analgesia", "stem": "A child with acute otitis media has significant ear pain. Which treatment should be offered for symptom control?", "options": {"A": "Regular paracetamol or ibuprofen", "B": "Long-term oral steroids", "C": "Anticoagulation", "D": "Immediate grommet insertion", "E": "Antihistamines as routine treatment"}, "correct_letter": "A", "correct_answer": "A. Regular paracetamol or ibuprofen", "why_correct": "NICE recommends regular paracetamol or ibuprofen for pain in children with acute otitis media.", "exam_trap": "Analgesia is central management even when an antibiotic is being considered.", "takeaway": "AOM management starts with pain control.", "source": "NICE NG91, updated March 2022."},
  {"id": "MAK-612", "subject": "ENT: throat, sleep & nose", "topic": "antihistamines", "title": "Acute otitis media: antihistamines", "stem": "A parent asks whether an antihistamine will speed recovery from acute otitis media. What should be explained?", "options": {"A": "They routinely cure AOM", "B": "They reduce the need for analgesia", "C": "Evidence suggests they do not help symptoms", "D": "They prevent mastoiditis", "E": "They are mandatory before antibiotics"}, "correct_letter": "C", "correct_answer": "C. Evidence suggests they do not help symptoms", "why_correct": "NICE advises explaining that decongestants and antihistamines do not help symptoms of acute otitis media.", "exam_trap": "Do not extrapolate treatment of allergic rhinitis to acute middle-ear infection.", "takeaway": "AOM → antihistamines/decongestants do not improve symptoms.", "source": "NICE NG91, updated March 2022."},
  {"id": "MAK-613", "subject": "ENT: throat, sleep & nose", "topic": "otorrhoea", "title": "Acute otitis media: otorrhoea", "stem": "A 3-year-old child has acute otitis media with otorrhoea. Which statement is correct?", "options": {"A": "Antibiotics can never be considered", "B": "This group may be more likely to benefit from antibiotics", "C": "Immediate mastoidectomy is required", "D": "It is diagnostic of cholesteatoma", "E": "No analgesia should be given"}, "correct_letter": "B", "correct_answer": "B. This group may be more likely to benefit from antibiotics", "why_correct": "NICE identifies children of any age with otorrhoea as a group that may be more likely to benefit from antibiotic treatment, while still allowing clinical judgement regarding no, back-up or immediate antibiotics.", "exam_trap": "Otorrhoea increases the likelihood of benefit but does not mean every child automatically requires immediate antibiotics.", "takeaway": "AOM + otorrhoea → antibiotic benefit is more plausible, but assess individually.", "source": "NICE NG91, updated March 2022."},
  {"id": "MAK-614", "subject": "ENT: throat, sleep & nose", "topic": "Bilateral AOM in a young child", "title": "Bilateral AOM in a young child", "stem": "A 20-month-old child has acute otitis media affecting both ears and is otherwise clinically stable. Which statement is correct?", "options": {"A": "Bilateral disease is irrelevant to management", "B": "Children under 2 with bilateral infection may be more likely to benefit from antibiotics", "C": "Surgery is always required", "D": "Antibiotics are contraindicated", "E": "Mastoidectomy is first-line"}, "correct_letter": "B", "correct_answer": "B. Children under 2 with bilateral infection may be more likely to benefit from antibiotics", "why_correct": "NICE identifies children under 2 years with bilateral acute otitis media as a group more likely to benefit from antibiotics.", "exam_trap": "Age and laterality matter.", "takeaway": "AOM under 2 + bilateral → consider greater likelihood of antibiotic benefit.", "source": "NICE NG91, updated March 2022."},
  {"id": "MAK-615", "subject": "ENT: throat, sleep & nose", "topic": "Acute otitis media with mastoiditis", "title": "Acute otitis media with mastoiditis", "stem": "A child with acute otitis media develops post-auricular swelling and tenderness with systemic deterioration. What is the appropriate management?", "options": {"A": "Routine community follow-up", "B": "Hospital referral", "C": "Reassurance", "D": "Earwax treatment", "E": "No further assessment"}, "correct_letter": "B", "correct_answer": "B. Hospital referral", "why_correct": "NICE recommends hospital referral when acute otitis media is associated with acute complications including mastoiditis.", "exam_trap": "Post-auricular swelling in an unwell child is not simple uncomplicated AOM.", "takeaway": "AOM + mastoiditis → hospital.", "source": "NICE NG91, updated March 2022."},
  {"id": "MAK-616", "subject": "ENT: head & neck", "topic": "Acute otitis media with facial paralysis", "title": "Acute otitis media with facial paralysis", "stem": "A child with acute otitis media develops ipsilateral facial nerve paralysis. What should happen?", "options": {"A": "Reassure and review in 6 months", "B": "Hospital referral", "C": "Treat only with topical ear drops", "D": "Hearing aid fitting", "E": "No further investigation"}, "correct_letter": "B", "correct_answer": "B. Hospital referral", "why_correct": "Facial nerve paralysis is listed by NICE as an acute complication of AOM requiring hospital referral.", "exam_trap": "Facial paralysis is a complication, not a routine feature of uncomplicated AOM.", "takeaway": "AOM + facial palsy = complicated disease → hospital.", "source": "NICE NG91, updated March 2022."},
  {"id": "MAK-617", "subject": "ENT: throat, sleep & nose", "topic": "Acute otitis media with meningitis", "title": "Acute otitis media with meningitis", "stem": "A child with acute otitis media develops fever, neck stiffness and reduced consciousness. What is the most appropriate action?", "options": {"A": "Routine ENT referral", "B": "Hospital emergency management", "C": "Oral antihistamine", "D": "Ear irrigation", "E": "Observation at home"}, "correct_letter": "B", "correct_answer": "B. Hospital emergency management", "why_correct": "Meningitis is a serious complication associated with acute otitis media and requires emergency hospital management.", "exam_trap": "Do not anchor on the ear infection when systemic neurological deterioration develops.", "takeaway": "AOM + meningism/reduced consciousness → emergency management.", "source": "NICE NG91, updated March 2022."},
  {"id": "MAK-618", "subject": "ENT: throat, sleep & nose", "topic": "Acute otitis media review", "title": "Acute otitis media review", "stem": "A child with acute otitis media is being managed without an immediate antibiotic prescription. When should the family seek further medical assessment?", "options": {"A": "Only after 6 months", "B": "If symptoms worsen rapidly or significantly, fail to start improving after 3 days, or the child becomes systemically very unwell", "C": "Only if hearing loss persists for 1 year", "D": "Only after a second episode", "E": "Never"}, "correct_letter": "B", "correct_answer": "B. If symptoms worsen rapidly or significantly, fail to start improving after 3 days, or the child becomes systemically very unwell", "why_correct": "NICE gives these safety-netting criteria when an antibiotic is not prescribed immediately.", "exam_trap": "Safety-netting is part of treatment, not an optional extra.", "takeaway": "No immediate antibiotic → explicit 3-day/worsening/systemic safety-net.", "source": "NICE NG91, updated March 2022."},
  {"id": "MAK-619", "subject": "ENT: throat, sleep & nose", "topic": "Adult persistent otorrhoea", "title": "Adult persistent otorrhoea", "stem": "An adult has recurrent ear discharge despite appropriate treatment. The ear canal and tympanic membrane appear abnormal. What is the appropriate next step?", "options": {"A": "Ignore it", "B": "ENT referral", "C": "Routine cardiovascular review", "D": "Long-term antihistamine", "E": "No further examination"}, "correct_letter": "B", "correct_answer": "B. ENT referral", "why_correct": "NICE recommends considering ENT referral where ear discharge has not resolved, has not responded to treatment or recurs, particularly with an abnormal appearance.", "exam_trap": "Persistent/recurrent otorrhoea requires consideration of chronic ear disease.", "takeaway": "Persistent/recurrent otorrhoea → ENT assessment.", "source": "NICE NG98, updated October 2023."},
  {"id": "MAK-620", "subject": "ENT: throat, sleep & nose", "topic": "Adult persistent ear pain", "title": "Adult persistent ear pain", "stem": "An adult has ear pain lasting 10 days despite first-line treatment. There is no obvious acute infection explaining the persistence. What is the appropriate management?", "options": {"A": "No further assessment", "B": "ENT referral", "C": "Ear irrigation indefinitely", "D": "Routine review in 2 years", "E": "Hearing aid only"}, "correct_letter": "B", "correct_answer": "B. ENT referral", "why_correct": "NICE recommends considering ENT referral when ear pain persists for 1 week or more despite first-line treatment.", "exam_trap": "Persistent otalgia may be referred pain from head-and-neck pathology.", "takeaway": "Persistent otalgia despite treatment → investigate the cause.", "source": "NICE NG98, updated October 2023."},
  {"id": "MAK-621", "subject": "ENT: throat, sleep & nose", "topic": "Abnormal tympanic membrane", "title": "Abnormal tympanic membrane", "stem": "An adult has hearing loss and an abnormal tympanic membrane with a visible polypoid growth. What is the appropriate management?", "options": {"A": "Reassurance", "B": "ENT referral", "C": "Routine hearing-aid fitting only", "D": "Antibiotics indefinitely", "E": "No follow-up"}, "correct_letter": "B", "correct_answer": "B. ENT referral", "why_correct": "NICE lists abnormal appearance of the outer ear or eardrum, including polyp formation and abnormal bony or skin growths, as indications to consider ENT referral.", "exam_trap": "A polyp in the ear canal or middle-ear region can represent significant chronic ear disease.", "takeaway": "Abnormal TM/polyp → ENT, not simple hearing-aid management.", "source": "NICE NG98, updated October 2023."},
  {"id": "MAK-622", "subject": "ENT: throat, sleep & nose", "topic": "Middle-ear effusion after URTI", "title": "Middle-ear effusion after URTI", "stem": "An adult develops a middle-ear effusion during an upper respiratory tract infection. It resolves as the infection improves. Which statement is most appropriate?", "options": {"A": "This automatically indicates nasopharyngeal carcinoma", "B": "Persistent effusion after the infection would warrant further assessment", "C": "Immediate cochlear implantation is indicated", "D": "Long-term antibiotics are mandatory", "E": "No examination is ever required"}, "correct_letter": "B", "correct_answer": "B. Persistent effusion after the infection would warrant further assessment", "why_correct": "NICE specifically highlights middle-ear effusion that is absent an acute URTI or persists after an acute URTI as a reason to consider ENT referral.", "exam_trap": "The concerning feature is persistence or lack of an infectious explanation.", "takeaway": "Adult effusion + no/persistent URTI → investigate.", "source": "NICE NG98, updated October 2023."},
  {"id": "MAK-623", "subject": "ENT: throat, sleep & nose", "topic": "Recurrent vertigo and hearing loss", "title": "Recurrent vertigo and hearing loss", "stem": "An adult has recurrent episodes of vertigo with fluctuating hearing loss that are not associated with an upper respiratory infection. What is the appropriate next step?", "options": {"A": "Ignore the hearing symptoms", "B": "Specialist ENT/audiovestibular assessment", "C": "Ear syringing only", "D": "Immediate tonsillectomy", "E": "Long-term antibiotics"}, "correct_letter": "B", "correct_answer": "B. Specialist ENT/audiovestibular assessment", "why_correct": "NICE recommends considering referral for diagnostic investigation where hearing loss fluctuates without an associated URTI, particularly when accompanied by recurrent vertigo.", "exam_trap": "Fluctuating hearing loss plus vertigo suggests inner-ear pathology rather than simple conductive disease.", "takeaway": "Fluctuating hearing loss + recurrent vertigo → audiovestibular/ENT assessment.", "source": "NICE NG98, updated October 2023."},
  {"id": "MAK-624", "subject": "ENT: throat, sleep & nose", "topic": "Tinnitus with recurrent vertigo", "title": "Tinnitus with recurrent vertigo", "stem": "A patient has persistent tinnitus associated with recurrent episodes of vertigo. What is the appropriate principle?", "options": {"A": "It requires no further consideration", "B": "Consider specialist assessment", "C": "Treat as impacted wax without examination", "D": "Start antibiotics automatically", "E": "Immediate laryngectomy"}, "correct_letter": "B", "correct_answer": "B. Consider specialist assessment", "why_correct": "NICE identifies persistent tinnitus associated with vestibular symptoms and recurrent/persistent vertigo as requiring assessment according to the relevant pathway.", "exam_trap": "Tinnitus plus vestibular symptoms broadens the differential beyond isolated benign tinnitus.", "takeaway": "Tinnitus + recurrent vertigo → investigate the vestibular/otological cause.", "source": "NICE NG155, 2020; NICE NG98, updated 2023."},
  {"id": "MAK-625", "subject": "ENT: throat, sleep & nose", "topic": "Distressing tinnitus", "title": "Distressing tinnitus", "stem": "A patient with tinnitus remains severely distressed despite initial tinnitus support, and the distress is preventing normal daily activities. What does NICE recommend?", "options": {"A": "Ignore the psychological impact", "B": "Assessment within 2 weeks", "C": "Routine review after 5 years", "D": "Immediate mastoidectomy", "E": "Antibiotics"}, "correct_letter": "B", "correct_answer": "B. Assessment within 2 weeks", "why_correct": "NICE recommends referral for assessment and management within 2 weeks when tinnitus causes significant distress affecting mental wellbeing despite initial support.", "exam_trap": "The referral criterion is significant persistent distress, not merely the existence of tinnitus.", "takeaway": "Tinnitus causing major persistent distress → expedited assessment.", "source": "NICE NG155, 2020."},
  {"id": "MAK-626", "subject": "ENT: throat, sleep & nose", "topic": "OME reassessment", "title": "OME reassessment", "stem": "A child has bilateral OME with associated hearing loss and is managed initially without surgery. When should hearing be reassessed?", "options": {"A": "1 week", "B": "1 month", "C": "3 months", "D": "1 year", "E": "Only when the child becomes an adult"}, "correct_letter": "C", "correct_answer": "C. 3 months", "why_correct": "NICE recommends reassessing hearing after 3 months in children with bilateral OME and hearing loss.", "exam_trap": "Do not confuse this with the approach to children who have OME without hearing loss.", "takeaway": "Bilateral OME + hearing loss → reassess at 3 months.", "source": "NICE NG233, 2023."},
  {"id": "MAK-627", "subject": "ENT: throat, sleep & nose", "topic": "Unilateral OME with hearing loss", "title": "Unilateral OME with hearing loss", "stem": "A child has unilateral OME associated with hearing loss. Which is the appropriate initial reassessment strategy?", "options": {"A": "Never reassess", "B": "Consider hearing reassessment after 3 months", "C": "Immediate cochlear implant", "D": "Immediate systemic antibiotics", "E": "Immediate tonsillectomy"}, "correct_letter": "B", "correct_answer": "B. Consider hearing reassessment after 3 months", "why_correct": "NICE recommends considering reassessment of hearing after 3 months for unilateral OME with hearing loss.", "exam_trap": "The recommendation differs from bilateral OME but still centres on monitoring hearing and impact.", "takeaway": "Unilateral OME + hearing loss → consider 3-month reassessment.", "source": "NICE NG233, 2023."},
  {"id": "MAK-628", "subject": "ENT: throat, sleep & nose", "topic": "OME and hearing aids", "title": "OME and hearing aids", "stem": "A child has persistent OME-related hearing loss. The family does not want surgery. Which non-surgical option can be considered?", "options": {"A": "Hearing aid", "B": "Long-term systemic antibiotics", "C": "Oral corticosteroids", "D": "Decongestants", "E": "Proton-pump inhibitors"}, "correct_letter": "A", "correct_answer": "A. Hearing aid", "why_correct": "NICE recommends considering air-conduction hearing aids or bone-conduction devices for children with OME-related hearing loss.", "exam_trap": "Hearing support can be an alternative to surgical treatment depending on the individual child and circumstances.", "takeaway": "OME-related hearing loss → hearing support is a legitimate treatment option.", "source": "NICE NG233, 2023."},
  {"id": "MAK-629", "subject": "ENT: throat, sleep & nose", "topic": "OME and adenoid hypertrophy", "title": "OME and adenoid hypertrophy", "stem": "A child has recurrent OME and symptoms suggesting adenoid hypertrophy. Which anatomical structure is particularly relevant to the pathophysiology of Eustachian tube dysfunction?", "options": {"A": "Palatine tonsil only", "B": "Adenoid tissue in the nasopharynx", "C": "Thyroid cartilage", "D": "Epiglottis", "E": "Vocal cord"}, "correct_letter": "B", "correct_answer": "B. Adenoid tissue in the nasopharynx", "why_correct": "Adenoid hypertrophy is associated with OME and can contribute to Eustachian tube dysfunction.", "exam_trap": "The adenoids are in the nasopharynx, not the oropharynx.", "takeaway": "OME + nasal obstruction/snoring → think adenoids.", "source": "NICE NG233, 2023."},
  {"id": "MAK-630", "subject": "ENT: head & neck", "topic": "Facial numbness with facial pain", "title": "Facial numbness with facial pain", "stem": "A 67-year-old patient develops persistent unilateral facial pain accompanied by persistent facial numbness. What is the appropriate management?", "options": {"A": "Reassurance and discharge", "B": "Neuroimaging using a suspected cancer pathway", "C": "Ear irrigation", "D": "Routine dental review only", "E": "Long-term antihistamines"}, "correct_letter": "B", "correct_answer": "B. Neuroimaging using a suspected cancer pathway", "why_correct": "NICE recommends urgent referral for neuroimaging (NG127) in adults with facial pain associated with persistent facial numbness or other abnormal neurological signs. This is a plain urgent neurological referral for neuroimaging, not a suspected cancer pathway (2-week-wait) referral — that mechanism belongs to NG12 and does not apply here.", "exam_trap": "Persistent numbness is a neurological red flag.", "takeaway": "Facial pain + persistent numbness → investigate for significant structural/neurological disease.", "source": "NICE NG127, updated October 2023."},
  {"id": "MAK-631", "subject": "ENT: head & neck", "topic": "Submandibular salivary gland stone", "title": "Submandibular salivary gland stone", "stem": "A 42-year-old man develops recurrent painful swelling beneath the jaw whenever he eats. The swelling settles between meals. What is the most likely diagnosis?", "options": {"A": "Parotid tumour", "B": "Submandibular sialolithiasis", "C": "Thyroid carcinoma", "D": "Branchial cyst", "E": "Lymphoma"}, "correct_letter": "B", "correct_answer": "B. Submandibular sialolithiasis", "why_correct": "Salivary stones commonly obstruct the submandibular gland/duct and classically cause pain and swelling associated with meals because salivary flow increases.", "exam_trap": "Meal-related swelling strongly suggests salivary duct obstruction.", "takeaway": "Painful gland swelling at mealtimes → think salivary stone.", "source": "NHS.uk: \"Salivary gland stones\" patient information page; [BL27]."},
  {"id": "MAK-632", "subject": "ENT: head & neck", "topic": "initial conservative treatment", "title": "Salivary gland stone: initial conservative treatment", "stem": "A patient has a small symptomatic salivary gland stone without systemic infection. Which measure can help promote salivary flow?", "options": {"A": "Fluid restriction", "B": "Sugar-free chewing gum or a sugar-free lozenge", "C": "Long-term corticosteroids", "D": "Anticoagulation", "E": "Immediate total gland excision"}, "correct_letter": "B", "correct_answer": "B. Sugar-free chewing gum or a sugar-free lozenge", "why_correct": "Increasing salivary flow can help a small stone pass. Hydration, gentle gland massage and sialogogues such as sugar-free gum or sweets can be used.", "exam_trap": "Do not attempt to remove a stone with a sharp object.", "takeaway": "Small salivary stone → hydrate + stimulate saliva + gentle massage.", "source": "NHS.uk: \"Salivary gland stones\" patient information page; [BL27]."},
  {"id": "MAK-633", "subject": "ENT: head & neck", "topic": "Salivary stone with infection", "title": "Salivary stone with infection", "stem": "A patient with a known salivary gland stone develops increasing gland swelling, erythema, purulent discharge and fever. What complication has developed?", "options": {"A": "Acute sialadenitis", "B": "Cholesteatoma", "C": "Ménière's disease", "D": "Otosclerosis", "E": "Vocal-cord paralysis"}, "correct_letter": "A", "correct_answer": "A. Acute sialadenitis", "why_correct": "Obstruction of salivary flow by a stone can predispose to infection of the gland.", "exam_trap": "The stone explains the obstruction; fever, erythema and purulent discharge indicate superimposed infection.", "takeaway": "Obstruction + fever/pus → infected salivary gland.", "source": "NHS.uk: \"Salivary gland stones\" patient information page; [BL27]."},
  {"id": "MAK-634", "subject": "ENT: head & neck", "topic": "Parotid duct location", "title": "Parotid duct location", "stem": "A surgeon is examining the oral cavity of a patient with suspected parotid duct obstruction. Where does the parotid duct normally open?", "options": {"A": "Behind the lower central incisor", "B": "Opposite the upper second molar", "C": "At the tip of the tongue", "D": "In the tonsillar fossa", "E": "At the vallecula"}, "correct_letter": "B", "correct_answer": "B. Opposite the upper second molar", "why_correct": "The parotid duct crosses the masseter, turns medially and opens into the oral cavity opposite the upper second molar.", "exam_trap": "The submandibular duct instead opens beside the frenulum of the tongue.", "takeaway": "Parotid duct → opposite upper second molar.", "source": "Standard surgical anatomy; NHS Greater Glasgow and Clyde ENT referral guidance, reviewed 2025."},
  {"id": "MAK-635", "subject": "ENT: head & neck", "topic": "Submandibular duct location", "title": "Submandibular duct location", "stem": "A patient has a suspected submandibular duct stone. Where should the clinician inspect the oral cavity?", "options": {"A": "Hard palate", "B": "Floor of the mouth beside the lingual frenulum", "C": "Buccal mucosa opposite the upper second molar", "D": "Posterior pharyngeal wall", "E": "Vallecula"}, "correct_letter": "B", "correct_answer": "B. Floor of the mouth beside the lingual frenulum", "why_correct": "Wharton's duct opens in the floor of the mouth beside the lingual frenulum.", "exam_trap": "Do not confuse Wharton's duct with Stensen's duct.", "takeaway": "Submandibular duct → floor of mouth.", "source": "Standard surgical anatomy; NHS Greater Glasgow and Clyde ENT guidance, reviewed 2025."},
  {"id": "MAK-636", "subject": "ENT: head & neck", "topic": "Parotid swelling and facial nerve", "title": "Parotid swelling and facial nerve", "stem": "A 59-year-old patient has a persistent unilateral parotid mass. Which nerve is particularly important when assessing a parotid lesion?", "options": {"A": "Facial nerve", "B": "Phrenic nerve", "C": "Hypoglossal nerve", "D": "Femoral nerve", "E": "Median nerve"}, "correct_letter": "A", "correct_answer": "A. Facial nerve", "why_correct": "The facial nerve passes through the parotid gland and divides into its terminal branches within the gland. Facial weakness in association with a parotid mass is therefore an important clinical finding.", "exam_trap": "The facial nerve does not provide the parasympathetic secretomotor supply to the parotid; that pathway involves CN IX.", "takeaway": "Parotid mass → always assess facial nerve function.", "source": "Standard head-and-neck surgical anatomy; NICE NG36"},
  {"id": "MAK-637", "subject": "ENT: head & neck", "topic": "Facial weakness with parotid mass", "title": "Facial weakness with parotid mass", "stem": "A patient with a longstanding parotid mass develops new ipsilateral facial weakness. Which interpretation is most concerning?", "options": {"A": "This proves the lesion is benign", "B": "Facial nerve dysfunction is a concerning feature requiring specialist assessment", "C": "It confirms a salivary stone", "D": "It excludes malignancy", "E": "It is diagnostic of Bell's palsy"}, "correct_letter": "B", "correct_answer": "B. Facial nerve dysfunction is a concerning feature requiring specialist assessment", "why_correct": "A parotid mass associated with facial nerve dysfunction raises concern for malignant or locally invasive disease.", "exam_trap": "Do not diagnose Bell's palsy when facial weakness occurs in the setting of a structural parotid lesion.", "takeaway": "Parotid mass + facial weakness → red flag for malignancy/invasion.", "source": "Standard head-and-neck oncology practice; NICE NG36; NICE NG12(urgent referral criteria for suspected head and neck cancer)."},
  {"id": "MAK-638", "subject": "ENT: head & neck", "topic": "Neck lump investigation", "title": "Neck lump investigation", "stem": "An adult has a persistent unexplained neck lump suspicious for an upper aerodigestive tract malignancy. Which investigation can be used to obtain cytology while reducing the risk associated with blind sampling?", "options": {"A": "Ultrasound-guided fine-needle aspiration", "B": "Diagnostic laparotomy", "C": "Lumbar puncture", "D": "Bone marrow biopsy", "E": "Colonoscopy"}, "correct_letter": "A", "correct_answer": "A. Ultrasound-guided fine-needle aspiration", "why_correct": "NICE recommends considering ultrasound guidance when performing FNA or core biopsy of a neck lump suspected to represent upper aerodigestive tract cancer.", "exam_trap": "An unexplained adult neck lump should not simply be excised without an appropriate diagnostic pathway.", "takeaway": "Suspicious neck lump → imaging + appropriately guided tissue sampling.", "source": "NICE NG36 (2016)."},
  {"id": "MAK-639", "subject": "ENT: head & neck", "topic": "Unknown primary with metastatic cervical SCC", "title": "Unknown primary with metastatic cervical SCC", "stem": "A patient has cervical lymph-node metastases confirmed as squamous cell carcinoma, but no primary tumour is identified clinically. Which imaging investigation may be used to search for an occult upper aerodigestive tract primary?", "options": {"A": "FDG PET-CT", "B": "Plain abdominal radiograph", "C": "DEXA scan", "D": "Renal ultrasound", "E": "Echocardiography"}, "correct_letter": "A", "correct_answer": "A. FDG PET-CT", "why_correct": "NICE recommends considering FDG PET-CT as the first investigation to identify the primary site when metastatic nodal squamous cell carcinoma is suspected to arise from the upper aerodigestive tract.", "exam_trap": "This is an occult-primary problem, not simply unexplained cervical lymphadenopathy.", "takeaway": "Cervical metastatic SCC + unknown primary → PET-CT can search for the occult primary.", "source": "NICE NG36 (2016)."},
  {"id": "MAK-640", "subject": "ENT: head & neck", "topic": "Thyroid swelling with airway compromise", "title": "Thyroid swelling with airway compromise", "stem": "A patient with a large thyroid swelling develops stridor and increasing difficulty breathing. What is the appropriate response?", "options": {"A": "Routine thyroid clinic referral", "B": "Immediate airway assessment and emergency management", "C": "Reassurance", "D": "Oral antibiotics only", "E": "Review in 6 months"}, "correct_letter": "B", "correct_answer": "B. Immediate airway assessment and emergency management", "why_correct": "Stridor from a thyroid swelling indicates potential airway compromise.", "exam_trap": "The presence of a thyroid mass does not make the airway problem less urgent.", "takeaway": "Neck mass + stridor → airway emergency.", "source": "NICE NG12 (updated 2025)."},
  {"id": "MAK-641", "subject": "ENT: head & neck", "topic": "Vocal-cord paralysis", "title": "Vocal-cord paralysis", "stem": "A patient develops unilateral vocal-cord paralysis after thyroid surgery. Which nerve has most likely been injured?", "options": {"A": "Recurrent laryngeal nerve", "B": "Optic nerve", "C": "Facial nerve", "D": "Accessory nerve", "E": "Greater auricular nerve"}, "correct_letter": "A", "correct_answer": "A. Recurrent laryngeal nerve", "why_correct": "The recurrent laryngeal nerves supply most intrinsic muscles of the larynx and are vulnerable during thyroid surgery.", "exam_trap": "External branch of the superior laryngeal nerve injury primarily affects pitch rather than producing the classic unilateral vocal-cord paralysis.", "takeaway": "Thyroid surgery + vocal-cord palsy → recurrent laryngeal nerve.", "source": "Standard surgical anatomy and thyroid-surgery principles."},
  {"id": "MAK-642", "subject": "ENT: head & neck", "topic": "Bilateral recurrent laryngeal nerve injury", "title": "Bilateral recurrent laryngeal nerve injury", "stem": "A patient develops bilateral vocal-cord paralysis following neck surgery. Which complication is most concerning?", "options": {"A": "Airway obstruction", "B": "Diarrhoea", "C": "Renal failure", "D": "Visual loss", "E": "Lower-limb weakness"}, "correct_letter": "A", "correct_answer": "A. Airway obstruction", "why_correct": "Bilateral vocal-cord paralysis can leave the cords close to the midline and significantly narrow the airway.", "exam_trap": "Bilateral recurrent laryngeal nerve injury can produce a more serious airway problem than unilateral palsy.", "takeaway": "Bilateral RLN palsy → think airway.", "source": "Standard surgical anatomy and postoperative airway management principles."},
  {"id": "MAK-643", "subject": "ENT: head & neck", "topic": "External branch of superior laryngeal nerve", "title": "External branch of superior laryngeal nerve", "stem": "A professional singer develops difficulty producing high-pitched sounds after thyroid surgery. Which nerve is most likely to have been injured?", "options": {"A": "External branch of the superior laryngeal nerve", "B": "Hypoglossal nerve", "C": "Facial nerve", "D": "Glossopharyngeal nerve", "E": "Greater occipital nerve"}, "correct_letter": "A", "correct_answer": "A. External branch of the superior laryngeal nerve", "why_correct": "The external branch supplies the cricothyroid muscle, which tenses and lengthens the vocal cords and contributes to production of high-pitched sounds.", "exam_trap": "Do not automatically attribute every post-thyroid voice problem to recurrent laryngeal nerve injury.", "takeaway": "Loss of high pitch after thyroid surgery → external SLN.", "source": "Standard surgical anatomy."},
  {"id": "MAK-644", "subject": "ENT: head & neck", "topic": "Laryngeal cartilage", "title": "Laryngeal cartilage", "stem": "Which laryngeal cartilage forms the main anterior and lateral framework of the larynx and is commonly known as the \"Adam's apple\"?", "options": {"A": "Cricoid", "B": "Thyroid", "C": "Arytenoid", "D": "Corniculate", "E": "Cuneiform"}, "correct_letter": "B", "correct_answer": "B. Thyroid", "why_correct": "The thyroid cartilage forms the largest cartilage of the laryngeal skeleton and creates the laryngeal prominence.", "exam_trap": "The cricoid is the only complete cartilaginous ring of the airway.", "takeaway": "Adam's apple = thyroid cartilage.", "source": "Standard surgical anatomy."},
  {"id": "MAK-645", "subject": "ENT: head & neck", "topic": "Cricoid cartilage", "title": "Cricoid cartilage", "stem": "Which statement about the cricoid cartilage is correct?", "options": {"A": "It is an incomplete anterior ring", "B": "It is the only complete cartilaginous ring of the airway", "C": "It forms the epiglottis", "D": "It contains the vocal cords", "E": "It is part of the hyoid bone"}, "correct_letter": "B", "correct_answer": "B. It is the only complete cartilaginous ring of the airway", "why_correct": "The cricoid forms a complete ring around the airway.", "exam_trap": "The tracheal rings are incomplete posteriorly; the cricoid is complete.", "takeaway": "Cricoid = complete airway ring.", "source": "Standard surgical anatomy."},
  {"id": "MAK-646", "subject": "ENT: head & neck", "topic": "Cricothyroid membrane", "title": "Cricothyroid membrane", "stem": "In an emergency airway procedure, which structure lies between the thyroid and cricoid cartilages?", "options": {"A": "Cricothyroid membrane", "B": "Thyrohyoid membrane only", "C": "Vocal ligament", "D": "Pharyngobasilar fascia", "E": "Buccopharyngeal fascia"}, "correct_letter": "A", "correct_answer": "A. Cricothyroid membrane", "why_correct": "The cricothyroid membrane lies between the thyroid cartilage and cricoid cartilage and is an important anatomical landmark for emergency front-of-neck access.", "exam_trap": "It is below the thyroid cartilage and above the cricoid cartilage.", "takeaway": "Thyroid → cricothyroid membrane → cricoid.", "source": "Standard surgical anatomy."},
  {"id": "MAK-647", "subject": "ENT: head & neck", "topic": "Laryngeal inlet", "title": "Laryngeal inlet", "stem": "Which structure forms the anterior boundary of the laryngeal inlet?", "options": {"A": "Epiglottis", "B": "Cricoid cartilage", "C": "Arytenoid cartilage", "D": "Vocal ligament", "E": "Hyoid body"}, "correct_letter": "A", "correct_answer": "A. Epiglottis", "why_correct": "The epiglottis forms the anterior boundary of the laryngeal inlet.", "exam_trap": "The aryepiglottic folds form the lateral boundaries.", "takeaway": "Laryngeal inlet → epiglottis anteriorly.", "source": "Standard surgical anatomy."},
  {"id": "MAK-648", "subject": "ENT: head & neck", "topic": "Sensory supply above the vocal cords", "title": "Sensory supply above the vocal cords", "stem": "Which nerve carries sensation from the larynx above the vocal cords?", "options": {"A": "Internal branch of superior laryngeal nerve", "B": "Recurrent laryngeal nerve", "C": "Hypoglossal nerve", "D": "Facial nerve", "E": "Glossopharyngeal nerve"}, "correct_letter": "A", "correct_answer": "A. Internal branch of superior laryngeal nerve", "why_correct": "The internal laryngeal nerve, a branch of the superior laryngeal nerve, supplies sensation above the vocal folds.", "exam_trap": "The recurrent laryngeal nerve supplies sensation below the vocal folds.", "takeaway": "Above cords = internal SLN; below cords = RLN.", "source": "Standard surgical anatomy."},
  {"id": "MAK-649", "subject": "ENT: head & neck", "topic": "Laryngeal sensation below the vocal cords", "title": "Laryngeal sensation below the vocal cords", "stem": "Which nerve carries sensory fibres from the larynx below the vocal cords?", "options": {"A": "Recurrent laryngeal nerve", "B": "Internal superior laryngeal nerve", "C": "Facial nerve", "D": "Hypoglossal nerve", "E": "Greater auricular nerve"}, "correct_letter": "A", "correct_answer": "A. Recurrent laryngeal nerve", "why_correct": "The recurrent laryngeal nerve provides sensation below the vocal folds as well as motor supply to most intrinsic laryngeal muscles.", "exam_trap": "Do not interchange the sensory territories of the two laryngeal nerves.", "takeaway": "Below cords = recurrent laryngeal nerve.", "source": "Standard surgical anatomy."},
  {"id": "MAK-650", "subject": "ENT: head & neck", "topic": "early glottic disease", "title": "Laryngeal cancer: early glottic disease", "stem": "A patient is diagnosed with a newly diagnosed T1a squamous-cell carcinoma of the glottic larynx. Which treatment does NICE recommend?", "options": {"A": "Transoral laser microsurgery", "B": "Total oesophagectomy", "C": "Radical neck dissection alone", "D": "Total laryngectomy for all patients", "E": "Antibiotic therapy"}, "correct_letter": "A", "correct_answer": "A. Transoral laser microsurgery", "why_correct": "NICE recommends transoral laser microsurgery for newly diagnosed T1a squamous-cell carcinoma of the glottic larynx.", "exam_trap": "Do not automatically equate early glottic cancer with total laryngectomy.", "takeaway": "T1a glottic SCC → transoral laser microsurgery.", "source": "NICE NG36 (2016)."},
  {"id": "MAK-651", "subject": "ENT: head & neck", "topic": "Early glottic cancer T1b–T2", "title": "Early glottic cancer T1b–T2", "stem": "A patient has T1b–T2 squamous-cell carcinoma of the glottic larynx. Which treatment options does NICE recognise?", "options": {"A": "Transoral laser microsurgery or radiotherapy", "B": "Antibiotics or observation", "C": "Total laryngectomy only", "D": "Thyroidectomy or chemotherapy only", "E": "No treatment"}, "correct_letter": "A", "correct_answer": "A. Transoral laser microsurgery or radiotherapy", "why_correct": "NICE recommends a choice between transoral laser microsurgery and radiotherapy for T1b–T2 glottic squamous-cell carcinoma.", "exam_trap": "The treatment choice depends on tumour and patient factors rather than one universal operation.", "takeaway": "Early glottic SCC → organ-preserving treatment options exist.", "source": "NICE NG36 (2016)."},
  {"id": "MAK-652", "subject": "ENT: head & neck", "topic": "Advanced laryngeal cancer and treatment choice", "title": "Advanced laryngeal cancer and treatment choice", "stem": "A patient has T3 squamous-cell carcinoma of the larynx. Which treatment options are recognised by NICE?", "options": {"A": "Radiotherapy with concomitant chemotherapy or surgery with adjuvant radiotherapy ± chemotherapy", "B": "Antibiotics alone", "C": "Observation only", "D": "Tonsillectomy alone", "E": "Ear surgery"}, "correct_letter": "A", "correct_answer": "A. Radiotherapy with concomitant chemotherapy or surgery with adjuvant radiotherapy ± chemotherapy", "why_correct": "NICE recommends discussing these treatment approaches for T3 laryngeal SCC.", "exam_trap": "Treatment decisions in advanced laryngeal cancer involve both oncological control and preservation of airway, swallowing and voice.", "takeaway": "T3 laryngeal SCC → multidisciplinary organ-preservation versus surgical strategy.", "source": "NICE NG36 (2016)."},
  {"id": "MAK-653", "subject": "ENT: head & neck", "topic": "Neck node metastasis in head-and-neck SCC", "title": "Neck node metastasis in head-and-neck SCC", "stem": "A patient has a small oral cavity squamous-cell carcinoma with a clinically N0 neck. Which principle applies to early oral cavity cancer?", "options": {"A": "The neck can never require treatment", "B": "Surgical management of the neck should be offered", "C": "Antibiotics eradicate occult nodal disease", "D": "Neck dissection is prohibited", "E": "Only chest imaging is required"}, "correct_letter": "B", "correct_answer": "B. Surgical management of the neck should be offered", "why_correct": "NICE recommends surgical management of the neck for early T1–T2, N0 oral cavity cancer.", "exam_trap": "A clinically negative neck does not necessarily mean there is no risk of occult nodal metastasis.", "takeaway": "Early oral SCC → consider management of the clinically N0 neck.", "source": "NICE NG36 (2016)."},
  {"id": "MAK-654", "subject": "ENT: head & neck", "topic": "Sentinel node biopsy in oral cancer", "title": "Sentinel node biopsy in oral cancer", "stem": "A patient has T1–T2 N0 oral cavity cancer and is being considered for surgical management of the neck. Which alternative to elective neck dissection does NICE recognise in suitable patients?", "options": {"A": "Sentinel lymph-node biopsy", "B": "Lumbar puncture", "C": "Bone marrow aspiration", "D": "Carotid stenting", "E": "No nodal assessment"}, "correct_letter": "A", "correct_answer": "A. Sentinel lymph-node biopsy", "why_correct": "NICE recommends sentinel lymph-node biopsy as an alternative to elective neck dissection for suitable patients with early T1–T2 N0 oral cavity cancer, unless cervical access is already required for another reason such as free-flap reconstruction.", "exam_trap": "This is specific to selected early oral cavity cancer, not all head-and-neck cancers.", "takeaway": "Early oral SCC, N0 → sentinel node biopsy can replace elective neck dissection in selected patients.", "source": "NICE NG36 (2016)."},
  {"id": "MAK-655", "subject": "ENT: head & neck", "topic": "Head-and-neck cancer MDT", "title": "Head-and-neck cancer MDT", "stem": "A patient has newly diagnosed upper aerodigestive tract squamous-cell carcinoma. Where should definitive treatment planning occur?", "options": {"A": "Solely in primary care", "B": "Multidisciplinary head-and-neck cancer team", "C": "Emergency department only", "D": "Community pharmacy", "E": "No multidisciplinary discussion is required"}, "correct_letter": "B", "correct_answer": "B. Multidisciplinary head-and-neck cancer team", "why_correct": "Head-and-neck cancers require coordinated assessment and treatment planning involving appropriate surgical, oncological, radiological, pathological and supportive disciplines.", "exam_trap": "Do not treat complex head-and-neck malignancy as an isolated surgical problem.", "takeaway": "Head-and-neck cancer → MDT planning.", "source": "NICE head-and-neck cancer service guidance; NICE NG36."},
  {"id": "MAK-656", "subject": "ENT: head & neck", "topic": "Persistent unilateral throat pain with otalgia", "title": "Persistent unilateral throat pain with otalgia", "stem": "A 58-year-old patient has persistent unilateral throat pain for more than 4 weeks and referred unilateral ear pain. Otoscopy is normal. What should be considered?", "options": {"A": "Head-and-neck malignancy", "B": "Simple otitis externa", "C": "Ménière's disease", "D": "Otosclerosis", "E": "BPPV"}, "correct_letter": "A", "correct_answer": "A. Head-and-neck malignancy", "why_correct": "Referred otalgia with normal otoscopy can arise from pathology in the pharynx, larynx or other head-and-neck structures. Persistent unilateral symptoms are a red flag.", "exam_trap": "A normal ear examination does not exclude significant head-and-neck pathology.", "takeaway": "Normal ear + persistent unilateral otalgia → examine the throat/head and neck.", "source": "NICE NG12 and head-and-neck cancer referral framework."},
  {"id": "MAK-657", "subject": "ENT: head & neck", "topic": "avoid blind excision", "title": "Neck lump: avoid blind excision", "stem": "An adult presents with an unexplained cervical lymph-node mass suspicious for metastatic head-and-neck cancer. Which approach should generally be avoided as the initial diagnostic procedure?", "options": {"A": "Appropriate specialist assessment", "B": "Ultrasound-guided FNA where indicated", "C": "Unplanned open excision of the neck mass", "D": "Imaging", "E": "Upper aerodigestive tract assessment"}, "correct_letter": "C", "correct_answer": "C. Unplanned open excision of the neck mass", "why_correct": "A persistent adult neck lump may represent metastatic malignancy. Diagnostic evaluation should be appropriately planned, often using imaging and needle sampling rather than simply excising the node without establishing the diagnostic pathway.", "exam_trap": "An apparently isolated lymph node may be the first manifestation of a head-and-neck primary.", "takeaway": "Adult neck lump → investigate systematically before excision.", "source": "NICE NG36 (2016)."},
  {"id": "MAK-658", "subject": "ENT: head & neck", "topic": "Dysphagia with head-and-neck symptoms", "title": "Dysphagia with head-and-neck symptoms", "stem": "A 64-year-old smoker develops progressive dysphagia accompanied by persistent hoarseness and an unexplained neck lump. What is the most appropriate overall approach?", "options": {"A": "Treat reflux for several months without investigation", "B": "Urgent assessment for head-and-neck malignancy", "C": "Routine audiology", "D": "Ear irrigation", "E": "Reassurance"}, "correct_letter": "B", "correct_answer": "B. Urgent assessment for head-and-neck malignancy", "why_correct": "The combination of progressive swallowing difficulty, persistent hoarseness and an unexplained neck lump is concerning for upper aerodigestive tract malignancy.", "exam_trap": "Multiple converging red flags should increase urgency rather than being treated as separate minor symptoms.", "takeaway": "Progressive dysphagia + hoarseness + neck lump → cancer pathway.", "source": "NICE NG12 (updated 2025)."},
  {"id": "MAK-659", "subject": "ENT: head & neck", "topic": "Trismus and oral malignancy", "title": "Trismus and oral malignancy", "stem": "A 60-year-old patient develops persistent trismus associated with an unexplained oral lesion. Which diagnosis should be considered?", "options": {"A": "Oral/head-and-neck malignancy", "B": "BPPV", "C": "Otosclerosis", "D": "Simple otitis externa", "E": "Ménière's disease"}, "correct_letter": "A", "correct_answer": "A. Oral/head-and-neck malignancy", "why_correct": "Persistent trismus associated with oral or oropharyngeal pathology can indicate infiltrative head-and-neck disease and warrants appropriate assessment.", "exam_trap": "Do not attribute persistent unexplained trismus automatically to temporomandibular dysfunction.", "takeaway": "Persistent trismus + suspicious oral lesion → investigate malignancy.", "source": "NICE NG36 (2016); NICE NG12 (updated 2025)."},
  {"id": "MAK-660", "subject": "ENT: head & neck", "topic": "Neck lump and occult primary", "title": "Neck lump and occult primary", "stem": "A patient has a cervical lymph-node biopsy showing metastatic squamous-cell carcinoma, but clinical examination does not identify a primary tumour. Which statement is most accurate?", "options": {"A": "The lymph node should simply be excised and no further investigation undertaken", "B": "The upper aerodigestive tract should be systematically investigated for an occult primary", "C": "The diagnosis must be lymphoma", "D": "The primary tumour must be in the colon", "E": "No imaging is useful"}, "correct_letter": "B", "correct_answer": "B. The upper aerodigestive tract should be systematically investigated for an occult primary", "why_correct": "Metastatic cervical squamous-cell carcinoma may arise from an occult upper aerodigestive tract primary. NICE recommends a structured diagnostic pathway, including FDG PET-CT in appropriate patients and subsequent targeted assessment when the primary remains unidentified.", "exam_trap": "Cervical metastatic SCC is not itself the primary diagnosis; the primary site must be sought.", "takeaway": "Cervical metastatic SCC + unknown primary → structured head-and-neck occult-primary work-up.", "source": "NICE NG36 (2016)."},
  {"id": "MAK-661", "subject": "ENT: throat, sleep & nose", "topic": "natural history", "title": "Acute sore throat: natural history", "stem": "A 24-year-old patient presents with an uncomplicated acute sore throat. There are no features suggesting a serious complication. Which statement is most accurate?", "options": {"A": "Most cases require antibiotics", "B": "Symptoms commonly last around 1 week and usually resolve without antibiotics", "C": "Symptoms normally persist for 4–6 weeks", "D": "Tonsillectomy is usually indicated", "E": "IV antibiotics are routinely required"}, "correct_letter": "B", "correct_answer": "B. Symptoms commonly last around 1 week and usually resolve without antibiotics", "why_correct": "Acute sore throat, including pharyngitis and tonsillitis, is usually self-limiting. NICE states that symptoms can last around 1 week and most people recover without antibiotics.", "exam_trap": "A sore throat does not automatically mean bacterial infection.", "takeaway": "Acute sore throat → usually self-limiting.", "source": "NICE NG84, 2018."},
  {"id": "MAK-662", "subject": "ENT: throat, sleep & nose", "topic": "FeverPAIN", "title": "FeverPAIN", "stem": "Which clinical scoring system can help identify adults and children who are more likely to benefit from antibiotics for acute sore throat?", "options": {"A": "Wells score", "B": "FeverPAIN", "C": "CHA₂DS₂-VASc", "D": "CURB-65", "E": "Glasgow-Blatchford score"}, "correct_letter": "B", "correct_answer": "B. FeverPAIN", "why_correct": "NICE recommends FeverPAIN or Centor criteria to identify people with acute sore throat who are more likely to benefit from antibiotics.", "exam_trap": "FeverPAIN is for acute sore throat; it is not a general sepsis score.", "takeaway": "Sore throat antibiotic decision → FeverPAIN or Centor.", "source": "NICE NG84, 2018."},
  {"id": "MAK-663", "subject": "ENT: throat, sleep & nose", "topic": "Acute sore throat and dehydration", "title": "Acute sore throat and dehydration", "stem": "A 9-year-old child with acute tonsillitis is unable to drink adequately and is becoming dehydrated. What is the most important immediate management priority?", "options": {"A": "Tonsillectomy", "B": "Assess and treat dehydration", "C": "Long-term prophylactic antibiotics", "D": "Hearing assessment", "E": "Nasal surgery"}, "correct_letter": "B", "correct_answer": "B. Assess and treat dehydration", "why_correct": "In acute throat infection, inability to maintain hydration is a clinically important complication requiring active management.", "exam_trap": "The immediate surgical principle is not simply to label the infection; assess the child's physiological status.", "takeaway": "Sore throat + inability to drink → think hydration and systemic status first.", "source": "NICE NG84, 2018; general paediatric acute-care principles."},
  {"id": "MAK-664", "subject": "ENT: throat, sleep & nose", "topic": "Antibiotics and acute sore throat", "title": "Antibiotics and acute sore throat", "stem": "A patient with uncomplicated acute sore throat asks why antibiotics are not automatically prescribed. What is the best explanation?", "options": {"A": "Antibiotics are never effective against bacteria", "B": "Most sore throats resolve without antibiotics and antibiotics provide limited benefit for many patients", "C": "Antibiotics always cause serious harm", "D": "Sore throat is always fungal", "E": "Antibiotics prevent all future episodes"}, "correct_letter": "B", "correct_answer": "B. Most sore throats resolve without antibiotics and antibiotics provide limited benefit for many patients", "why_correct": "NICE emphasises the self-limiting nature of acute sore throat and recommends using clinical scoring to identify patients more likely to benefit from antibiotics.", "exam_trap": "Avoid the false dichotomy that either every sore throat needs antibiotics or antibiotics are never appropriate.", "takeaway": "Antibiotics are selective, not automatic, in acute sore throat.", "source": "NICE NG84, 2018."},
  {"id": "MAK-665", "subject": "ENT: throat, sleep & nose", "topic": "Tonsillectomy for recurrent tonsillitis", "title": "Tonsillectomy for recurrent tonsillitis", "stem": "A patient has recurrent, severe, documented episodes of acute tonsillitis that substantially interfere with normal activities despite appropriate medical management. Which intervention may be considered after specialist assessment?", "options": {"A": "Tonsillectomy", "B": "Cochlear implantation", "C": "Mastoidectomy", "D": "Tympanoplasty", "E": "Thyroidectomy"}, "correct_letter": "A", "correct_answer": "A. Tonsillectomy", "why_correct": "Recurrent, clinically significant tonsillitis is an established indication for considering tonsillectomy after appropriate specialist assessment.", "exam_trap": "The indication is recurrent clinically significant disease, not simply having large tonsils.", "takeaway": "Recurrent disabling tonsillitis → consider tonsillectomy.", "source": "[SIGN117]: Management of Sore Throat and Indications for Tonsillectomy; [ENTUK] guidance on tonsillectomy, which set out recurrent acute or chronic tonsillitis as an indication for tonsillectomy."},
  {"id": "MAK-666", "subject": "ENT: throat, sleep & nose", "topic": "Tonsillectomy and obstructive symptoms", "title": "Tonsillectomy and obstructive symptoms", "stem": "A child has markedly enlarged tonsils causing obstructive breathing during sleep. Which operation may be considered?", "options": {"A": "Tonsillectomy/adenotonsillar surgery", "B": "Tympanoplasty", "C": "Parotidectomy", "D": "Septoplasty only", "E": "Cochlear implantation"}, "correct_letter": "A", "correct_answer": "A. Tonsillectomy/adenotonsillar surgery", "why_correct": "Enlarged tonsils and adenoids are important causes of paediatric obstructive sleep apnoea. Children with symptoms of sleep apnoea should be referred for specialist assessment.", "exam_trap": "Persistent sleep apnoea is not simply normal childhood snoring.", "takeaway": "Child + obstructive sleep symptoms + enlarged tonsils/adenoids → ENT assessment.", "source": "NICE NG127 (2019)."},
  {"id": "MAK-667", "subject": "ENT: throat, sleep & nose", "topic": "Paediatric obstructive sleep apnoea", "title": "Paediatric obstructive sleep apnoea", "stem": "A 7-year-old child snores loudly and has witnessed pauses in breathing during sleep. What is the most appropriate next step?", "options": {"A": "Reassurance only", "B": "Referral to ENT or paediatric respiratory services", "C": "Immediate antibiotics", "D": "Ear irrigation", "E": "No investigation unless daytime sleepiness develops"}, "correct_letter": "B", "correct_answer": "B. Referral to ENT or paediatric respiratory services", "why_correct": "NICE recommends referral of children with symptoms of sleep apnoea to ENT or paediatric respiratory services.", "exam_trap": "Daytime sleepiness is not required before referral.", "takeaway": "Child with witnessed apnoea → specialist assessment.", "source": "NICE NG127 (2019)."},
  {"id": "MAK-668", "subject": "ENT: throat, sleep & nose", "topic": "when to suspect", "title": "Adult OSAHS: when to suspect", "stem": "Which combination most strongly suggests obstructive sleep apnoea/hypopnoea syndrome in an adult?", "options": {"A": "Snoring and witnessed apnoeas", "B": "Isolated anosmia", "C": "Tinnitus and hearing loss", "D": "Recurrent epistaxis", "E": "Dysphagia alone"}, "correct_letter": "A", "correct_answer": "A. Snoring and witnessed apnoeas", "why_correct": "NICE recommends assessing adults for OSAHS when they have two or more suggestive features, including snoring, witnessed apnoeas, unrefreshing sleep, waking headaches and excessive daytime sleepiness.", "exam_trap": "OSAHS is not diagnosed from snoring alone.", "takeaway": "Snoring + witnessed apnoea → think OSAHS.", "source": "NICE NG202, 2021."},
  {"id": "MAK-669", "subject": "ENT: throat, sleep & nose", "topic": "OSAHS diagnostic investigation", "title": "OSAHS diagnostic investigation", "stem": "An adult has suspected OSAHS based on clinical assessment. Which investigation should NICE recommend?", "options": {"A": "Home respiratory polygraphy", "B": "Routine CT head", "C": "Diagnostic bronchoscopy in every patient", "D": "Echocardiography", "E": "Colonoscopy"}, "correct_letter": "A", "correct_answer": "A. Home respiratory polygraphy", "why_correct": "NICE recommends offering home respiratory polygraphy to people with suspected OSAHS.", "exam_trap": "Do not assume that full inpatient polysomnography is required for every patient.", "takeaway": "Suspected adult OSAHS → home respiratory polygraphy.", "source": "NICE NG202, 2021."},
  {"id": "MAK-670", "subject": "ENT: throat, sleep & nose", "topic": "OSAHS and negative oximetry", "title": "OSAHS and negative oximetry", "stem": "A patient has significant symptoms strongly suggestive of OSAHS, but home oximetry is negative. What is the appropriate next investigation?", "options": {"A": "Stop investigating", "B": "Consider respiratory polygraphy or polysomnography", "C": "Tonsillectomy immediately", "D": "Antibiotics", "E": "CT abdomen"}, "correct_letter": "B", "correct_answer": "B. Consider respiratory polygraphy or polysomnography", "why_correct": "NICE recommends considering respiratory polygraphy or polysomnography when oximetry is negative but significant symptoms persist.", "exam_trap": "A negative oximetry result does not necessarily exclude OSAHS.", "takeaway": "High clinical suspicion + negative oximetry → further sleep investigation.", "source": "NICE NG202, 2021."},
  {"id": "MAK-671", "subject": "ENT: throat, sleep & nose", "topic": "Adult moderate/severe OSAHS", "title": "Adult moderate/severe OSAHS", "stem": "An adult is diagnosed with symptomatic moderate-to-severe OSAHS. Which treatment is recommended?", "options": {"A": "Fixed-level CPAP", "B": "Long-term antibiotics", "C": "Tonsillectomy for everyone", "D": "Oxygen therapy alone", "E": "No treatment"}, "correct_letter": "A", "correct_answer": "A. Fixed-level CPAP", "why_correct": "NICE recommends fixed-level CPAP, alongside lifestyle advice, for adults with moderate or severe OSAHS.", "exam_trap": "Oxygen alone is not equivalent to treating upper-airway obstruction.", "takeaway": "Moderate/severe symptomatic OSAHS → CPAP.", "source": "NICE NG202, 2021; NICE TA139 updated 2021."},
  {"id": "MAK-672", "subject": "ENT: throat, sleep & nose", "topic": "Tonsillectomy in adult OSAHS", "title": "Tonsillectomy in adult OSAHS", "stem": "An adult has OSAHS, very large obstructive tonsils and a BMI of 31 kg/m². Which surgical treatment can be considered?", "options": {"A": "Tonsillectomy", "B": "Total laryngectomy", "C": "Mastoidectomy", "D": "Parotidectomy", "E": "Septal cautery"}, "correct_letter": "A", "correct_answer": "A. Tonsillectomy", "why_correct": "NICE recommends considering tonsillectomy for people with OSAHS who have large obstructive tonsils and BMI below 35 kg/m².", "exam_trap": "This is a selected surgical group; CPAP remains a major treatment for moderate/severe OSAHS.", "takeaway": "OSAHS + large obstructive tonsils + BMI <35 → consider tonsillectomy.", "source": "NICE NG202, 2021."},
  {"id": "MAK-673", "subject": "ENT: throat, sleep & nose", "topic": "OSAHS and driving risk", "title": "OSAHS and driving risk", "stem": "A professional driver has suspected OSAHS with significant daytime sleepiness. What should happen?", "options": {"A": "Routine assessment without regard to occupation", "B": "Prioritised assessment because vigilance-critical work increases risk", "C": "Reassurance", "D": "Immediate tonsillectomy", "E": "No assessment unless hypertension develops"}, "correct_letter": "B", "correct_answer": "B. Prioritised assessment because vigilance-critical work increases risk", "why_correct": "NICE recommends rapid assessment for suspected OSAHS in people whose occupation requires critical vigilance, including vocational drivers.", "exam_trap": "Occupational risk is part of the clinical assessment.", "takeaway": "Suspected OSAHS + safety-critical occupation → prioritise assessment.", "source": "NICE NG202, 2021."},
  {"id": "MAK-674", "subject": "ENT: throat, sleep & nose", "topic": "Post-traumatic anosmia", "title": "Post-traumatic anosmia", "stem": "A patient loses their sense of smell immediately after a head injury. There are no other neurological abnormalities. What does NICE recommend?", "options": {"A": "Routine neurological referral solely for anosmia", "B": "Immediate brain biopsy", "C": "Do not routinely refer solely for post-traumatic loss of smell", "D": "Immediate tonsillectomy", "E": "Antibiotics for 6 months"}, "correct_letter": "C", "correct_answer": "C. Do not routinely refer solely for post-traumatic loss of smell", "why_correct": "NICE states that isolated loss of smell immediately after head injury does not routinely require neurological referral.", "exam_trap": "Post-traumatic anosmia is common and can be persistent; it does not automatically indicate major intracranial injury.", "takeaway": "Isolated post-traumatic anosmia → usually no routine neurology referral.", "source": "NICE NG127 (2019)."},
  {"id": "MAK-675", "subject": "ENT: throat, sleep & nose", "topic": "Persistent unexplained anosmia", "title": "Persistent unexplained anosmia", "stem": "An adult has unexplained loss of smell lasting 5 months. There is no obvious rhinological cause. What should be considered?", "options": {"A": "Neuroimaging", "B": "Immediate tonsillectomy", "C": "No further assessment", "D": "Ear irrigation", "E": "Long-term antibiotics"}, "correct_letter": "A", "correct_answer": "A. Neuroimaging", "why_correct": "NICE recommends considering neuroimaging for unexplained loss of smell or taste lasting more than 3 months.", "exam_trap": "The recommendation applies to unexplained persistent symptoms, not every episode of transient anosmia.", "takeaway": "Unexplained anosmia >3 months → consider neuroimaging.", "source": "NICE NG127 (2019)."},
  {"id": "MAK-676", "subject": "ENT: throat, sleep & nose", "topic": "Olfactory hallucinations", "title": "Olfactory hallucinations", "stem": "A patient reports brief, repetitive episodes of smelling burning rubber when no such smell is present. The episodes are stereotyped and recurrent. What neurological condition should be considered?", "options": {"A": "Temporal-lobe epilepsy", "B": "BPPV", "C": "Otitis externa", "D": "Ménière's disease", "E": "Otosclerosis"}, "correct_letter": "A", "correct_answer": "A. Temporal-lobe epilepsy", "why_correct": "NICE recommends neurological assessment for transient, repetitive smell or taste hallucinations because they can represent focal seizures.", "exam_trap": "A smell hallucination is different from simple loss or distortion of smell.", "takeaway": "Stereotyped olfactory hallucinations → think focal seizure.", "source": "NICE NG127 (2019)."},
  {"id": "MAK-677", "subject": "ENT: throat, sleep & nose", "topic": "Septal haematoma after nasal trauma", "title": "Septal haematoma after nasal trauma", "stem": "A 19-year-old sustains a nasal injury. Examination reveals a soft, fluctuant swelling of the nasal septum with bilateral nasal obstruction. What is the most appropriate management?", "options": {"A": "Same-day ENT assessment", "B": "Routine review in 6 months", "C": "Reassurance", "D": "Nasal steroid spray only", "E": "No treatment"}, "correct_letter": "A", "correct_answer": "A. Same-day ENT assessment", "why_correct": "A septal haematoma can compromise the blood supply to septal cartilage and lead to cartilage necrosis, deformity and infection if untreated.", "exam_trap": "Septal haematoma is a surgical emergency following nasal trauma.", "takeaway": "Nasal trauma + fluctuant septal swelling → septal haematoma → urgent ENT.", "source": "NHS GGC ENT guidance, reviewed May 2025."},
  {"id": "MAK-678", "subject": "ENT: throat, sleep & nose", "topic": "Why septal haematoma matters", "title": "Why septal haematoma matters", "stem": "Why must a septal haematoma be treated promptly?", "options": {"A": "It causes permanent sensorineural deafness", "B": "It can compromise septal cartilage and cause deformity", "C": "It inevitably causes meningitis", "D": "It causes retinal detachment", "E": "It always becomes malignant"}, "correct_letter": "B", "correct_answer": "B. It can compromise septal cartilage and cause deformity", "why_correct": "Blood beneath the septal mucosa can interrupt cartilage nutrition. Untreated haematoma can lead to cartilage destruction, septal perforation, deformity and potentially infection.", "exam_trap": "The problem is not simply the volume of blood; it is the effect on cartilage viability.", "takeaway": "Septal haematoma → cartilage ischaemia → deformity if untreated.", "source": "NHS GGC ENT guidance, reviewed 2025."},
  {"id": "MAK-679", "subject": "ENT: throat, sleep & nose", "topic": "Nasal fracture imaging", "title": "Nasal fracture imaging", "stem": "A patient has an isolated uncomplicated suspected nasal fracture with no neurological or other facial injuries. Which statement is most accurate?", "options": {"A": "Plain X-ray is routinely essential", "B": "Clinical assessment usually determines management", "C": "MRI is mandatory", "D": "CT head is mandatory in every case", "E": "Bone scan is required"}, "correct_letter": "B", "correct_answer": "B. Clinical assessment usually determines management", "why_correct": "Plain nasal radiographs have limited value and are generally not required for uncomplicated nasal fractures; management is guided primarily by clinical findings.", "exam_trap": "Do not order imaging simply to prove an uncomplicated nasal fracture.", "takeaway": "Simple nasal fracture → clinical assessment, not routine X-ray.", "source": "NHS hospital ENT guidance, current UK practice."},
  {"id": "MAK-680", "subject": "ENT: throat, sleep & nose", "topic": "Nasal fracture with clear rhinorrhoea", "title": "Nasal fracture with clear rhinorrhoea", "stem": "A patient sustains a significant facial injury and subsequently develops persistent unilateral clear watery nasal discharge. What should be considered?", "options": {"A": "CSF rhinorrhoea", "B": "Simple allergic rhinitis", "C": "Otitis externa", "D": "BPPV", "E": "Salivary obstruction"}, "correct_letter": "A", "correct_answer": "A. CSF rhinorrhoea", "why_correct": "Clear unilateral rhinorrhoea following significant head/facial trauma raises concern for a skull-base injury with CSF leakage.", "exam_trap": "Do not dismiss clear rhinorrhoea after trauma as ordinary nasal secretions.", "takeaway": "Head trauma + clear unilateral rhinorrhoea → think CSF leak.", "source": "NHS nasal-trauma guidance; current UK emergency practice."},
  {"id": "MAK-681", "subject": "ENT: throat, sleep & nose", "topic": "Nasal foreign body", "title": "Nasal foreign body", "stem": "A 4-year-old child has unilateral foul-smelling purulent nasal discharge. What diagnosis should be considered?", "options": {"A": "Nasal foreign body", "B": "Bilateral allergic rhinitis", "C": "Otosclerosis", "D": "Ménière's disease", "E": "Thyroid carcinoma"}, "correct_letter": "A", "correct_answer": "A. Nasal foreign body", "why_correct": "Unilateral foul-smelling nasal discharge in a child is a classic presentation of a retained nasal foreign body.", "exam_trap": "Bilateral watery symptoms are more typical of rhinitis; unilateral offensive discharge should trigger consideration of a foreign body.", "takeaway": "Child + unilateral offensive nasal discharge → foreign body until assessed.", "source": "Standard paediatric ENT clinical practice."},
  {"id": "MAK-682", "subject": "ENT: throat, sleep & nose", "topic": "Button battery in the nose", "title": "Button battery in the nose", "stem": "A child has inserted a button battery into one nostril. What is the appropriate management?", "options": {"A": "Wait for spontaneous passage", "B": "Emergency removal", "C": "Nasal steroid spray", "D": "Routine review in 1 week", "E": "Oral antihistamine"}, "correct_letter": "B", "correct_answer": "B. Emergency removal", "why_correct": "Button batteries can rapidly cause local tissue injury through electrical and chemical mechanisms and require urgent removal.", "exam_trap": "Do not treat a button battery like an inert bead.", "takeaway": "Button battery in nose/ear → emergency removal.", "source": "UK paediatric ENT emergency practice."},
  {"id": "MAK-683", "subject": "ENT: throat, sleep & nose", "topic": "failed removal", "title": "Nasal foreign body: failed removal", "stem": "A child has a nasal foreign body that cannot be safely removed in the emergency department. What is the safest next step?", "options": {"A": "Repeated blind instrumentation", "B": "Specialist ENT assessment/removal", "C": "Leave it indefinitely", "D": "Give antibiotics and ignore the object", "E": "Insert a nasal pack"}, "correct_letter": "B", "correct_answer": "B. Specialist ENT assessment/removal", "why_correct": "Repeated blind attempts can push the foreign body posteriorly or cause mucosal trauma and aspiration. Unsuccessful removal should prompt appropriate specialist management.", "exam_trap": "More attempts do not necessarily mean safer removal.", "takeaway": "Failed safe removal → stop, refer, don't repeatedly traumatise the nose.", "source": "Standard paediatric ENT emergency practice."},
  {"id": "MAK-684", "subject": "ENT: throat, sleep & nose", "topic": "Foreign body aspiration risk", "title": "Foreign body aspiration risk", "stem": "A child has a small object lodged in the posterior nasal cavity and begins coughing suddenly during attempted removal. What is the immediate concern?", "options": {"A": "Aspiration into the lower airway", "B": "Ménière's disease", "C": "Otosclerosis", "D": "Thyroid storm", "E": "Acute pancreatitis"}, "correct_letter": "A", "correct_answer": "A. Aspiration into the lower airway", "why_correct": "Manipulation of a nasal foreign body can dislodge it posteriorly, creating an aspiration risk.", "exam_trap": "The airway must be considered during any attempted removal of a foreign body.", "takeaway": "Nasal foreign body + coughing during removal → think aspiration.", "source": "Standard paediatric ENT emergency practice."},
  {"id": "MAK-685", "subject": "ENT: throat, sleep & nose", "topic": "Septal deviation", "title": "Septal deviation", "stem": "A patient has chronic unilateral nasal obstruction following previous nasal trauma. Examination demonstrates a deviated nasal septum. Which structure is primarily responsible for the anatomical obstruction?", "options": {"A": "Nasal septum", "B": "Tympanic membrane", "C": "Epiglottis", "D": "Arytenoid cartilage", "E": "Parotid duct"}, "correct_letter": "A", "correct_answer": "A. Nasal septum", "why_correct": "A deviated nasal septum can narrow one nasal passage and produce chronic unilateral obstruction.", "exam_trap": "Do not confuse structural obstruction with allergic mucosal swelling.", "takeaway": "Persistent unilateral obstruction after trauma → assess the septum.", "source": "Standard ENT anatomy and clinical practice."},
  {"id": "MAK-686", "subject": "ENT: throat, sleep & nose", "topic": "Nasal obstruction and rhinitis", "title": "Nasal obstruction and rhinitis", "stem": "A patient has bilateral nasal obstruction, sneezing and clear watery rhinorrhoea that varies with exposure to house dust. What diagnosis is most likely?", "options": {"A": "Allergic rhinitis", "B": "Nasal septal haematoma", "C": "CSF leak", "D": "Nasal foreign body", "E": "Cholesteatoma"}, "correct_letter": "A", "correct_answer": "A. Allergic rhinitis", "why_correct": "Bilateral fluctuating obstruction, sneezing and clear rhinorrhoea associated with an environmental trigger are characteristic of allergic rhinitis.", "exam_trap": "This pattern differs from unilateral foul-smelling discharge caused by a foreign body.", "takeaway": "Sneezing + clear watery bilateral rhinorrhoea + trigger → allergic rhinitis.", "source": "Standard UK ENT/primary-care practice."},
  {"id": "MAK-687", "subject": "ENT: throat, sleep & nose", "topic": "Nasal corticosteroid for allergic rhinitis", "title": "Nasal corticosteroid for allergic rhinitis", "stem": "A patient with persistent allergic rhinitis has troublesome nasal congestion. Which treatment is appropriate?", "options": {"A": "Intranasal corticosteroid", "B": "Long-term oral antibiotics", "C": "Immediate septoplasty", "D": "Tonsillectomy", "E": "Mastoidectomy"}, "correct_letter": "A", "correct_answer": "A. Intranasal corticosteroid", "why_correct": "Intranasal corticosteroids are an established treatment for allergic rhinitis, particularly where nasal congestion is prominent.", "exam_trap": "Treatment should target the inflammatory nasal disease rather than proceeding directly to surgery.", "takeaway": "Allergic rhinitis + congestion → intranasal corticosteroid is a core treatment.", "source": "NICE/UK allergic-rhinitis clinical practice."},
  {"id": "MAK-688", "subject": "ENT: throat, sleep & nose", "topic": "Nasal obstruction and sleep apnoea", "title": "Nasal obstruction and sleep apnoea", "stem": "An adult with suspected OSAHS also has significant chronic nasal congestion. What underlying condition should be assessed?", "options": {"A": "Rhinitis", "B": "Otosclerosis", "C": "Salivary stone", "D": "Cholesteatoma", "E": "Parotid tumour"}, "correct_letter": "A", "correct_answer": "A. Rhinitis", "why_correct": "NICE recommends assessing people with OSAHS and nasal congestion for underlying allergic or vasomotor rhinitis.", "exam_trap": "Nasal congestion may contribute to sleep-related symptoms but does not itself establish OSAHS.", "takeaway": "OSAHS + nasal congestion → assess for rhinitis.", "source": "NICE NG202, 2021."},
  {"id": "MAK-689", "subject": "ENT: throat, sleep & nose", "topic": "Vasomotor rhinitis with OSAHS", "title": "Vasomotor rhinitis with OSAHS", "stem": "A patient with OSAHS has persistent nasal congestion. Assessment suggests vasomotor rather than allergic rhinitis. Which treatment does NICE recommend initially?", "options": {"A": "Topical nasal corticosteroid", "B": "Long-term oral antibiotics", "C": "Tonsillectomy in every case", "D": "Systemic anticoagulation", "E": "Mastoidectomy"}, "correct_letter": "A", "correct_answer": "A. Topical nasal corticosteroid", "why_correct": "NICE recommends topical nasal corticosteroids for vasomotor rhinitis in people with OSAHS.", "exam_trap": "Do not assume every congested nose in OSAHS is allergic.", "takeaway": "OSAHS + vasomotor rhinitis → topical nasal steroid.", "source": "NICE NG202, 2021."},
  {"id": "MAK-690", "subject": "ENT: throat, sleep & nose", "topic": "Post-tonsillectomy haemorrhage", "title": "Post-tonsillectomy haemorrhage", "stem": "A patient presents to the emergency department 8 days after tonsillectomy with fresh oral bleeding. What is the most appropriate initial approach?", "options": {"A": "Reassure and discharge", "B": "Treat as a potentially significant postoperative haemorrhage and urgently involve ENT/anaesthetic teams", "C": "Give oral antihistamine only", "D": "Perform blind throat packing in the waiting room", "E": "Arrange routine outpatient review"}, "correct_letter": "B", "correct_answer": "B. Treat as a potentially significant postoperative haemorrhage and urgently involve ENT/anaesthetic teams", "why_correct": "Post-tonsillectomy haemorrhage can rapidly become life-threatening. The patient requires urgent airway, circulation and bleeding assessment with early senior ENT and anaesthetic involvement.", "exam_trap": "A patient who looks initially stable can deteriorate rapidly.", "takeaway": "Post-tonsillectomy bleeding = airway/haemorrhage emergency.", "source": "[ENTUK]: post-tonsillectomy haemorrhage guidance, and UK ENT emergency practice, which recognise haemorrhage as a significant complication of tonsillectomy."},
  {"id": "MAK-691", "subject": "Hand trauma", "topic": "FDP laceration", "title": "Hand trauma: FDP laceration", "stem": "A 28-year-old man sustains a deep laceration across the palmar aspect of his right index finger. He cannot actively flex the distal interphalangeal joint. Which structure is most likely completely divided?", "options": {"A": "Flexor digitorum superficialis", "B": "Flexor digitorum profundus", "C": "Extensor digitorum", "D": "Lumbrical", "E": "First dorsal interosseous"}, "correct_letter": "B", "correct_answer": "B. Flexor digitorum profundus", "why_correct": "Flexor digitorum profundus inserts onto the distal phalanx and is responsible for flexion of the distal interphalangeal joint. Isolated inability to flex the DIP joint therefore strongly suggests FDP disruption.", "exam_trap": "Do not equate inability to flex the finger generally with FDP injury. Test the DIP joint specifically with the PIP joint stabilised.", "takeaway": "DIP flexion = FDP.", "source": "[BSSH], Flexor Tendon Injury."},
  {"id": "MAK-692", "subject": "Hand trauma", "topic": "FDS vs FDP testing", "title": "Hand trauma: FDS vs FDP testing", "stem": "A patient has a laceration across the palmar aspect of the middle finger. Active flexion of the proximal interphalangeal joint is absent, but isolated distal interphalangeal flexion is preserved. Which structure is most likely injured?", "options": {"A": "Flexor digitorum profundus", "B": "Flexor digitorum superficialis", "C": "Extensor digitorum", "D": "Flexor pollicis longus", "E": "Lumbrical"}, "correct_letter": "B", "correct_answer": "B. Flexor digitorum superficialis", "why_correct": "FDS flexes the PIP joint. During isolated testing, the other fingers are held extended to reduce FDP contribution through the common muscle-tendon unit.", "exam_trap": "FDP flexes both the DIP and contributes to overall finger flexion. FDS is specifically assessed at the PIP joint.", "takeaway": "PIP flexion = FDS; DIP flexion = FDP.", "source": "[BSSH], Flexor Tendon Injury."},
  {"id": "MAK-693", "subject": "Hand trauma", "topic": "tendon injury assessment", "title": "Hand trauma: tendon injury assessment", "stem": "A patient with a deep finger laceration has loss of active finger flexion. What additional examination is essential before deciding on management?", "options": {"A": "Blood pressure only", "B": "Capillary glucose only", "C": "Neurovascular assessment", "D": "Abdominal examination", "E": "Visual acuity"}, "correct_letter": "C", "correct_answer": "C. Neurovascular assessment", "why_correct": "Tendons, digital nerves and vessels lie close together. A penetrating hand injury may damage more than one structure. Sensation, capillary refill and vascular status must therefore be documented.", "exam_trap": "A normal capillary refill does not exclude a digital nerve injury.", "takeaway": "Every significant hand wound requires assessment of tendon, nerve and vascular function.", "source": "[BSSH] Hand Injuries / Flexor and Extensor Tendon Injury resources."},
  {"id": "MAK-694", "subject": "Hand trauma", "topic": "extensor tendon (DIP)", "title": "Hand trauma: extensor tendon (DIP)", "stem": "A patient sustains a laceration over the dorsal aspect of the finger and cannot actively extend the distal interphalangeal joint. Which injury is most likely?", "options": {"A": "FDP injury", "B": "FDS injury", "C": "Mallet finger", "D": "Boutonnière injury", "E": "Trigger finger"}, "correct_letter": "C", "correct_answer": "C. Mallet finger", "why_correct": "Loss of active DIP extension is characteristic of disruption of the terminal extensor mechanism.", "exam_trap": "Boutonnière deformity involves loss of active PIP extension, not DIP extension.", "takeaway": "DIP extension failure = think mallet injury.", "source": "[BSSH], Extensor Tendon Injury."},
  {"id": "MAK-695", "subject": "Hand trauma", "topic": "central slip injury", "title": "Hand trauma: central slip injury", "stem": "A patient develops inability to actively extend the proximal interphalangeal joint after a forceful injury to the finger. Which tendon structure is most likely affected?", "options": {"A": "Central slip of the extensor mechanism", "B": "FDP", "C": "FDS", "D": "Terminal extensor tendon", "E": "A1 pulley"}, "correct_letter": "A", "correct_answer": "A. Central slip of the extensor mechanism", "why_correct": "The central slip contributes to extension of the PIP joint. Injury can produce a boutonnière deformity.", "exam_trap": "Do not confuse PIP extension failure with mallet finger, which affects the DIP joint.", "takeaway": "PIP extension failure after injury → consider central-slip injury.", "source": "[BSSH], Boutonnière Injury."},
  {"id": "MAK-696", "subject": "Hand trauma", "topic": "extensor tendon repair", "title": "Hand trauma: extensor tendon repair", "stem": "A patient with a clean dorsal finger laceration cannot fully extend the finger. What is the most appropriate next principle?", "options": {"A": "Assume the wound is superficial because the skin wound is small", "B": "Assess extensor tendon function and neurovascular status", "C": "Discharge without examination", "D": "Test only sensation", "E": "Apply a plaster and ignore tendon function"}, "correct_letter": "B", "correct_answer": "B. Assess extensor tendon function and neurovascular status", "why_correct": "Extensor tendons lie immediately beneath the skin and may be divided by relatively small wounds.", "exam_trap": "The size of the skin wound does not reliably indicate the severity of underlying tendon injury.", "takeaway": "Small dorsal wound + loss of extension = tendon injury until proven otherwise.", "source": "[BSSH], Extensor Tendon Injury."},
  {"id": "MAK-697", "subject": "Hand trauma", "topic": "juncturae tendinum", "title": "Hand trauma: juncturae tendinum", "stem": "A patient with an extensor tendon laceration can partially extend the finger despite a suspected complete tendon injury. Which anatomical feature can produce misleading preserved extension?", "options": {"A": "Annular ligament", "B": "Juncturae tendinum", "C": "Flexor retinaculum", "D": "Palmar aponeurosis", "E": "A1 pulley"}, "correct_letter": "B", "correct_answer": "B. Juncturae tendinum", "why_correct": "The juncturae tendinum can transmit extensor force between neighbouring tendons, potentially allowing some extension despite disruption of an individual extensor tendon.", "exam_trap": "Preserved extension does not always exclude extensor tendon division.", "takeaway": "Extensor testing must be performed carefully and individually.", "source": "[BSSH], Extensor Tendon Injuries in the Hand, professional guidance."},
  {"id": "MAK-698", "subject": "Hand trauma", "topic": "ulnar nerve laceration", "title": "Hand trauma: ulnar nerve laceration", "stem": "A patient sustains a sharp laceration to the wrist. There is reduced sensation over the little finger and ulnar half of the ring finger. Which nerve is most likely injured?", "options": {"A": "Median", "B": "Radial", "C": "Ulnar", "D": "Musculocutaneous", "E": "Axillary"}, "correct_letter": "C", "correct_answer": "C. Ulnar", "why_correct": "The ulnar nerve supplies sensation to the little finger and the ulnar half of the ring finger on the palmar side, with corresponding dorsal sensory territory.", "exam_trap": "Do not diagnose a median nerve injury simply because the wound is at the wrist; map the sensory deficit.", "takeaway": "Map sensory loss anatomically rather than by wound location.", "source": "Applied surgical anatomy; [BSSH] hand-trauma assessment guidance."},
  {"id": "MAK-699", "subject": "Hand trauma", "topic": "vascular assessment", "title": "Hand trauma: vascular assessment", "stem": "A patient with a penetrating hand injury has absent capillary refill in a digit. What is the priority?", "options": {"A": "Ignore the finding if sensation is intact", "B": "Urgent vascular assessment", "C": "Immediate physiotherapy", "D": "Routine outpatient review in several weeks", "E": "Treat with oral analgesia only"}, "correct_letter": "B", "correct_answer": "B. Urgent vascular assessment", "why_correct": "Absent or severely impaired digital perfusion may represent arterial injury and threatens tissue viability.", "exam_trap": "Normal sensation does not guarantee adequate perfusion.", "takeaway": "Hand trauma + compromised perfusion = urgent surgical/vascular assessment.", "source": "[BSSH] Standards of Care in Hand Trauma: Revascularisation Management."},
  {"id": "MAK-700", "subject": "Hand trauma", "topic": "functional assessment", "title": "Hand trauma: functional assessment", "stem": "A patient sustains a deep laceration across the palm. Which combination represents the most appropriate initial functional assessment?", "options": {"A": "Tendon function only", "B": "Sensation only", "C": "Vascular status only", "D": "Tendon, neurological and vascular assessment", "E": "Pain score only"}, "correct_letter": "D", "correct_answer": "D. Tendon, neurological and vascular assessment", "why_correct": "Hand injuries may involve skin, tendons, nerves, vessels, bones and joints. A structured assessment must therefore evaluate all relevant structures.", "exam_trap": "A visible tendon injury should not stop the examiner from checking nerves and vessels.", "takeaway": "Think T-N-V: tendon, nerve, vascular.", "source": "[BSSH] Hand Injuries; BSSH Standards of Care in Hand Trauma."},
  {"id": "MAK-701", "subject": "Hand trauma", "topic": "flexor sheath infection", "title": "Hand trauma: flexor sheath infection", "stem": "A patient develops severe finger pain, swelling and tenderness after a penetrating injury. The finger is held in slight flexion and passive extension is extremely painful. What diagnosis should be suspected?", "options": {"A": "Trigger finger", "B": "Flexor sheath infection", "C": "Osteoarthritis", "D": "Dupuytren disease", "E": "Simple bruising"}, "correct_letter": "B", "correct_answer": "B. Flexor sheath infection", "why_correct": "The combination is characteristic of pyogenic flexor tenosynovitis. Kanavel's signs include fusiform swelling, tenderness along the flexor sheath, a flexed resting posture and pain on passive extension.", "exam_trap": "Do not treat suspected flexor sheath infection as simple cellulitis.", "takeaway": "Kanavel signs → urgent hand-surgical assessment.", "source": "[BSSH], Flexor Sheath Infection standard."},
  {"id": "MAK-702", "subject": "Hand trauma", "topic": "flexor tenosynovitis management", "title": "Hand trauma: flexor tenosynovitis management", "stem": "What is the appropriate management principle for suspected pyogenic flexor tenosynovitis?", "options": {"A": "Routine outpatient review", "B": "Massage and mobilisation", "C": "Elevation, splintage, IV antibiotics and urgent hand-surgical referral", "D": "Steroid injection", "E": "Oral analgesia alone"}, "correct_letter": "C", "correct_answer": "C. Elevation, splintage, IV antibiotics and urgent hand-surgical referral", "why_correct": "Flexor sheath infection can rapidly compromise tendon function and generally requires urgent specialist management. BSSH notes that most patients require urgent surgical washout.", "exam_trap": "Do not wait for obvious pus before involving the hand-surgery team.", "takeaway": "Flexor sheath infection is a surgical infection, not a routine minor hand infection.", "source": "[BSSH], Flexor Sheath Infection standard."},
  {"id": "MAK-703", "subject": "Hand trauma", "topic": "Kanavel signs", "title": "Hand trauma: Kanavel signs", "stem": "Which of the following is NOT one of the classic Kanavel signs?", "options": {"A": "Fusiform swelling", "B": "Tenderness along the flexor sheath", "C": "Pain on passive extension", "D": "Finger held in flexion", "E": "Loss of radial pulse"}, "correct_letter": "E", "correct_answer": "E. Loss of radial pulse", "why_correct": "The classic Kanavel signs are fusiform swelling, tenderness along the flexor tendon sheath, pain on passive extension and a flexed resting posture.", "exam_trap": "A vascular deficit is important but is not a Kanavel sign.", "takeaway": "Kanavel = swelling + sheath tenderness + passive-extension pain + flexed posture.", "source": "[BSSH], Flexor Sheath Infection standard."},
  {"id": "MAK-704", "subject": "Hand trauma", "topic": "flexor sheath infection risk", "title": "Hand trauma: flexor sheath infection risk", "stem": "A patient has a penetrating hand wound sustained while gardening. What complication should particularly be considered if there is progressive pain, swelling and reduced finger movement?", "options": {"A": "Flexor sheath infection", "B": "Migraine", "C": "Otitis externa", "D": "Carpal tunnel syndrome", "E": "Frozen shoulder"}, "correct_letter": "A", "correct_answer": "A. Flexor sheath infection", "why_correct": "Penetrating injuries can introduce bacteria into the flexor sheath, producing a potentially destructive infection.", "exam_trap": "The external wound may appear deceptively minor.", "takeaway": "Penetrating hand injury + escalating pain/swelling = actively exclude deep infection.", "source": "[BSSH], Flexor Sheath Infection standard."},
  {"id": "MAK-705", "subject": "Hand trauma", "topic": "tendon injury imaging", "title": "Hand trauma: tendon injury imaging", "stem": "A patient cuts the palm with glass and has reduced finger movement. Which investigation may be particularly useful in addition to clinical tendon examination?", "options": {"A": "Plain radiograph", "B": "EEG", "C": "CT brain", "D": "Echocardiogram", "E": "DEXA scan"}, "correct_letter": "A", "correct_answer": "A. Plain radiograph", "why_correct": "Radiography may identify retained glass or associated bony/joint injury. Clinical examination remains essential for tendon function.", "exam_trap": "A normal radiograph does not exclude tendon injury.", "takeaway": "Glass injury → think retained foreign body and associated structural injury.", "source": "[BSSH], Flexor Tendon Injury."},
  {"id": "MAK-706", "subject": "Hand trauma", "topic": "mallet finger", "title": "Hand trauma: mallet finger", "stem": "A patient has a closed injury causing a drooping fingertip and inability to actively extend the DIP joint. What is the usual initial management principle?", "options": {"A": "Immediate abdominal surgery", "B": "Finger splintage", "C": "IV thrombolysis", "D": "Steroid injection into the tendon", "E": "No treatment or follow-up"}, "correct_letter": "B", "correct_answer": "B. Finger splintage", "why_correct": "Closed extensor injuries such as mallet finger are commonly managed with appropriate splintage and hand-surgical/therapy follow-up.", "exam_trap": "Closed tendon injury does not automatically mean surgery.", "takeaway": "Closed extensor injury → identify the tendon level and consider splintage.", "source": "[BSSH], Extensor Tendon Injury."},
  {"id": "MAK-707", "subject": "Hand trauma", "topic": "postoperative tendon rehab", "title": "Hand trauma: postoperative tendon rehab", "stem": "A patient undergoes flexor tendon repair. Which postoperative principle is particularly important for functional recovery?", "options": {"A": "Prolonged complete immobilisation without therapy", "B": "Protected hand therapy", "C": "Immediate unrestricted gripping", "D": "Repeated forceful passive stretching", "E": "Avoid all movement for six months"}, "correct_letter": "B", "correct_answer": "B. Protected hand therapy", "why_correct": "After flexor tendon repair, controlled rehabilitation is crucial to promote tendon gliding while protecting the repair.", "exam_trap": "More immobilisation is not necessarily better; excessive immobilisation can contribute to adhesions and stiffness.", "takeaway": "Flexor tendon repair = repair + splinting + carefully controlled rehabilitation.", "source": "[BSSH], Flexor Tendon Injury."},
  {"id": "MAK-708", "subject": "Hand trauma", "topic": "tendon re-rupture", "title": "Hand trauma: tendon re-rupture", "stem": "A patient notices a sudden “ping” followed by loss of finger flexion several weeks after flexor tendon repair. What complication should be suspected?", "options": {"A": "Tendon repair rupture", "B": "Migraine", "C": "Carpal tunnel syndrome", "D": "Osteoporosis", "E": "Septic arthritis of the knee"}, "correct_letter": "A", "correct_answer": "A. Tendon repair rupture", "why_correct": "A sudden change in active movement after tendon repair, particularly with a reported “ping”, raises concern for repair failure.", "exam_trap": "Do not simply attribute sudden loss of movement to postoperative stiffness.", "takeaway": "Sudden loss of tendon function after repair → urgent specialist review.", "source": "[BSSH], Flexor Tendon Injury."},
  {"id": "MAK-709", "subject": "Hand trauma", "topic": "active movement testing", "title": "Hand trauma: active movement testing", "stem": "A patient has a suspected flexor tendon injury. Why is active movement particularly important when examining the hand?", "options": {"A": "It directly tests tendon continuity", "B": "It measures bone density", "C": "It diagnoses infection alone", "D": "It excludes vascular injury", "E": "It measures sensation"}, "correct_letter": "A", "correct_answer": "A. It directly tests tendon continuity", "why_correct": "Active movement tests whether the musculotendinous unit can transmit force across the injured area.", "exam_trap": "Passive movement may remain preserved despite complete tendon disruption.", "takeaway": "Compare active and passive movement in suspected tendon injury.", "source": "[BSSH], Flexor Tendon Injury."},
  {"id": "MAK-710", "subject": "Hand trauma", "topic": "combined injury referral", "title": "Hand trauma: combined injury referral", "stem": "A patient has a severe hand injury with suspected tendon, nerve and vascular damage. Which specialist service is most appropriate for definitive assessment?", "options": {"A": "Dermatology", "B": "Hand surgery service", "C": "Ophthalmology", "D": "Gastroenterology", "E": "Endocrinology"}, "correct_letter": "B", "correct_answer": "B. Hand surgery service", "why_correct": "Complex hand trauma frequently requires specialist assessment because several structures may be injured simultaneously and functional outcome depends on appropriate management.", "exam_trap": "Do not manage complex structural hand trauma as a simple skin laceration.", "takeaway": "Complex hand injury → early specialist hand-surgery involvement.", "source": "[BSSH] Hand Injury Triage and Standards of Care."},
  {"id": "MAK-711", "subject": "Major trauma & fluids", "topic": "suspected spinal injury", "title": "Major trauma: suspected spinal injury", "stem": "A patient falls from a height and has neck pain with reduced sensation in both hands. What is the immediate principle?", "options": {"A": "Encourage active neck movement", "B": "Protect the cervical spine while assessment proceeds", "C": "Sit the patient upright and rotate the neck", "D": "Massage the cervical muscles", "E": "Discharge if blood pressure is normal"}, "correct_letter": "B", "correct_answer": "B. Protect the cervical spine while assessment proceeds", "why_correct": "Possible spinal injury requires cervical-spine protection while the patient undergoes structured trauma assessment.", "exam_trap": "Normal blood pressure does not exclude cervical-spine injury.", "takeaway": "Trauma + neurological symptoms + neck pain = protect the cervical spine.", "source": "NICE NG41, Spinal injury: assessment and initial management (2016)."},
  {"id": "MAK-712", "subject": "Major trauma & fluids", "topic": "spinal injury red flags", "title": "Major trauma: spinal injury red flags", "stem": "During assessment of suspected spinal injury, which neurological feature increases concern for spinal injury?", "options": {"A": "Isolated mild headache", "B": "Hand or foot weakness", "C": "Mild thirst", "D": "Abdominal bloating", "E": "Isolated ankle swelling"}, "correct_letter": "B", "correct_answer": "B. Hand or foot weakness", "why_correct": "Motor weakness is an important neurological indicator of possible spinal injury.", "exam_trap": "Do not focus only on obvious paralysis; subtle weakness can be clinically significant.", "takeaway": "Trauma + weakness or altered sensation → actively assess for spinal injury.", "source": "NICE NG41, Spinal injury: assessment and initial management (2016)."},
  {"id": "MAK-713", "subject": "Major trauma & fluids", "topic": "skull-base fracture imaging", "title": "Major trauma: skull-base fracture imaging", "stem": "A patient with major facial trauma has a complex skull-base fracture and develops neurological symptoms suggesting posterior circulation involvement. Which imaging may be required to assess vascular injury?", "options": {"A": "CT or MR angiography of the neck vessels", "B": "Plain abdominal radiograph", "C": "Ultrasound of the gallbladder", "D": "DEXA scan", "E": "Mammography"}, "correct_letter": "A", "correct_answer": "A. CT or MR angiography of the neck vessels", "why_correct": "NICE recommends CT or MRI angiography when there is suspicion of vascular injury, including certain high-risk fractures and posterior circulation syndromes.", "exam_trap": "A normal initial neurological examination does not eliminate the possibility of traumatic vascular injury when high-risk features are present.", "takeaway": "High-risk cervical/facial trauma + vascular concern → consider CT/MR angiography.", "source": "NICE NG232, Head injury: assessment and early management, recommendation 1.6.10 (2023)."},
  {"id": "MAK-714", "subject": "Major trauma & fluids", "topic": "cervical ligamentous injury imaging", "title": "Major trauma: cervical ligamentous injury imaging", "stem": "A patient with head injury requires assessment for possible cervical ligamentous injury after CT imaging. Which modality may be considered for ligamentous or disc injury?", "options": {"A": "MRI", "B": "Plain abdominal X-ray", "C": "DEXA", "D": "Mammography", "E": "Echocardiography"}, "correct_letter": "A", "correct_answer": "A. MRI", "why_correct": "MRI can assess ligamentous and disc injuries suggested by CT or clinical findings.", "exam_trap": "CT is excellent for bony injury but does not provide the same assessment of soft-tissue structures.", "takeaway": "Bone injury → CT; suspected ligamentous/disc injury → MRI may add information.", "source": "NICE NG232, Head injury: assessment and early management (2023)."},
  {"id": "MAK-715", "subject": "Major trauma & fluids", "topic": "fluid resuscitation principle", "title": "Major trauma: fluid resuscitation principle", "stem": "A patient with major trauma has active haemorrhage in hospital. Which fluid replacement principle is recommended by NICE?", "options": {"A": "Large-volume crystalloid replacement as the default", "B": "Blood components according to a major haemorrhage protocol", "C": "Oral water only", "D": "Dextrose infusion alone", "E": "No resuscitation until CT is completed"}, "correct_letter": "B", "correct_answer": "B. Blood components according to a major haemorrhage protocol", "why_correct": "For patients with active bleeding in hospital, NICE advises against crystalloid fluid replacement and recommends blood-component resuscitation according to the major haemorrhage approach.", "exam_trap": "Do not automatically apply routine IV-fluid resuscitation principles to uncontrolled major haemorrhage.", "takeaway": "Active major bleeding → haemorrhage control + blood-component resuscitation.", "source": "NICE NG39, Major trauma: assessment and initial management (2016)."},
  {"id": "MAK-716", "subject": "Major trauma & fluids", "topic": "massive transfusion ratio", "title": "Major trauma: massive transfusion ratio", "stem": "According to NICE major-trauma guidance, what plasma:red-cell ratio is recommended for adults with active bleeding in hospital?", "options": {"A": "1:4", "B": "1:2", "C": "1:1", "D": "2:1", "E": "4:1"}, "correct_letter": "C", "correct_answer": "C. 1:1", "why_correct": "NICE recommends a ratio of 1 unit of plasma to 1 unit of red cells for adults aged 16 or over when replacing fluid volume in active bleeding.", "exam_trap": "Do not confuse this with routine fluid therapy for patients who are not actively bleeding.", "takeaway": "Major haemorrhage: know the local major-haemorrhage protocol and the current component-resuscitation principles.", "source": "NICE NG39, Major trauma: assessment and initial management, recommendation 1.5.24 (2016)."},
  {"id": "MAK-717", "subject": "Major trauma & fluids", "topic": "sepsis fluid bolus", "title": "Major trauma: sepsis fluid bolus", "stem": "A haemodynamically unstable patient with suspected sepsis requires IV fluid resuscitation. Under current NICE adult sepsis guidance, what is the initial crystalloid bolus?", "options": {"A": "50 ml", "B": "100 ml", "C": "250 ml", "D": "1 litre", "E": "2 litres"}, "correct_letter": "C", "correct_answer": "C. 250 ml", "why_correct": "Current NICE NG253 recommends an initial 250 ml isotonic crystalloid bolus, ideally over 10–15 minutes, with reassessment after each bolus.", "exam_trap": "Do not automatically use the older “500 ml bolus” rule from general adult IV-fluid guidance when answering a current sepsis-specific question.", "takeaway": "Current sepsis guidance: 250 ml → reassess → further 250 ml boluses if needed.", "source": "NICE NG253, Managing suspected sepsis (2025)."},
  {"id": "MAK-718", "subject": "Major trauma & fluids", "topic": "sepsis fluid reassessment", "title": "Major trauma: sepsis fluid reassessment", "stem": "A patient receiving IV fluid resuscitation for suspected sepsis has received 250 ml. What should happen next?", "options": {"A": "Automatically prescribe another 2 litres", "B": "Reassess the patient", "C": "Stop all monitoring", "D": "Give furosemide routinely", "E": "Discharge immediately"}, "correct_letter": "B", "correct_answer": "B. Reassess the patient", "why_correct": "NICE recommends reassessment after each 250 ml bolus. Further boluses depend on the patient's response and clinical context.", "exam_trap": "Fluid resuscitation is not an automatic fixed-volume prescription.", "takeaway": "Bolus → reassess → decide.", "source": "NICE NG253, Managing suspected sepsis (2025)."},
  {"id": "MAK-719", "subject": "Major trauma & fluids", "topic": "maintenance framework", "title": "Fluid therapy: maintenance framework", "stem": "A stable adult in hospital requires IV fluids but is not in shock and has no major ongoing losses. Which framework should guide the prescription?", "options": {"A": "Resuscitation only", "B": "The 5 Rs: resuscitation, routine maintenance, replacement, redistribution and reassessment", "C": "Antibiotic stewardship principles only", "D": "Blood-transfusion protocol", "E": "Insulin sliding scale alone"}, "correct_letter": "B", "correct_answer": "B. The 5 Rs: resuscitation, routine maintenance, replacement, redistribution and reassessment", "why_correct": "NICE adult IV-fluid guidance uses the 5 Rs to structure fluid assessment and prescribing.", "exam_trap": "Not every patient receiving IV fluid needs a resuscitation bolus.", "takeaway": "First identify the purpose of the fluid: resuscitation, maintenance, replacement or redistribution, then reassess.", "source": "NICE CG174, Intravenous fluid therapy in adults in hospital (2013)."},
  {"id": "MAK-720", "subject": "Major trauma & fluids", "topic": "examination domains", "title": "MRCS Part B: examination domains", "stem": "A surgical trainee is asked which major domains are tested in the current MRCS Part B examination. Which answer is most accurate?", "options": {"A": "Only anatomy", "B": "Only operative technical skills", "C": "Anatomy and surgical pathology, applied surgical science and critical care, and clinical/procedural/communication skills", "D": "Only pharmacology", "E": "Only written MCQs"}, "correct_letter": "C", "correct_answer": "C. Anatomy and surgical pathology, applied surgical science and critical care, and clinical/procedural/communication skills", "why_correct": "The RCS describes Part B as a clinical practical examination covering applied knowledge and applied skills. This includes anatomy and surgical pathology, applied surgical science and critical care, communication, history taking and clinical/procedural skills.", "exam_trap": "Part A and Part B are different assessment formats, but their underlying surgical knowledge overlaps substantially.", "takeaway": "Build Part A knowledge so that it remains clinically transferable to Part B.", "source": "[RCSEng], MRCS examination syllabus and guidance."},
  {"id": "MAK-721", "subject": "Vascular, endocrine surgery & perioperative care", "topic": "intermittent claudication", "title": "Vascular: intermittent claudication", "stem": "A 67-year-old man has calf pain after walking 150 metres that settles after several minutes of rest. His foot is warm and there is no tissue loss. What is the most likely diagnosis?", "options": {"A": "Acute limb ischaemia", "B": "Intermittent claudication", "C": "Critical limb ischaemia", "D": "Deep-vein thrombosis", "E": "Compartment syndrome"}, "correct_letter": "B", "correct_answer": "B. Intermittent claudication", "why_correct": "Reproducible exertional muscle pain relieved by rest is characteristic of intermittent claudication due to peripheral arterial disease.", "exam_trap": "Do not call all lower-limb pain in a smoker “critical ischaemia”. Critical limb ischaemia implies substantially more severe disease, often with rest pain or tissue loss.", "takeaway": "Exertional reproducible pain → claudication.", "source": "NICE CG147, Peripheral arterial disease: diagnosis and management (2012)."},
  {"id": "MAK-722", "subject": "Vascular, endocrine surgery & perioperative care", "topic": "ankle-brachial pressure index", "title": "Vascular: ankle-brachial pressure index", "stem": "A patient is being assessed for suspected peripheral arterial disease. Which bedside measurement is recommended as part of the assessment?", "options": {"A": "Ankle–brachial pressure index", "B": "Central venous pressure", "C": "Peak expiratory flow rate", "D": "Glasgow Coma Scale", "E": "Pulmonary artery pressure"}, "correct_letter": "A", "correct_answer": "A. Ankle–brachial pressure index", "why_correct": "NICE recommends measuring the ankle–brachial pressure index in people with suspected peripheral arterial disease.", "exam_trap": "Do not use pulse oximetry as a substitute for ABPI when diagnosing PAD.", "takeaway": "Suspected PAD → pulses + ABPI.", "source": "NICE CG147, Peripheral arterial disease, recommendations 1.3.1-1.3.3 (2012)."},
  {"id": "MAK-723", "subject": "Vascular, endocrine surgery & perioperative care", "topic": "ABPI in diabetes", "title": "Vascular: ABPI in diabetes", "stem": "A patient with diabetes has exertional leg pain and a foot ulcer. His ankle–brachial pressure index is apparently normal. What is the most appropriate interpretation?", "options": {"A": "PAD is excluded", "B": "PAD remains possible", "C": "The ulcer must be venous", "D": "The patient cannot have arterial disease because he has diabetes", "E": "ABPI proves the ulcer is neuropathic"}, "correct_letter": "B", "correct_answer": "B. PAD remains possible", "why_correct": "NICE specifically advises that PAD should not be excluded in people with diabetes on the basis of a normal or raised ABPI alone.", "exam_trap": "Diabetes can cause arterial calcification, which may make ankle pressures misleadingly high.", "takeaway": "Diabetes + suspicious symptoms → normal ABPI does not automatically exclude PAD.", "source": "NICE CG147, Peripheral arterial disease, recommendation 1.3.4 (2012)."},
  {"id": "MAK-724", "subject": "Vascular, endocrine surgery & perioperative care", "topic": "revascularisation imaging", "title": "Vascular: revascularisation imaging", "stem": "A patient with PAD is being considered for revascularisation. What is the recommended first-line imaging modality?", "options": {"A": "Plain radiography", "B": "Duplex ultrasound", "C": "CT brain", "D": "MRI spine", "E": "Echocardiography"}, "correct_letter": "B", "correct_answer": "B. Duplex ultrasound", "why_correct": "NICE recommends duplex ultrasound as first-line imaging for people with PAD in whom revascularisation is being considered.", "exam_trap": "Do not automatically select CT angiography simply because it provides detailed vascular images.", "takeaway": "PAD requiring revascularisation → duplex first.", "source": "NICE CG147, Peripheral arterial disease, recommendation 1.4.1 (2012)."},
  {"id": "MAK-725", "subject": "Vascular, endocrine surgery & perioperative care", "topic": "claudication conservative treatment", "title": "Vascular: claudication conservative treatment", "stem": "A patient with intermittent claudication has received risk-factor advice but remains significantly limited by symptoms. What conservative treatment should be offered?", "options": {"A": "Bed rest", "B": "Supervised exercise programme", "C": "Routine long-term opioids", "D": "Immediate major amputation", "E": "Routine thrombolysis"}, "correct_letter": "B", "correct_answer": "B. Supervised exercise programme", "why_correct": "NICE recommends a supervised exercise programme for people with intermittent claudication.", "exam_trap": "Exercise is treatment, not simply general lifestyle advice.", "takeaway": "Claudication → risk-factor modification + supervised exercise.", "source": "NICE CG147, Peripheral arterial disease, recommendation 1.5.1 (2012)."},
  {"id": "MAK-726", "subject": "Vascular, endocrine surgery & perioperative care", "topic": "critical limb ischaemia", "title": "Vascular: critical limb ischaemia", "stem": "A patient has severe peripheral arterial disease with ischaemic tissue loss. Which statement is most appropriate?", "options": {"A": "Major amputation should automatically be first-line treatment", "B": "Vascular multidisciplinary assessment is required", "C": "PAD never requires revascularisation", "D": "Exercise alone is always sufficient", "E": "ABPI is unnecessary"}, "correct_letter": "B", "correct_answer": "B. Vascular multidisciplinary assessment is required", "why_correct": "NICE recommends assessment by a vascular multidisciplinary team before treatment decisions in critical limb ischaemia.", "exam_trap": "Severe ischaemia does not automatically mean amputation.", "takeaway": "Threatened limb → involve vascular specialists and consider revascularisation.", "source": "NICE CG147, Peripheral arterial disease, recommendation 1.6.1 (2012)."},
  {"id": "MAK-727", "subject": "Vascular & fracture complications", "topic": "vascular injury after alignment", "title": "Fracture: vascular injury after alignment", "stem": "A patient sustains a complex tibial fracture and has persistent clinical signs of vascular injury after fracture alignment. What is the appropriate principle?", "options": {"A": "Observe for 48 hours", "B": "Immediate surgical exploration", "C": "Discharge with oral analgesia", "D": "Wait for routine outpatient angiography", "E": "Apply compression stockings"}, "correct_letter": "B", "correct_answer": "B. Immediate surgical exploration", "why_correct": "NICE recommends immediate surgical exploration when hard signs of vascular injury persist after necessary restoration of limb alignment and joint reduction.", "exam_trap": "Do not delay definitive treatment for routine imaging when there are persistent hard signs of vascular injury.", "takeaway": "Hard vascular signs after major limb trauma → urgent exploration.", "source": "NICE NG37, Fractures (complex): assessment and management, recommendation 1.2.3 (2016)."},
  {"id": "MAK-728", "subject": "Vascular & fracture complications", "topic": "devascularised limb management", "title": "Fracture: devascularised limb management", "stem": "A patient with a complex fracture has a cold, pulseless limb. Which investigation should NOT delay revascularisation when a limb is clearly devascularised?", "options": {"A": "Angiography", "B": "Full blood count", "C": "Group and save", "D": "ECG", "E": "U&E"}, "correct_letter": "A", "correct_answer": "A. Angiography", "why_correct": "NICE states that revascularisation should not be delayed for angiography in people with complex fractures and a devascularised limb.", "exam_trap": "Imaging can define anatomy, but it must not become a reason to delay urgent limb salvage.", "takeaway": "Clearly devascularised limb → restore perfusion urgently.", "source": "NICE NG37, Fractures (complex): assessment and management, recommendation 1.2.5 (2016)."},
  {"id": "MAK-729", "subject": "Vascular & fracture complications", "topic": "compartment syndrome vigilance", "title": "Fracture: compartment syndrome vigilance", "stem": "A patient sustains a tibial fracture. Which complication requires continued vigilance during the first 48 hours after injury or fixation?", "options": {"A": "Compartment syndrome", "B": "Cataract", "C": "Chronic liver disease", "D": "Peptic ulcer disease", "E": "Otitis media"}, "correct_letter": "A", "correct_answer": "A. Compartment syndrome", "why_correct": "NICE recommends maintaining awareness of compartment syndrome for 48 hours following tibial fracture or fixation, with regular assessment and documentation.", "exam_trap": "A patient who initially appears well can subsequently develop compartment syndrome.", "takeaway": "Tibial fracture → serial compartment assessment.", "source": "NICE NG37, Fractures (complex): assessment and management, recommendation 1.2.7 (2016)."},
  {"id": "MAK-730", "subject": "Vascular & fracture complications", "topic": "compartment syndrome recognition", "title": "Fracture: compartment syndrome recognition", "stem": "A patient with suspected acute compartment syndrome has escalating pain, particularly with passive stretch of the affected muscles. What is the key concern?", "options": {"A": "Benign postoperative pain", "B": "Raised compartment pressure threatening muscle and nerve viability", "C": "Venous eczema", "D": "Chronic osteoarthritis", "E": "Cellulitis alone"}, "correct_letter": "B", "correct_answer": "B. Raised compartment pressure threatening muscle and nerve viability", "why_correct": "Acute compartment syndrome is caused by increased pressure within a closed fascial compartment, compromising microvascular perfusion and potentially causing irreversible muscle and nerve injury.", "exam_trap": "Do not wait for absent pulses before recognising compartment syndrome.", "takeaway": "Severe escalating pain + pain on passive stretch → compartment syndrome until excluded.", "source": "NICE NG37, Fractures (complex): assessment and management, compartment-syndrome recommendations (2016)."},
  {"id": "MAK-731", "subject": "Breast surgery", "topic": "new lump referral pathway", "title": "Breast: new lump referral pathway", "stem": "A 42-year-old woman has a new unexplained breast lump. Which investigation pathway is most appropriate?", "options": {"A": "Ignore the lump if it is painless", "B": "Assessment through a breast diagnostic pathway", "C": "Antibiotics for six months", "D": "Routine neurological referral", "E": "No examination is required"}, "correct_letter": "B", "correct_answer": "B. Assessment through a breast diagnostic pathway", "why_correct": "An unexplained breast lump in an adult requires appropriate breast assessment. NICE recommends suspected-cancer referral for an unexplained breast lump in people aged 30 and over.", "exam_trap": "Pain does not reliably distinguish benign from malignant breast disease.", "takeaway": "New unexplained breast lump in an adult → investigate.", "source": "NICE NG12, suspected breast cancer recommendations (updated 2025)."},
  {"id": "MAK-732", "subject": "Breast surgery", "topic": "unilateral nipple discharge", "title": "Breast: unilateral nipple discharge", "stem": "A 55-year-old woman has unilateral spontaneous nipple discharge. What is the most appropriate approach?", "options": {"A": "Reassure without assessment", "B": "Urgent breast assessment", "C": "Treat with antibiotics indefinitely", "D": "Immediate mastectomy without diagnosis", "E": "Ignore if there is no fever"}, "correct_letter": "B", "correct_answer": "B. Urgent breast assessment", "why_correct": "NICE identifies unilateral nipple discharge in people aged 50 and over as a feature warranting suspected-cancer-pathway referral.", "exam_trap": "Absence of a palpable lump does not exclude significant breast pathology.", "takeaway": "Unilateral concerning nipple change/discharge in an older woman → breast assessment.", "source": "NICE NG12, recommendation 1.4.1 (updated 2025)."},
  {"id": "MAK-733", "subject": "Breast surgery", "topic": "triple assessment", "title": "Breast: triple assessment", "stem": "A 48-year-old woman has a suspicious breast lump. Which combination best represents the principle of triple assessment?", "options": {"A": "History, ECG and chest X-ray", "B": "Clinical assessment, imaging and tissue diagnosis when indicated", "C": "Blood pressure, urinalysis and CT brain", "D": "Mammography alone", "E": "MRI alone"}, "correct_letter": "B", "correct_answer": "B. Clinical assessment, imaging and tissue diagnosis when indicated", "why_correct": "Breast diagnosis commonly uses clinical assessment, appropriate imaging and pathological assessment of tissue when required.", "exam_trap": "No single component should automatically be treated as definitive in every patient.", "takeaway": "Breast lump → triple-assessment concept.", "source": "Standard UK breast-surgical diagnostic practice; NICE NG12 (updated 2025)."},
  {"id": "MAK-734", "subject": "Breast surgery", "topic": "axillary lymphadenopathy", "title": "Breast: axillary lymphadenopathy", "stem": "A woman with breast cancer has palpable axillary lymphadenopathy. Which anatomical concept is particularly important when assessing regional spread?", "options": {"A": "Axillary lymphatic drainage", "B": "Portal venous drainage", "C": "Caval drainage", "D": "Mesenteric drainage", "E": "Pelvic lymphatic drainage only"}, "correct_letter": "A", "correct_answer": "A. Axillary lymphatic drainage", "why_correct": "The axillary nodes are a major regional lymphatic basin for breast cancer, making axillary examination and staging clinically important.", "exam_trap": "Do not confuse lymphatic drainage with venous drainage.", "takeaway": "Breast cancer → think lymphatic drainage and axillary staging.", "source": "Applied surgical anatomy; [MCOA9]."},
  {"id": "MAK-735", "subject": "Urology", "topic": "painless visible haematuria", "title": "Urology: painless visible haematuria", "stem": "A man presents with painless visible haematuria without evidence of urinary infection. He is 52 years old. What is the most appropriate next principle?", "options": {"A": "Reassure permanently", "B": "Urgent urological assessment for possible malignancy", "C": "Treat with steroids", "D": "Diagnose renal colic without assessment", "E": "Ignore if renal function is normal"}, "correct_letter": "B", "correct_answer": "B. Urgent urological assessment for possible malignancy", "why_correct": "NICE recommends suspected-cancer-pathway referral for unexplained visible haematuria in adults aged 45 and over when it is not attributable to UTI or persists/recurs after successful treatment.", "exam_trap": "Normal renal function does not exclude urinary tract malignancy.", "takeaway": "Unexplained visible haematuria → cancer pathway consideration.", "source": "NICE NG12, urological cancer recommendations (updated 2025)."},
  {"id": "MAK-736", "subject": "Urology", "topic": "LUTS and prostate assessment", "title": "Urology: LUTS and prostate assessment", "stem": "A man has lower urinary tract symptoms including hesitancy, weak stream and nocturia. Which assessment may be appropriate when prostate cancer is being considered?", "options": {"A": "PSA and digital rectal examination", "B": "EEG", "C": "Spirometry only", "D": "Colonoscopy only", "E": "ABPI only"}, "correct_letter": "A", "correct_answer": "A. PSA and digital rectal examination", "why_correct": "NICE recommends considering PSA testing and digital rectal examination in men with relevant lower urinary tract symptoms, erectile dysfunction or visible haematuria when assessing for prostate cancer.", "exam_trap": "Lower urinary tract symptoms are common and do not automatically mean prostate cancer, but they can warrant assessment depending on the clinical context.", "takeaway": "LUTS + cancer concern → PSA + DRE may be appropriate.", "source": "NICE NG12, recommendation 1.6.2 (updated 2025)."},
  {"id": "MAK-737", "subject": "Urology", "topic": "malignant-feeling prostate", "title": "Urology: malignant-feeling prostate", "stem": "A man has a prostate that feels malignant on digital rectal examination. What is the appropriate next principle?", "options": {"A": "Reassure because PSA is unknown", "B": "Suspected-cancer referral", "C": "Treat empirically with antibiotics for six months", "D": "Ignore the finding", "E": "Repeat examination in five years"}, "correct_letter": "B", "correct_answer": "B. Suspected-cancer referral", "why_correct": "NICE recommends suspected-cancer-pathway referral when the prostate feels malignant on DRE.", "exam_trap": "A concerning DRE should not be dismissed simply because the patient has no urinary symptoms.", "takeaway": "Malignant-feeling prostate → urgent cancer pathway.", "source": "NICE NG12, recommendation 1.6.1 (updated 2025)."},
  {"id": "MAK-738", "subject": "Urology", "topic": "acute urinary retention", "title": "Urology: acute urinary retention", "stem": "A man develops acute painful urinary retention with a distended bladder. What is the immediate management principle?", "options": {"A": "Delay decompression until PSA returns", "B": "Urgent bladder decompression", "C": "Encourage excessive oral fluids", "D": "Give laxatives only", "E": "Observe for one week"}, "correct_letter": "B", "correct_answer": "B. Urgent bladder decompression", "why_correct": "Acute urinary retention is a painful, potentially complicated condition requiring prompt bladder drainage.", "exam_trap": "Do not delay catheterisation simply to obtain a definitive cause.", "takeaway": "Acute retention → decompress first, investigate cause.", "source": "Standard UK acute-urological practice; NICE NG12 (updated 2025)."},
  {"id": "MAK-739", "subject": "Urology", "topic": "post-biopsy sepsis", "title": "Urology: post-biopsy sepsis", "stem": "A man develops fever and rigors after a transrectal prostate biopsy. What serious complication must be considered?", "options": {"A": "Sepsis", "B": "Cataract", "C": "Migraine", "D": "Appendicitis", "E": "Chronic venous insufficiency"}, "correct_letter": "A", "correct_answer": "A. Sepsis", "why_correct": "Prostate biopsy can introduce infection. NICE notes sepsis as an important serious complication of transrectal biopsy.", "exam_trap": "Post-biopsy fever is not automatically a harmless inflammatory response.", "takeaway": "Post-urological procedure + fever/rigors → assess urgently for sepsis.", "source": "NICE NG131, Prostate cancer: diagnosis and management (2019, updated 2021)."},
  {"id": "MAK-740", "subject": "Paediatric surgery", "topic": "pyloric stenosis", "title": "Paediatric surgery: pyloric stenosis", "stem": "An infant under 2 months develops progressively worsening projectile vomiting after feeds. What diagnosis should be considered?", "options": {"A": "Hypertrophic pyloric stenosis", "B": "Acute appendicitis", "C": "Crohn disease", "D": "Diverticular disease", "E": "Adult peptic ulcer disease"}, "correct_letter": "A", "correct_answer": "A. Hypertrophic pyloric stenosis", "why_correct": "NICE identifies frequent forceful/projectile vomiting in infants up to 2 months as a red flag for hypertrophic pyloric stenosis and recommends same-day specialist assessment for progressively worsening or forceful vomiting.", "exam_trap": "Do not simply label repeated vomiting as gastro-oesophageal reflux.", "takeaway": "Young infant + progressive projectile vomiting → pyloric stenosis.", "source": "NICE NG1, Gastro-oesophageal reflux disease in children and young people: diagnosis and management, recommendations 1.1.5 and 1.1.19 (2015)."},
  {"id": "MAK-741", "subject": "Paediatric surgery", "topic": "green vomit", "title": "Paediatric surgery: green vomit", "stem": "An infant presents with green vomit. What is the most appropriate interpretation?", "options": {"A": "Typical physiological reflux", "B": "Possible intestinal obstruction requiring urgent specialist assessment", "C": "Normal teething", "D": "Isolated lactose intolerance", "E": "Simple viral rhinitis"}, "correct_letter": "B", "correct_answer": "B. Possible intestinal obstruction requiring urgent specialist assessment", "why_correct": "Bilious vomiting in an infant is a red flag for possible intestinal obstruction, including malrotation with volvulus.", "exam_trap": "The colour matters: green/bile-stained vomiting is not ordinary reflux.", "takeaway": "Infant + bilious vomiting = obstruction until proven otherwise.", "source": "NICE NG1, Gastro-oesophageal reflux disease in children and young people: diagnosis and management, recommendations on red-flag vomiting (2015)."},
  {"id": "MAK-742", "subject": "Paediatric surgery", "topic": "bilious vomiting", "title": "Paediatric surgery: bilious vomiting", "stem": "An infant has unexplained bile-stained vomiting. Which investigation does NICE recommend urgently?", "options": {"A": "Same-day upper GI contrast study", "B": "Routine colonoscopy", "C": "DEXA scan", "D": "MRI knee", "E": "Outpatient ECG only"}, "correct_letter": "A", "correct_answer": "A. Same-day upper GI contrast study", "why_correct": "NICE recommends an urgent same-day upper GI contrast study for infants with unexplained bile-stained vomiting to exclude serious obstruction such as midgut volvulus.", "exam_trap": "Do not delay investigation because the abdomen initially appears soft.", "takeaway": "Bilious vomiting in an infant → urgent assessment for malrotation/volvulus.", "source": "NICE NG1, Gastro-oesophageal reflux disease in children and young people: diagnosis and management, recommendation 1.1.16 (2015)."},
  {"id": "MAK-743", "subject": "Burns & paediatric fluids", "topic": "non-accidental burn pattern", "title": "Paediatric surgery: non-accidental burn pattern", "stem": "A child has a scald injury involving both buttocks and the perineum with a sharply demarcated distribution. What should this pattern raise concern about?", "options": {"A": "Child maltreatment", "B": "Simple sunburn", "C": "Contact dermatitis", "D": "Viral exanthem", "E": "Psoriasis"}, "correct_letter": "A", "correct_answer": "A. Child maltreatment", "why_correct": "NICE identifies sharply demarcated burns, forced-immersion patterns and burns involving areas such as the buttocks and perineum as patterns that should raise concern about maltreatment.", "exam_trap": "The pattern and developmental history matter, not just the reported mechanism.", "takeaway": "Suspicious burn pattern → safeguarding assessment.", "source": "NICE CG89, Child maltreatment: when to suspect maltreatment in under 18s (2009, updated 2017)."},
  {"id": "MAK-744", "subject": "Burns & paediatric fluids", "topic": "forced-immersion burn", "title": "Paediatric surgery: forced-immersion burn", "stem": "A child has a burn injury with a pattern resembling forced immersion. What is the most appropriate response?", "options": {"A": "Document and assess safeguarding concerns", "B": "Ignore the pattern if the burn is small", "C": "Discharge without further assessment", "D": "Treat only with analgesia", "E": "Assume accidental injury"}, "correct_letter": "A", "correct_answer": "A. Document and assess safeguarding concerns", "why_correct": "A suspicious burn pattern should trigger consideration of maltreatment and appropriate safeguarding assessment.", "exam_trap": "Small burn size does not make a suspicious mechanism irrelevant.", "takeaway": "Burn pattern + unsuitable explanation → safeguarding.", "source": "NICE CG89, Child maltreatment, thermal injuries recommendations (2009, updated 2017)."},
  {"id": "MAK-745", "subject": "Burns & paediatric fluids", "topic": "TBSA estimation", "title": "Burns: TBSA estimation", "stem": "In a major burn, which method is used to estimate the percentage of total body surface area burned, particularly in children?", "options": {"A": "Lund and Browder chart", "B": "Glasgow Coma Scale", "C": "Wells score", "D": "CHA2DS2-VASc", "E": "APGAR score"}, "correct_letter": "A", "correct_answer": "A. Lund and Browder chart", "why_correct": "The Lund and Browder method is used to estimate burn total body surface area and accounts for changing body proportions with age.", "exam_trap": "Do not use a single fixed adult percentage map for children.", "takeaway": "Burn TBSA → Lund and Browder, particularly important in children.", "source": "NICE MIB58, Mersey Burns for calculating fluid resuscitation in adults and children with severe burns (2016)."},
  {"id": "MAK-746", "subject": "Burns & paediatric fluids", "topic": "shock bolus", "title": "Paediatric fluids: shock bolus", "stem": "A child requires IV fluid resuscitation for shock unrelated to diabetic ketoacidosis. Which initial bolus does current NICE paediatric IV-fluid guidance recommend?", "options": {"A": "1 ml/kg", "B": "5 ml/kg", "C": "10 ml/kg", "D": "50 ml/kg", "E": "100 ml/kg"}, "correct_letter": "C", "correct_answer": "C. 10 ml/kg", "why_correct": "NICE recommends glucose-free crystalloids containing sodium 131–154 mmol/L, with a 10 ml/kg bolus over less than 10 minutes for children and young people requiring IV fluid resuscitation, with reassessment and adjustment for comorbidities.", "exam_trap": "Do not automatically apply adult 500 ml bolus rules to children.", "takeaway": "Paediatric fluid resuscitation → weight-based prescription.", "source": "NICE NG29, Intravenous fluid therapy in children and young people in hospital, recommendation 1.3.1 (2015)."},
  {"id": "MAK-747", "subject": "Burns & paediatric fluids", "topic": "bolus volume calculation", "title": "Paediatric fluids: bolus volume calculation", "stem": "A child weighing 20 kg requires IV fluid resuscitation under the standard NICE paediatric algorithm. What volume corresponds to the initial 10 ml/kg bolus?", "options": {"A": "20 ml", "B": "50 ml", "C": "100 ml", "D": "200 ml", "E": "500 ml"}, "correct_letter": "D", "correct_answer": "D. 200 ml", "why_correct": "10 ml/kg × 20 kg = 200 ml.", "exam_trap": "Paediatric fluid prescriptions are weight-based; avoid using arbitrary adult volumes.", "takeaway": "Always calculate paediatric resuscitation by weight.", "source": "NICE NG29, Intravenous fluid therapy in children and young people, recommendation 1.3.1 (2015)."},
  {"id": "MAK-748", "subject": "Burns & paediatric fluids", "topic": "extent assessment", "title": "Burns: extent assessment", "stem": "An adult with a significant burn requires formal assessment of burn extent before fluid resuscitation calculations. Which measurement is most important?", "options": {"A": "Total body surface area burned", "B": "Height alone", "C": "BMI alone", "D": "Head circumference", "E": "Mid-arm circumference alone"}, "correct_letter": "A", "correct_answer": "A. Total body surface area burned", "why_correct": "Burn resuscitation calculations depend on burn size and patient characteristics. Accurate TBSA assessment is therefore fundamental.", "exam_trap": "Do not calculate burn fluid requirements from burn depth alone.", "takeaway": "Significant burn → determine TBSA accurately before formal fluid calculation.", "source": "NICE MIB58, Mersey Burns for calculating fluid resuscitation in adults and children with severe burns (2016)."},
  {"id": "MAK-749", "subject": "Perioperative medicine & nutrition", "topic": "adult maintenance water", "title": "Fluid therapy: adult maintenance water", "stem": "A patient requires IV fluids for routine maintenance rather than resuscitation. Which adult daily water requirement is recommended initially by NICE?", "options": {"A": "5–10 ml/kg/day", "B": "10–15 ml/kg/day", "C": "25–30 ml/kg/day", "D": "50–60 ml/kg/day", "E": "100 ml/kg/day"}, "correct_letter": "C", "correct_answer": "C. 25–30 ml/kg/day", "why_correct": "NICE recommends an initial routine-maintenance prescription of approximately 25–30 ml/kg/day of water, with adjustment for clinical circumstances.", "exam_trap": "Maintenance requirements are not the same as resuscitation requirements.", "takeaway": "Adult maintenance ≠ resuscitation.", "source": "NICE CG174, Intravenous fluid therapy in adults in hospital, recommendation 1.4.1 (2013)."},
  {"id": "MAK-750", "subject": "Perioperative medicine & nutrition", "topic": "hyperchloraemic acidosis", "title": "Fluid therapy: hyperchloraemic acidosis", "stem": "A hospitalised adult receiving IV fluids has been prescribed sodium chloride 0.9% for several days and develops hyperchloraemia with acidaemia. What should be considered?", "options": {"A": "Reassess the IV-fluid prescription and acid–base status", "B": "Automatically increase the sodium chloride concentration", "C": "Ignore the chloride result", "D": "Stop all monitoring", "E": "Give potassium routinely"}, "correct_letter": "A", "correct_answer": "A. Reassess the IV-fluid prescription and acid–base status", "why_correct": "NICE recommends monitoring chloride in patients receiving fluids with chloride concentrations above 120 mmol/L and reassessing the fluid prescription and acid–base status if hyperchloraemia or acidaemia develops.", "exam_trap": "A normal sodium concentration does not make the fluid prescription automatically appropriate.", "takeaway": "IV fluids are drugs: prescribe, monitor and reassess.", "source": "NICE CG174, Intravenous fluid therapy in adults in hospital, recommendation 1.2.5 (2013)."}
];
